#include <stdio.h>
#include <stdlib.h> //qsort

struct shoe{
	double duration, fine;
	int position;
};

int cmp(const void *a, const void *b){
	const struct shoe *sa = a;
	const struct shoe *sb = b;
	double x = sa->fine/sa->duration;
	double y = sb->fine/sb->duration;

	if (x>y)
		return -1;
	else if(x<y)
		return 1;
	return 1;
}

int main(){
	int casesize, k;
	scanf("%d",&casesize);
	struct shoe shoes[casesize];
	for (k=0; k<casesize; k++){
		scanf("%lf %lf",&shoes[k].duration, &shoes[k].fine);
		shoes[k].position = k+1;
	}
	size_t elemsize = sizeof shoes[0];
	size_t count = sizeof(shoes)/elemsize;
	qsort(shoes, count, elemsize, cmp);
	printf("%d",shoes[0].position);
	for(k=1; k<casesize; k++)
		printf(" %d",shoes[k].position);
	printf("\n");

	return 0;
}

