#define MAX 25      // Maximo numero de nos

int n;              // Numero de nos do grafo
char adj[MAX][MAX]; // Matriz de adjacencias
char visited[MAX];  // Que nos ja foram visitados?

void dfs(int v) {
  int i;
  visited[v] = 1;
  for (i=1; i<=n; i++)
    if (adj[v][i] && !visited[i])
      dfs(i);
}

int main() {
  int i, edges, a, b,contador=0;

  scanf("%d", &n);
  scanf("%d", &edges);
  for (i=0; i<edges; i++) {
    scanf("%d %d", &a, &b);
    adj[a][b] = adj[b][a] = 1;
  }
  for(i=1;i<=edges;i++)
    if(visited[i]==0){
      contador++;
      dfs(i);
    }
  //putchar('\n');
  if(n>0 && edges==0) contador=n;
  printf("%d\n",contador);
  return 0;
}

