#include <stdio.h>
#include <stdlib.h>

#define MAX_LENGTH  1000

int cmpint(const void *i1, const void *i2){
	return *(int*)i1 - *(int*)i2;
}

int bisearch(int v[], int low, int high, int c){
	int middle;
	while(low < high){
		middle = low+(high-low)/2;
		//printf("C==%d V==%d\n",c,v[middle]);
		if(v[middle] >= c)	high = middle;
		else low = middle + 1;
	}
	//printf("V==%d  low==%d   middle==%d\n",v[middle],low, middle);
	if(c>v[low]) return -1;
	return low;

}

int main() {
	int n,i,p,j,size=0;
	int temp[MAX_LENGTH],somas[MAX_LENGTH], pares[MAX_LENGTH];

	scanf("%d",&n);

	for (i = 0; i < n; i++)
	{
		scanf("%d",&p);
		temp[i] = p;
	}
	for (i = 0; i < n; i++){
		for (j = 0; j < n; j++){
			if(i!=j){
				somas[size] = temp[i]+temp[j];
				size++;

			}
		}
	}
	qsort(somas, size-1, sizeof(int), cmpint);
	//printf("%d\n",size);
	scanf("%d",&n);

	for(i =0; i < n; i++){
		scanf("%d",&pares[i]);
	}
	for(i =0; i < n; i++){
		p=bisearch( somas, 0,  size-1, pares[i]);
		if(p==-1)
			printf("%d\n",somas[size-1]);
		else if(p==0)
			printf("%d\n",somas[0]);
		else if(p>size)
			printf("%d\n",somas[size-1]);
		else{
			if(pares[i] == somas[p])
				printf("%d\n",somas[p]);
			else if((somas[p]-pares[i])==(pares[i]-somas[p-1]))
				printf("%d %d\n",somas[p-1],somas[p]);
			else if((somas[p]-pares[i])<(pares[i]-somas[p-1]))
				printf("%d\n",somas[p]);
			else
				printf("%d\n",somas[p-1]);
		}
	}

	return 0;
}

