#include <stdio.h>
#include <stdlib.h>

#define N 1000
#define S 1000000

int pesquisaBin(int somav[S], int p, int begin, int end){
  int mid = 0;

  while(begin < end){
    mid = begin + (end - begin)/2;
    if(p == somav[mid])
      return mid;

    else if(p < somav[mid])
      end = mid + 1;
    else
      end = end + 1;
  }
  return 0;
}

int compare_int(const void * a, const void * b){
  return ( *(int*)a - *(int*)b );
}


int main() {
  int somav[S], k, n, i, j, v[N], p, res, per;

  scanf("%d", &n);

  for(i=0; i<n; i++)
    scanf("%d", &v[i]);

  scanf("%d", &per);

  k=0;
  for(i=0; i<n; i++){
    for(j=0; j<n; j++){
      somav[k]= v[i] + v[j];
      k++;
    }
  }

  qsort(somav, S, sizeof(int), compare_int);

  for(i=0; i<per; i++){
    scanf("%d", &p);
    res = pesquisaBin(somav, p, 0, k-1);
    printf("%d\n", res);
  }


  return 0;
}

