#include <stdio.h>
#include <stdlib.h>

// Funcao para comparar dois elementos de um array (necessaria para o qsort)
// Esta funcao deve devolver:
//  - numero < 0 se elemento "a" for menor que elemento "b"
//  - numero > 0 se elemento "a" for maior que elemento "b"
//  - zero, se elemento "a" for igual ao elemento "b"
int compare_int(const void *a, const void *b) {
  int i1 = *((int *)a);
  int i2 = *((int *)b);

  if (i1 < i2) return -1;
  if (i1 > i2) return +1;
  return 0;
}

int main() {
  int i;
  int n; //numeros que contem
  // Um array exemplo 
  scanf("%d\n", &n);
  int v[100];
  //int v[10] = {33, 4, 28, 18, 15, 2, 8, 17, 42, 39};

  // printf(" Antes de ordenar: ");
  for (i=0; i<n; i++)
    scanf("%d", &v[i]);
    //printf("%d ", v[i]);
    //putchar('\n');

  // Chamada ao sort padrao da linguagem C
  // qsort(array, quantidade_elementos, tamanho_um_elemento, funcao_comparar)
  qsort(v, n, sizeof(int), compare_int);

  //printf("Depois de ordenar: ");
  for (i=0; i<n; i++)
    printf("%d ", v[i]);
  putchar('\n');

  return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX 1000000
#define MAXM 1000

typedef struct {
	int l;
	int r;
} Caminhos;

Caminhos c[MAXM];

int n, m, i, min=0, k=0, inicio=0, fim=0;

void solve() {

	k=m;

	if(c[0].l >= m && c[0].r >= m) {
		printf("0\n");
	}

	else {
		inicio=c[0].l;
		fim=c[0].r;

		min++;

		if(k >= 0) {

			for(i=1;i<n;i++) {
				if(c[i].l==fim && c[i].r <= m) {
					inicio=c[i].l;
					fim=c[i].r;
					min++;
					k=k-(c[i].r - c[i].l);
				}
			}
		}
	}

	printf("%d\n", min);
}

int comparaInicio(const void *a, const void *b) {


