int b_search(int low, int n, int chave, int soma[]) {
  int meio;
  while (low < n) {
    meio = low + (n - low)/2;
    if(soma[meio] >= chave) {
      n = meio;
    }
    else {
      low = meio + 1;
    }
  }
  if (soma[low] < chave) {
    return -1;
  }
  return (low);
}

int compare(int soma[],int x,int chave) {
  if (soma[x] == chave)
    return chave;
  else if (x==0)
    return soma[0];
  else {
    if (soma[x] - chave > chave - soma[x-1])
      return soma[x-1];
    else if (soma[x] - chave < chave - soma[x-1])
      return soma[x];
  }
  return 0;
}


