      aux[i++] = v[p2++];
  }
  while (p1<=mid){
    aux[i++] = v[p1++];                      // Adicionar o que resta
  }
  while (p2<=end){
    aux[i++] = v[p2++];

  }
  for (i=start; i<=end; i++){
    v[i] = aux[i];

  }

  return count;
}

