typedef struct {
  int i, f,tam;
} Segment;

int compare(const void *a, const void *b) {
  Segment *s1 = (Segment *)a;
  Segment *s2 = (Segment *)b;
  if (s1->i < s2->i) return -1;
  else  return +1;

}
int cobre(Segment v[],int tam,int n,int e,int last){
  if (e>=tam||last>n) return 0;
  int i=last;
  int m=0;
  while (i<n){
    if (v[i].i>e)break;
    if (v[i].f-e>m){m=v[i].f;last=i;}
    i++;
  }
  return 1+cobre(v,tam,n,m,last);
}     
int main(){
  int tam,n,i=0,c;
  scanf("%d%d",&tam,&n);
  Segment v[n];
  while(i<n){
    scanf("%d%d",&v[i].i,&v[i].f);
    v[i].tam=v[i].f-v[i].i;
    i++;
  }
  qsort(v,n,sizeof(Segment),compare);
  c=cobre(v,tam,n,0,0);
  printf("%d\n",c);
  return 0;
}

