// Exemplo de pesquisa em profundidade (DFS) num grafo nao dirigido

#include <stdio.h>

#define MAX 101      // Maximo numero de nos

int n;              // Numero de nos do grafo
char adj[MAX][MAX]; // Matriz de adjacencias
char visited[MAX];  // Que nos ja foram visitados?

void dfs(int v) {
  int i;
  // printf("%d ", v);
  visited[v] = 1;
  for(i=1;i<=n;i++)
    if(adj[v][i] && !visited[i]){
      dfs(i);
    }
}

int main() {
  int i, edges, a, b;
  int j,k;
  int contador=0;
  scanf("%d", &n);
  scanf("%d", &edges);
  if(edges==0)
    printf("%d\n",n);
  else{
    for(i=1;i<n+1;i++){
      visited[i]=0;
    }
    for(j=0;j<edges;j++) {
      scanf("%d %d", &a, &b);
      adj[a][b] = adj[b][a] = 1;
    }
    for(k=1;k<n+1;k++){
      if(!visited[k]){
	contador++;
	dfs(k);
      } // Pesquisa em profundidade a partir do no 1
    }
    printf("%d\n",contador);
  }

  // putchar('\n');
  return 0;
}

