#define MAX 1000


int subida(int piramide[MAX][MAX], int n){

	int i, j;
	for(i = n - 1; i >= 0; i--){
		for(j = 0; j < n; j++){

			if(piramide[i - 1][j] != 0){
				piramide[i - 1][j] = piramide[i][j] + piramide[i][j + 1];
			}
		}
	}
	return(piramide[0][0]);
}

