struct segment{
	long start, end, length;
};

int startsortcmp(const void *a, const void *b){ // sort by start point
	const struct segment *sa = a;
	const struct segment *sb = b;
	if (sa->start < sb->start)
		return -1;
	else if (sa->start > sb->start)
		return 1;
	else{ //if they start at the same point, put the longer segment firt
		if(sa->length > sb->length)
			return -1;
		else if (sa->length < sb->length)
			return 1;
	}
	return 0;
}

int countsegs(struct segment segments[], int m, int n){
	//printf("entered countsegs\n");
	int i = 0, k, count = 1, newseg = 0;
	bool newsegfound = false;

	while (i < m && segments[i].end<=n){ // while we still haven't found a segment that touches the end
		k = i;
		//printf("entered while loop, i=%d, k=%d, newseg=%d, count=%d\n",i,k,newseg,count);
		while (segments[k].start <= segments[i].end && k<=m){ // chose the possible next segment that reaches furthest
			if (segments[k].end > segments[newseg].end){
				newseg = k;
				newsegfound = true;
				//printf("Im stuck\n");
			}
			k++;
		}	

		if(newsegfound){
			count += 1;
			newsegfound = false;
			i = newseg; // i equals new segment chosen
		}
		else // if after the loop no other new segment was found then it's over
			break;
	}
	return count;
}

