long merge (int v[], int start, int med, int end) {
  int i,j,k;
  long inv = 0;
  i = start;
  j = med+1;
  k = 0;
  int tmp[end-start+1];
  while (i <= med && j <= end) {
    if (v[i] <= v[j]) {
      tmp[k] = v[i];
      k++;
      i++;
    }
    else {
      inv += (med - i + 1);
      tmp[k] = v[j];
      k++;
      j++;
    }
  }

  while (i <= med) {
    tmp[k] = v[i];
    k++;
    i++;
  }

  while (j <= end) {
    tmp[k] = v[j];
    k++;
    j++;
  }

  for (i = 0; i < k; i++) {
    v[i + start] = tmp[i];
  }
  return inv;
}

long mergesort (int v[], int start, int end) {
  int med = (start + end) / 2;
  if (start == end) return 0;
  long inv = 0;
  inv += mergesort (v, start, med);
  inv += mergesort (v, med+1, end);


  inv += merge (v, start, med, end);

  return inv;
}

