void swapV(int* a, int* b) {
    int aux;
    aux = *a;
    *a = *b;
    *b = aux;
}

int divide(int vec[], int esquerdo, int direito) {
    int i, j;

    i = esquerdo;
    for (j = esquerdo + 1; j <= direito; ++j) {
        if (vec[j] < vec[esquerdo]) {
            ++i;
            swapV(&vec[i], &vec[j]);
        }
    }
    swapV(&vec[esquerdo], &vec[i]);

    return i;
}

void qqsort(int vec[], int esquerdo, int direito)
{
    int r;

    if (direito > esquerdo) {
        r = divide(vec, esquerdo, direito);
        qqsort(vec, esquerdo, r - 1);
        qqsort(vec, r + 1, direito);
    }
}

