int binsearch(int list[], int lo, int hi, int key)
{
    int mid;

    mid = (lo + hi) / 2;

    while(list[mid+1] == list[mid])
      mid++;

    if (list[mid] <= key && list[mid+1] > key)
      {
	if(mid==0)
	  return list[1];

	int a = key-list[mid]; //distancia pra tras
	int b = list[mid+1] - key; // distancia pra frente

	if(a>b) 
	  return list[mid+1];
	if(b>a)
	  return list[mid];
	else
	{
	  printf("%d ", list[mid]);
	  return list[mid+1];
	}
      }

    else if (list[mid] > key)
      return binsearch(list, lo, mid - 1, key);

    else if (list[mid] < key)
      return binsearch(list, mid + 1, hi, key);

    return -1;
}

