long long mergesort(int v[], int start, int end) {

	int inv = 0;

	int middle = (start+end)/2;

	if (start == end)
		return 0;

	inv += mergesort(v, start, middle);
	inv += mergesort(v, middle+1, end);
	inv += merge(v, start, middle, end);

	return inv;
}

long long merge(int v[], int start, int middle, int end) {

	int ve[(end-start+1)];
	int i, inv=0;
	int a=start, b=middle+1, k=0;


		while (a <= middle && b <= end) {
			if (v[a] <= v[b])
				ve[k++] = v[a++];

			else {
				ve[k++] = v[b++];
				inv += middle - a + 1 ;
//				printf("INV: %lld | MID: %lld | A: %lld\n", inv, middle, a);
			}
		}

		while (a <= middle)
			ve[k++] = v[a++];

		while (b <= end)
			ve[k++] = v[b++];


	for (i=0 ; i<k ; i++)
		v[i+start] = ve[i];

	return inv;
}

