void merge (int v[], int start, int middle,int end){
  int aux_size=end-start+1;
  int aux[aux_size];
  int a=start,b=middle+1,i;

  for(i=0;i<aux_size; i++){
    if(a>middle){
      aux[i]=v[b];
      b++;
    }
    else if (b>end){
      aux[i]=v[a];
      a++;
    }
    else if (v[b]>v[a]){
      aux[i]=v[a];
      a++;
    }
    else{
      aux[i]=v[b];
      b++;
    }
  }
  for(i=0, a=start; i<aux_size; i++,a++){
    v[a]=aux[i];
  }
}

