      if(b>a)
	return list[mid];

      else
	{
	  printf("%d ", list[mid]);
	  return list[mid+1];
	}



    }

    else if (list[mid] > key)
        return binsearch(list, lo, mid - 1, key);

    else if (list[mid] < key)
