void bubbleSort(int* a, int s)
{
    int last_index;
    int i;

    do
    {
        last_index = 0;

        for(i = 1; i <= s - 1; i++)
        {
            if(a[i-1] > a[i])
            {
                int tmp = a[i-1];
                a[i-1] = a[i];
                a[i] = tmp;
                last_index = i;
            }
        }

        s = last_index;

    } while(last_index > 0);
}

