int calcular(int mat[MAX][MAX], int n){
	int i, j;

	for(i=n-1; i>=1; i--){
		for(j=1; j<=i; j++){
			mat[i][j] = mat[i][j] + max(mat[i+1][j], mat[i+1][j+1]);
