int search(int key, int ini, int end) {
	int i=0;
	int j;
	int mid, val, flag;

	while (ini<=end) {
		mid = (end- ini)/2 + ini;
		val = best[0]-key;
		if (val<0)
			val = val * -1;
		if (pares[mid] == key) {
			best[0] = pares[mid];
			return 0;
		}
		else if (pares[mid]>key) {
			if ((pares[mid] - key) == val && best[0] != pares[0]) {
				i++;
				flag = 0;
				for (j=0; j < i && flag == 0; j++) {
					if (best[j] == pares[mid]) {
						flag = 1;
						i--;
					}
					else if (best[j] > pares[mid]) {
						best[j+1] = best[j];
						best[j] = pares[mid];
					}
					else
						best[i] = pares[mid];
				}
			}
			else if ((pares[mid]-key) < val) {
				best[0] = pares[mid];
				i=0;
			}
			end = mid-1;
		}
		else {
			if ((key - pares[mid]) == val && best[0] != pares[0]) {
				i++;
				flag = 0;
				for (j=0; j<i && flag == 0; j++) {
					if (best[j] == pares[mid]) {
						flag = 1;
						i--;
					}
					else if (best[j] > pares[mid]) {
						best[j+1] = best[j];
						best[j] = pares[mid];
					}
					else
						best[i] = pares[mid];
				}
			}
			else if ((key - pares[mid]) < val) {
				best[0] = pares[mid];
				i=0;
			}
			ini = mid+1;
		}
	}
	return i;
}

