long long merge(int v[],int start,int middle,int end){

  int i,m,k,l,temp[end+1];

  l=start;
  i=start;
  m=middle+1;
  long long troca=0;

  while((l<=middle)&&(m<=end)){

    if(v[l]<=v[m]){
      temp[i]=v[l];
      l++;
    }
    else{
      temp[i]=v[m];
      m++;
 troca += middle+1-l;
    }
    i++;
  }

  if(l>middle){
    for(k=m;k<=end;k++){
      temp[i]=v[k];
      i++;
    }
  }
  else{
    for(k=l;k<=middle;k++){
      temp[i]=v[k];
      i++;
    }
  }

  for(k=start;k<=end;k++){
    v[k]=temp[k];
  }
  return troca;
}

