int binsearch(int low, int high,int key){
  int mid;
  while(low < high){
    mid=low+(high-low)/2;
    if(sum[mid]==key) return mid;
    if(sum[mid]>key) high=mid;
    else low=mid+1;
  }
  if(sum[low]<key) return(-1);
  return(low);
}

