void mergesort(int a[], int low, int high)
{

  if (low < high) 
    {
      int m = (high + low)/2;
      mergesort(a, low, m);
      mergesort(a, m + 1, high);
      merge(a, low, m, high);
    }

}

void merge(int a[], int low, int mid, int high)
{
    int b[MAX];
    int i = low, j = mid + 1, k = 0;

    while (i <= mid && j <= high) {
        if (a[i] <= a[j])
            b[k++] = a[i++];
        else
            b[k++] = a[j++];
    }
    while (i <= mid)
        b[k++] = a[i++];

    while (j <= high)
        b[k++] = a[j++];

    k--;
    while (k >= 0) {
        a[low + k] = b[k];
        k--;
    }
}

