void merge(int v[],int start,int middle, int end){
  int k[(end-start)+1],j=0;
  int left = start;
  int rigth=middle+1;

  while(rigth<=end && left<=middle){
    if(v[left]<=v[rigth]){
      k[j]=v[left];
      left++;
    }
    else{
      k[j]=v[rigth];
      rigth++;
    }
    j++;
  }

  while(left<=middle){
    k[j]=v[left];
    j++;
    left++;
      }
  while(rigth<=end){
    k[j]=v[rigth];
    j++;
    rigth++;
  }

  for(j=0;j<end-start+1;j++){
    v[start+j]=k[j];
  }


}



void mergesort(int v[],int start,int end){
  int middle =(start+end)/2;
  if(start==end) return;
  mergesort(v,start,middle);
  mergesort(v,middle+1,end);
  merge(v,start,middle,end);

}

