int computeInvertions(int*, int);
int mergeSort(int*, int, int);
int merge(int*, int, int, int);

int main()
{
    int size;           /* hold array size */
    int* array;         /* input sequence */
    int num_inversions; /* holds result */
    int i;              /* iterator */

    num_inversions = 0;

    scanf("%d", &size);

    array = (int*) malloc(size * sizeof(int));

    // read to array
    for(i = 0; i < size; i++)
    {
        scanf("%d", &array[i]);
    }

    num_inversions = computeInvertions(array, size);

    // print array
    printf("%d\n", num_inversions);

    return 0;
}

int computeInvertions(int* a, int s)
{
    return mergeSort(a, 0, s);
}

int mergeSort(int* a, int start, int end)
{
    int middle;
    int num_inversions;

    num_inversions = 0;

    if(end > start)
    {
        middle = (start+end)/2;

        num_inversions += mergeSort(a, start, middle);
        num_inversions += mergeSort(a, middle+1, end);
        num_inversions += merge(a, start, middle, end);
    }

    return num_inversions;
}

int merge(int* a, int p_left, int middle, int p_right)
{
    int i, j, k;
    int num_inversions;
    int* tmp;

    i = k = p_left;
    j = middle + 1;
    num_inversions = 0;
    tmp = (int*) malloc(sizeof(int) * (p_right - p_left + 1));

    while((i <= middle) && (j <= p_right))
    {
        if(a[i] <= a[j])
        {
            tmp[k] = a[i];
            i = i + 1;            
        }
        else
        {
            tmp[k] = a[j];            
            j = j + 1;
            num_inversions = num_inversions + (middle - i);
        }

        k = k + 1;
    }

    while(i <= middle)
    {
        tmp[k] = tmp[i];
        k++;
        i++;
    }

    while(j <= p_right)
    {
        tmp[k] = tmp[i];
        k++;
        i++;
    }

    for(i = p_left; i < p_right; i++)
    {
        a[i] = tmp[i];
    }

    return num_inversions;
}

