int search(int sum[], int low, int high, int val){

  while(low < high){
    int mid = low + (high - low) / 2;

    if(sum[mid] == val)
      return mid;

    if(sum[mid] > val)
      high = mid;

    else
      low = mid + 1;
  }
  if(sum[low] < val)
    return -1;
  return low;
}


