#define MAX 1000000

int merge(int v[], int start, int middle, int end);
int mergesort(int v[], int start, int end);

int main () {
	int n, i, v[MAX];

	scanf("%d", &n);

	for (i=0; i<n; i++)
		scanf("%d", &v[i]);

	printf("%d\n", 	mergesort(v, 0, n-1));

	return 0;
}

int mergesort(int v[], int start, int end) {

	int inv = 0;

	int middle = (start+end)/2;

	if (start == end)
		return 0;

	inv = 0;
	inv = mergesort(v, start, middle);
	inv += mergesort(v, middle+1, end);
	inv += merge(v, start, middle, end);

	return inv-1;
}

int merge(int v[], int start, int middle, int end) {

	int ve[MAX];
	int i, inv_count=0;
	int a=start, b=middle+1, k=0;


		while (a <= middle && b <= end) {
			if (v[a] < v[b])
				ve[k++] = v[a++];

			else
				ve[k++] = v[b++];
				inv_count += b-1;
		}

		while (a <= middle)
			ve[k++] = v[a++];

		while (b <= end)
			ve[k++] = v[b++];


	for (i=0 ; i<k ; i++)
		v[i+start] = ve[i];

	return inv_count;
}

