  //printf("bsearch\n");
  int middle;
  while (low < high){
    middle = low + (high-low)/2;
    add(v[middle],query);
    //printf("middle: %d\n",middle);
    if(v[middle] == query){
      //printf("v[%d] == query\n",middle);
      add(query,query);
      return;
    }
    else if(v[middle] < query){
      low = middle + 1;
      //printf("v[%d] (low)\n",low);
      add(v[low],query);
    }
    else{
      high = middle;
      //printf("v[%d] (high)\n",high);
      add(v[high],query);
    }
  }
  //printf("--bsearch--\n");
}

