int cmp(const void *a, const void *b){
	const struct shoe *sa = a;
	const struct shoe *sb = b;
	double x = (double) sa->fine/sa->duration;
	double y = (double) sb->fine/sb->duration;

	if (x>y)
		return -1;
	else if(x<y)
		return 1;
	return 1;
}

