#include <stdio.h>
#include <stdlib.h>

int computeInvertions(int*, int);
int mergeSort(int*, int, int);
int merge(int*, int, int, int);

int main()
{
    int size;           /* hold array size */
    int* array;         /* input sequence */
    int num_inversions; /* holds result */
    int i;              /* iterator */

    num_inversions = 0;

    scanf("%d", &size);

    array = (int*) malloc(size * sizeof(int));

    // read to array
    for(i = 0; i < size; i++)
    {
        scanf("%d", &array[i]);
    }

    num_inversions = computeInvertions(array, size);

    // print array
    printf("%d\n", num_inversions);

    return 0;
}

int computeInvertions(int* a, int s)
{
    return mergeSort(a, 0, s);
}

int mergeSort(int* a, int start, int end)
{
    int middle;
    int num_inversions;

    num_inversions = 0;

    if(end > start)
    {
        middle = (start+end)/2;

        num_inversions += mergeSort(a, start, middle);
        num_inversions += mergeSort(a, middle+1, end);
        num_inversions += merge(a, start, middle, end);
    }

    return num_inversions;
}

int merge(int* a, int start, int middle, int end)
{
    int p_left, p_right, k;     /* iterators */
    int num_inversions;         /* holds result */
    int* tmp;                   /* auxiliary array to store sorted values */

    p_left  = start;
    p_right = middle + 1;
    k = start;    
    num_inversions = 0;
    tmp = (int*) malloc(sizeof(int) * (end - start + 1));

    while(p_left <= middle && p_right <= end)
    {
        if(a[p_left] <= a[p_right])
        {
            tmp[k] = a[p_left];
            p_left = p_left + 1;            
        }
        else
        {
            tmp[k] = a[p_right];            
            p_right = p_right + 1;

            // magic trick :)
            num_inversions = num_inversions + (middle - p_left);
        }

        k = k + 1;
    }

    // Copy the remaining elements of left sub-array
    while(p_left <= middle)
    {
        tmp[k] = tmp[p_left];
        k++;
        p_left++;
    }

    // Copy the remaining elements of right sub-array
    while(p_right <= end)
    {
        tmp[k] = tmp[p_left];
        k++;
        p_left++;
    }

    // Copy back the merged elements to original array
    for(k = start; k < end; k++)
    {
        a[k] = tmp[k];
    }

    return num_inversions;
}

