void merge(int v[],int start,int middle,int end){
  int i,p1,p2,aux[100000];
  p1=start;
  p2=middle+1;
  i=start;
  while(p1<=middle && p2<=end){
    if(v[p1]<=v[p2])
      aux[i++]=v[p1++];

    else
      aux[i++]=v[p2++];
  }
  while(p1<=middle)
    aux[i++]=v[p1++];

  while(p2<=end)
    aux[i++]=v[p2++];

  for(i=start;i<=end;i++)
    v[i]=aux[i];
}

void mergesort(int v[],int start,int end){
  int middle;
  if(start<end){
    middle=(start+end)/2;
    mergesort(v,start,middle);
    mergesort(v,middle+1,end);
    merge(v,start,middle,end);
  }
}

