long inv;

void merge(int v[], int s, int m, int e){
  int tam=e-s+1;
  int a[tam];
  int j=s,k=m,i=0, p;

  while(j<m &&k<=e){
    if(v[j]<=v[k])
      a[i]=v[j++];
    else {
      inv += m-j;
      a[i]=v[k++];      
    }
    i++;
  }


  while(j<m)
    a[i++]=v[j++];
  while(k<=e)
    a[i++]=v[k++];
  for(p=0;p<tam;p++)
    v[p+s]=a[p];

}
