void soma (int n){

	for (i = 0; i < n; ++i)
	{
		for (j = i; j < n-1; ++j)
		{
			somas[k]= numeros[i] + numeros[j+1];
			k++;
		}
	}
}

void merge(int inicio, int metade, int fim) {
   int a=inicio, b=metade+1, i;

   for(i = inicio; a <= metade && b <= fim; i++) {
      if(somas[a] <= somas[b])
         temp[i] = somas[a++];
      else
         temp[i] = somas[b++];
   }

   while(a <= metade)    
      temp[i++] = somas[a++];

   while(b <= fim)   
      temp[i++] = somas[b++];

   for(i = inicio; i <= fim; i++)
      somas[i] = temp[i];
}

void sort(int inicio, int fim) {
   int metade;

   if(inicio < fim) {
      metade = (inicio + fim) / 2;
      sort(inicio, metade);
      sort(metade+1, fim);
      merge(inicio, metade, fim);
   } else { 
      return;
   }   
}


int bsearch (int inicio, int fim, int b){
	int metade;
	while (inicio < fim){
		metade = inicio + (fim - inicio)/2;
		if(somas[metade] == b){
			return metade;
		}
		if (somas[metade] < b){
				inicio = metade;
		}
		if (somas[metade] > b){
				fim = metade;
		}
	}
	return metade;


}

