#include <stdio.h>

void quickSort (int *a, int n) {
   	if (n < 2)
    return;
    int p = a[n / 2];
    int *l = a;
    int *r = a + n - 1;
    while (l <= r) {
        if (*l < p) {
            l++;
        }
        else if (*r > p) {
            r--;
        }
        else {
            int t = *l;
            *l = *r;
            *r = t;
            l++;
            r--;
        }
    }
    quickSort(a, r - a + 1);
    quickSort(l, a + n - l);
}

