void merge(int inicio, int metade, int fim) {
   int a=inicio, b=metade+1, i;

   for(i = inicio; a <= metade && b <= fim; i++) {
      if(somas[a] <= somas[b])
         temp[i] = somas[a++];
      else
         temp[i] = somas[b++];
   }

   while(a <= metade)    
      temp[i++] = somas[a++];

   while(b <= fim)   
      temp[i++] = somas[b++];

   for(i = inicio; i <= fim; i++)
      somas[i] = temp[i];
}

