void pesquisa_binaria( int m,int M,int somaproxima[],int x,int pergunta[]){
  int inferior=m;
  int superior=M;
  int meio;

  while(inferior<=superior){
    meio= (superior + inferior)/2;

    if(somaproxima[meio]>=pergunta[x])
      superior=meio - 1;
    else
      inferior=meio + 1;
  }

  int d1=abs(somaproxima[inferior] - pergunta[x]);
  int d2=abs(somaproxima[inferior-1] - pergunta[x]);
  if(d1==d2)
    printf("%d %d\n",somaproxima[inferior-1] , somaproxima[inferior]);
  else if(d1<d2)
    printf("%d\n",somaproxima[inferior]);
  else 
    printf("%d\n",somaproxima[inferior-1]);

}

