		v[i].ratio = v[i].dias/v[i].multa;
		v[i].i=i+1;
	}

	// Chamada ao sort padrao da linguagem C
  	// qsort(array, quantidade_elementos, tamanho_um_elemento, funcao_comparar)
  	qsort(v, n, sizeof(Sapateiro), compareSapateiro);	

  	for (i=0;i<n;i++){
		printf("%d ",v[i].i);
	}
	printf("\n");





