// Tipo para guardar uma encomenda
typedef struct {
  int indice;  //valor do indice da encomenda
  int duracao;
  int multa;
  float racio;
} Encomenda;

// Funcao para comparar dois elementos de um array (necessaria para o qsort)
// Esta funcao deve devolver:
//  - numero < 0 se elemento "a" for menor que elemento "b"
//  - numero > 0 se elemento "a" for maior que elemento "b"
//  - zero, se elemento "a" for igual ao elemento "b"
int compareEncomenda(const void *a, const void *b) {
  Encomenda *p1 = (Encomenda *)a;
  Encomenda *p2 = (Encomenda *)b;

  if (p1->racio < p2->racio)
    return -1;
  if (p1->racio > p2->racio)
    return +1;

  return 0;
}

int main() {

  int i, N;

  // Ler N encomendas
  scanf("%d", &N);

  Encomenda Ni[N];

  for (i=0; i<N; i++){
    scanf("%d %d", &Ni[i].duracao, &Ni[i].multa);
    Ni[i].indice = i+1;
    Ni[i].racio = (float)Ni[i].duracao/Ni[i].multa;

    // Chamada ao sort padrao da linguagem C
    // qsort(array, quantidade_elementos, tamanho_um_elemento, funcao_comparar)
    qsort(Ni, N, sizeof(Encomenda), compareEncomenda);
  }

  printf("%d", Ni[0].indice);
  for (i=1; i<N; i++){
    printf(" %d", Ni[i].indice);
  }

  putchar('\n');

  return 0;
}

