void calcways(int pyramid[n][n], int a){
	int b;
	for (b=0; b<=a; b++){
		if (pyramid[a][b] != -1){
			if (pyramid[a+1][b] == -1 && pyramid[a+1][b+1] == -1) //if both chambers bellow are obstructed
				pyramid[a][b] = -1;
			else if (pyramid[a+1][b] == -1) //if downleft chamber is obstructed
				pyramid[a][b] = pyramid[a+1][b+1];
			else if (pyramid[a+1][b+1] == -1) //if downright chamber is obstructed
				pyramid[a][b] = pyramid[a+1][b];
			else
				pyramid[a][b] = pyramid[a+1][b] + pyramid[a+1][b+1];
		}
	}
}

