void mergesort(int v[], int start, int end) {
  int middle;

  if(start<end){
    middle=(start+end)/2;
mergesort(v, start, middle);
mergesort(v, middle+1, end);
merge(v, start, middle, end);
  }
}

void merge(int v[],int start,int middle,int end){

    int i,m,k,l,temp[MAX];

    l=start;
    i=start;
    m=middle+1;

    while((l<=middle)&&(m<=end)){

         if(v[l]<=v[m]){
             temp[i]=v[l];
             l++;
         }
         else{
             temp[i]=v[m];
             m++;
         }
         i++;
    }

    if(l>middle){
         for(k=m;k<=end;k++){
             temp[i]=v[k];
             i++;
         }
    }
    else{
         for(k=l;k<=middle;k++){
             temp[i]=v[k];
             i++;
         }
    }

    for(k=start;k<=end;k++){
         v[k]=temp[k];
    }
}

