int pesquisaBinaria(int sum[], int low, int high, int key){
  int med = 0; //caso especifico em que o array somas so tem um elemento

  while (low < high) {
    med = low + (high - low)/2;
    //printf("\n%d\n", med);
    if (sum[med] == key) return key;
    if (sum[med] > key)
      high = med;
    else low = med + 1;

  }
  //printf("low->>>>%d\n",low);
  med = low;

  if (med > 0){
    if (key - sum[med-1] == sum[med] - key){
      printf("%d ",sum[med-1]);
      return sum[med];
    }
    else if (key - sum[med-1] < sum[med] - key)
      return sum[med-1];
    else if (sum[med] - key < key - sum[med-1])
      return sum[med];
  }

  return sum[med];

}

