typedef struct{
  int l;
  int r;
} seg;

int greedy(seg v[], int m, int i, int end){
  int best=0, besti;
  end = v[i].r;
  if(end>=m)
    return 1;
  i++;
  while(v[i].l <= end){
    if(v[i].r >= best){
      best = v[i].r;
      besti=i;
    }
    i++;
  }
  return 1+greedy(v,m,besti,end);
}

int comparel(const void *a, const void *b){
  seg *s1 = (seg *)a;
  seg *s2 = (seg *)b;

  if (s1->l < s2->l) return -1;
  else if (s1->l > s2->l) return +1;
  else if (s1->r > s2->r) return -1;
  return +1;
}

