typedef struct {
  int duracao;
  int multa;
  float racio;
  int posicao;
} Encomenda;

int compare(const void *a, const void *b) {
  Encomenda *s1 = (Encomenda *)a;
  Encomenda *s2 = (Encomenda *)b;
  if (s1->racio > s2->racio) return -1;
  else if(s1->racio==s2->racio){
    if(s1->posicao<s2->posicao)return -1;
    else return 1;
  }
  else  return +1;
}
int main(){
  int n,i=0;
  scanf("%d",&n);
  Encomenda s[n];
  while(i<n){
    scanf("%d%d",&s[i].duracao,&s[i].multa);
    s[i].racio=(float)s[i].multa/s[i].duracao;
    s[i].posicao=i+1;
    i++;
  }
  i=0;
  qsort(s,n,sizeof(Encomenda),compare);
  while (i<n){
    if(i!=n-1)printf("%d ",s[i].posicao);else printf("%d\n",s[i].posicao);
    i++;
  }
  return 0;
}

