typedef struct{
  int esq, dir;
} segmento;

int comp(const void *s1, const void *s2) {

  segmento *f = (segmento*)s1;
  segmento *s = (segmento*)s2;

  if( f->esq > s->esq ) return  1;
  if( f->esq < s->esq ) return -1;
  if( f->dir > s->dir ) return 1;
  if( f->dir < s->dir ) return -1;

  return 0;
}

