int v[MAX], w[MAX], somas[999000], value1, value2;

void mergeSort(int *vetor, int posicaoInicio, int posicaoFim) {
    int i, j, k, metadeTamanho, *vetorTemp;

    if(posicaoInicio == posicaoFim) 
    	return;

    metadeTamanho = (posicaoInicio + posicaoFim ) / 2;
    mergeSort(vetor, posicaoInicio, metadeTamanho);
    mergeSort(vetor, metadeTamanho + 1, posicaoFim);

    i = posicaoInicio;
    j = metadeTamanho + 1;
    k = 0;
    vetorTemp = (int *) malloc(sizeof(int) * (posicaoFim - posicaoInicio + 1));

    while(i < metadeTamanho + 1 || j  < posicaoFim + 1) {
        if (i == metadeTamanho + 1 ) { 
            vetorTemp[k] = vetor[j];
            j++;
            k++;
        }
        else {
            if (j == posicaoFim + 1) { 
                vetorTemp[k] = vetor[i];
                i++;
                k++;
            }
            else {
                if (vetor[i] < vetor[j]) {
                    vetorTemp[k] = vetor[i];
                    i++;
                    k++;
                }
                else {
                    vetorTemp[k] = vetor[j];
                    j++;
                    k++;
                }
            }
        }

    }
    for(i = posicaoInicio; i <= posicaoFim; i++) {
        vetor[i] = vetorTemp[i - posicaoInicio];
    }
    free(vetorTemp);
}

int PesquisaBinaria ( int vet[], int chave, int Tam)
{
     int inf = 0;    
     int sup = Tam-1; 
     int meio;
     while (inf <= sup)
     {
          meio = (inf + sup)/2;
          if (chave == vet[meio])
               return vet[meio];
          if (chave < vet[meio])
               sup = meio-1;
          else
               inf = meio+1;
     }
     if ( (vet[sup]-chave) == (chave-vet[inf]) ){
     	value1=vet[sup];
     	value2=vet[inf];
     	return -1;
     }
     else if ( sup < inf && (chave-vet[sup]) < (vet[inf])-chave ){
     	value1=vet[sup];
     	return -2;
     }
     else if ( sup < inf && (chave-vet[sup]) > (vet[inf])-chave ){
     	value1=vet[inf];
     	return -2;
     }
     return -2;
}

