void func(int a, int b,int j,struct grafo *g,int contador,int L)
{
  int i;
  for (i=0;i<=L;i++) {

    if ((a==g[i].inicio)&&(g[i].visitado==0)){
      contador++;
      g[i].visitado=1;
      if (contador==1)	{ g[i].first=1; }
      a=g[i].inicio;
      b=g[i].fim;
      func (a,b,i,g,contador,L);
    }
    if ((a==g[i].fim)&&(g[i].visitado==0)){
      contador++;
      g[i].visitado=1;
      if (contador==1)	{g[i].first=1;}
      a=g[i].fim;
      b=g[i].inicio;
      func (a,b,i,g,contador,L);
    }
    if ((b==g[i].inicio)&&(g[i].visitado==0)){
      contador++;
      g[i].visitado=1;
      if (contador==1)	{g[i].first=1;}
      a=g[i].inicio;
      b=g[i].fim;
      func (a,b,i,g,contador,L);
    }
    if ((b==g[i].fim)&&(g[i].visitado==0)){
      contador++;
      g[i].visitado=1;
      if (contador==1)	{g[i].first=1;}
      a=g[i].fim;
      b=g[i].inicio;
