typedef struct {
  int inicio,fim;
} Segmento;

int mincover(Segmento v[],int end,int m,int n){
  int count=0,i,start=0,best_end=0;
  while(end<m){
    for(i=start;v[i].inicio<=end;i++){
      if(v[i].inicio<=end)
	if(v[i].fim>best_end)
	  best_end=v[i].fim;     
    }
    start=i;
    end=best_end;
    count++;
  } 
  return count;
}

int compareInicio(const void *a, const void *b){
  Segmento *p1 = (Segmento *)a;
  Segmento *p2 = (Segmento *)b;
  if(p1->inicio < p2->inicio) return -1;
  if(p1->inicio > p2->inicio) return +1;
  return 0;
}

