void merge(int a[], int low, int mid, int high)
{
  int b[100000];
  int i = low, j = mid + 1, k = 0;

  while (i <= mid && j <= high) {
    if (a[i] <= a[j])
      b[k++] = a[i++];
    else
      b[k++] = a[j++];
  }
  while (i <= mid)
    b[k++] = a[i++];

  while (j <= high)
    b[k++] = a[j++];

  k--;
  while (k >= 0) {
    a[low + k] = b[k];
    k--;
  }
}

