#define MAX_N 1001

typedef struct {
  int inicio,fim,tamanho;
} Segmento;

int mincover(Segmento v[],int end,int m,int n){
  int count=0,i;
  while(end<m){
    int best_tam=0,best_i=-1;
    for(i=0;i<n;i++){
      if(v[i].inicio==end && v[i].tamanho > best_tam){
	best_i=i;
	best_tam=v[i].tamanho;
      }
    }
    if(best_i!=-1){
      end=v[best_i].fim;
      count++;
    }
    else
      end++;
  }
  return count;
}

int compareInicio(const void *a, const void *b){
  Segmento *p1 = (Segmento *)a;
  Segmento *p2 = (Segmento *)b;
  if(p1->inicio < p2->inicio) return -1;
  if(p1->inicio > p2->inicio) return +1;
  return 0;
}

