void merge(int v[], int start, int mid, int end)
{
    int u[100000];
    int i = start, j = mid + 1, k = 0;

    while (i <= mid && j <= end) {
        if (v[i] <= v[j])
            u[k++] = v[i++];
        else
            u[k++] = v[j++];
    }
    while (i <= mid)
        u[k++] = v[i++];

    while (j <= end)
        u[k++] = v[j++];

    k--;
    while (k >= 0) {
        v[start + k] = u[k];
        k--;
    }
}

