#define MAX 1001

int pir[MAX][MAX];
long long pir_paths[MAX][MAX];

void make_pir(int n){
	int i, j;
	for(i = 0; i < n; i++)
		for(j = 0; j <= i; j++){
			pir[i][j] = 1;
			pir_paths[i][j] = 1;
		}
}

void destroy_pir(int n, int level, int position){
	pir[n-level][position-1] = 0;
	pir_paths[n-level][position-1] = 0;
}

void compute_paths(int n){
	int i, j;
	for(i = n - 2; i >= 0; i--){
		for(j = 0; j <= i; j++){
			if(pir[i][j] != 0){
				pir_paths[i][j] = pir_paths[i+1][j] + pir_paths[i+1][j+1];
			}
			else
				pir_paths[i][j] = 0;
		}
	}
}

int main(){
	int n, d;
	int temp1, temp2;
	int i;
