int bubblesort(int v[], int n){
  int trocas=0, tmp=0;
  int i;

  do{
    int last_pos=0;
    for (i = 1; i < n; i++){

      if (v[i-1] > v[i]){
	trocas++;
	tmp = v[i-1];
	v[i-1] = v[i];
	v[i] = tmp;
	last_pos=i;
      }  
    }
    n=last_pos;
  }while(n>0);

  return trocas;
}

