#include <stdio.h>

void merge (int v[], int s, int m, int e) {
  int tmp[e-s+1], i, j, c;
  for (c = 0, i = s, j = m+1; c <= e-s; c++) {
    if (j > e)
      tmp[c] = v[i++];
    else if (i > m)
      tmp[c] = v[j++];
    else if (v[i] < v[j])
      tmp[c] = v[i++];
    else
      tmp[c] = v[j++];
  }

  for (c = 0; c <= e-s; c++)
    v[s+c] = tmp[c];
}

void mergesort(int v[], int start, int end) {
  int middle = (start+end)/2;
  if (end-start) {
    mergesort(v, start, middle);
    mergesort(v, middle+1, end);
    merge(v, start, middle, end);
  }
}

