#include <stdio.h>

void quicksort2(int a[][2], int firstIndex, int lastIndex)
{

  int pivot, temp, index1, index2, temp2;

    if(firstIndex < lastIndex)
    {

        pivot = firstIndex;
        index1 = firstIndex;
        index2 = lastIndex;

        //Sorting in Ascending order with quick sort
        while(index1 < index2)
        {
            while(a[index1][0] <= a[pivot][0] && index1 < lastIndex)
            {
                index1++;
            }
            while(a[index2][0] > a[pivot][0])
            {
                index2--;
            }

            if(index1 < index2)
            {
                //Swapping
                temp = a[index1][0];
				temp2 = a[index1][1];
                a[index1][0] = a[index2][0];
				a[index1][1] = a[index2][1];
                a[index2][0] = temp;
                a[index2][1] = temp2;		
            }
        }


        temp = a[pivot][0];
		temp2 = a[pivot][1];
        a[pivot][0] = a[index2][0];
		a[pivot][1] = a[index2][1];
        a[index2][0] = temp;
		a[index2][1] = temp2;


        quicksort2(a, firstIndex, index2-1);
        quicksort2(a, index2+1, lastIndex);
    }
}


