#include <stdio.h>

void merge(int v[],int w[], int start, int middle, int end){
  int pe, pd, paux, aux[end-start+1],aux2[end-start+1],paux2;

  pe = start;
  pd = middle+1;
  paux = 0;
  paux2=0;

  while (pe <= middle && pd<=end) {
    if (v[pe] < v[pd]) {
      aux[paux] = v[pe];
      aux2[paux2]=w[pe];
      paux++;
      paux2++;
      pe++;
    } 
    else {
      aux[paux] = v[pd];
      aux2[paux2] = w[pd];
      paux++;
      paux2++;
      pd++;
    }
  }

  // copiar o resto

  while(pe<=middle){
    aux[paux]=v[pe];
    aux2[paux2]=w[pe];
    paux++;
    paux2++;
    pe++;
  }

  while(pd<=end){
    aux[paux]=v[pd];
    aux2[paux2]=w[pd];
    paux2++;
    paux++;
    pd++;
  }

  // copiar aux para v

  int i;
  for(i=start;i<=end;i++){
    v[i]=aux[i-start];
    w[i]=aux2[i-start];
  }
}


void mergesort(int v[],int w[], int start, int end){
  int middle=(start+end)/2;
  if (start<end){
    mergesort(v,w,start,middle);
    mergesort(v,w,middle+1,end);
    merge(v,w,start,middle,end);
  }
}

