int twoSum(int *v, int bot, int top, int target)
{
	if(bot == top) return closest;
	int sum;
	sum = v[top] + v[bot];
	minDiff = abs(closest - target);
	newDiff = abs(sum - target);	
	if(newDiff == minDiff)
	{
