int merge(int vec[], int vecSize) {
  int mid;
  int i, j, k;
  int* tmp;
  int counter = 1;

  tmp = (int*) malloc(vecSize * sizeof(int));

  mid = vecSize / 2;

  i = 0;
  j = mid;
  k = 0;
  while (i < mid && j < vecSize) {
    if (vec[i] <= vec[j]) {
      tmp[k] = vec[i++];
    }
    else {
      tmp[k] = vec[j++];
    }
    ++k;
    counter++;
  }

  if (i == mid) {
    while (j < vecSize) {
      tmp[k++] = vec[j++];
    }
  }
  else {
    while (i < mid) {
      tmp[k++] = vec[i++];

    }
  }

  for (i = 0; i < vecSize; ++i) {
    vec[i] = tmp[i];
  }
  free(tmp); 
  return counter;
}

int mergeSort(int vec[], int vecSize) {
  int mid;
  int counter = 0;

  if (vecSize > 1) {
    mid = vecSize / 2;
    counter =  counter + mergeSort(vec, mid);
    counter =  counter + mergeSort(vec + mid, vecSize - mid);
    counter =  counter + merge(vec, vecSize);
  }

  return counter;
}

