		if ( part == 0 )
			return 0;
		if ( val < v[i])
			return 0;
		acum = acum + v[i];
		if ( acum > val ){
			acum = v[i];
			check++;
		}
		if ( check == part )
			return 0;
	}
	return 1;
}

