/**
 * Returns the number of inversions of the given array.
 */
int computeInvertions(int* a, int s)
{
    return mergeSort(a, 0, s-1);
}

/**
 * Sorts the given array.
 * @param a     - array to sort
 * @param start - first position
 * @param end   - last position
 * @return returns the number of inversions on the array
 */
int mergeSort(int* a, int start, int end)
{
    int middle;
    int num_inversions;

    num_inversions = 0;

    if(end > start)
    {
        middle = (start+end)/2;

        num_inversions += mergeSort(a, start, middle);
        num_inversions += mergeSort(a, middle+1, end);
        num_inversions += merge(a, start, middle, end);
    }

    return num_inversions;
}

/**
 * Merges two sorted arrays;  
 * @return returns the inversions count in the arrays.
 */
int merge(int* a, int start, int middle, int end)
{
    int p_left, p_right, k;     /* iterators */
    int num_inversions;         /* holds result */
    int* tmp;                   /* auxiliary array to store sorted values */
    //int i;

    //for (i=start; i<=end; i++) printf("%d ", a[i]);
    //printf("\n");


    p_left         = start;
    p_right        = middle + 1;
    k              = 0;    
    num_inversions = 0;
    //printf("malloc %d %d %d\n", end, start, end-start+1);
    tmp            = (int*) malloc(sizeof(int) * (end - start + 1));

    while(p_left <= middle && p_right <= end)
    {
        if(a[p_left] <= a[p_right])
        {            
            tmp[k] = a[p_left];            
            p_left = p_left + 1;            
        }
        else
        {
            tmp[k]  = a[p_right];            
            p_right = p_right + 1;

            // magic trick
            num_inversions = num_inversions + (middle - p_left+1);
        }

        k = k + 1;
    }

    // Copy the remaining elements of left sub-array
    while(p_left <= middle)
    {
        tmp[k] = a[p_left];        
        k      = k + 1;
        p_left = p_left + 1;
    }

    // Copy the remaining elements of right sub-array
    while(p_right <= end)
    {
        tmp[k]  = a[p_right];        
        k       = k + 1;
        p_right = p_right + 1;
    }

    // Copy back the merged elements to original array
    for(k = start; k <= end; k++)
    {
        a[k] = tmp[k-start];
    }


    //for (i=start; i<=end; i++) printf("%d ", a[i]);
    //printf("\n");


    //puts("-----------------------------");



    return num_inversions;
}

