int pesquisa_binaria(Segmento seg[],int low, int high, int coberto){
	int middle;
	int max=0;
	while(low < high){
		middle = low + (high-low)/2;
		if (seg[middle].start<=coberto){		
			if(seg[middle].end>coberto && seg[middle].end>max){
				max=seg[middle].end;
				high=middle;
			}else{
				low=middle+1;
			}
		}
		else{
			high=middle;
		}
		printf("LOW: %d MIDDLE: %d HIGH: %d START: %d END: %d MAX: %d \n",low,middle,high,seg[middle].start,seg[middle].end ,max);
	}
	return low;
}

int preenche(Segmento seg[],int n, int coberto){
	int i=0;
	int max=0;
	for(i=0;i<n;i++){
		if(seg[i].start<=coberto && seg[i].end>coberto){
			if(seg[i].end>max){
				max=seg[i].end;
			}
		}
	}

	//printf("MAX: %d ANTERIOR: %d\n",max,anterior );

	return max;
}

int compare(const void *elem1,const void *elem2){
	Segmento first = *(Segmento*) elem1;
	Segmento second = *(Segmento*) elem2;
	if (first.start>second.start) return 1;
	if (second.start<second.start) return -1;
	else{
		if (first.end>second.end) return 1;
		if (first.end<second.end) return -1;
		else return 0;
	}
}

