#include <stdio.h>

int mergesort (int *arr, int start, int end) {
  int i, j, k, med;  
  if (start == end) return 0; //vazio  
  med = (start+end)/2;  
  int inv1 = mergesort(arr, start, med);
  int inv2 = mergesort(arr, med+1, end);  
  i = start;
  j = med+1;
  k = 0;  
  int inv3 = 0;
  int tmp[end-start+1];
  while (i < med+1 || j < end+1) {
    if (i == med+1) {
      tmp[k] = arr[j];
      j++;
      k++;
    }
    else {
      if (j == end+1) {
	tmp[k] = arr[i];
	i++;
	k++;
      }
      else {
	if (arr[i] < arr[j]) {
	  tmp[k] = arr[i];
	  i++;
	  k++;
	}
	else {
	  inv3 += (med - i) + 1;
	  tmp[k] = arr[j];
	  j++;
	  k++;
	}
      }
    }
  }

  for (i = start; i <= end; i++) {
    arr[i] = tmp[i-start];
  }
  return inv1+inv2+inv3;
}

