int binsearch(int inicio, int fim, int valor) {


	while(inicio <= fim) {

		w=0;

		meio=(fim-inicio)/2+inicio;

		dif=abs(best[0]-valor);

		if(soma[meio] == valor) {
			best[1]=0;
