			if(dif > (soma[meio]-valor)) {
				best[0]=soma[meio];
				best[1]=0;
			}
			else if((dif == (soma[meio]-valor)) && best[0] != soma[meio] && best[1] != soma[meio]) {
				w++;
				best[w]=soma[meio];
			}

			fim=meio-1;
