#include <stdio.h>

void troca(int* a, int* b) {
  int aux;
  aux = *a;
  *a = *b;
  *b = aux;
}

void quicksort(int numeros[], int left, int right) {
  int pivot = left, i;

  if(right > left) {
    for(i = left; i <= right; i++) {
      if(numeros[left] > numeros[i]) {
	pivot++;
	troca(&numeros[pivot], &numeros[i]);
      }
    }

    troca(&numeros[left], &numeros[pivot]);

    quicksort(numeros, left, pivot-1);
    quicksort(numeros, pivot+1, right);
  }
}

int main() {
  int i, n;
  scanf("%d", &n);

  int numeros[n];
  for(i=0; i<n; i++) scanf("%d", &numeros[i]);

  quicksort(numeros, 0, n-1);

  printf("%d", numeros[0]);
  for(i=1; i<n; i++) printf(" %d", numeros[i]);
  printf("\n");

  return 0;	 
}

