int compareSeg(const void *a, const void *b) {
  Segmentos *p1 = (Segmentos *)a;
  Segmentos *p2 = (Segmentos *)b;

  if (p1->inicio > p2->inicio){
       return +1;
  }
  if (p1->inicio < p2->inicio){
      return -1;
  }
  if (p1->inicio == p2->inicio){
    if(p1->fim > p2->fim)
      return -1;
    if(p1->fim < p2->fim)
      return +1;
    if(p1->fim == p2->fim)
      return 0;
  }
  return 0;
}

int resolve(Segmentos v[], int n, int m){
  int j, i = 1;
  int end = v[0].fim;
  int escolha = 1;
  int conta = 1;

  while(end < m){
    for (j=i;j<n;j++)
      if (v[j].inicio <= end && v[j].fim > v[escolha].fim)
	escolha = j;
    end = v[escolha].fim;
    conta ++;
  }
  return conta;
}

