// Funcao para comparar dois elementos de um array (necessaria para o qsort)
// Esta funcao deve devolver:
//  - numero < 0 se elemento "a" for menor que elemento "b"
//  - numero > 0 se elemento "a" for maior que elemento "b"
//  - zero, se elemento "a" for igual ao elemento "b"
int k=0;
int compare_int(const void *a, const void *b) {
  int i1 = *((int *)a);
  int i2 = *((int *)b);

  if (i1 < i2) return -1;
  if (i1 > i2) return +1;
  return 0;
}


//bisearch(array, inicio do array, final do array,valor a procurar)
int bisearch(int sum[], int low, int high, int val){

  while(low < high){
    int mid = low + (high - low) / 2;

    if(sum[mid] == val)
      return mid;

    if(sum[mid] > val)
      high = mid;

    else
      low = mid + 1;
  }
  if(sum[low] < val)
    return -1;
  return low;
}

