int binsearch(int v[],int elem, int start, int end,int best) {
    if(start>=end) {
        if(abs(elem-v[best])>abs(elem-v[start]))
            return start;
        else
            return best;
        }
    int middle=(start +end)/2;
    if(best==-1)
        best=middle;
    if( v[middle]==elem)
          return middle;
    else if(abs(v[middle]-elem)<abs(v[best]-elem))
          best =middle;

    if(v[middle]>elem)
           return binsearch(v,elem,start,middle,best);
    else return binsearch(v,elem,middle+1,end,best);

    }


