long long merge (int v[], int start, int med, int end) {
  int i,j,k;
  long long inv = 0;
  i = start;
  j = med+1;
  k = 0;
  int tmp[end-start+1];
  while (i <= med && j <= end) {
    if (v[i] <= v[j]) {
      tmp[k] = v[i];
      k++;
      i++;
    }
    else {
      inv += (med - i + 1);
      tmp[k] = v[j];
      k++;
      j++;
    }
  }

  while (i <= med) {
    tmp[k] = v[i];
    k++;
    i++;
  }

  while (j <= end) {
    tmp[k] = v[j];
    k++;
    j++;
  }

  for (i = 0; i < k; i++) {
    v[i + start] = tmp[i];
  }
