int procurame(int key, int low, int high){

  int i=0, j, middle, val, c,d;

  while (low <= high) {
    middle = low + (high - low)/2;
    val = somas[0]-key;
    if (val<0)
      val = val*-1;
    if (pares[middle]==key){
      somas[0]=pares[middle];
      return 0;
    }
    else if (pares[middle]>key){
      if ((pares[middle]-key) == val && somas[0] != pares[0]){
        i++;
        d=0;
        for(j=0; j<i && d==0; j++){
          if (somas[j]==pares[middle]){
            c=1;
            i--;
          }
          else if (somas[j] > pares[middle]){
            somas[j+1] = somas[j];
            somas[j] = pares[middle];
          }
          else
            somas[i] = pares[middle];
        }
      }
      else if ((pares[middle]-key) < val) {
        somas[0] = pares[middle];
        i=0;
      }
      high = middle-1;
    }
    else {
      if ((key - pares[middle]) == val && somas[0] != pares[0]){
        i++;
        c=0;
        for (j=0; j<i && c==0; j++) {
          if (somas[j] == pares[middle]) {
