long long inversoes_brute_force(long long v[],long long n);
long long inversoes_merge_rec(long long v[], long long start, long long end);
long long inversoes_merge(long long v[], long long start, long long middle, long long end);

int main(){

	long long n,i;
	scanf("%lld", &n);
	long long v[n];

	for(i=0; i<n; i++){
		scanf("%lld",&v[i]);
	}

	long long n_inversoes;
	//n_inversoes=inversoes_brute_force(v,n);
	//prlong longf("BRUTE FORCE:    %d\n", n_inversoes);
	n_inversoes=inversoes_merge_rec(v,0,n-1);
	//prlong longf("MERGE ALTERADO: %d\n", n_inversoes);
	printf("%lld\n",n_inversoes);
	return 0;
}

long long inversoes_brute_force(long long v[],long long n){
	long long contador=0;
	long long i,j;

	for(i=0; i<n;i++){
		for(j=i+1; j<n; j++){
			if(v[i]>v[j])
				contador++;
		}
	}
	return contador;
}

long long inversoes_merge_rec(long long v[], long long start, long long end){
	long long contador=0;
	long long middle = (start+end)/2;
	/*Aqui vem uma condicao de paragem de recursao*/
	if(start==end){
		return 0;
	}
	contador += inversoes_merge_rec(v,start,middle); 
	contador += inversoes_merge_rec(v,middle+1,end); 
	contador += inversoes_merge(v,start,middle,end);

	return contador;
}

long long inversoes_merge(long long v[], long long start, long long middle, long long end){
	long long contador=0;

	long long i=start;
	long long i_control=0;
	long long j=middle+1;
	long long j_control=0;
	long long k=start;
	long long novo_v[end+1];
	while(k<=end){		
		//i chegou ao limite, apenas vemos se valor em i é mais pequeno que em j		
		if(i==middle){				
			if(i_control==1){	//o v[i] ja foi usado por isso copio o v[j] que ainda tem elementos
				novo_v[k]=v[j];
				contador+=j-k;		//CONTAR QUANTAS POSICOES O NUMERO ESTA DESLOCADO DO ARRAY ORDENADO (j-k)
				k++;
				j++;
				continue;
			}					//v[i] nao usado e é mais pequeno que v[j]
			if(v[i]<=v[j]){
				novo_v[k]=v[i];
				k++;
				i_control=1;
				continue;
			}
		}
		//j chegou ao limite, apenas vemos se valor em j é mais pequeno que em i
		if(j==end){
			if(j_control==1){	//v[j] ja foi usado por isso copio o v[i] que ainda tem elementos
				novo_v[k]=v[i];
				k++;
				i++;
				continue;
			}					//v[j] nao usado e é mais pequeno que v[i]
			if(v[j]<v[i]){
				novo_v[k]=v[j];
				contador+=j-k;		//CONTAR QUANTAS POSICOES O NUMERO ESTA DESLOCADO DO ARRAY ORDENADO (j-k)
				k++;
				j_control=1;
				continue;
			}
		}
		//ainda nao atingiram os extremos corre normalmente
		if(v[i]<=v[j]){
			novo_v[k]=v[i];
			i++;
			k++;
		}
		else{
			novo_v[k]=v[j];
			contador+=j-k;			//CONTAR QUANTAS POSICOES O NUMERO ESTA DESLOCADO DO ARRAY ORDENADO (j-k)
			j++;
			k++;
		}
	}
	//Copiar os valores agora ordenados para o vector original
	for(i=start;i<=end;i++){
		v[i]=novo_v[i];
	}
	return contador;
}

