    adj[a][b] = adj[b][a] = 1;
  }

  dfs(1); // Pesquisa em profundidade a partir do no 1

  for(i = 2; i <= n; i++) {
	if(!visited[i]) {
		counter++;
		dfs(i);
	}
  }

  printf("%d\n", counter);

  return 0;
}

