int bisearch(int v[], int low, int high, int c){
	int middle;
	while(low < high){
		middle = low+(high-low)/2;
		//printf("C==%d V==%d\n",c,v[middle]);
		if(v[middle] >= c)	high = middle;
		else low = middle + 1;
	}

	if(c>v[low]) return -1;
	return low;

}

