#include <stdio.h>

#define MAX 100005



int merge(int v[], int start, int middle, int end) {
  int i, p1, p2, aux[MAX],count=0;;

  p1=start;     // "Apontador" do array da metade esquerda
  p2=middle+1;  // "Apontador" do array da metade direita
  i = start;    // "Apontador" do array aux[] a conter juncao
  while (p1<=middle && p2<=end) {            // Enquanto de para comparar
    if (v[p1] <= v[p2]) 
      aux[i++] = v[p1++];  // Escolher o menor e adicionar
    else {               
      aux[i++] = v[p2++];
      count= count + middle ; // ACRESCENTADO, ver se é middle ou middle -1
    }
  }
  while (p1<=middle) 
    aux[i++] = v[p1++];     // Adicionar o que resta
  while (p2<=end)    
    aux[i++] = v[p2++];

  for (i=start; i<=end; i++) 
    v[i] = aux[i];  // Copiar array aux[] para v[]

  return count;
}

int mergesort(int v[], int start, int end){
  int count=0,middle;
  if (start<end){

    middle= (start+end)/2;
    count= count + mergesort(v, start, middle);
    count= count + mergesort(v, middle+1, end);
    count= count + merge(v, start, middle, end);
  }
  return count;
}




