class krusk {

    int p;
    int r;
    int na;
    int cnt;
    int custos;
    matriz o[];
    no nos[];
    krusk(matriz m [],int tnos,int tlig,int zz){
	p = tnos;
	r = tlig;
	na = 0;
	cnt=0;
	custos=zz;
	nos= new no[tnos];
	o = m;
    }

    void principal () {

	int ii=0;

	sort(o,r);

	for (int k=0;k<r;k++) {

	    if ((findset(o[k].a)) != (findset(o[k].b))){
		ii++;
		cnt += o[k].v;
		union(o[k].a,o[k].b);
	    }

	}
	if (ii == (p-1)){
	    System.out.println("rendimento optimo:" + (cnt+custos));}
	else {System.out.println("impossivel");

	}
    }

    void sort (matriz m[],int n){

	matriz key;
	int i= 0;

	for (int j = 1;j<n;j++){
	    key = m[j];
	    i = j-1;
	    while (i > -1 && m[i].v > key.v){
		m[i+1] = m[i];
		i = i-1;
	    }
	    m[i+1] = key;
	}
    }

    void makeset(int x) {	

	no n;
	n = new no(0,x,x);
	nos[na] = n;
	na++;
    }

    int findset(int x) {

	int ind = find (x);
	if (x != nos[ind].p){
	    nos[ind].p = findset(nos[ind].p);
	}
	return nos[ind].p;
    }

    int find(int x){

	for(int i=0;i<p;i++){
	    if (nos[i] != null){
		if (nos[i].tag == x){
		    return i;	
		}
	    }
	}
	makeset(x);
	return na-1;
    }

    void union (int x,int y){

	link(findset(x),findset(y));
    }

    void link(int x,int y){

	int h = find(x);
	int g = find(y);

	if (nos[h].rank > nos[g].rank){
	    nos[g].p = nos[h].tag;
	}
	else {
	    nos[h].p = nos[g].tag;
	    if (nos[h].rank == nos[g].rank){
		nos[g].rank += 1;
	    }
	}
    }
}

