	int middle = low + (high - low)/2;
	if (somas [middle] == val)
	    System.out.print (val);
	else if (somas[middle]>val){
	    if (high-low==0)
		System.out.print(somas[low]);
	    else
		bsearch (somas, low, middle,val);
	}
	else{
	    if (high-low!=0){
		int dif1 = Math.abs(somas [middle] - val);
		int dif2 = Math.abs(somas [middle+1] - val);
		if (dif1<dif2)
		    if (high-low==0)
			System.out.print (somas[low]);
		    else
			bsearch (somas,low,middle,val);
		else if (dif1>dif2)
		    if (high-low==0)
			System.out.print (somas[low]);
		    else
			bsearch (somas,middle+1,high,val);
		else if (dif1 == 1 && dif2 ==1)
		    System.out.print (somas[middle] + " " + somas[middle+1]);
		else
		    bsearch (somas, middle+1, high, val);
	    }
	    else
		System.out.print (somas[low]);
	}
    }
    public static int[] somas (int [] v){
	int size = ((v.length*v.length)-v.length)/2;
	int [] somas = new int [size];
	int k = 0;
	Arrays.sort (v);
	for (int i = 0; i < v.length; i++){
	    for (int j=i+1; j < v.length; j++){
		somas [k] = v[i]+v[j];
		k++;
	    }
	}
	Arrays.sort(somas);
	return somas;
    }
    public static void main (String [] args){
	Scanner stdin = new Scanner (System.in);
	int n = stdin.nextInt();
	int [] v = new int [n];
	for (int i = 0; i < n; i++)
	    v[i] = stdin.nextInt();
	int q = stdin.nextInt();
	int [] quest = new int [q];
	for (int j = 0; j < q; j++){
	    quest [j] = stdin.nextInt();
	    bsearch (somas(v),0,somas(v).length-1,quest[j]);
	    System.out.println();
	}
    }
}

