import java.util.*;

class No{
	int val;
	int tempof;
	LinkedList<No> adj;
	boolean visitado;

	No(int n){
		val = n;
		tempof = 0;
		adj = new LinkedList<No>();
		visitado = false;
	}
	void addLigacao(No x){
		adj.addLast(x);
	}
}

class Grafo{
	int tempo, nalunos;
	No graf[];
	No graft[];
	LinkedList<Integer> grupos;

	Grafo(int np){
		this.nalunos = np;
		tempo = 0;
		graf = new No[np+1];
		graft = new No[np+1];
		grupos = new LinkedList<Integer>();
	}
	private void inicializar(){
		for(int i = 1; i<=nalunos; i++){
			graf[i] = new No(i);
			graft[i] = new No(i);
		}
	}
	void criaGrafo(Scanner in){
		inicializar();
		for(int i = 1; i<=nalunos; i++){
			int namigo = in.nextInt();
			for(int j = 0; j<namigo; j++){
				int amigo = in.nextInt();
				graf[i].addLigacao(graf[amigo]);
				graft[amigo].addLigacao(graft[i]);
			}
		}
	}

	int calculaDia(){
		PriorityQueue<Integer> aux=new PriorityQueue<Integer>(nalunos);
		aux.add(1);
		tempo++;
		while(!aux.isEmpty()){
			boolean visit = false;
			int n = aux.remove();
			if(!graf[n].visitado){
				for (No no : graf[n].adj){
					if (!graf[no.val].visitado){
						aux.add(no.val);
					}else{
						visit = true;
					}		
				}
				if (visit == true){
					tempo++;
				}
				graf[n].visitado = true;
			}
		}
		return tempo;
	}

}

