        if (ratio < enc.ratio) return -1;
	if (ratio > enc.ratio) return +1;
        if (ratio == enc.ratio) {
            if (dias > enc.dias) return +1;
            if (dias < enc.dias) return -1;
            if (dias == enc.dias) {
                Integer numA = multa;
                Integer numB = enc.multa;
                return numA.toString().compareTo( numB.toString() );
            }
        }
	return 0;
    }
}
