class MyLinkedList<T>
{
    Node<T> first;
    Node<T> last;
    int size;

    Node<T> ref;

    MyLinkedList()
	{
	    first=null;
	    last=null;
	    size=0;

	    ref=null;
	}

    public int size()
    {
	return size;
    }


    public void addFirst(T val)
    {
	if(size==0)
	    {
		first=new Node<T>(val);
		last=first;
	    }
	else
	    {
		first.prev=new Node<T>(val,null,first);
		first=first.prev;
	    }
	size++;
    }

    public void addLast(T val)
    {
	if(size==0)
	    {
		first=new Node<T>(val);
		last=first;

	    }
	else
	    {

		last.next=new Node<T>(val,last,null);
		last=last.next;
	    }
	size++;
    }


    public void removeFirst()
    {
	if(size==0)
	    throw new IndexOutOfBoundsException();

	else if(size==1)
	    {
		first=null;
		last=null;
	    }

	else
	    {
		first=first.next;
		first.prev=null;
	    }

	size--;
    }

    public void removeLast()
    {
	if(size==0)
	    throw new IndexOutOfBoundsException();
	else if(size==1)
	    {
		first=null;
		last=null;
	    }

	else
	    {
		last=last.prev;
		last.next=null;
	    }
	size--;
    }

    public T get(int index)
    {
	if(index<0 || index>=size)
	    throw new IndexOutOfBoundsException();
	else if(size==1)
	    {
		return first.val;
	    }
	else
	    {
		if(index<=size/2)
		    {
			Node<T> p=first;
			for(int i=0;i<size;i++)
			    {
				if(i==index)
				    return p.val;
				else
				    {
					p=p.next;
				    }
			    }
		    }
		else
		    {
			Node<T> p=last;
			for(int i=size-1;i>=0;i--)
			    {
				if(i==index)
				    return p.val;
				else
				    {
					p=p.prev;
				    }
			    }
		    }
	    }
	return null;
    }

    public void remove(int index)
    {
	if(index<0 || index>=size)
	    throw new IndexOutOfBoundsException();
	else if(index==0)
	    {
		removeFirst();
	    }
	else if(index==size-1)
	    {
		removeLast();
	    }
	else
	    {
		if(index<=size/2)
		    {
			Node<T> p=first;
			for(int i=0;i<size;i++)
			    {
				if(i==index)
				    {
					p.prev.next=p.next;
					p.next.prev=p.prev;
					size--;
					break;
				    }
				else
				    {
					p=p.next;
				    }
			    }
		    }
		else
		    {
			Node<T> p=last;
			for(int i=size-1;i>=0;i--)
			    {
				if(i==index)
				    {
					p.prev.next=p.next;
					p.next.prev=p.prev;
					size--;
					break;
				    }
				else
				    {
					p=p.prev;
				    }
			    }
		    }
	    }

    }


    public int indexOf(T val)
    {
	if(size==0)
	    return -1;
	else
	    {
		Node<T> p=first;
		for(int i=0;i<=size-1;i++)
		    {
			if(p.val.equals(val))
			    return i;
			else
			    p=p.next;
		    }
	    }
	return -1;
    }

    public void add(T val,int index)
    {
	if(index<0 || index>=size)
	    throw new IndexOutOfBoundsException();
	else if(index==0)
	    {
		addFirst(val);
	    }
	else if(index==size-1)
	    {
		addLast(val);
	    }
	else
	    {
		if(index<=size/2)
		    {
			Node<T> p=first;
			for(int i=0;i<size;i++)
			    {
				if(i==index)
				    {
					Node <T> subs=new Node<T>(val,p.prev,p);
					p.prev.next=subs;
					p.prev=subs;

					size++;
					break;
				    }
				else
				    p=p.next;
			    }
		    }
		else
		    {
			Node<T> p=last;
			for(int i=size-1;i>=0;i--)
			    {
				if(i==index)
				    {
					Node <T> subs=new Node<T>(val,p.prev,p);
					p.prev.next=subs;
					p.prev=subs;

					size++;
					break;
				    }
				else
				    p=p.prev;
			    }
		    }
	    }


    }

    public void add(T val)
    {
	addLast(val);
    }




    public void clear()
    {
	first=null;
	last=null;
	size=0;
    }



    public void setRef(int index)
    {
	if(index<0 || index>=size)
	    throw new IndexOutOfBoundsException();
	else if(index==0)
	    {
		ref=first;
	    }
	else if(index==size-1)
	    {
		ref=last;
	    }
	else
	    {
		if(index<=size/2)
		    {
			Node<T> p=first;
			for(int i=0;i<size;i++)
			    {
				if(i==index)
				    {
					ref= p;
					break;
				    }
				else
				    {
					p=p.next;
				    }
			    }
		    }
		else
		    {
			Node<T> p=last;
			for(int i=size-1;i>=0;i--)
			    {
				if(i==index)
				    {
					ref= p;
					break;
				    }
				else
				    {
					p=p.prev;
				    }
			    }
		    }
	    }

    }

    public void incRef()
    {
	if(ref==last)
	    throw new IndexOutOfBoundsException();
	else
	    ref=ref.next;
    }
    public void decRef()
    {
	if(ref==first)
	    throw new IndexOutOfBoundsException();
	else
	    ref=ref.prev;
    }

    public T getRef()
    {
	return ref.val;
    }

    public boolean isLast()
    {
	if(ref==last)
	    return true;
	else
	    return false;
    }

    public boolean isFirst()
    {
	if(ref==first)
	    return true;
	else
	    return false;
    }

    public String toString()
    {
	String s =new String("[");
	Node<T> p=first;


	for(int i=0;i<size && p!=null;i++)
	    {

		if(i==size-1)
		    s+=" "+p.val.toString();
		else
		    s+=" "+p.val.toString()+",";

		p=p.next;
	    }

	return s+"]";
    }
    public void print()
    {
	Node<T> p=first;
	System.out.print("[");
	for(int i=0;i<size && p!=null;i++)
	    {
		if(i==size-1)
		    System.out.print(" "+p.val.toString());
		else
		    System.out.print(" "+p.val.toString()+",");
		p=p.next;
	    }
	System.out.println("]");
    }

}

