				key[i] = Integer.MAX_VALUE;
				color[i] = 1; // 1 white
			}
			key[root] = 0;
			Heapmin H = new Heapmin(key, V);
			int u;
			rendimento = 0;
			while (!H.isvazia()) {
				u = H.extramin();
				for (Edge e : nos[u].adj) {
