class Sapato implements Comparable<Sapato> {
  int dias, multa, id;
  float ratio;

  Sapato(int d, int m, int id) {
    this.dias = d;
    this.multa = m;
    this.id = id;

    this.ratio = (float)m / (float)d;
  }

  @Override
  public int compareTo(Sapato that) {
    Float is = this.ratio;
    Float at = that.ratio;

    int ret = at.compareTo(is);

    if (ret == 0) {
      Integer tis = this.id;
      Integer tat = that.id;

      return tis.compareTo(tat);
    }

    return ret;
  }

  @Override
  public String toString() {
    return "ID: " + id + " D: " + dias + " M: " + multa;
  }
}

