class Encomenda{

	public static int G[][];
	public static int cont[];
	public static LinkedList<Integer> nodes = new LinkedList<Integer>();

	public static int W[][];

	public static int d[];

	public static void main(String args[]){
		Scanner scn = new Scanner(System.in);

		// dados da jaula
		int lmin = scn.nextInt();
		int lmax = scn.nextInt();
		int cmin = scn.nextInt();
		int cmax = scn.nextInt();
		int amin = scn.nextInt();

		int origem = scn.nextInt();
		int destino = scn.nextInt();

		LinkedList<Arco> arc = new LinkedList<Arco>();

		int x = scn.nextInt();
		while (x != -1){
			int y = scn.nextInt();
			int lm = scn.nextInt();
			int cm = scn.nextInt();
			int am = scn.nextInt();

			if (lm >= lmin && cm >= cmin && am >= amin)
				arc.add(new Arco(insertNode(x), insertNode(y), Math.min(cmax, cm)));

			x = scn.nextInt();
		}

		G = new int[nodes.size()][nodes.size()-1];
		cont = new int[nodes.size()];
		W = new int[nodes.size()][nodes.size()];

		for (Arco a: arc){
			G[a.x][cont[a.x]++] = a.y;
			G[a.y][cont[a.y]++] = a.x;
			W[a.x][a.y] = W[a.y][a.x] = a.val;
		}

		int r = Dijkstra(insertNode(origem), insertNode(destino));

		System.out.println(r);
	}

	public static int Dijkstra(int s, int destino){
		d = new int[nodes.size()];
		d[s] = Integer.MAX_VALUE;

		boolean color[] = new boolean[nodes.size()];
		PriorityQueue<Integer> Q = new PriorityQueue<Integer>(nodes.size(), 
			new Comparator<Integer>(){
				public int compare(Integer x, Integer y){
					return d[y]-d[x];
				}
			});

		Q.add(s);
		while (!Q.isEmpty()){
			int x = Q.remove();
			if (x == destino) return d[x];
			color[x] = true;

			for(int i=0; i<cont[x]; i++){
				int k = G[x][i];
				if (!color[k]){
					if (d[k] < Math.min(d[x], W[x][k])){
						d[k] = Math.min(d[x], W[x][k]);
						Q.remove(k);
						Q.add(k);
					}
				}
			}
		}
		return -1;
	}

	// faz a gestao e pesquisa dos ids dos nos
	public static int insertNode(int x){
		int p = 0;
		for (int i: nodes){
			if (i == x) return p;
			p++;
		}
		nodes.add(x);
		return nodes.size()-1;
	}

	static class Arco{
		int x;
		int y;
		int val;

		Arco(int x, int y, int val){
			this.x = x;
			this.y = y;
			this.val = val;
		}
	}
}

