		int v = a.extremo_final();
		if(!visitado[v]){
		    visitado[v] = true; 
		    d[v] = d[u] + 1;
		    if(v==destino)
			return d[v];
		    fila.addLast(new Integer (v));
		}
	    }
	}
	return -1;
    }

