    static void conexos() {
        int contador=0;
        for(int i=1; i<=n; i++) visited[i] = false;
        for (int i=1; i<=n; i++){
            if (!visited[i]) {
                contador++;
                dfs(i);
            }
        }
        System.out.println(contador);
