	    par[i]=new Par(in.nextDouble(),in.nextDouble());
	}
	for(int i=0;i<N;i++){
	    for(int j=i+1;j<N;j++){
		peso[i]=calcpeso(par[i],par[j]);
		g.addLink(i,j,peso[i]);
	    }
	} 
	double mst=0;
	g.prim(0);
	for (int i=1;i<N;i++ ) {
	    mst+=g.nodes[i].dist;	
	}
