class om {
	public static void main(String args[]) {
		Scanner in = new Scanner(System.in);

		int nnos = in.nextInt();
		int nr = in.nextInt();
		int custo = in.nextInt();

		Grafo g = criaGrafo(in, nnos, nr);
		int l = PrimMax(g);

		if(l==Integer.MIN_VALUE) System.out.println("impossivel");
		else System.out.println("rendimento optimo: "+(l-(nnos-1)*custo));
	}

	static Grafo criaGrafo(Scanner in, int nnos, int nr) {
		Grafo g = new Grafo(nnos);

		for (int i = 0; i < nr; i++) {
			int v = in.nextInt(), w = in.nextInt(), r = in.nextInt();

			g.insert_new_arc(v, w, r);
			g.insert_new_arc(w, v, r);
		}

		return g;
	}

	static int PrimMax(Grafo g) {
		boolean vis[] = new boolean[g.num_vertices()+1];
		int lucro[] = new int[g.num_vertices()+1];
		for (int i = 0; i < lucro.length; i++) {
			lucro[i] = Integer.MIN_VALUE;
		}
		lucro[1] = 0;

		int l=0;
		Heapmax pq = new Heapmax(lucro, g.num_vertices());

		while (pq.size>0) {
			int v = pq.extractMax();
			vis[v] = true;
			if(lucro[v]==Integer.MIN_VALUE) return Integer.MIN_VALUE;

			for (Arco a : g.adjs_no(v)) {
				int w = a.extremo_final();

				if(!vis[w] && lucro[w]<a.valor_arco()) {
					lucro[w] = a.valor_arco();
					pq.increaseKey(w, lucro[w]);
				}
			}

			l += lucro[v];
		}

		return l;
	}
}

