// Classe que representa um grafo
class Graph {
    int n;           // Numero de nos do grafo
    Node nodes[];    // Array para conter os nos

    Graph(int n) {
	this.n = n;
	nodes  = new Node[n+1]; // +1 se os comecam em 1 ao inves de 0


    }
	public void addLink(int a, int b) {
	    nodes[a].adj.add(b);
	    nodes[b].adj.add(a);
	}


    // Algoritmo de Prim
    public double prim(Graph g, Node no, int n) {

	for (int i=2; i<=n; i++) {
	    nodes[i].pai = -1;
	    nodes[i].distance = 99999;
	}
	nodes[1].distance = 0;
	PriorityQueue<Node> q = new PriorityQueue<Node>();
	for (int i=1; i<=n; i++)
	    q.add(nodes[i]);

	while (q.size() > 0) {
	    Node n1 = q.poll();
	    for (int w : n1.adj)
		if ( q.contains(nodes[w]) && (Dist(n1,nodes[w]) < nodes[w].distance)) {
		    nodes[w].pai = n1.index;
		    nodes[w].distance = Dist(n1,nodes[w]);
		    q.add(nodes[w]);		    
		}
	}
	double s = 0;
	for (int i=1; i<=n; i++)
	    s += g.nodes[i].distance;


	return s;

    }

	public double Dist( Node no1, Node no2) {
	    return Math.sqrt(Math.pow(no1.x-no2.x, 2) + Math.pow(no1.y-no2.y,2));
	}

}  
