public class Encomenda {
    static HashMap<Integer,LinkedList<node>> trajecto = new HashMap<Integer, LinkedList<node>>();
    static int limites[] = new int[5];

    public static void main(String args[])
    {
        int temp[] = new int[5];
        int origem, destino;
        Scanner stdin = new Scanner(System.in);
        //Preencher os limites [0]->L_Min [1]->L_Max [2]->C_Min [3]->C_Max [4]->A_Min
        for(int i = 0;i<limites.length;i++)
        {
            limites[i]=stdin.nextInt();
        }
        stdin.nextLine();

        origem = stdin.nextInt();
        destino = stdin.nextInt();
        stdin.nextLine();

        while(!stdin.hasNext("-1"))
        {
            for(int i = 0;i<temp.length;i++)
            {
                temp[i]=stdin.nextInt();
            }
            stdin.nextLine();

            if(limites[0]<=temp[2] & limites[2]<=temp[3] & limites[4]<=temp[4]){

                contruir_grafo(temp[0], temp[1], temp[3], 1);
            }
        }
        System.out.println(pesquisa(origem, destino, trajecto, limites[3]));
    }

    public static void contruir_grafo(int inicio, int fim, int C_Max, int s)
    {
        if(trajecto.containsKey(inicio))
        {
            LinkedList<node> tmp = trajecto.get(inicio);
            node temp = new node();
            temp.fim = fim;
            temp.peso = C_Max;
            tmp.add(temp);
            trajecto.put(inicio, tmp);
            s*=-1;
        }
        else
        {
            LinkedList<node> tmp = new LinkedList<node>();
            node temp = new node();
            temp.fim = fim;
            temp.peso = C_Max;
            tmp.add(temp);
            trajecto.put(inicio, tmp);
            s*=-1;
        }

        if(s<0)
            contruir_grafo(fim, inicio, C_Max, s);

        for(Object k: trajecto.keySet())
        {
            int i=(Integer)k;
            LinkedList<node> tmp = trajecto.get(i);
            for(node n: tmp)
            {
                System.out.println("Inicio " + k + " Fim " + n.fim + " Peso " + n.peso);
            }
        }
        System.out.println();

    }

    static int pesquisa(int origem, int destino,HashMap<Integer,LinkedList<node>> trajecto, int C_Max)
    {
        HashMap<Integer,Integer> distancia = new HashMap<Integer, Integer>();
        distancia.put(destino, 0);
        ArrayList<Integer> visitados = new ArrayList<Integer>();

        for(Integer i: trajecto.keySet())
        {
            distancia.put(i, 0);
        }
        distancia.put(origem, C_Max);

        while(trajecto.size()>visitados.size())
        {
            int maior=-1;
            int vertice=0;
            for(int i: distancia.keySet())
            {
                if(!visitados.contains(i))
                {
                    if(distancia.get(i)>maior)
                    {
                        vertice = i;
                        maior = distancia.get(i);
                    }
                }

            }
            visitados.add(vertice);
            for(node j: trajecto.get(vertice))
            {
                if(!visitados.contains(j.fim))
                {
                    distancia.put(j.fim, max(min(distancia.get(vertice),j.peso),distancia.get(j.fim)));
                }
            }
        }
        return distancia.get(destino);
    }

    public static int min(int a, int b)
    {
        if(a<=b)
            return a;
        else
            return b;
    }

    public static int max(int a, int b)
    {
        if(a>=b)
            return a;
        else
            return b;
    }
}

