import java.util.*;

public class CoberturaMinima {
    private static int segmentSize;
    private static int[][] segments;

    public static void main(String[] args) {
	readInput();
	dataProcessing();
    }

    private static void readInput() {
	Scanner in = new Scanner(System.in);
	segmentSize = in.nextInt();
	int n = in.nextInt();
	segments = new int[n][2];

	for (int i=0; i<n; i++) {
	    segments[i][0] = in.nextInt();
	    segments[i][1] = in.nextInt();
	}
    }

    private static void dataProcessing() {
	//Compare c = new Compare(0);
	Arrays.sort(segments,new Comparator<int[]>() {
		private int index_to_compare;
       		public int compare(int[] elem1, int[] elem2) {
		    return compare(elem1, elem2, index_to_compare); 
		}

		public int compare(int[] elem1, int elem2[], int index) {
		    if (elem1.length == index) { return 0; } 
		    if (elem1[index] == elem2[index]) { 
			return compare(elem1, elem2, index + 1);
		    }
		    return elem1[index] - elem2[index];
		}	
	    });
	int end = 0;
	int i = 0;
	int counter = 0;

	while (end < segmentSize) {
	    if (segments[i][0] <= end) {
		if (segments[i+1][0] == segments[i][0]) {
		    i++;
		    continue;
		}
		end = segments[i][1];
		counter++;
		i++;
	    }
	}
	writeOutput(counter);
    }

    private static void writeOutput(int c) {
	System.out.println(c);
    }
}

import java.lang.*;
import java.util.*;
import java.util.LinkedList;
import java.util.Scanner;

class NegocioElectronico {
    private static Scanner stdin = new Scanner(System.in);

    public static void main(String [] args) {
        int nStores = stdin.nextInt();
        int destination = stdin.nextInt();

        Grafo g = lerLojas(nStores);
        analisarLojas(g, destination);
    }

    public static Grafo lerLojas(int nStores) {
        Grafo g = new Grafo(nStores);

        int a = stdin.nextInt();
        while (a != -1) {
            int b = stdin.nextInt();
            int w = stdin.nextInt();

            g.insert_new_arc(a, b, w);
            g.insert_new_arc(b, a, w);

            a = stdin.nextInt();
        }

        return g;
    }

    public static void analisarLojas(Grafo g, int origem) {
        int [] dist = new int[g.num_vertices() + 1];
        boolean [] seen = new boolean[g.num_vertices() + 1];
        int [] pred = new int[g.num_vertices() + 1];

        for (int u = 1; u <= g.num_vertices(); u++) {
            dist[u] = Integer.MAX_VALUE;
            seen[u] = false;
            pred[u] = -1;
        }

        dist[origem] = 0;
        pred[origem] = origem;
        Heapmin q = new Heapmin(dist, g.num_vertices());

        while (q.size != 0) {
            int u = q.extractMin();

            for (Arco temp : g.adjs_no(u)) {
                int v = temp.extremo_final();

                if (dist[u] + g.find_arc(u, v).valor_arco() < dist[v]) {
                    dist[v] = dist[u] + g.find_arc(u, v).valor_arco();
                    q.decreaseKey(v, dist[v]);
                    pred[v] = u;
                }
            }
            seen[u] = true;
        }
    }
}

