class sociologia {
	public static void main(String args[]) {
		Scanner in = new Scanner(System.in);

		int n = in.nextInt();

		for (int i = 0; i < n; i++) {
			Grafo g = criaGrafo(in);
			kosarajuAdapt(g, i+1);
		}
	}

	static Grafo criaGrafo(Scanner in) {
		int nalunos = in.nextInt();
		Grafo g = new Grafo(nalunos);

		for (int i = 0; i < nalunos; i++) {
			int v = in.nextInt();
			int nr = in.nextInt();
			for (int j = 0; j < nr; j++) {
				g.insert_new_arc(v, in.nextInt(), 0);
			}
		}

		return g;
	}

	static void kosarajuAdapt(Grafo g, int num) {
		LinkedList<Integer> S = stackDFS(g);
		Grafo gt = gTransposto(g);

		boolean vis[] = new boolean[g.num_vertices()+1];

		int d=0;
		int f=0;

		while (!S.isEmpty()) {
			int v = S.pop();

			int c=0;
			if(!vis[v]) {
				c = DFS_Transposto(gt, v, vis);

				if(c>=4) d++;
				else f+=c;
			}
		}

		System.out.println("Caso #"+num);
		System.out.println(d+" "+f);
	}

	static Grafo gTransposto(Grafo g) {
		Grafo gt = new Grafo(g.num_vertices());

		for (int i = 1; i <= g.num_vertices(); i++) {
			for (Arco a : g.adjs_no(i)) {
				gt.insert_new_arc(a.extremo_final(), i, 0);
			}
		}

		return gt;
	}

	static LinkedList<Integer> stackDFS(Grafo g) {
		LinkedList<Integer> S = new LinkedList<Integer>();
		boolean vis[] = new boolean[g.num_vertices()+1];

		for (int i = 1; i <= g.num_vertices(); i++) {
			if(!vis[i]) {
				stackDFS_Visit(g, i, S, vis);
			}
		}

		return S;
	}

	static void stackDFS_Visit(Grafo g, int v, LinkedList<Integer> S, boolean vis[]) {
		vis[v] = true;

		for (Arco a : g.adjs_no(v)) {
			int w = a.extremo_final();

			if(!vis[w]) {
				stackDFS_Visit(g, w, S, vis);
			}
		}

		S.push(v);
	}

	static int DFS_Transposto(Grafo g, int v, boolean vis[]) {
		vis[v] = true;
		int c = 1;

		for (Arco a : g.adjs_no(v)) {
			int w = a.extremo_final();

			if(!vis[w]) {
				c += DFS_Transposto(g, w, vis);
			}
		}

		return c;
	}
}

import java.util.*;
import java.lang.*;
class Graph {

	public final Integer DIM = 1000;
	LinkedList<Integer>[] adj = null;
	int[] color, parent, startTime, finishTime;
	int time;
	@SuppressWarnings("unchecked")
	Graph() {
		adj = new LinkedList [DIM];
		color = new int[DIM];
		parent = new int[DIM];
		startTime = new int[DIM];
		finishTime = new int[DIM];
	}
	@SuppressWarnings("unchecked")
	Graph transpose() {
		Graph transposed = new Graph();
		for (int i = 0; this.adj[i] != null; i++) 
			transposed.adj[i] = new LinkedList<Integer>();
		for (int i = 0; this.adj[i] != null; i++) {
			Iterator<Integer> it = adj[i].iterator();
			while(it.hasNext()) {
				int node = it.next();
				transposed.adj[node].addLast(i);
			}
		}
		return transposed;
	}


	@SuppressWarnings("unchecked")
	void depthFirstSearch(LinkedList<Integer> fst, LinkedList<Integer> snd) {
		Arrays.fill(color, 0);
		Arrays.fill(parent, -1);
		Arrays.fill(startTime, -1);
		Arrays.fill(finishTime, -1);
		time = 0;
		Iterator<Integer> it = fst.iterator();
		while(it.hasNext()) {
			int source = it.next();	
			if (color[source] == 0)
				depthFirstVisit(source, snd);
		}
	}
	@SuppressWarnings("unchecked")
	void depthFirstVisit(int source, LinkedList<Integer> snd) {
		color[source] = 1;
		time += 1;
		startTime[source] = time;
		Iterator<Integer> it = adj[source].iterator();
		while (it.hasNext()) {
			int node = it.next();
			if (color[node] == 0) {
				parent[node] = source;
				depthFirstVisit(node, snd);
			}
		}
		color[source] = 2;
		time += 1;
		finishTime[source] = time;
		snd.addFirst(source);
	} 
	@SuppressWarnings("unchecked")
	PriorityQueue<Integer> findValues(int value, int[] vtr){
		PriorityQueue<Integer> fila = new PriorityQueue<Integer>();
		for (int i = 0; adj[i] != null; i++) 
			if (vtr[i] == value)
				fila.add(i);
		return fila;
	}
	@SuppressWarnings("unchecked")
	void makeTree (LinkedList<Integer> tree, int value) {
		if (value != -1)
			tree.add(value);	
		PriorityQueue<Integer> fila = new PriorityQueue<Integer>();
		fila = findValues(value, parent);
		while (!fila.isEmpty()) {
			int newValue = fila.remove();
			makeTree(tree, newValue);
		}
	}
	@SuppressWarnings("unchecked")
	LinkedList<Integer>[] buildTreeForest() {
		LinkedList<Integer>[] tree = (LinkedList<Integer>[]) new LinkedList[DIM];
		for (int i = 0; adj[i] != null; i++) {
			if (parent[i] == -1) {
				int aux = 0;
				for (int j = 0; tree[j] != null; j++)
					aux++;
				tree[aux] = new LinkedList<Integer>();
				makeTree(tree[aux], i);
			}
		}
		return tree;
	}

}

