class Heapmin {
    private static int posinvalida = 0;
    int sizeMax,size;

    Qnode[] a;
    int[] pos_a;

    Heapmin(int vec[], int n) {
	a = new Qnode[n + 1];
	pos_a = new int[n + 1];
	sizeMax = n;
	size = n;
	for (int i = 1; i <= n; i++) {
	    a[i] = new Qnode(i,vec[i]);
	    pos_a[i] = i;
	}

	for (int i = n/2; i >= 1; i--)
	    heapify(i);
    }

    int extractMin() {
	int vertv = a[1].vert;
	swap(1,size);
	pos_a[vertv] = posinvalida;  // assinala vertv como removido
	size--;
	heapify(1);
	return vertv;
    }

    void decreaseKey(int vertv, int newkey) {

	int i = pos_a[vertv];
	a[i].vertkey = newkey;

	while (i > 1 && compare(i, parent(i)) < 0) { 
	    swap(i, parent(i));
	    i = parent(i);
	}
    }


    void insert(int vertv, int key)
    { 
	if (sizeMax == size)
	    new Error("Heap is full\n");

	size++;
	a[size].vert = vertv;
	pos_a[vertv] = size;   // supondo 1 <= vertv <= n
	decreaseKey(vertv,key);   // diminui a chave e corrige posicao se necessario
    }

    void write_heap(){
	System.out.printf("Max size: %d\n",sizeMax);
	System.out.printf("Current size: %d\n",size);
	System.out.printf("(Vert,Key)\n---------\n");
	for(int i=1; i <= size; i++)
	    System.out.printf("(%d,%d)\n",a[i].vert,a[i].vertkey);

	System.out.printf("-------\n(Vert,PosVert)\n---------\n");

	for(int i=1; i <= sizeMax; i++)
	    if (pos_valida(pos_a[i]))
		System.out.printf("(%d,%d)\n",i,pos_a[i]);
    }

    private int parent(int i){
	return i/2;
    }
    private int left(int i){
	return 2*i;
    }
    private int right(int i){
	return 2*i+1;
    }

    private int compare(int i, int j) {
	if (a[i].vertkey < a[j].vertkey)
	    return -1;
	if (a[i].vertkey == a[j].vertkey)
	    return 0;
	return 1;
    }


    private void heapify(int i) {
	int l, r, smallest;

	l = left(i);
	if (l > size) l = i;

	r = right(i);
	if (r > size) r = i;

	smallest = i;
	if (compare(l,smallest) < 0)
	    smallest = l;
	if (compare(r,smallest) < 0)
	    smallest = r;

	if (i != smallest) {
	    swap(i, smallest);
	    heapify(smallest);
	}

    }

    private void swap(int i, int j) {
	Qnode aux;
	pos_a[a[i].vert] = j;
	pos_a[a[j].vert] = i;
	aux = a[i];
	a[i] = a[j];
	a[j] = aux;
    }

    private boolean pos_valida(int i) {
	return (i >= 1 && i <= size);
    }
}


class Encomenda {
	// idNos[0] corresponde a origem
	// idNos[1] corresponde a destino
	// nIdNos corresponde ao tamanho de idNos
	public static int[] idNos = new int[50001];
	public static int nIdNos = 0;
	public static LinkedList<Integer> visitados = new LinkedList<Integer>();
	public static Grafo g;
	public static int larguraMin;
	public static int larguraMax;
	public static int comprimentoMin;
	public static int comprimentoMax;
	public static int alturaMin;
	public static int origem;
	public static int destino;

	public static int[] comprimentos;
	public static int[] pai;

	public static int nosParaId(int no) {
		for(int i=0; i<nIdNos;i++) {
			if(idNos[i] == no) return i;
		}
		return -1;
	}

	public static int Dijkstra() {
		Arrays.fill(comprimentos, Integer.MAX_VALUE);
		Arrays.fill(pai, 0);
		comprimentos[0] = 0;
		Heapmin q = new Heapmin(comprimentos, nIdNos-1);
		while(q.size>0) {
			int noActual = q.extractMin();
			if(noActual==idNos[1]) return comprimentos[noActual];

			for(Arco arco : g.verts[noActual].adjs) {
				int no_adj = arco.no_final;
				int valor = arco.valor;

				if(valor < comprimentos[no_adj] && !visitados.contains(no_adj)) {		
					comprimentos[no_adj]=valor ;
					pai[no_adj]=noActual;
					q.decreaseKey(no_adj, comprimentos[no_adj]);
				}
			}
			visitados.add(noActual);
		}
		return -1;
	}

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		larguraMin = in.nextInt();
		larguraMax = in.nextInt();
		comprimentoMin = in.nextInt();
		comprimentoMax = in.nextInt();
		alturaMin = in.nextInt();
		origem = in.nextInt();
		destino = in.nextInt();
		idNos[0] = origem;
		idNos[1] = destino;
		nIdNos = 2;
		g = new Grafo(50001);
		// leitura de dados
		while(true) {
			int no1 = in.nextInt();
			if(no1 == -1) break;
			if(nosParaId(no1) == -1) {
				idNos[nIdNos] = no1;
				nIdNos++;
			}
			int no2 = in.nextInt();
			if(nosParaId(no2) == -1) {
				idNos[nIdNos] = no2;
				nIdNos++;
			}
			int noLarguraMax = in.nextInt();
			int noComprimentoMax = in.nextInt();
			int noAlturaMax = in.nextInt();
			if((noLarguraMax >= larguraMin) && (noComprimentoMax >= comprimentoMin) && (noAlturaMax >= alturaMin)) {
				g.insert_new_arc(nosParaId(no1), nosParaId(no2), noComprimentoMax);
				g.insert_new_arc(nosParaId(no2), nosParaId(no1), noComprimentoMax);

			}
		}

		comprimentos = new int[nIdNos];
		pai = new int[nIdNos];
		if(Dijkstra() == -1) System.out.println("0");
		else {
			int compMax = comprimentos[0];
			while(idNos[0] != idNos[1]) {
				if(comprimentos[idNos[1]] > compMax) compMax = comprimentos[idNos[1]];
				idNos[1] = pai[idNos[1]];
			}
		}
	}
}

