static int bs(int k, int somas[],int low, int high){

    while(low < high){

    int mid= low + (high-low)/2;
    if(somas[mid]==k)
	return mid;
    else if(somas[mid]>k)
	return bs(k,somas,low,mid);
    else
	return bs(k,somas,mid+1,high);


    }
    return low;

}
