import java.io.*;
import java.util.*;

public class MergeSort {

    // Juntar dois arrays ordenados
    // Assumir que os arrays sao v[start..middle] e v[middle+1..end]
    static int merge(int v[], int start, int middle, int end) {
	int i, p1, p2;
	int aux[] = new int[end+1];
	int count = 0;

	p1=start;     // "Apontador" do array da metade esquerda
	p2=middle+1;  // "Apontador" do array da metade direita
	i = start;    // "Apontador" do array aux[] a conter juncao
	while (p1<=middle && p2<=end) {            // Enquanto de para comparar
	    if (v[p1] <= v[p2]){
		aux[i++] = v[p1++];  // Escolher o menor e adicionar
		//count++;
	    }
	    else{
                aux[i++] = v[p2++];
		count++;
	    }
	}
	while (p1<=middle){
	    aux[i++] = v[p1++];     // Adicionar o que resta
	    count++;
	}
	while (p2<=end){
	    aux[i++] = v[p2++];

	}

	for (i=start; i<=end; i++) v[i] = aux[i];  // Copiar array aux[] para v[]
	return count;
    }

    // Ordenar array v[] com mergesort entre posicoes start e end
    static int mergesort(int v[], int start, int end) {
	int middle;
	int count = 0;
	if (start<end) {                 // Parar quando tamanho do array < 2
	    middle = (start+end)/2;        // Calcular ponto medio
	    count += mergesort(v, start, middle);   // Ordenar metade esquerda
	    count += mergesort(v, middle+1, end);   // Ordenar metade direita
	    count += merge(v, start, middle, end);  // Combinar duas metades ordenadas
	}
	return count;
    }

    public static void main(String args[]) {

	Scanner stdin = new Scanner(System.in);

	// Ler N numeros
	int n   = stdin.nextInt();
	int v[] = new int[n];
	for (int i=0; i<n; i++)
	    v[i] = stdin.nextInt();

	// Ordenar
	System.out.println(mergesort(v, 0, n-1));

	// Imprimir

    }
}

import java.util.*;

public class inversoesb {
	public static int[] v;
	public static int n;
	public static void main(String args[]){
		Scanner stdin = new Scanner(System.in);
		n = stdin.nextInt();
		v = new int[n];
		for(int i=0; i<n; i++)
			v[i]=stdin.nextInt();

		System.out.println(mergesort(v,0,n-1));
	}

	public static int mergesort(int v[], int start, int end){
		int middle;
		int qi=0;
		if(start<end){
			middle=(start+end)/2;				//middle = start + (end-start)/2
			qi+=mergesort(v, start, middle);
			qi+=mergesort(v, middle+1, end);
			qi+=merge(v, start, middle, end);
		}
		return qi;
	}

	public static int merge(int v[], int start, int middle, int end){
		int i, p1, p2,qi;
		qi=0;
		int aux[] = new int[end+1];

		p1=start;
		p2=middle+1;
		i = start;
		while (p1<=middle && p2<=end) {
			if(v[p1] <= v[p2]) aux[i++] = v[p1++];
			else {aux[i++] = v[p2++]; qi+=(middle-p1+1);} 
		} 

		while(p1<=middle) {aux[i++] = v[p1++]; qi++;}

		while(p2<=end) {aux[i++] = v[p2++]; }

		for(i=start; i<end; i++) v[i] = aux[i];
		return qi;
	}

}

