    Scanner kb = new Scanner(System.in);
    sol s = new sol(kb);
    int c = kb.nextInt();
    for(int i = 1; i <= c; i++){
      System.out.printf("Caso#%d\n",i);
      s.read();
      s.solve();
    }
  }
}

