class Grafo {
    No verts[];
    int nvs, narcos;

    public Grafo(int n) {
	nvs = n;
	narcos = 0;
	verts  = new No[n+1];
	for (int i = 0 ; i <= n ; i++)
	    verts[i] = new No();
        // para vertices numerados de 1 a n (posicao 0 nao vai ser usada)
    }

    public int num_vertices(){
	return nvs;
    }

    public int num_arcos(){
	return narcos;
    }

    public LinkedList<Arco> adjs_no(int i) {
	return verts[i].adjs;
    }

    public void insert_new_arc(int i, int j, int valor_ij){
	verts[i].adjs.addFirst(new Arco(j,valor_ij));
        narcos++;
    }

    public Arco find_arc(int i, int j){
	for (Arco adj: adjs_no(i))
	    if (adj.extremo_final() == j) return adj;
	return null;
    }
}

class Sociologia {
	public static void PP(int j) {
		if(!visitado[j]) {
			visitado[j] = true;
			for(Arco arco: grafo.verts[j].adjs) 
				PP(arco.no_final);
			pilha.addLast(j);
		}
	}
	public static void PP2(int j) {
		if(!visitado[j]) {
			visitado[j] = true;
			for(Arco arco: grafoTrans.verts[j].adjs) {
				PP2(arco.no_final);
			}
			n++;
		}
	}
	public static int n;
	public static boolean[] visitado;
	public static LinkedList<Integer> pilha = new LinkedList<Integer>();
	public static Grafo grafo;
	public static Grafo grafoTrans;
