			}
			Arrays.fill(visitado, false);
			for(int j=1;j<=nAlunos;j++) PP(j);
			Arrays.fill(visitado, false);
			while(pilha.size()!=0) {
				int j = pilha.removeLast();
				n = 0;
				if(!visitado[j]) PP2(j);
