class krusk {

    int mat[][];
    int nos[][];
    int p;
    int r;
    int na;
    int cnt;
    int custos;
    krusk(int matriz[][],int tnos,int tlig,int zz){
	p = tnos;
	mat = matriz;
	r = tlig;
	nos = new int[p][3];
	na = 0;
	cnt=0;
	custos=zz;
    }

    void principal () {

	//inicio();

	int ii=0;

	quicksort(mat,0,r-1);

	for (int i=0;i<r;i++){
	    if ((findset(mat[i][0])) != (findset(mat[i][1]))){
		ii++;
		cnt += mat[i][2];
		union(mat[i][0],mat[i][1]);
	    }
	}

	if (ii == (p-1)){

	    System.out.println("rendimento optimo:" + (cnt+custos));
	}
	else {System.out.println("impossivel");

	}
    }

    /*
    void inicio() {

	for (int ij=0;ij<p;ij++){
	    nos[ij][0] = 0;
	}
    }
    */
    void makeset(int x) {

	nos[na][0] = x;
	nos[na][1] = 0;
	nos[na][2] = x;
	na++;


    }

    int findset(int x) {

	int ind = find (x);
	if (nos[ind][2] != x) {
	    nos[ind][2] = findset(nos[ind][2]);
	}
	return nos[ind][2];
    }

    int find(int x){

	for(int i=0;i<p;i++){
	    if (nos[i][0]==x){
		return i;	
	    }
	}
	makeset(x);
	return na-1;
    }

    void union (int x,int y){

	link(findset(x),findset(y));
    }

    void link(int x,int y){

	int h = find(x);
	int g = find(y);

	if (nos[h][1] > nos[g][1]){
	    nos[g][2] = nos[h][0];
	}
	else {
	    nos[h][2] = nos[g][0];
	    if (nos[h][1] == nos[g][1]){
		nos[g][1] += 1;
	    }
	}
    }

    void quicksort (int f[][],int pp,int rr){

	if (pp < rr){
	    int q = part(f,pp,rr);
	    quicksort(f,pp,q-1);
	    quicksort(f,q+1,rr);
	}
    }

    int part(int f[][],int pp,int rr){

	int z = f[rr][2];

	int i = pp-1;

	for (int j=pp;j<=rr-1;j++){
	    if (f[j][2] <= z){
		i++;
		int xx = f[i][0];
		int yy = f[i][1];
		int zz = f[i][2];
		f[i][0] = f[j][0];
		f[i][1] = f[j][1];
		f[i][2] = f[j][2];
		f[j][0] = xx;
		f[j][1] = yy;
		f[j][2] = zz;
	    }
	}
	int xx = f[i+1][0];
	int yy = f[i+1][1];
	int zz = f[i+1][2];
	f[i+1][0] = f[rr][0];
	f[i+1][1] = f[rr][1];
	f[i+1][2] = f[rr][2];
	f[rr][0] = xx;
	f[rr][1] = yy;
	f[rr][2] = zz;


	return i+1;

    }
}

