		}


		for(int i=0; i<nS; i++){
			for(int j=0; j<nS; j++){
				if(i!=j){
					soma[i*j] = s[i]+s[j];	
				}

			}
		}

		Arrays.sort(soma);

		int nP = in.nextInt();

		for(int i=0; i<nP; i++){
			int p = in.nextInt();
			int min[] = binary(soma, 0, nS*nS - 1, p);
			if(min[1]==-1)
				System.out.println(min[0]);
			else
				System.out.println(min[0]+" "+min[1]);
		}
	}

	/*pensar melhor sobre isto*/


	public static int[] binary(int array[], int low, int high, int key){
		int difference = Integer.MAX_VALUE;
		int middle;

		int min[]={-1,-1};
		while (low <=high){
			middle = low+(high-low)/2;

			if (Math.abs(array[middle]-key) < difference && array[middle]!=0) {
				difference = Math.abs(array[middle] - key);

				min[0] = array[middle];
				if(Math.abs(array[middle+1]-key)== difference){
					min[1] = array[middle+1];
				}

			}
			if (key - array[middle] < 0) {
				high = middle-1;
			}
			else{
				low = middle+1;
			}
		}
		return min;

	}
}

import java.util.Scanner;

public class MergeSort{

	static void merge(int left[], int right[], int [] result){
		int i = 0, j = 0, k = 0;
		while(j < right.length && i < left.length){
			if(left[i] > right[j]){
				result[k++] = right[j++];
			}
			else{
				result[k++] = left[i++];
			}
		}
		for(int temp = i; temp < left.length; temp++){
			result[k++] = left[temp];
		}
		for(int temp = j; temp < right.length; temp++){
			result[k++] = right[temp];
		}
	}

	static int[] mergesort(int v[]) {
		if(v.length <= 1){
			return v;
		}
		int[] left = new int[v.length/2];
		int[] right = new int[v.length - left.length];
		System.arraycopy(v, 0, left, 0, left.length);
		System.arraycopy(v, left.length, right, 0, right.length);
		mergesort(left);
		mergesort(right);
		merge(left, right, v);
		return v;
	}

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);

		int lenArray = sc.nextInt();
		int v[] = new int[lenArray];
		for(int i = 0; i < lenArray; i++){
			v[i] = sc.nextInt();
		}
		v = mergesort(v);
		for(int i = 0; i < lenArray; i++){
			System.out.print(v[i]+" ");
		}
		System.out.println();
	}
}

