	for(int i=0;i<p;i++){
	    int min=Integer.MAX_VALUE;
	    int index = 0;
	    Arrays.fill(lowers,0);
	    pi=stdin.nextInt();
	    if(bsearch(somas,pi)) {
		System.out.println(pi);
	    }
	    else if(!bsearch(somas,pi)) {
		for(int j=0 ; j<somas.length ; j++) {
		    dist[j] = Math.abs(somas[j]-pi);
		    if(dist[j] < min) {
			min = dist[j];
			lowers[index] = somas[j];
		    }
		    else if(dist[j] == min) {
			index += 1;
			lowers[index] = somas[j];
		    }
		}
		for(int k=0 ; i<lowers.length && lowers[k]!=0 ; k++) {
		    if(index > 0) System.out.print(lowers[k]+" ");
		    else System.out.print(lowers[k]);
		}
		System.out.println();
	    }
	}
    }
}

