        Scanner in=new Scanner(System.in);
        n=in.nextInt();
        pesos= new double[n][n];
        sardas = new No[n];
        double distmin=0;
        for(int i=0; i<n; i++)
            sardas[i]= new No(in.nextDouble(), in.nextDouble());

        for(int i=0; i<n; i++)
            for(int j=0; j<n; j++)
                pesos[i][j]= cdist(sardas[i], sardas[j]);

        prim(0);

        for(int i=0; i<n; i++)
            distmin+=sardas[i].dist;

        System.out.printf("%.2f\n", distmin);


