class Grafo {
    Node lista [];
    int ordem [];

    Grafo (int n) {
        lista = new Node [n];
        ordem = new int [n];
        for (int i = 0; i<n; i++) {
            lista[i] = new Node ();            
        }
    }

    public void criar_lig (int pri, int seg, int custo) {
        lista[pri-1].ligacoes.add(new Lig(seg-1, custo));
        lista[seg-1].ligacoes.add(new Lig(pri-1, custo));        
    }

    public void dij (int origem) {
        LinkedList <Node> aux = new LinkedList <Node> ();
        lista[origem-1].custo_estimado = 0;
        aux.add(lista[origem-1]);

        while (!aux.isEmpty()) {
            Node j = aux.remove();
            for (Lig x : j.ligacoes) {
                if ((j.custo_estimado + x.custo) < lista[x.regiao].custo_estimado ) {
                    lista[x.regiao].custo_estimado = j.custo_estimado + x.custo;         
                }
                if (!lista[x.regiao].visto) {
                    aux.add(lista[x.regiao]);
                }
            }
            j.visto = true;
        }
    }

    public void ordenar (int n) {
        for (int i=0; i<n; i++) {
             int min = 999999;
             int v = 1;
             for (int j = 0; j<n; j++) {
                 if (lista[j].custo_estimado < min && lista[j].visto) {
                     min = lista[j].custo_estimado;
                     v = j+1;
                 }
             }
             lista[v-1].visto = false;
             ordem[i]=v;
        }
    }
}


