	for(int i=0;i<n;i++)
	    nodes[i].father=null;

    }


    public void prim(int s){
	nullAllFathers();
	setAllDistancesAS(1000000000);
	nodes[s].dist=0.0;
	PriorityQueue<Integer> pq = new PriorityQueue<Integer>();
	for (int i=0;i<n ;i++ ) {
	    pq.add(i);
	}
	while(!pq.isEmpty()){
	    int u= pq.poll();
	    for(Edge v : nodes[u].adj){
		if(pq.contains(v.linked.id) && v.weight < v.linked.dist  ){
		    v.linked.father=u;
		    v.linked.dist=v.weight;
		}
	    }
	}
    }
}	

