import java.util.Scanner;

public class Inversoes {

    // Juntar dois arrays ordenados
    // Assumir que os arrays sao v[start..middle] e v[middle+1..end]

    static int merge(int v[], int start, int middle, int end) {
        int i, p1, p2;
        int aux[] = new int[end + 1];
        int count = 0;
        p1 = start;     // "Apontador" do array da metade esquerda
        p2 = middle + 1;  // "Apontador" do array da metade direita
        i = start;    // "Apontador" do array aux[] a conter juncao
        while (p1 <= middle && p2 <= end) {            // Enquanto de para comparar
            if (v[p1] <= v[p2]) {
                aux[i++] = v[p1++];  // Escolher o menor e adicionar
            } else {
                aux[i++] = v[p2++];
                count = count + (middle - start);
            }
        }
        while (p1 <= middle) {
            aux[i++] = v[p1++];     // Adicionar o que resta
        }
        while (p2 <= end) {
            aux[i++] = v[p2++];
        }

        for (i = start; i <= end; i++) {
            v[i] = aux[i];  // Copiar array aux[] para v[]
        }
        return count;
    }

    // Ordenar array v[] com mergesort entre posicoes start e end
    static int mergesort(int v[], int start, int end) {
        int middle, contador=0;
        if (start < end) {                 // Parar quando tamanho do array < 2
            middle = (start + end) / 2;        // Calcular ponto medio
            contador += mergesort(v, start, middle);   // Ordenar metade esquerda
            contador += mergesort(v, middle + 1, end);   // Ordenar metade direita
            contador += merge(v, start, middle, end);// Combinar duas metades ordenadas
        }
        return contador;
    }

    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int v[] = new int[n];

        for (int i = 0; i < n; i++) {
            v[i] = in.nextInt();
        }
        // Ordenar
       // mergesort(v, 0, n - 1);

        // Imprimir
        System.out.print(mergesort(v,0,n-1));

    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Somas {

    static int bsearch(int[] v, int low, int n, int k) {
        int middle = 0;
        while (low < n) {
            middle = low + (n - low) / 2;
            if (k == v[middle]) {
                return middle;
            } else if (k < v[middle]) {
                n = middle - 1;
            } else {
                low = middle + 1;
            }
        }

        middle = low;

        if (middle > 0) {
            if (k - v[middle - 1] < v[middle] - k) {
                return middle - 1;
            }
            if (k - v[middle - 1] == v[middle] - k) {
                System.out.print(v[middle - 1] + " " );
                return middle;
            }
            if (v[middle] - k < k - v[middle - 1]) {
                return middle;
            }
        }

        return middle;
    }

    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int v[] = new int[n];
        //int size = (n * (n - 1)) / 2;
        //int pi;
        int np = 0;

        for (int i = 0; i < n; i++) {
            v[i] = in.nextInt();
            np = np + i;
        }

        int somas[] = new int[np];
        int pos = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                somas[pos] = v[i] + v[j];
                pos++;
            }
        }

        Arrays.sort(somas);

        int p = in.nextInt();
        int resp;
        for (int i = 0; i < p; i++) {
            pos = in.nextInt();
            resp = bsearch(somas, 0, np-1, pos);
            if (resp != -1) {
                System.out.println(somas[resp]);
            } else {
                System.out.println(resp);
            }
        }
    }
}

