	for (int i=0; i<n; i++)
	    v[i] = stdin.nextInt();

	for (int i=0; i<n; i++)
		for (int j=i+1; j<n; j++){
			somas[contador] = v[i]+v[j];
			contador++;
		}

	Arrays.sort(somas);


	int num = stdin.nextInt();

	for (int i = 0; i < num; i++)
		resultados(stdin.nextInt());
	}



}

