	        	if (c == 0) // If the size is the same.
	        	{
	          		c = l2.max - l1.max; // Compares the start of each line.

	        	}
        		return c;
        	}
        });
        int usedLines = 0;
        int current = 0;
        int bestLine = 0;
        int i=0;
        while(current < mainMaxLine)
        {
        	while (i<numberLines && arrayLines[i].min <= current)
			{
				if(arrayLines[i].max >= arrayLines[bestLine].max)
				{
					bestLine = i;
				}
