class Qnode {
    int vert;
    int vertkey;

    Qnode(int v, int key) {
	vert = v;
	vertkey = key;
    }
}

class Heapmin {
    private static int posinvalida = 0;
    int sizeMax,size;

    Qnode[] a;
    int[] pos_a;

    Heapmin(int vec[], int n) {
	a = new Qnode[n + 1];
	pos_a = new int[n + 1];
	sizeMax = n;
	size = n;
	for (int i = 1; i <= n; i++) {
	    a[i] = new Qnode(i,vec[i]);
	    pos_a[i] = i;
	}

	for (int i = n/2; i >= 1; i--)
	    heapify(i);
    }

    int extractMin() {
	int vertv = a[1].vert;
	swap(1,size);
	pos_a[vertv] = posinvalida;  // assinala vertv como removido
	size--;
	heapify(1);
	return vertv;
    }

    void decreaseKey(int vertv, int newkey) {

	int i = pos_a[vertv];
	a[i].vertkey = newkey;

	while (i > 1 && compare(i, parent(i)) < 0) { 
	    swap(i, parent(i));
	    i = parent(i);
	}
    }


    void insert(int vertv, int key)
    { 
	if (sizeMax == size)
	    new Error("Heap is full\n");

	size++;
	a[size].vert = vertv;
	pos_a[vertv] = size;   // supondo 1 <= vertv <= n
	decreaseKey(vertv,key);   // diminui a chave e corrige posicao se necessario
    }

    void write_heap(){
	System.out.printf("Max size: %d\n",sizeMax);
	System.out.printf("Current size: %d\n",size);
	System.out.printf("(Vert,Key)\n---------\n");
	for(int i=1; i <= size; i++)
	    System.out.printf("(%d,%d)\n",a[i].vert,a[i].vertkey);

	System.out.printf("-------\n(Vert,PosVert)\n---------\n");

	for(int i=1; i <= sizeMax; i++)
	    if (pos_valida(pos_a[i]))
		System.out.printf("(%d,%d)\n",i,pos_a[i]);
    }

    private int parent(int i){
	return i/2;
    }
    private int left(int i){
	return 2*i;
    }
    private int right(int i){
	return 2*i+1;
    }

    private int compare(int i, int j) {
	if (a[i].vertkey < a[j].vertkey)
	    return -1;
	if (a[i].vertkey == a[j].vertkey)
	    return 0;
	return 1;
    }


    private void heapify(int i) {
	int l, r, smallest;

	l = left(i);
	if (l > size) l = i;

	r = right(i);
	if (r > size) r = i;

	smallest = i;
	if (compare(l,smallest) < 0)
	    smallest = l;
	if (compare(r,smallest) < 0)
	    smallest = r;

	if (i != smallest) {
	    swap(i, smallest);
	    heapify(smallest);
	}

    }

    private void swap(int i, int j) {
	Qnode aux;
	pos_a[a[i].vert] = j;
	pos_a[a[j].vert] = i;
	aux = a[i];
	a[i] = a[j];
	a[j] = aux;
    }

    private boolean pos_valida(int i) {
	return (i >= 1 && i <= size);
    }
}

public class negocio_eletronico_m {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);

		int nLojas = in.nextInt();
		int dest = in.nextInt();
		Grafo rede = new Grafo(nLojas);

		int reg1 = in.nextInt();
		while (reg1 != -1) {
			int reg2 = in.nextInt();
			int dist = in.nextInt();
			rede.insert_new_arc(reg1, reg2, dist);
			rede.insert_new_arc(reg2, reg1, dist);
			reg1 = in.nextInt();
		}

		boolean[] marked = new boolean[nLojas+1];
		int[] pai = new int[nLojas + 1];
		int[] dist = new int[nLojas + 1];

		for (int i = 0; i < nLojas + 1; ++i) {
			marked[i] = false;
			pai[i] = 0;
			dist[i] = Integer.MAX_VALUE;
		}

		dist[dest] = 0;
		marked[dest] = true;
		Heapmin newHeap = new Heapmin(dist, nLojas);

		LinkedList<Integer> prioList = new LinkedList<Integer>();
		while (newHeap.size > 0) {
			int v = newHeap.extractMin();
			marked[v] = true;
			prioList.add(v);
			LinkedList<Arco> arcList = rede.adjs_no(v);
			for (Arco arc : arcList) {
				int val = arc.valor + dist[v];
				int w = arc.no_final;
				if (marked[w] == false && val < dist[w]) {
					dist[w] = val;
					pai[w] = v;
					newHeap.decreaseKey(w, dist[w]);
				}
			}
		}

		String str = "";
		for (Integer i : prioList)
			str += i + " ";

		System.out.println(str.substring(0, str.length()-1));
	}
}

