import java.util.Scanner;

public class Sardas {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		double coord[][] = new double[n][2];
		for(int l=0; l<n; l++){
			coord[l][0] = in.nextDouble();
			coord[l][1] = in.nextDouble();
		}
		int nos = coord.length;
		double dist[][] = new double[nos][nos];
		for(int i=0; i<nos; i++){
			for(int j=0; j<nos; j++){
				double distance = Math.sqrt((Math.pow(coord[i][0] - coord[j][0], 2) + Math.pow(coord[i][1] - coord[j][1], 2)));
				dist[i][j] = distance;
			}
		}
		boolean arv[] = new boolean[nos];
		double d[] = new double[nos];
		for(int i=0; i<nos; i++){
			d[i] = Double.MAX_VALUE;
			arv[i] = false;
		}
		d[0] = 0;
		double c = 0;
		for(int i=0; i<nos; i++){
			int nmin = -1;
			double min = Double.MAX_VALUE;
			for(int j=0; j<nos; j++){
				if(d[j]<min & arv[j] == false){
					min = d[j];
					nmin = j;
				}
			}
			arv[nmin] = true;
			c += min;
			for(int j=0; j<nos; j++)
				if(dist[nmin][j] < d[j])
					d[j] = dist[nmin][j];
		}
		System.out.println(String.format("%.2f",  c));
	}

}

import java.util.LinkedList;
import java.util.ListIterator;
import java.util.Scanner;

class Qnode {
	int vert;
	int vertkey;

	Qnode(int v, int key) {
		vert = v;
		vertkey = key;
	}
}

class Heapmin {
	private static int posinvalida = 0;
	int sizeMax, size;

	Qnode[] a;
	int[] pos_a;

	Heapmin(int vec[], int n) {
		a = new Qnode[n + 1];
		pos_a = new int[n + 1];
		sizeMax = n;
		size = n;
		for (int i = 1; i <= n; i++) {
			a[i] = new Qnode(i, vec[i]);
			pos_a[i] = i;
		}

		for (int i = n / 2; i >= 1; i--)
			heapify(i);
	}

	int extractMin() {
		int vertv = a[1].vert;
		swap(1, size);
		pos_a[vertv] = posinvalida; // assinala vertv como removido
		size--;
		heapify(1);
		return vertv;
	}

	void decreaseKey(int vertv, int newkey) {

		int i = pos_a[vertv];
		a[i].vertkey = newkey;

		while (i > 1 && compare(i, parent(i)) < 0) {
			swap(i, parent(i));
			i = parent(i);
		}
	}

	void insert(int vertv, int key) {
		if (sizeMax == size)
			new Error("Heap is full\n");

		size++;
		a[size].vert = vertv;
		pos_a[vertv] = size; // supondo 1 <= vertv <= n
		decreaseKey(vertv, key); // diminui a chave e corrige posicao se
									// necessario
	}

	void write_heap() {
		System.out.printf("Max size: %d\n", sizeMax);
		System.out.printf("Current size: %d\n", size);
		System.out.printf("(Vert,Key)\n---------\n");
		for (int i = 1; i <= size; i++)
			System.out.printf("(%d,%d)\n", a[i].vert, a[i].vertkey);

		System.out.printf("-------\n(Vert,PosVert)\n---------\n");

		for (int i = 1; i <= sizeMax; i++)
			if (pos_valida(pos_a[i]))
				System.out.printf("(%d,%d)\n", i, pos_a[i]);
	}

	private int parent(int i) {
		return i / 2;
	}

	private int left(int i) {
		return 2 * i;
	}

	private int right(int i) {
		return 2 * i + 1;
	}

	private int compare(int i, int j) {
		if (a[i].vertkey < a[j].vertkey)
			return -1;
		if (a[i].vertkey == a[j].vertkey)
			return 0;
		return 1;
	}

	private void heapify(int i) {
		int l, r, smallest;

		l = left(i);
		if (l > size)
			l = i;

		r = right(i);
		if (r > size)
			r = i;

		smallest = i;
		if (compare(l, smallest) < 0)
			smallest = l;
		if (compare(r, smallest) < 0)
			smallest = r;

		if (i != smallest) {
			swap(i, smallest);
			heapify(smallest);
		}

	}

	private void swap(int i, int j) {
		Qnode aux;
		pos_a[a[i].vert] = j;
		pos_a[a[j].vert] = i;
		aux = a[i];
		a[i] = a[j];
		a[j] = aux;
	}

	private boolean pos_valida(int i) {
		return (i >= 1 && i <= size);
	}
}

class Arco {
	int no_final;
	int valor;

	Arco(int fim, int v) {
		no_final = fim;
		valor = v;
	}

	int extremo_final() {
		return no_final;
	}

	int valor_arco() {
		return valor;
	}
}

class No {
	// int label;
	LinkedList<Arco> adjs;

	No() {
		adjs = new LinkedList<Arco>();
	}
}

class Grafo {
	No verts[];
	int nvs, narcos;

	public Grafo(int n) {
		nvs = n;
		narcos = 0;
		verts = new No[n + 1];
		for (int i = 0; i <= n; i++)
			verts[i] = new No();
		// para vertices numerados de 1 a n (posicao 0 nao vai ser usada)
	}

	public int num_vertices() {
		return nvs;
	}

	public int num_arcos() {
		return narcos;
	}

	public LinkedList<Arco> adjs_no(int i) {
		return verts[i].adjs;
	}

	public void insert_new_arc(int i, int j, int valor_ij) {
		verts[i].adjs.addFirst(new Arco(j, valor_ij));
		narcos++;
	}

	public Arco find_arc(int i, int j) {
		for (Arco adj : adjs_no(i))
			if (adj.extremo_final() == j)
				return adj;
		return null;
	}

	public int[] dijkstra(int dest) {
		int[] dist = new int[nvs + 1];
		int pai[] = new int[nvs + 1];
		for (int i = 1; i <= nvs; i++) {
			dist[i] = Integer.MAX_VALUE;
		}
		dist[dest] = 0;
		pai[dest] = 0;
		Heapmin Q = new Heapmin(dist, nvs);
		while (Q.size != 0) {
			int v = Q.extractMin();
			if (dist[v] == Integer.MAX_VALUE) {
				dist[v]=-1;
				break;
			}
			ListIterator<Arco> li = verts[v].adjs.listIterator();
			while (li.hasNext()) {
				Arco n = li.next();
				if ((dist[v] + n.valor) < dist[n.no_final]) {
					dist[n.no_final] = dist[v] + n.valor;
					pai[n.no_final] = v;
					Q.decreaseKey(n.no_final, dist[n.no_final]);
				}
			}
		}
			return dist;

	}
}

public class negocioelectronico {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n=sc.nextInt();
		Grafo gr=new Grafo(n);
		int[]vec=new int[n+1];

		int dest=sc.nextInt();
		int a=sc.nextInt();
		while(a!=-1){
			int b=sc.nextInt();
			int p=sc.nextInt();
			gr.insert_new_arc(a, b, p);
			gr.insert_new_arc(b, a, p);
			a=sc.nextInt();
		}
		vec=gr.dijkstra(dest);
		int min=Integer.MAX_VALUE;
		int index=0;
		System.out.print("\n");
		for(int i=1;i<=n;i++){
			for(int j=1;j<=n;j++){
				if((min>vec[j])&&(vec[j]!=-1))
					{
					index=j;
					min=vec[j];
					}

				}
			System.out.print(index+" ");
			vec[index]=-1;
			min=Integer.MAX_VALUE;
		}
	}
}

import java.util.*;

class Piramide{
	public static int verifica(int[][] v, int x, int y, int n){
			if ((x == n-1))
				return 1;
			else if (v[x+1][y]!=-1 && v[x+1][y+1]!=-1 && v[x+1][y]!=0 && v[x+1][y+1]!=0){
				if (x+1 != n-1){
					v[x+1][y] = -1;
					v[x+1][y+1] = -1;}
				return verifica(v, x+1, y, n) + verifica(v, x+1, y+1, n);}
			else if (v[x+1][y]!= -1 && v[x+1][y]!=0){
				if (x+1 != n-1)
					v[x+1][y] = -1;
				return verifica(v, x+1, y, n);}
			else if (v[x+1][y+1]!= -1 && v[x+1][y+1]!=0){
				if (x+1 != n-1)
					v[x+1][y+1] = -1;
				return verifica(v, x+1, y+1, n);}
			return 0;
	}

	public static void main(String[] args){
		Scanner input = new Scanner(System.in);
		int n = input.nextInt();
		int d = input.nextInt();
		int[][] v = new int[n][n];
		for (int i = 0; i < n; i++){
			for (int j = 0; j <= i; j++){
					v[i][j] = 1;
			}
		}

		for (int h = 0; h < d; h++){
			int x = input.nextInt();
			int y = input.nextInt();
			v[n-x][y-1] = 0;
		}

		int c = verifica(v,0,0,n);
		System.out.print(c);
	}
}

