public class Prob16 {
	static final int TAM = 101;
	static int matriz[][] = new int[TAM][TAM];
	static boolean visit[][] = new boolean[TAM][TAM];
	static int l; // numero de linhas
	static int c; // numero de colunas
	static int caracter[] = new int[1000];
	static String str;
	static int somaFalso;
	static int maximo = -1;

	public static void dfs(int l, int c) {
		somaFalso = 0;
		for (int i = 0; i < l; i++) {
			for (int j = 0; j < c; j++) {
				if (visit[i][j] == false) {
					somaFalso++;
					dfs_aux(i, j, l, c, somaFalso);
				}
			}
		}

	}

	public static void dfs_aux(int i, int j, int l, int c, int somaFalso) {
		if (i < l - 1 && i > 0)
			if (j < c - 1 && j > 0)
				if (visit[i][j] == false) {
					visit[i][j] = true;
					if (matriz[i][j] == 1)// se nesta posicao existe um caracter
						caracter[somaFalso]++;
					dfs_aux(i++, j, l, c, somaFalso);
					dfs_aux(i, j--, l, c, somaFalso);
				}

	}

	public static void main(String args[]) {
		Scanner stdin = new Scanner(System.in);
		l = stdin.nextInt();
		c = stdin.nextInt();
		stdin.nextLine();
		for (int i = 0; i < l; i++) {
			str = stdin.nextLine();
			for (int j = 0; j < c; j++) {
				if (str.charAt(j) == '#' || str.charAt(j) == 'P') {
					matriz[i][j] = -1;
					visit[i][j] = true;
				} else if (str.charAt(j) == 'C')
					matriz[i][j] = 1;
				else
					matriz[i][j] = 0;
			}
		}
		dfs(l, c);
		for(int i = 0; i < somaFalso; i++){
			if(maximo < caracter[i])
				maximo = caracter[i];
		}
		System.out.println(maximo);
	}
}

