			    if(meio-1 >= inicio) 
				if(b > a[meio-1]) {
				    verifica(b, meio, a);
				    return;
				}
			    fim = meio;
			}
			else {
			    if(meio+1 <= fim)
				if(b > a[meio] && b < a[meio+1]) {
				    verifica(b, meio, a);
				    return;
				}
			inicio = meio+1;
			}
		    }
	}
