// Exemplo de pesquisa em largura (BFS) num grafo nao dirigido
// (codigo feito na teorica - inclui calculo de distancias)

import java.io.*;
import java.util.*;
import java.util.Arrays;
import java.util.Arrays;

// Classe que representa um no
class Node {
    public LinkedList<Integer> adj; // Lista de adjacencias
    public boolean visited;         // Valor booleano que indica se foi visitao numa pesquisa
    public int distance;            // Distancia do no origem da pesquisa

    Node() {
	adj = new LinkedList<Integer>();
	visited = false;
	distance = -1;
    }
}

// Classe que representa um grafo
class Graph {
    int n;           // Numero de nos do grafo
    Node nodes[];    // Array para conter os nos
    int matrix[][];		//matriz que guarda as distancia minimas

    Graph(int n) {
	this.n = n;
	nodes  = new Node[n+1]; // +1 se os comecam em 1 ao inves de 0
	for (int i=1; i<=n; i++)
	    nodes[i] = new Node();
	matrix = new int[n+1][n+1];

    }


    public void addLink(int a, int b) {
	nodes[a].adj.add(b);
	nodes[b].adj.add(a);
    }

    // Algoritmo de pesquisa em largura
    public void bfs(int v) {
	LinkedList<Integer> q = new LinkedList<Integer>();

	q.add(v);
	nodes[v].visited = true;
	nodes[v].distance = 0;

	while (q.size() > 0) {
	    int u = q.removeFirst();
	    matrix[v][u]= nodes[u].distance;
	    //System.out.println(u + " [dist=" + nodes[u].distance + "]");
	    for (int w : nodes[u].adj)
		if (!nodes[w].visited) {
		    q.add(w);
		    nodes[w].visited  = true;
		    nodes[w].distance = nodes[u].distance + 1; 
		}	    
	}
    }
    public void emptyNode(){
    	for(int i=1; i<=n;i++)
    		nodes[i].visited=false;
    }

    public void printMatrix(int[][] m){
    	for(int i=1; i<=n; i++){
    		System.out.println();
    		for(int j=1; j<=n;j++)
    			System.out.print(m[i][j] + " ");
    	}
    }

    public int excentricidade(int a){
    	int max=0;
    	for(int i=1; i<=n;i++){
    		if(matrix[a][i]>max)
    			max=matrix[a][i];
    	}
    	return max;
    }
}
