                return find(p)==find(q);
            }
        public void union(int p, int q){
                int i = find(p);
                int j = find(q);
                if(i==j)return;
                if(size[i]<size[j]){id[i]=j;size[j]+=size[i];}
                else if(size[j]<size[i]){id[j]=i;size[i]+=size[j];}
                else {id[j]=i;size[i]+=size[j];}
                count--;
                }            
        }
