    class Kruskall{
          int weight=0;
          int siz;
          int cust;
          int nvert;
          private Queue<Arco> mst = new LinkedList<Arco>();
          Heapmax heap;
          Arco[] arcos;
          Union_find uf ;
          Kruskall(int nvs, Heapmax h, Arco[] arc,int custo){
          heap=h;
          arcos=arc;
          uf=new Union_find(nvs+1);
          nvert=nvs;
          cust=custo;
          }
          void exec(){
              while(!heap.isEmpty() && mst.size()<nvert-1){
              int a = heap.extractMin();
              Arco temp = arcos[a-1];
              int v=temp.vert_origem;
              int w=temp.no_final;
              if(!uf.conected(v, w)){
                  uf.union(v, w);
                  mst.offer(temp);
                  weight+=temp.valor;

                }

              }

              siz=mst.size()*cust;
              int temp = weight-siz;
              System.out.println(uf.count() == 2 ? "rendimento optimo: "+temp : "impossivel");

                }

            }


