class Dijkstra{
            int dist[];
            int pai[];
            Grafo grafo;
            Queue<Integer> fila = new LinkedList<Integer>();
            int verti;
            int vertf;
            Heapmax heap;
        Dijkstra(Grafo g , int vert, Heapmax h){ 
            dist = new int[g.nvs+1];
            pai = new int[g.nvs+1];
            grafo=g;
            verti=vert;
            heap=h;
            for (int i = 1; i < dist.length; i++) { dist[i]=Integer.MAX_VALUE;pai[i]=-1;}

        }
        Dijkstra(Grafo g , int vi, int vf){
            dist=new int[g.nvs+1];
            pai=new int[g.nvs+1];
            grafo=g;
            verti=vi;
            vertf=vf;
            for (int i = 1; i < dist.length; i++) { dist[i]=Integer.MAX_VALUE;pai[i]=-1;}
            heap=new Heapmax(dist,dist.length);
            }

        void run(){
             dist[verti]=0;
             heap.decreaseKey(verti, dist[verti]);

            while(!heap.isEmpty() && heap.a[1].vertkey!=Integer.MAX_VALUE){
            int next = heap.extractMin();

            fila.add(next);
            for (Arco c : grafo.verts[next].adjs) {

                     int v = c.no_final;
                     int d=dist[next]+c.valor;
                     if(dist[v]>d){dist[v]=d;pai[v]=next;heap.decreaseKey(v, dist[v]);}
           }
              } 

            while(!fila.isEmpty())
                   if(fila.size()>1) System.out.print(fila.poll()+" ");
                   else System.out.println(fila.poll()); 

        }


}





