class sol{
  Scanner kb;
  sol(Scanner kb){this.kb = kb;}
  int N,src,dst;
  int Lmin, Lmax, Cmin, Cmax, Amin;
  HashMap<Integer,Integer> map = new HashMap<Integer,Integer>();
  HashMap<Integer,Integer> rmap = new HashMap<Integer,Integer>();
  ArrayList<LinkedList<edge>> adj = new ArrayList<LinkedList<edge>>();
  int find_node(int u){
    if(map.containsKey(u)) return map.get(u);
    else{
      adj.add(new LinkedList<edge>());
      int p = map.size();
      //System.out.printf("$$$%d\n",p);
      map.put(u,p);
      rmap.put(p,u);//REMOVER NO FIM
      return p;
    }
  }
  void read(){
    adj.clear();
    map.clear();
    Lmin = kb.nextInt();
    Lmax = kb.nextInt();
    Cmin = kb.nextInt();
    Cmax = kb.nextInt();
    Amin = kb.nextInt();
    src = find_node(kb.nextInt());
    dst = find_node(kb.nextInt());
    while(true){
      int t = kb.nextInt();
      if(t==-1) break;
      int u = find_node(t);
      int v = find_node(kb.nextInt());
      //System.out.printf(">%d %d\n",u,v);
      int l = kb.nextInt();
      int c = kb.nextInt();
      int a = kb.nextInt();
      if(l>=Lmin && c>=Cmin && a>=Amin){
        if(c>Cmax) c = Cmax;
        adj.get(u).add(new edge(v,c));
        adj.get(v).add(new edge(u,c));
      }
    }
    N = map.size();
  }
  void print_graph(){
    for(int u = 0; u < N; u++){
      System.out.printf("%d:",rmap.get(u));
      for(edge e : adj.get(u)){
        System.out.printf(" (%d,%d)",rmap.get(e.dest),e.cap);
      }
      System.out.printf("\n");
    }
  }
  void solve(){
    //print_graph();
    int mat[][] = new int[N][N];
    for(int u = 0; u < N; u++){
      for(edge e : adj.get(u)){
        if(e.cap>mat[u][e.dest]){
          mat[u][e.dest] = e.cap;
        }
      }
    }
    for(int k = 0; k < N; k++){
      for(int u = 0; u < N; u++){
        for(int v = 0; v < N; v++){
          mat[u][v] = Math.max(mat[u][v],Math.min(mat[u][k],mat[k][v]));
        }
      }
    }
    System.out.printf("%d\n",mat[src][dst]);
  }
}

