    sol s = new sol(kb);
    s.read();
    s.solve();
  }
}

import java.util.*;
class NegocioElectronico { 
	static final int inf=Integer.MAX_VALUE;
	static int nlojas;
	static Gnode[] lista;
	static String ordem;

	static class Gnode {
		int id, d;
		Gnode pai;
		LinkedList<Edge> adj;

		Gnode(int id) {
			this.id=id;
			d=inf;
			pai=null;
			adj=new LinkedList<Edge> ();
		}
	}

	static class Edge {
		Gnode d; //destino
		int p;
		Edge(Gnode d, int p) {
			this.d=d;
			this.p=p;
		}
	}

	/**
	 * @param args
	 */
	public static void main(String[] args) {
		int destino, a, b, p;
		Edge tmp;
		Gnode noA, noB;
		Scanner in;

		in=new Scanner(System.in);
		nlojas=in.nextInt();
		destino=in.nextInt();

		lista=new Gnode[nlojas];
		ordem="";

		for(int i=0; i<nlojas; i++)
			lista[i]=new Gnode(i+1);

		boolean terminou=false;

		while(!terminou) {
			a=in.nextInt();
			if(a<0)
				terminou=true;
			else {
				b=in.nextInt();
				p=in.nextInt(); //peso
				noA=lista[a-1];
				noB=lista[b-1];

				tmp=new Edge(noB,p);	
				noA.adj.add(tmp);
				tmp=new Edge(noA,p);
				noB.adj.add(tmp);
			}
		}
		Dijkstra(destino);
		System.out.println(ordem);

	}

	private static void Dijkstra(int destino) {
		lista[destino-1].d=0;
		LinkedList<Gnode> fila=new LinkedList<Gnode> ();

		for(Gnode i: lista)
			fila.add(i);

		while(!fila.isEmpty()) {
			Gnode u=ExtractMin(fila);

			if (ordem.equals(""))
				ordem+=u.id;
			else
				ordem+=" "+u.id;

			for(Edge v: u.adj)
				Relax(u,v.d,v.p);
		}
	}

	private static Gnode ExtractMin(LinkedList<Gnode> fila) {
		int size=fila.size();
		Gnode res=null;
		int min=inf;
		int index=-1;

		for(int i=0; i<size; i++) {
			Gnode tmp=fila.get(i);
			if (tmp.d<min) {
				min=tmp.d;
				res=tmp;
				index=i;
			}
		}
		fila.remove(index);
		return res;
	}

	private static void Relax(Gnode u, Gnode v, int peso) {
		if (v.d>u.d+peso) {
			v.d=u.d+peso;
			v.pai=u;			
		}
	}

}

