class Negocio{
    public static void main(String args[]){
	Scanner in = new Scanner (System.in);

	int nlojas = in.nextInt();
	int source = in.nextInt();
	int[][] mat = new int[nlojas+1][nlojas+1];
	GNode[] grafo = new GNode[nlojas+1];

	for (int i=1; i<=nlojas; i++){
	    grafo[i] = new GNode(i);
	}

	grafo[source].dist = 0;

	int key1 = in.nextInt();
	int key2;
	int w;

	while (key1!=-1){
	    key2 = in.nextInt();
	    w = in.nextInt();
	    mat[key1][key2] = w;
	    mat[key2][key1] = w;

	    key1 = in.nextInt();
	}
	//acaba leitura   
	//dijkstra p ordenar dist lojas
	LinkedList<GNode> fila = new LinkedList<GNode>();
	for(int k=1; k<=nlojas; k++){
	    fila.addFirst(grafo[k]);
	}

	while (fila.isEmpty()!=true){
	    GNode u = extractmin(fila);
	    for (int m=1; m<=nlojas; m++){
		GNode n = grafo[m];
		if (mat[u.key][m]!=0)
		    relax(u,n,mat);
	    }
	    u.determinado = true;

	    if (fila.isEmpty())
		System.out.print(u.key);
	    else
		System.out.print(u.key+" ");
	}
    }


    public static GNode extractmin(LinkedList<GNode> fila){
	int size = fila.size();
	GNode res=null;
	int min=Integer.MAX_VALUE;
	int index=-1;

	for (int i=0; i<size; i++){
	    GNode tmp = fila.get(i);
	    if (tmp.dist==min && res!=null){
		if (tmp.key<res.key){
		    min = tmp.dist;
		    res = tmp;
		    index =i;
		}
	    }
	    if (tmp.dist<min) {

		min = tmp.dist;
		res = tmp;
		index =i;
	    }
	}
	fila.remove(index);
	return res;
    }

    public static void relax(GNode u, GNode v, int[][] mat){
	if (v.dist > (u.dist + mat[u.key][v.key])){
	    v.dist = (u.dist + mat[u.key][v.key]);
	    v.pai = u;
	}
    }
}

