public class Sums {
	public static int[] somas;

	public static int custombinarySearch(int start, int end, int[] v, int key) {

		while (start < end) {
			int mid = start + (end - start)/2;
			if (key == v[mid]) {
				return mid;
			}
			if (key <= v[mid]) {
				end = mid;
			} else {
				start = mid + 1;
			}
		}
		if(v[start] < key) return -1;
		return(end);
	}
	public static int compare(int[] somas,int x,int p) {
		if (somas[x] == p)
			return p;
		else if (x==0)
			return somas[0];
		else {
