public class SomasMaisProximas {

	public static int valorCondicional = 0;
	public static int pesquisar(int[] v, int key){
		valorCondicional = 0;
		int middle, end = v.length, start = 0;
		if(key < v[start]){
			return v[start];
		}
		else if(key >= v[end-1]){
			return v[end-1];
		}
		while(start <= end){
			middle = (start+end)/2;
			if(key == v[middle]){
				return v[middle];
			}
			else if(key < v[middle] && key > v[middle-1]){
				if(v[middle]-key < v[middle-1]-key){
					return v[middle];
				}
				if(v[middle]-key > key-v[middle-1]){
					return v[middle-1];
				}
				else {
					valorCondicional = v[middle];
					return v[middle-1];
				}
			}
			else if(key < v[middle]){
				end = middle-1;
			}
			else {
				start = middle+1;
			}
		}
		return -1;
	}

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);

		int nPerguntas = sc.nextInt();
		sc.nextLine();
		int perguntas[] = new int[nPerguntas];
		for(int i = 0; i < nPerguntas; i++){
			perguntas[i] = sc.nextInt();
		}
		int nQueries = sc.nextInt();
		sc.nextLine();
		int queries[] = new int[nQueries];
		for(int i = 0; i < nQueries; i++){
			queries[i] = sc.nextInt();
		}
		List<Integer> somas = new ArrayList<Integer>();
		for(int i = 0; i < nPerguntas-1; i++){
			for(int j = i+1; j < nPerguntas; j++){
				somas.add(perguntas[i] + perguntas[j]);
			}
		}
		Collections.sort(somas);
		int somasArray[] = new int[somas.size()];

		for(int i = 0; i < somas.size(); i++) 
			somasArray[i] = somas.get(i);

		for(int i = 0; i < nQueries; i++){
			int k = pesquisar(somasArray, queries[i]);			
			if(valorCondicional != 0){
				System.out.println(k + " " + valorCondicional);
			}
			else {
				System.out.println(k);	
			}
		}
	}
}

