class DAA007 {

    static int n, k, l=0; // Combinacoes de 'n', 'k' a 'k'
    static int comb[], s[], somas[];   // Guardar a combinacao em si

    // Funcao recursiva para colocar numero na posicao 'pos',
    // sabendo que nesta posicao podem vir numeros a partir de 'first'
    static void goComb(int pos, int first) {

	// Chegamos ao fim da combinacao, vamos imprimi-la
	if (pos == k) {
        int sum = 0;
	    for (int i=0; i<k; i++) {
        sum += s[comb[i]];
        }
        somas[l] = sum;
        l++;
	}

	// Vamos a meio da combinacao
	// Gerar numero nao usado para colocar nesta posicao
	else {
	    for (int i=first; i<n; i++) {
		comb[pos] = i;
		goComb(pos+1, i+1);
	    }
	}
    }

    static int binom(int n, int k) {

        if (k>n-k) k=n-k;

        int b=1;

        for (int i=1, m=n; i<=k; i++, m--)
            b=b*m/i;

        return b;
    }

    static void bsearch(int v[], int low, int high, int key) {

        int close=0;
        boolean interval = false;

        while (low <= high) {

            int middle = low + (high-low)/2;

            int d1 = Math.abs(key - v[middle]);
            int d2 = Math.abs(key - v[middle+1]);

            if (key == v[middle]) close = v[middle];

