                low = middle+1;
                interval = true;
            }

            if (d1<d2) {

                close=v[middle];
                high = middle-1;
            }

            if (d1>d2) {

                close=v[middle+1];
                low = middle+1;
            }
        }

        if (!interval) System.out.println(close);

        //if (v[low] < key) return -1;
        //return low;
    }

