        //if (Math.abs(key - bsearch(somas,0,high,key)) == Math.abs(key - bsearch(somas,0,high,key))) System.out.println(bsearch(somas,0,high,key-1) + " " + bsearch(somas,0,high,key));
        /*else*/ bsearch(somas,0,high,key);
    }

    public static void main (String args[]) {

        Scanner in = new Scanner(System.in);

