		Double e1 = ((double)this.m)/this.d;
		Double e2 = ((double)e.m)/e.d;
		if(e2.compareTo(e1) != 0)
			return e2.compareTo(e1);
		else
			return this.indice - e.indice;
	}
	public String toString(){
		return this.indice + "";
	}
}

