    public static long solved (Boolean[][] p, int layers) {
	long cont[][]  = new long[1000][1000];
	for (int i=0;i<=layers;i++) {
	    for (int j=0;j<=layers;j++) {
		cont[i][j]=0;
	    }
	}
	for (int j=0;j<=layers;j++) {
	    cont[layers-1][j]=1;
	}
	for (int i=layers-2;i>=0;i--) {
	    for (int j=0;j<layers;j++) {
