public class somas {

	static int bsearch(int [] sum, int low, int high, int key){
		int middle = 0;
		while(low < high){
			middle = low + (high - low)/2;
			if(key == sum[middle])
				return middle;
			else if(key < sum[middle])
				high = middle;
			else low = middle + 1;
		}

		middle = low;
		if(middle > 0){
			if(key - sum[middle-1] < sum[middle] - key)
				return middle-1;
			if(key - sum[middle-1] == sum[middle] - key){
				System.out.print(sum[middle-1] + " " );
				return middle;
			}
			if(sum[middle]-key < key - sum[middle-1])
				return middle;
		}
		return middle;

	}

