	    set[i] = input.nextInt(); 
	    sumsize+=i;
	    i++;
	}


	int[] sums = new int[sumsize];
	for (i=0; i<size; i++){
	    for (j=0; j<i; j++){
	        sums[y] = set[i]+set[j];
	        y++;
	    }
	}
	Arrays.sort(sums);

	int     qsize = input.nextInt();
