class VerticesAdj {//os objectos desta classe serao guardados em listas (cada um e no duma lista). Cada uma das listas tera todos vertices que tem em comum um vertice que que lhes esta ligado no grafo e tambem sera guardado o custo dessas ligacoes (arestas) nos vertices correspondentes.

    int vertice;
    int lmax; //largura maxima
    int cmax; //comprimento maximo
    int hmax; //altura maxima
    VerticesAdj prox;

    VerticesAdj(int v, int l, int c, int h, VerticesAdj p){
	vertice=v;
	lmax=l;
	cmax=c;
	hmax=h;
	prox=p;
    }
}

class Grafo {

    VerticesAdj v[]; //v[i] tem todos os vertices que estao ligados ao vertice i (lista dos vertices adjacentes de i). Os vertices estao numerados de 1 a nverts
    int nverts;

    int lmin; //largura minima que a jaula pode ter
    int lmax; //largura maxima que a jaula pode ter
    int cmin; //comprimento minimo que a jaula pode ter
    int cmax; //comprimento maximo que a jaula pode ter
    int hmin; //altura minima que a jaula pode ter

    /*********************Algoritmo Dijkstra*********************/

    private int comp[]; //comp[i] e o comprimento maximo que a jaula pode ter durante o caminho de um dado vertice ate i
    private int prec[]; //prec[i] e o precedente do vertice i, no caminho de distancia minima (custo minimo) de um dado vertice ate ao vertice i   

    /*********************Algoritmo Dijkstra*********************/

    Grafo(int nv, int ln, int lx, int cn, int cx, int hn){
	nverts=nv;

	v=new VerticesAdj[nv+1];
	for(int i=1;i<=nv;i++)
	    v[i]=null;

	lmin=ln;
	lmax=lx;
	cmin=cn;
	cmax=cx;
	hmin=hn;

	comp=new int[nv+1];
	prec=new int[nv+1];
    }

    void inserirLigacao(int v1, int v2, int l, int c, int h){
	v[v1]=new VerticesAdj(v2,l,c,h,v[v1]);
	v[v2]=new VerticesAdj(v1,l,c,h,v[v2]);
    }

    void comprimentoMax_jaula(int origem, int destino){
	dijkstra(origem);

	if(comp[destino]>cmax)
	    System.out.println("0");
	else
	    System.out.println(comp[destino]);
    }

    /*********************Algoritmo Dijkstra*********************/
    private void dijkstra(int vert){


	int largmax[]=new int[nverts+1];
	int altmax[]=new int[nverts+1];

	for(int i=1;i<=nverts;i++){ 
	    comp[i]=1000; 
	    largmax[i]=0;
	    altmax[i]=0;
	    prec[i]=nverts;
	}

	comp[vert]=0;

	Heap f=new Heap(nverts);
	f.decreaseKey(vert,comp[vert]);

	while(!f.isEmpty()){ 
	    int u=f.extractMin();

	    if(u!=vert && comp[u]>=cmin && comp[u]<=cmax && largmax[u]>=lmin && altmax[u]>=hmin){

		for(VerticesAdj p=v[u];p!=null;p=p.prox){

		    if(p.lmax>=lmin && p.cmax>=cmin && p.hmax>=hmin)
			if(comp[u]<=comp[p.vertice]){

			    largmax[p.vertice]=p.lmax;
			    altmax[p.vertice]=p.hmax;

			    comp[p.vertice]=comp[u];
			    f.decreaseKey(p.vertice,comp[p.vertice]);
			    prec[p.vertice]=u; 
			}
		}
	    }

	    else if(u==vert){	   
		for(VerticesAdj p=v[u];p!=null;p=p.prox){

		    largmax[p.vertice]=p.lmax;
		    altmax[p.vertice]=p.hmax;
		    comp[p.vertice]=p.cmax;
		    f.decreaseKey(p.vertice,comp[p.vertice]);
		    prec[p.vertice]=vert;
		}	
	    }
	}
    }
    /*********************Algoritmo Dijkstra*********************/

}

