	for(int i =1; i<=g.num_vertices(); i++){
	    cap[i]= 0;
	}
	cap[d]=Integer.MAX_VALUE;
	Heapmax hmax = new Heapmax(cap,g.num_vertices());
	while(hmax.size!=0){
