class PQueue{
	int sizeMax, size;
	int pos_a[];
	No a[];

	PQueue(int V) {
		sizeMax=V;
		size=V;
		pos_a=new int[V+1];
		a=new No[V+1];



	}
	boolean BuildTree(int c[]) { // construir a Heap dados os custos
		a[0]=new No(0,0);

		for(int i = 1; i <= sizeMax;i++){

			a[i] = new No(i,c[i]);
			pos_a[i] = i;
	        }

		Maxheapify();
		return true;
	}
	void printQueue() {
		for(int i = 0; i <= size; i++) {
			System.out.println("Valor: " + a[i].vertix + " Prio: " + a[i].peso);
		}
		System.out.println();
	}



	void Maxheapify() {
			for(int i = sizeMax/ 2; i >= 1; i--)
				heapify(i);
	}

	void insert(int v, int key)
	{ 

	  size++;
	  a[size].vertix = v;
	  pos_a[v] = size;   // supondo 0 <= v < n
	  a[size].peso = key;
	  decreaseKey(v,key);   // obriga corrigir posicao
	}


	int compare(int i, int j){
		  if (a[i].peso > a[j].peso)
		    return -1;
		  if (a[i].peso == a[j].peso)
		    return 0;
		  return 1;
	}

	void swap(int i,int j){
		No aux;
		pos_a[a[i].vertix] = j;
		pos_a[a[j].vertix] = i;
		aux = a[i];
		a[i] = a[j];
		a[j] = aux;
	}
	void heapify(int i) {

		  int l, r, smallest;
		  l = 2*i;
		  if (l > size) l = i;
		  r = 2*i+1;
		  if (r > size) r = i;

		  smallest = i;
		  if (compare(l,smallest) < 0) 
		    smallest = l;
		  if (compare(r,smallest) < 0) 
		    smallest = r;

		  if (i != smallest) {
		    swap(i,smallest);
		    heapify(smallest);
		  }
		}


	int extractMin() {
		  int v = a[1].vertix;
		  swap(1,size);
		  size--;
		  heapify(1);
		  return v;
		}

	void decreaseKey(int v, int newkey){
		  int i = pos_a[v];
		  a[i].peso = newkey;

		  while(i > 1 && compare(i,i/2) < 0){
		    swap(i,i/2);
		    i = i/2;
		  }
		}

}
