import java.util.*;

class Grafo {
	Vert verts[];

	Grafo (int n) {
		int i;
		verts = new Vert[n+1];
		for (i=0; i <= n; i++) verts[i] = new Vert(i);
	}

	void addAdj (int x, int y, int l, int c, int a) {
		verts[x].adicionarAdj(y, l, c, a);
	} 
}

class Vert {
	int label;
	Arco adjs;

	Vert (int n) {
		label = n;
		adjs = null;
	}

	void adicionarAdj (int x, int l, int c, int a) {
		Arco aux;
		aux = new Arco(adjs, x, l, c, a);
		adjs = aux;
	}
}

class Arco {
	int proxVert, l, c, a;
	Arco prox;

	Arco (Arco x, int p, int la, int co, int al) {
		proxVert = p;
		l = la;
		c = co;
		a = al;
		prox = x;
	}
}

class Lista {
	Node first;
	int length;

	Lista () {
		length = 0;
		first = null;
	}

	boolean isEmpty () {
		if (length == 0) return true;
		return false;
	} 

	void addNode (int n) {
		Node aux;
		if (length == 0) {
			first = new Node(n, null);
		} else {
			aux = new Node(n, first);
			first = aux;
		}
		length++;
	}

	int removeFirst () {
		int n;
		n = first.val;
		first = first.prox;
		length--;
		return n;
	}

	class Node {
		int val;
		Node prox;

		Node (int v, Node p) {
			val = v;
			prox = p;
		}
	}
}

