import java.util.*;

public class Ordenando {

	public static int[] mergeSort(int [] a){
		if(a.length<=1)
			return a;

		//dividir array
		int[] first = new int[a.length/2];
		int[] second = new int[a.length - first.length];

		//copiar valores do vector a

		System.arraycopy(a, 0, first, 0, first.length);
		System.arraycopy(a, first.length, second, 0, second.length);

		//recursao do metodo
		mergeSort(first);
		mergeSort(second);

		//merge para resultado final
		merge(first, second, a);
		return a;
	}

	public static void merge(int[] first, int second[], int [] result){
		int a = 0; //posicao do vector first
		int b = 0; //posicao do vector second
		int i=0;   //posicao do vector end

		while(a<first.length && b<second.length){
			if(first[a]<second[b]){
				result[i] = first[a];
				a++;
			}
			else{
				result[i] = second[b];
				b++;
			}
			i++;
		}

		System.arraycopy(first, a, result, i, first.length -a);
		System.arraycopy(second, b, result, i, second.length-b);
	}

	public static void main(String[] args){
		Scanner in = new Scanner(System.in);
		int tam = in.nextInt();
		int[] aven = new int[tam];
		for(int i=0; i<tam; i++){
			aven[i] = in.nextInt();
		}
		System.out.println();
		aven = mergeSort(aven);
		for(int i=0; i<tam; i++){
			if(i>0)
				System.out.print(" ");
			System.out.print(aven[i]);
		}
		System.out.println();
	}
}

import java.util.Scanner;

public class negocio {

	/**
	 * @param args
	 */
	public static void main(String[] args) {
		Scanner myScan = new Scanner(System.in);
		int nLojas = myScan.nextInt();
		nLojas++;
		int destino = myScan.nextInt();
		int matriz[][] = new int[nLojas][nLojas];

		int or, dest, custo;
		while (true) {
			or = myScan.nextInt();
			if (or == -1)
				break;
			dest = myScan.nextInt();
			custo = myScan.nextInt();
			matriz[or][dest] = custo;
			matriz[dest][or] = custo;
		}

		for (int k = 1; k < nLojas; k++) {
			for (int i = 1; i < nLojas; i++) {
				for (int j = 1; j < nLojas; j++) {
					if (matriz[i][j] == 0 && i != j)
						matriz[i][j] = 9999;
					matriz[i][j] = Math.min(matriz[i][j], matriz[i][k]
							+ matriz[k][j]);
				}
			}
		}

		int minValue = 9999;
		int index = 0;

		for (int i = 1; i < nLojas; i++) {
			for (int j = 1; j < nLojas; j++) {
				if (matriz[destino][j] < minValue) {
					minValue = matriz[destino][j];
					index = j;
				}
			}

			System.out.printf("%d ", index);
			matriz[destino][index] = 9999;
			index = 0;
			minValue = 9999;
		}

	}

}

