import java.util.*;
import java.io.*;

class Pares implements Comparable<Pares>{
    public int dia, multa, index;
    public float ratio;
    Pares(int d, int m, int i){
	dia = d;
	multa = m;
	index = i;
	ratio = (float)multa/dia;
    }

    @Override
    public int compareTo(Pares p) {
	if(ratio < p.ratio) return 1;
	if(ratio > p.ratio) return -1;
	return 0;
    }

}

