import java.util.*;

class encomenda implements Comparable<encomenda> {
	int d;	//duração
	int m; //multa
	float racio;
	int no;
	encomenda(int a, int b, int c){
		d=a;
		m=b;
		racio = b/a;
		no = c;
	}

	public int compareTo(encomenda n){
		if(racio>n.racio) return -1;
		else if(racio<n.racio) return 1;
		else {
			if(no>n.no) return -1;
			else return 1;
		}
	}
}

