import java.util.*;
import java.io.*;


class sardas{
    double x;
    double y;

    sardas(double x, double y){
	this.x = x;
	this.y = y;
    }

    static double dist(sardas a, sardas b){
	double xm = a.x - b.x;
	double ym = a.y - b.y;

	return (Math.sqrt((xm*xm) + (ym*ym)));
    }
}

class moo21{
