	no n;
	n = new no(0,x,x);
	nos[na] = n;
	na++;
    }

    int findset(int x) {

	int ind = find (x);
	if (x != nos[ind].p){
	    nos[ind].p = findset(nos[ind].p);
	}
	return nos[ind].p;
    }

    int find(int x){

	for(int i=0;i<p;i++){
	    if (nos[i] != null){
		if (nos[i].tag == x){
		    return i;	
		}
	    }
	}
	makeset(x);
	return na-1;
    }

    void union (int x,int y){

	link(findset(x),findset(y));
    }

    void link(int x,int y){

	int h = find(x);
	int g = find(y);

	if (nos[h].rank > nos[g].rank){
	    nos[g].p = nos[h].tag;
	}
	else {
	    nos[h].p = nos[g].tag;
	    if (nos[h].rank == nos[g].rank){
		nos[g].rank += 1;
