import java.util.*;
import java.io.*;

public class SomasMaisProximas {

	public static int valorCondicional = 0;
	public static int pesquisar(int[] v, int key){
		valorCondicional = 0;
		int middle, end = v.length, start = 0;
		if(key < v[start]){
			return v[start];
		}
		else if(key >= v[end-1]){
			return v[end-1];
		}
		while(start <= end){
			middle = (start+end)/2;
			if(key == v[middle]){
				return v[middle];
			}
			else if(key < v[middle] && key > v[middle-1]){
				if(v[middle]-key < key-v[middle-1]){
					return v[middle];
				}
				else if(v[middle]-key > key-v[middle-1]){
					return v[middle-1];
				}
				else {
					valorCondicional = v[middle];
					return v[middle-1];
				}
			}
			else if(key < v[middle]){
				end = middle-1;
			}
			else {
				start = middle+1;
			}
		}
		return -1;
	}

	public static void main(String[] args) throws IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int nPerguntas = Integer.parseInt(br.readLine());
		String perguntas[] = new String[nPerguntas];
		perguntas = br.readLine().split(" ");
		int nQueries = Integer.parseInt(br.readLine());
		String queries[] = new String[nQueries];
		queries = br.readLine().split(" ");
		int somas[] = new int[nPerguntas*((nPerguntas-1))/2];
		int n = 0;
		for(int i = 0; i < nPerguntas-1; i++){
			for(int j = i+1; j < nPerguntas; j++){
				somas[n++] = Integer.parseInt(perguntas[i]) + Integer.parseInt(perguntas[j]);
			}
		}
		Arrays.sort(somas);
		for(int i = 0; i < nQueries; i++){
			int k = pesquisar(somas, Integer.parseInt(queries[i]));			
			if(valorCondicional != 0){
				System.out.println(k + " " + valorCondicional);
			}
			else {
				System.out.println(k);
			}
		}
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Somas {

    static int bsearch(int[] v, int low, int n, int k) {
        int middle = 0;
        while (low < n) {
            middle = low + (n - low) / 2;
            if (k == v[middle]) {
                return middle;
            } else if (k < v[middle]) {
                n = middle - 1;
            } else {
                low = middle + 1;
            }
        }

        middle = low;

        if (middle > 0) {
            if (k - v[middle - 1] < v[middle] - k) {
                return middle - 1;
            }
            if (k - v[middle - 1] == v[middle] - k) {
                System.out.print(v[middle - 1] + " " );
                return middle;
            }
            if (v[middle] - k < k - v[middle - 1]) {
                return middle;
            }
        }

        return middle;
    }

    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int v[] = new int[n];
        //int size = (n * (n - 1)) / 2;
        int pi;
        int np = 0;

        for (int i = 0; i < n; i++) {
            v[i] = in.nextInt();
            np = np + i;
        }

        int somas[] = new int[np];
        int pos = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                somas[pos] = v[i] + v[j];
                pos++;
            }
        }

        Arrays.sort(somas);

        int p = in.nextInt();
        int resp;
        for (int i = 0; i < p; i++) {
            pi = in.nextInt();
            resp = bsearch(somas, 0, np-1, pi);
            if (resp != -1) {
                System.out.println(somas[resp]);
            } else {
                System.out.println(resp);
            }
        }
    }
}

