class sociologia {
	public static void main(String args[]) {
		Scanner in = new Scanner(System.in);

		int n = in.nextInt();

		for (int i = 0; i < n; i++) {
			Grafo g = criaGrafo(in);
			kosarajuAdapt(g, i+1);
		}
	}

	static Grafo criaGrafo(Scanner in) {
		int nalunos = in.nextInt();
		Grafo g = new Grafo(nalunos);

		for (int i = 0; i < nalunos; i++) {
			int v = in.nextInt();
			int nr = in.nextInt();
			for (int j = 0; j < nr; j++) {
				g.insert_new_arc(v, in.nextInt(), 0);
			}
		}

		return g;
	}

	static void kosarajuAdapt(Grafo g, int num) {
		LinkedList<Integer> S = stackDFS(g);
		Grafo gt = gTransposto(g);

		boolean vis[] = new boolean[g.num_vertices()+1];

		int d=0;
		int f=0;

		while (!S.isEmpty()) {
			int v = S.pop();

			int c=0;
			if(!vis[v]) {
				c = DFS_Transposto(gt, v, vis);

				if(c>=4) d++;
				else f+=c;
			}
		}

		System.out.println("Caso #"+num);
		System.out.println(d+" "+f);
	}

	static Grafo gTransposto(Grafo g) {
		Grafo gt = new Grafo(g.num_vertices());

		for (int i = 1; i <= g.num_vertices(); i++) {
			for (Arco a : g.adjs_no(i)) {
				gt.insert_new_arc(a.extremo_final(), i, 0);
			}
		}

		return gt;
	}

	static LinkedList<Integer> stackDFS(Grafo g) {
		LinkedList<Integer> S = new LinkedList<Integer>();
		boolean vis[] = new boolean[g.num_vertices()+1];

		for (int i = 1; i <= g.num_vertices(); i++) {
			if(!vis[i]) {
				stackDFS_Visit(g, i, S, vis);
			}
		}

		return S;
	}

	static void stackDFS_Visit(Grafo g, int v, LinkedList<Integer> S, boolean vis[]) {
		vis[v] = true;

		for (Arco a : g.adjs_no(v)) {
			int w = a.extremo_final();

			if(!vis[w]) {
				stackDFS_Visit(g, w, S, vis);
			}
		}

		S.push(v);
	}

	static int DFS_Transposto(Grafo g, int v, boolean vis[]) {
		vis[v] = true;
		int c = 1;

		for (Arco a : g.adjs_no(v)) {
			int w = a.extremo_final();

			if(!vis[w]) {
				c += DFS_Transposto(g, w, vis);
			}
		}

		return c;
	}
}




class Qnode {
    int vert;
    int vertkey;

    Qnode(int v, int key) {
	vert = v;
	vertkey = key;
    }
}

class Heapmax {
    private static int posinvalida = 0;
    int sizeMax,size;

    Qnode[] a;
    int[] pos_a;

    Heapmax(int vec[], int n) {
	a = new Qnode[n + 1];
	pos_a = new int[n + 1];
	sizeMax = n;
	size = n;
	for (int i = 1; i <= n; i++) {
	    a[i] = new Qnode(i,vec[i]);
	    pos_a[i] = i;
	}

	for (int i = n/2; i >= 1; i--)
	    heapify(i);
    }

    int extractMax() {
	int vertv = a[1].vert;
	swap(1,size);
	pos_a[vertv] = posinvalida;  // assinala vertv como removido
	size--;
	heapify(1);
	return vertv;
    }

    void increaseKey(int vertv, int newkey) {

	int i = pos_a[vertv];
	a[i].vertkey = newkey;

	while (i > 1 && compare(i, parent(i)) > 0) { 
	    swap(i, parent(i));
	    i = parent(i);
	}
    }


    void insert(int vertv, int key)
    { 
	if (sizeMax == size)
	    new Error("Heap is full\n");

	size++;
	a[size].vert = vertv;
	pos_a[vertv] = size;   // supondo 1 <= vertv <= n
	increaseKey(vertv,key);
    }

    void write_heap(){
	System.out.printf("Max size: %d\n",sizeMax);
	System.out.printf("Current size: %d\n",size);
	System.out.printf("(Vert,Key)\n---------\n");
	for(int i=1; i <= size; i++)
	    System.out.printf("(%d,%d)\n",a[i].vert,a[i].vertkey);

	System.out.printf("-------\n(Vert,PosVert)\n---------\n");

	for(int i=1; i <= sizeMax; i++)
	    if (pos_valida(pos_a[i]))
		System.out.printf("(%d,%d)\n",i,pos_a[i]);
    }

    private int parent(int i){
	return i/2;
    }
    private int left(int i){
	return 2*i;
    }
    private int right(int i){
	return 2*i+1;
    }

    private int compare(int i, int j) {
	if (a[i].vertkey < a[j].vertkey)
	    return -1;
	if (a[i].vertkey == a[j].vertkey)
	    return 0;
	return 1;
    }


    private void heapify(int i) {
	int l, r, smallest;

	l = left(i);
	if (l > size) l = i;

	r = right(i);
	if (r > size) r = i;

	smallest = i;
	if (compare(l,smallest) > 0)
	    smallest = l;
	if (compare(r,smallest) > 0)
	    smallest = r;

	if (i != smallest) {
	    swap(i, smallest);
	    heapify(smallest);
	}

    }

    private void swap(int i, int j) {
	Qnode aux;
	pos_a[a[i].vert] = j;
	pos_a[a[j].vert] = i;
	aux = a[i];
	a[i] = a[j];
	a[j] = aux;
    }

    private boolean pos_valida(int i) {
	return (i >= 1 && i <= size);
    }
}


