	}

	static void prim(Grafo g, int c){
		int lucro[] = new int[g.nvs+1];
		boolean vis[] = new boolean[g.nvs+1];
		for (int i = 1; i <= g.nvs; i++) {
			lucro[i] = Integer.MIN_VALUE;
		}
		lucro[1]=0;
		Heapmax h = new Heapmax(lucro, g.nvs);
		int max = 0, nr = -1;
		while(h.size>0){
			int v = h.extractMax();
			vis[v]=true;
			if(lucro[v]==Integer.MIN_VALUE) {
				max = Integer.MIN_VALUE;
				break;
			}
			max+=lucro[v];
			for (Arco a : g.adjs_no(v)) {
				if(lucro[a.extremo_final()]<a.valor && vis[a.extremo_final()]==false){
					lucro[a.extremo_final()]=a.valor;
					h.increaseKey(a.extremo_final(), lucro[a.extremo_final()]);
