	Scanner stdin = new Scanner(System.in);

	n = stdin.nextInt(); //Quantidade de números da minha sequência

	v = new int[n]; // Alocar memoria para a sequência

	for(int i=0;i<n;i++){
	    v[i] = stdin.nextInt();
	}

    }
    //------------------------------------------------------------------

    public static void main(String args[]) {

	readInput();

	//solve1();

	solve2();
    }

}

