public class ProbC{
	public static void main (String args[]){
		Scanner in = new Scanner (System.in);
		int n = in.nextInt();
		boolean [][] matrix = new boolean [n][n];

		int d = in.nextInt();

		for(int i =0; i< d; i++){
			int c = in.nextInt();
			int p = in.nextInt();
			matrix [n-c][p-1] =true; 
		}
		search(matrix,n);
	}

	private static void search(boolean[][] matrix, int n) {
		// TODO Auto-generated method stub
		int i =0, j =0, paths =0;
		paths = search_(matrix, n,i,j,paths);
		System.out.println(paths);

	}

	private static int search_(boolean[][] matrix, int n, int i, int j, int paths) {
		// TODO Auto-generated method stub
		if(i+1==n || j+1 == n){
			return paths +1;

		}
		if(matrix[i+1][j]==false){
			paths=search_(matrix,n,i+1,j,paths);
		}
		if(matrix[i+1][j+1]==false){
			paths=search_(matrix, n, i+1, j+1, paths);
		}
		return paths;
	}
}

