class Graph {
    int n;           // Numero de nos do grafo
    Node nodes[];    // Array para conter os nos
    int[][] matrix;

    Graph(int n) {
	this.n = n;
	nodes  = new Node[n+1]; // +1 se os comecam em 1 ao inves de 0
	matrix = new int[n+1][n+1];
	for (int i=1; i<=n; i++)
	    nodes[i] = new Node();
    }

    public void addLink(int a, int b) {
	nodes[a].adj.add(b);
	nodes[b].adj.add(a);
    }

    // Algoritmo de pesquisa em largura
    public void bfs(int v, int s) {
		LinkedList<Integer> q = new LinkedList<Integer>();
		LinkedList<Integer> q2 = new LinkedList<Integer>();

		q.add(v);
		q2.add(v);

		nodes[v].visited = true;
		nodes[v].distance = 0;

		while (q.size() > 0) {
		    int u = q.removeFirst();
		    //System.out.println("i = " + v + " j = " + u + " val = " + nodes[u].distance);

		    matrix[v][u] = nodes[u].distance;
		   // System.out.println( matrix[v][u] + " na posicao i = " + v + " j = " + u);

		    //System.out.println(u + " [dist=" + nodes[u].distance + "]");
		    for (int w : nodes[u].adj){
				if (!nodes[w].visited) {
			    q.add(w);
			    nodes[w].visited  = true;
			    nodes[w].distance = nodes[u].distance + 1; 
				}	   
			}

    	}

    	nodes[v].visited = false;
		nodes[v].distance = 0;
		for(int i=1; i<=s; i++){
		    for (int w : nodes[i].adj){
				if (nodes[w].visited == true) {
			   		//q.addLast(w);
			   		nodes[w].visited  = false;
			    	nodes[w].distance = 0; 
				}	   
			}
	    }

	}
}

