class Grafo {
	No verts[];
	int nvs, narcos;

	public Grafo(int n) {
		nvs = n;
		narcos = 0;
		verts = new No[n + 1];
		for (int i = 0; i <= n; i++)
			verts[i] = new No();
		// para vertices numerados de 1 a n (posicao 0 nao vai ser usada)
	}

	public int num_vertices() {
		return nvs;
	}

	public int num_arcos() {
		return narcos;
	}

	public LinkedList<Arco> adjs_no(int i) {
		return verts[i].adjs;
	}

	public void insert_new_arc(int i, int j, int valor_ij) {
		verts[i].adjs.addFirst(new Arco(j, valor_ij));
		narcos++;
	}

	public Arco find_arc(int i, int j) {
		for (Arco adj : adjs_no(i))
			if (adj.extremo_final() == j)
				return adj;
		return null;
	}

	public int[] dijkstra(int dest) {
		int[] dist = new int[nvs + 1];
		int pai[] = new int[nvs + 1];
		for (int i = 1; i <= nvs; i++) {
			dist[i] = Integer.MAX_VALUE;
		}
		dist[dest] = 0;
		pai[dest] = 0;
		Heapmin Q = new Heapmin(dist, nvs);
		while (Q.size != 0) {
			int v = Q.extractMin();
			if (dist[v] == Integer.MAX_VALUE) {
				dist[v]=-1;
				break;
			}
			ListIterator<Arco> li = verts[v].adjs.listIterator();
			while (li.hasNext()) {
				Arco n = li.next();
				if ((dist[v] + n.valor) < dist[n.no_final]) {
					dist[n.no_final] = dist[v] + n.valor;
					pai[n.no_final] = v;
					Q.decreaseKey(n.no_final, dist[n.no_final]);
				}
			}
		}
			return dist;

	}
}

