import java.util.Scanner;


// Estrutura para representar um no da arvore
class Node {
    boolean isBlack; // Nó preto?
    boolean isNull;  // Nó nulo?
    int value;       // Valor
    Node left, right; // Filhos

    Node(int v) {
	isNull  = (v==0);
	isBlack = (v>=0);
	value   = Math.abs(v);
    }
}
public class DAA_016 {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

	int n =  in.nextInt(); //quantidade de árvores a considerar

	for (int i=0; i<n; i++) {

	Node root = PREORDER(in);

	    if(rootProperty(root) && redProperty(root) && blackProperty(root) && isBST(root))

                System.out.println("SIM"); //árvore é uma red-black tree
            else

                System.out.println("NAO"); //árvore não é uma red-black tree
	}
    }

    // Ler input em preorder
    static Node PREORDER(Scanner in) {
	int v = in.nextInt();
	Node aux = new Node(v);
	if (v!=0) {
	    aux.left  = PREORDER(in);
	    aux.right = PREORDER(in);
	}
	return aux;
    }

    // Menor valor da arvore
    static int min(Node t) {
	if (t.isNull) return Integer.MAX_VALUE;
	int minLeft  = min(t.left);
	int minRight = min(t.right);
	return Math.min(t.value, Math.min(minLeft, minRight));
    }

    // Maior valor da arvore
     static int max(Node t) {
	if (t.isNull) return Integer.MIN_VALUE;
	int minLeft  = max(t.left);
	int minRight = max(t.right);
	return Math.max(t.value, Math.max(minLeft, minRight));
    }

    // Quantidade de nos (internos)
      static int tamanho(Node t) {
	if (t.isNull) return 0;
	return 1 + tamanho(t.left) + tamanho(t.right);
    }





    //A raíz da árvore é preta
    static boolean rootProperty(Node t) {
	if (t.isBlack) return true; 
	return false;
    }

    // Os filhos de um nó vermelho são pretos
    static boolean redProperty(Node t) {
        if(t.isNull)
            return true;
        if(!(t.isBlack)) {
            if (!(t.left.isBlack) || !(t.right.isBlack))
                return false;
	    else
		return redProperty(t.left) && redProperty(t.right);         
	}
        return redProperty(t.left) && redProperty(t.right);
    }


    //Para cada da nó, um caminho para qualquer uma das suas folhas descendentes tem o mesmo número de nós pretos
    static boolean blackProperty(Node t){
	int left = blackPropertyCounter(t.left);
	int right = blackPropertyCounter(t.right);
	if(left==-1 || right==-1)
	    return false ;
	if( left == right )
	    return true;
	else
	    return false;
    }

   static int blackPropertyCounter(Node t){ //funçao deita com ajuda
	if(t.isNull) 
	    return 0;
	int left = blackPropertyCounter(t.left);
	int right = blackPropertyCounter(t.right);
	if( left == -1 || right == -1 )
	    return -1 ;
	if( left == right ){
	    if(t.isBlack)
        	return (left+1);
	    else
        	return (left);
	}
	else
	    return -1;
    }


    static boolean isBST(Node t) {
        if (t.isNull)
            return true;
        if (t.left != null && (t.value) < (max(t.left))) //nós descendentes à sua esquerda tem de ser menores
            return false;
        if (t.right != null && (t.value) > (min(t.right))) //nós descendentes á sua direita tem de ser maiores
            return false;
        return isBST(t.left) && isBST(t.right);
    }


}

