class Grafo{
	int nreg;
	int dest;
	No n[];
	int pesos[][];


	Grafo(int nr, int d){
		nreg = nr;
		dest = d;
		n = new No[nreg+1];
		pesos = new int [nreg+1][nreg+1];

	}

	void inicializar(){
		for(int i=1; i<=nreg; i++){
			n[i] = new No(i);
		}
	}

	void criarGrafo(int p1, int p2, int dt){
		pesos[p1][p2] = dt;
		pesos[p2][p1] = dt;
		n[p1].adicionarLigacao(n[p2]);
		n[p2].adicionarLigacao(n[p1]);
	}

	void Dijkstra(){
		LinkedList<No> Q = new LinkedList<No>();
		LinkedList<No> S = new LinkedList<No>();;
		for(int i=1; i<n.length; i++){
			Q.addLast(n[i]);
		}
		n[dest].peso = 0;

		while(!Q.isEmpty()){
			No u = extract_Min(Q);
			S.addLast(u);

			for(int i=0; i<u.adj.size(); i++){
				int v = u.adj.get(i).valor;
				int d = u.peso + pesos[u.valor][v];
				if(n[v].peso > d){
					n[v].peso = d;
				}
			}
		}
		for(int i=0; i<S.size(); i++){
			if(i == (S.size()-1)){
				System.out.print(S.get(i).valor);
				System.out.println();
			}
			else{
				System.out.print(S.get(i).valor + " ");
			}
		}
	}

	private No extract_Min(LinkedList<No> Q){
		int min_peso = Integer.MAX_VALUE;
		int index = 0;
		No valor = new No(0);
		for(int i=0; i<Q.size(); i++){
			No tmp = Q.get(i);
			if(tmp.peso < min_peso){
				min_peso = tmp.peso;
				index = i;
				valor = Q.get(i);
			}
		}
		Q.remove(index);
		return valor;
	}	
}


