			sardas[u].used = true;

			custo+= min; 


			for (int v=0;v<nS ;v++ ) {
				if ( (sardas[v].used == false) && (distancias[u][v] ) < sardas[v].dist ){ sardas[v].dist = distancias[u][v];  }
			}


		}

		return custo;

	}



