    void inicio() {

	for (int ij=0;ij<p;ij++){
	    nos[ij][0] = 0;
	}
    }

    void makeset(int x) {

	nos[na][0] = x;
	nos[na][1] = 0;
	nos[na][2] = x;
	na++;


    }

    int findset(int x) {

	int ind = find (x);
	if (nos[ind][2] != x) {
	    nos[ind][2] = findset(nos[ind][2]);
	}
	return nos[ind][2];
    }

    int find(int x){

	for(int i=0;i<p;i++){
	    if (nos[i][0]==x){
		return i;	
	    }
	}
	makeset(x);
	return na-1;
    }

    void union (int x,int y){

	link(findset(x),findset(y));
    }

    void link(int x,int y){

	int h = find(x);
	int g = find(y);

	if (nos[h][1] > nos[g][1]){
	    nos[g][2] = nos[h][0];
	}
	else {
	    nos[h][2] = nos[g][0];
	    if (nos[h][1] == nos[g][1]){
		nos[g][1] += 1;
	    }
	}
    }
    /*
    int min(int pp,int f[][]){

	int ind = 0;
	int i =0;

	while (f[i][2] == 0){
	    i++;
	    if (i==(pp-1)){break;}
	}


	int min = f[i][2];
	for (int b=i;b<pp;b++) {

	    if (min >= f[b][2] && f[b][2] != 0){
		min = f[b][2];
		ind = b;
	    }
	}

	return ind;
    }
    */

    void quicksort (int f[][],int pp,int rr){

	if (pp < rr){
	    int q = part(f,pp,rr);
	    quicksort(f,pp,q-1);
	    quicksort(f,q+1,rr);
	}
    }

    int part(int f[][],int pp,int rr){

	int z = f[rr][2];

	int i = pp-1;

	for (int j=pp;j<=rr-1;j++){
	    if (f[j][2] <= z){
		i++;
		int xx = f[i][0];
		int yy = f[i][1];
		int zz = f[i][2];
		f[i][0] = f[j][0];
		f[i][1] = f[j][1];
		f[i][2] = f[j][2];
		f[j][0] = xx;
		f[j][1] = yy;
		f[j][2] = zz;
	    }
	}
	int xx = f[i+1][0];
	int yy = f[i+1][1];
	int zz = f[i+1][2];
	f[i+1][0] = f[rr][0];
	f[i+1][1] = f[rr][1];
	f[i+1][2] = f[rr][2];
	f[rr][0] = xx;
	f[rr][1] = yy;
	f[rr][2] = zz;


	return i+1;

    }
}

