		int[] locais = new int[30];
		i=0;
		valor = std.nextInt();
		while(valor!=0)
		{
			if(!existe(valor,locais))
				locais[i] = valor;
			else
				locais = apaga(valor,locais,i);
			i++;
			valor = std.nextInt();
		}
		for(int j=0;j<30;j++)
			if(locais[j]>0)
				System.out.println(locais[j]);
	}

	static boolean existe(int valor, int[] locais){
		for(int i=0;i<30;i++)
			if(valor==locais[i])
				return true;
		return false;
	}

	static int[] apaga(int valor, int[] locais,int n){
		for(int i=0;i<30;i++)
		{

			if(valor==locais[i])
			{
				for(int j=i+1;j<n;j++)
					locais[j] = 0;
				return locais;
			}
		}
		return locais;
	}
}

