class fila {

    int size;
    Node first;
    Node last;

    fila () {
	size = 0;
	first=last=null;
    }

    void addlast (Node x) {

	if (size==0) {
	    first = last = x;
	}
	else if (size==1) {

	    first.next = x;
	    last = x;
	}
	else {
	    last.next=x;
	    last=x;
	}
	size++;
    }

    Node remove () {

	Node tmp = first;
	first=first.next;
	size--;
	return tmp;
    }

}

