class Grafo {

	LinkedList<Node> total;

	Grafo() {
		total = new LinkedList<Node>();
	}

	void colocaGrafo(int n) {
		total.add(new Node(n));
	}

	void adicionaLigacao(int o, int d, int valor) {
		for (Node n : total)
			if (n.num == o) {
				n.ligacoes.add(d);
				n.pesos.add(valor);
			}
	}

	void Prim(Node i) {
		int count = 0;
		int max = 0;
		Node Maximo = null;
		i.peso = 0;
		LinkedList<Node> fila = new LinkedList<Node>();
		for (Node n : total)
			fila.add(n);
		while (fila.isEmpty() == false) {
			for (Node l : fila) {
				if (l.peso >= max) {
					max = l.peso;
					Maximo = l;
				}
			}
			if (Maximo != null) {
				for (int k : Maximo.ligacoes) {
					for (Node f : total)
						if (k == f.num)
							if (fila.contains(f) && Maximo.pesos.get(count) > f.peso) {
								f.pai = Maximo;
								f.peso = Maximo.pesos.get(count);
							}
					count++;
				}
			}
			else
				break;
			count = 0;
			fila.remove(Maximo);
			Maximo = null;
			max = 0;
		}
	}

}

