		Dimension d = new Dimension(w,l,h);
		Edge e1 = new Edge(e,d);
		Edge e2 = new Edge(s,d);
		g.get(s).add(e1);
		g.get(e).add(e2);
	    }
	}
    }

    int handles(int s){
	if(t.containsKey(s))
	    return t.get(s);
	else{
	    index++;
	    g.add(new ArrayList<Edge>());
	    t.put(s,index);
	    return index;
	}
