class Estudantes{

	String primeiro_nome;
	String apelido;
	int    nota;

	Estudantes(String x, String y, int z){
		primeiro_nome = x;
		apelido = y;
		nota = z;
	}		
}


class ComparadorNota implements Comparator<Estudantes>{
	@Override
	public int compare(Estudantes a, Estudantes b){

		if (a.nota == b .nota){
			if (a.primeiro_nome.compareTo(b.primeiro_nome) == 0 ){
				return a.apelido.compareTo(b.apelido); 
			}
			else{
				return a.primeiro_nome.compareTo(b.primeiro_nome); 
			}
		}

		else{
			return a.nota > b.nota ? -1 : a.nota == b.nota ? 0: 1;
		}

	}
}

class ComparadorAlfa implements Comparator<Estudantes> {
	@Override
