public class RedeBiologica {    
    static Grafo lergrafo(Scanner in){
	Grafo g;
	int nNos = in.nextInt(); 
	int nRamos = in.nextInt(); 
	int noInicio, noFim;
	g = new Grafo(nNos);		
	for(int i=0; i<nRamos; i++){	
	    noInicio = in.nextInt();
	    noFim = in.nextInt();
	    g.insert_new_arc(noInicio, noFim);
	    g.insert_new_arc(noFim, noInicio);
	}
	return g;
    }

    static int distmin(Grafo g,int noOrigem,int destino) {
	int d[] = new int[g.nvs+1];
	boolean visitado[] = new boolean[g.nvs+1];
	for (int u = 0; u < g.nvs+1 ; u++){ 
	    visitado[u] = false; 
	}   
	visitado[noOrigem] = true; 
	d[noOrigem] = 0;
	LinkedList<Integer>fila = new LinkedList<Integer>(); 
	fila.add(new Integer (noOrigem));
	while (!fila.isEmpty()) {
	    Integer aux = (Integer)fila.removeFirst() ; int u = aux.intValue(); 
	    for(Arco a: g.adjs_no(u)){
		int v = a.extremo_final();
		if(!visitado[v]){
		    visitado[v] = true; 
		    d[v] = d[u] + 1;
		    if(v==destino)
			return d[v];
		    fila.addLast(new Integer (v));
		}
	    }
	}
	return -1;
    }

    public static void main(String[] args) {
	Scanner in = new Scanner(System.in);
	Grafo g= lergrafo(in);
	int matr[][] = new int[g.nvs+1][g.nvs+1];
	for(int i=1;i<=g.nvs;i++){
	    for(int j=1;j<=g.nvs;j++){
		if(i==j)
		    matr[i][j]=0;
		else
		    matr[i][j]=distmin(g,i,j);		    
	    }
	}
	int exc[]=new int[g.nvs+1];
	for(int i=1;i<=g.nvs;i++){
	    for(int j=1;j<=g.nvs;j++){
		if(matr[i][j]>exc[i])
		    exc[i]=matr[i][j];
	    }
	}
	int diam=exc[1];
	for(int k=2;k<=g.nvs;k++){
	    if(exc[k]>diam)
		diam=exc[k];
	}
	int raio=exc[1];
	for(int k=2;k<=g.nvs;k++){
	    if(exc[k]<raio)
		raio=exc[k];
	}
	System.out.println(diam);
	System.out.println(raio);
	for(int k=1;k<=g.nvs;k++){
	    if(exc[k]==raio)
		System.out.print(k+" ");
