import java.util.ArrayList;
import java.util.Scanner;

class encomenda {
	static class Gnode {
		int val;
		int d;
		ArrayList<Edge> adj;

		Gnode(int val) {
			this.val=val;
			d=Integer.MIN_VALUE;
			adj=new ArrayList<Edge> ();
		}
	}
	static class Edge {
		Gnode dest; //destino
		int p; //peso

		Edge(Gnode dest, int p) {
			this.dest=dest;
			this.p=p;
		}
	}

	/**
	 * @param args
	 */

	private static ArrayList<Gnode> list;
	public static void main(String[] args) {
		Scanner in;
		int lmin, lmax, cmin, cmax, amin;
		int origem, destino;
		int plmax, pcmax, pamax;

		boolean terminou;
		int a, b;

		list=new ArrayList<Gnode> ();
		in=new Scanner(System.in);
		lmin=in.nextInt();
		lmax=in.nextInt();
		cmin=in.nextInt();
		cmax=in.nextInt();
		amin=in.nextInt();
		origem=in.nextInt();
		destino=in.nextInt();
		terminou=false;

		while(!terminou) {
			a=in.nextInt();
			if(a==-1)
				terminou=true;
			else {
				b=in.nextInt();
				plmax=in.nextInt();
				pcmax=in.nextInt();
				pamax=in.nextInt();
				if(plmax>=lmin && plmax<=lmax && pcmax>=cmin && pcmax<=cmax && pamax>=amin)
					inserirPercurso(a,b,pcmax);
			}
		}
		Dijkstra(origem, destino);
	}

	private static void Dijkstra(int origem, int destino) {
		int res=Integer.MAX_VALUE;
		changeDist(origem, 0);

		while(!list.isEmpty()) {
			Gnode u=extractMax(list);

			if(u.d>0 && u.d<res)
				res=u.d;
			if(u.val==destino)
				break;

			for(Edge v: u.adj)
				relax(u,v.dest,v.p);
		}
		System.out.println(res);
	}

	private static void relax(Gnode u, Gnode v, int p) {
		if(u.d==0)
			v.d=p;
		else
			v.d=min(u.d,p);
	}

	private static int min(int d, int i) {
		if(d<i)
			return d;
		return i;
	}

	private static Gnode extractMax(ArrayList<Gnode> list) {
		int size=list.size();
		Gnode res=null;
		int max=-1;
		int index=-1;

		for(int i=0; i<size; i++) {
			Gnode tmp=list.get(i);
			if (tmp.d>max) {
				max=tmp.d;
				res=tmp;
				index=i;
			}
		}
		list.remove(index);
		return res;
	}

	private static void changeDist(int key, int k) throws RuntimeException {
		Gnode tmp;
		boolean found=false;
		int n=list.size();

		for(int i=0; i<n && !found; i++) {
			tmp=list.get(i);
			if(tmp.val==key) {
				tmp.d=k;
				list.set(i, tmp);
				found=true;
			}	
		}

		if(!found)
			throw new RuntimeException("key not in list");
	}

	private static void inserirPercurso(int a, int b, int pcmax) {
		int n=list.size();
		Gnode tmp;
		Gnode    nodeA,  nodeB;
		int		  indA,   indB;
		boolean foundA, foundB;

		nodeA=nodeB=null;
		indA=indB=-1;
		foundA=foundB=false;

		for(int i=0; i<n; i++) {
			tmp=list.get(i);
			if(tmp.val==a) {
				foundA=true;
				nodeA=tmp;
				indA=i;
			}
			else if (tmp.val==b) {
				foundB=true;
				nodeB=tmp;
				indB=i;
			}

			if(foundA && foundB)
				break;
		}

		if(!foundA)
			nodeA=new Gnode(a);
		if(!foundB) 
			nodeB=new Gnode(b);

		nodeA.adj.add(new Edge(nodeB, pcmax));
		nodeB.adj.add(new Edge(nodeA, pcmax));

		if(!foundA)
			list.add(nodeA);
		else
			list.set(indA, nodeA);
		if(!foundB)
			list.add(nodeB);
		else
			list.set(indB, nodeB);
	}

}

