	public static int[] binary(int array[], int low, int high, int key){
		int result[]={-1,-1};
		while(low <= high){
			int middle = low + (high-low)/2;

			if(key == array[middle]){
				result[0] = array[middle];
				return result;
			}
			else if(key < array[middle]){
				high = middle -1;
				result[1]=array[high];
			}
			else{
				low = middle+1;
				result[0]=array[low];
			}
		}
		return result;


