		nos=n;
		ligacoes=l;
		custo1=c;
		Ligacoes=new Node[nos+1];
		G=new int[nos+1][nos+1];
	}

	void inicializa(){
		for(int i=1; i <= nos;i++){
			Ligacoes[i]=new Node(i);
		}
	}

