	nullAllFathers();
	setAllDistancesAS(1000000000);
	nodes[s].dist=0.0;
	PriorityQueue<Integer> pq = new PriorityQueue<Integer>();
	for (int i=0;i<n ;i++ ) {
	    pq.add(i);
	}
	while(!pq.isEmpty()){
