		{
			for(int l=0; l<matrixDim; l++)
			{
					// IF XY ...
					if(matrix[c][l])
					{
						for(int colSearch=0;colSearch<matrixDim;colSearch++)
						{
							if(matrix[l][colSearch]) // ... AND YZ
								matrix[c][colSearch] = true; // XZ

							if(matrix[colSearch][c]) // ... AND ZX
								matrix[colSearch][l] = true; // ZY								
						}
					}				
			}
		}
	}
