public class main {

	public static void Dijkstra(Grafo g, int t) {
		int numVertices = g.num_vertices();
		int dist[] = new int[numVertices + 1];
		for (int i = 1; i <= numVertices; i++) {
			dist[i] = Integer.MAX_VALUE;
		}

		dist[t] = 0;
		Heapmin q = new Heapmin(dist, numVertices-1);

		int v = 0, w = 0, dvw = 0;

		int index = 0;

		while (!q.isEmpty()) {
			v = q.extractMin();
			if (dist[v] != Integer.MAX_VALUE) {
				for (Arco a : g.adjs_no(v)) {
					w = a.extremo_final();
					dvw = a.valor_arco();
					if (dist[w] > dist[v] + dvw) {
						dist[w] = dist[v] + dvw;
						q.decreaseKey(w, dist[w]);
					}
				}
			}
			if (index == 0) {
				System.out.print(v);
			} else {
				System.out.print(" " + v);
			}
			index++;
		}
	}

	public static void main(String[] args) {

		Scanner stdin = new Scanner(System.in);

		int nRegioes = stdin.nextInt();
		int destino = stdin.nextInt();

		int reg1 = 0;
		int reg2 = 0;
		int dist = 0;

		Grafo g = new Grafo(nRegioes + 1);

		while ((reg1 = stdin.nextInt()) != -1) {
			reg2 = stdin.nextInt();
			dist = stdin.nextInt();

			g.insert_new_arc(reg1, reg2, dist);
			g.insert_new_arc(reg2, reg1, dist);
		}
		Dijkstra(g, destino);
		System.out.println();
	}
}

import java.util.*;

class Node {

	int num;
	int peso;
	LinkedList<Node> ligacoes;
	boolean visitado;

	Node(int n, int p) {
		num = n;
		peso = p;
		ligacoes = new LinkedList<Node>();
		visitado = false;
	}
}

class Grafo {

	LinkedList<Node> arvore;
	LinkedList<Node> arvoreMinima;

	Grafo() {
		arvore = new LinkedList<Node>();
		arvoreMinima = new LinkedList<Node>();
	}

	void colocaGrafo(int n) {
		arvore.add(new Node(n, 0));
	}

	void adicionaLigacao(int o, int d, int valor) {
		for (Node n : arvore)
			if (n.num == o)
				n.ligacoes.add(new Node(d, valor));
	}

	void Prim(int ini) {
		LinkedList<Node> fila = new LinkedList<Node>();
		for(Node i : arvore)
			if(i.num == 1){
				i.peso = 0;
				fila.add(i);
			}
		while (fila.isEmpty() == false) {
			Node NoMax = new Node(0, -1);
			for (Node l : fila)
				if (l.peso >= NoMax.peso)
					NoMax = l;
			fila.remove(NoMax);
			for (Node n : NoMax.ligacoes) {
				for (Node t : arvore) {
					if (t.num == n.num) {
						if (n.peso > t.peso && t.visitado == false) {
							t.peso = n.peso;
							if (fila.contains(t) == false)
								fila.add(t);
						}
					}
				}
			}
			for (Node t : arvore)
				if (t.num == NoMax.num)
					t.visitado = true;
			arvoreMinima.add(new Node(NoMax.num, NoMax.peso));
		}
	}
}

public class OticaMinimalista {
	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);
		int custo = 0;

		int nNos = in.nextInt();
		int nLig = in.nextInt();
		int manutencao = in.nextInt();
		Grafo grafo = new Grafo();

		for (int i = 1; i <= nNos; i++) {
			grafo.colocaGrafo(i);
		}

		for (int i = 0; i < nLig; i++) {
			int n1 = in.nextInt();
			int n2 = in.nextInt();
			int peso = in.nextInt();
			grafo.adicionaLigacao(n1, n2, peso);
			grafo.adicionaLigacao(n2, n1, peso);
		}
		if (nLig < nNos - 1)
			System.out.println("impossivel");

		else {
			grafo.Prim(1);

			if (grafo.arvoreMinima.size() < nNos)
				System.out.println("impossivel");
			else {
				for (Node n : grafo.arvoreMinima)
					custo += n.peso;
				System.out.println("rendimento optimo: "
						+ (custo - ((nNos - 1) * manutencao)));
			}
		}
	}
}

