class Node  {
    int valor;
    LinkedList <Integer> amigos;
    boolean visto;

    Node (int n) {
        valor = n;
        amigos = new LinkedList <Integer> ();
        visto = false;
    }
}

class Grafo {
    int ngrupos, nfora, aux;
    Node lista [];
    Node trans [];
    Stack <Node> pilha;

    Grafo (int n) {
        ngrupos = 0;
        nfora = 0;
        aux = 0;
        lista = new Node [n];
        trans = new Node [n];
        pilha = new Stack<Node> ();

        for (int i=0; i<n ; i++) {
            lista[i] = new Node (i);
            trans[i] = new Node (i);
        }
    }

    public void DFS () {
        for (Node i : lista) {
            if (!i.visto) {
                DFS_Visit(i);
            }
        }
    }

    public void DFS_Visit (Node i) {
        i.visto = true;
        for (int k : i.amigos) {
            if (!lista[k].visto) {
                DFS_Visit(lista[k]);
            }
        }
        pilha.push(trans[i.valor]);
    }

    public void DFS_T () {
        while (!pilha.isEmpty()) {
            Node a = pilha.pop();
            if (!trans[a.valor].visto) {
                DFS_TVisit(a);
                if (aux>3) 
                    ngrupos++;
                else 
                    nfora+=aux;
                aux = 0;
            }
        }
    }

    public void DFS_TVisit (Node i) {
        i.visto = true;
        for (int k : i.amigos) {
            if (!trans[k].visto) {
                DFS_TVisit(trans[k]);
            }
        }
        aux++;
    }
}
