import java.util.*;

/*********************Fila de prioridade*********************/
class Vertice {
    int vert;
    int chave;

    Vertice(int v,int c){
	vert=v;
	chave=c;
    }
}

class Heap {
    Vertice fila_p[]; //fila de prioridade. Tem dimensao igual ao numero de vertices do grafo
    int pos_v[]; //pos_v[i] e o indice de posicao do vertice i na fila de prioridade. Tem dimensao igual ao numero de vertices do grafo
    int nverts; //indica o numero de vertices que a fila de prioridade tem. Quando o i=nverts, fila_p[i] contem o elemento que esta no fim da fila

    Heap(int nv){
	fila_p=new Vertice[nv+1];
	pos_v=new int[nv+1];

	for(int i=0;i<=nv;i++){
	    fila_p[i]=new Vertice(i,0);
	    pos_v[i]=i;
	}

	nverts=nv;
    }

    boolean isEmpty(){
	return nverts==0;
    }

    private int compare(int i, int j){ //compara os vertices que estao na fila de prioridade na posicao i e j. A funcao retorna 1 se o vertice que esta em i tem prioridade superior ao que esta em j, -1 se tem inferior ou 0 se ambos sao iguais (o que nunca ira acontecer)
	if(fila_p[i].chave>fila_p[j].chave)
	    return 1;
	if(fila_p[i].chave<fila_p[j].chave)
	    return -1;
	if(fila_p[i].vert<fila_p[j].vert)
	    return 1;
	if(fila_p[i].vert>fila_p[j].vert)
	    return -1;
	return 0;
    }

    private void troca(int i, int pai_i){ //troca o vertice que tinha a posicao i com o seu pai que tinha posicao pai_i na heap
	int v1=fila_p[i].vert, v2=fila_p[pai_i].vert;
	pos_v[v1]=pai_i;
	pos_v[v2]=i;

	Vertice aux=fila_p[pai_i];
	fila_p[pai_i]=fila_p[i];
	fila_p[i]=aux;
    }

    private void heapify(int i){ //no inicio, o vertice que esta na posicao i da heap, esta na raiz, ou seja, i=1. Este vertice vai descer da arvore, caso este nao respeite a ordencao correcta da heap
	int fesq=i*2; //posicao do filho esquerdo (se existir) do vertice que esta na posicao i, na fila de prioridade 
	int fdir=i*2+1; //posicao do filho direito (se existir) do vertice que esta na posicao i, na fila de prioridade
	int max=i; //posicao do vertice que tem maior chave dos 3 vertices que estao a ser comparados, ou entao caso todos tenham a mesma chave e a posicao do que tem vertice menor, na fila de prioridade

	if(fesq<=nverts && compare(fesq,max)>0)
	    max=fesq;
	if(fdir<=nverts && compare(fdir,max)>0)
	    max=fdir;

	if(max!=i){
	    troca(max,i);
	    heapify(max); //na verdade, faz-se o heapify no vertice que tinha anteriormente a posicao i na heap, mas agora o i ja e o valor de fmin, devido a troca que foi feita
	}
    }

    void increaseKey(int v,int cnova){ //aumenta a chave do vertice i na heap e, consequentemente, podera ser necessario repor as condicoes iniciais de ordenacao
	int i=pos_v[v];
	fila_p[i].chave=cnova;

	while(i>1 && compare(i,i/2)>0){ //i>1 porque i=1 e a raiz da arvore da fila de prioridade
	    troca(i,i/2);
	    i=i/2;
	}
    }

    int extractMax(){ //retira o primeiro elemento da heap, que esta na posicao 1 e retorna esse valor. Como consequencia, a heap fica alterada e e necessario repor as suas condicoes iniciais de ordenacao 
	int vmax=fila_p[1].vert;
	fila_p[1]=fila_p[nverts];

	pos_v[vmax]=0;
	pos_v[fila_p[1].vert]=1;
	pos_v[fila_p[nverts].vert]=0;

	heapify(1);
	nverts--;
	return vmax;
    }
}
/*********************Fila de prioridade*********************/

class VerticesAdj {//os objectos desta classe serao guardados em listas (cada um e no duma lista). Cada uma das listas tera todos vertices que tem em comum um vertice que que lhes esta ligado no grafo e tambem sera guardado o custo dessas ligacoes (arestas) nos vertices correspondentes.

    int vertice;
    int cmax; //comprimento maximo
    VerticesAdj prox;

    VerticesAdj(int v, int c, VerticesAdj p){
	vertice=v;
	cmax=c;
	prox=p;
    }
}

class Grafo {

    VerticesAdj v[]; //v[i] tem todos os vertices que estao ligados ao vertice i (lista dos vertices adjacentes de i). Os vertices estao numerados de 1 a nverts
    int nverts;

    int cmax; //comprimento maximo que a jaula pode ter

    /*********************Algoritmo Dijkstra*********************/

    private int comp[]; //comp[i] e o comprimento maximo que a jaula pode ter durante o caminho de um dado vertice ate i
    private int prec[]; //prec[i] e o precedente do vertice i, no caminho de distancia minima (custo minimo) de um dado vertice ate ao vertice i   

    /*********************Algoritmo Dijkstra*********************/

    Grafo(int nv, int cm){
	nverts=nv;

	v=new VerticesAdj[nv+1];
	for(int i=1;i<=nv;i++)
	    v[i]=null;

	cmax=cm;

	comp=new int[nv+1];
	prec=new int[nv+1];
    }

    void inserirLigacao(int v1, int v2, int c){
	v[v1]=new VerticesAdj(v2,c,v[v1]);
	v[v2]=new VerticesAdj(v1,c,v[v2]);
    }

    void comprimentoMax_jaula(int origem, int destino){
	dijkstra(origem);
	System.out.println(comp[destino]);
    }

    /*********************Algoritmo Dijkstra*********************/
    private int comprimento_Min(int c1, int c2){
	if(c1<c2)
	    return c1;
	return c2;
    }

    private void dijkstra(int vert){

	for(int i=1;i<=nverts;i++){ 
	    comp[i]=0; 
	    prec[i]=nverts;
	}

	comp[vert]=cmax;

	Heap f=new Heap(nverts);
	f.increaseKey(vert,comp[vert]);

	while(!f.isEmpty()){ 
	    int u=f.extractMax();

	    for(VerticesAdj p=v[u];p!=null;p=p.prox)
		if(comprimento_Min(comp[u],p.cmax)>comp[p.vertice]){
		    comp[p.vertice]=comprimento_Min(comp[u],p.cmax);
		    f.increaseKey(p.vertice,comp[p.vertice]);
		    prec[p.vertice]=u; 
		}
	}

    }
    /*********************Algoritmo Dijkstra*********************/

}

