import java.util.*;

class No {
	int comp;
	int val;

	No(int v) {
		val = v;
		comp = 0;
	}
}

class Caminho {
	int maxLarg, maxComp, maxAlt;
	int origem, destino;

	Caminho(int l, int c, int a, int o, int d) {
		maxLarg = l;
		maxComp = c;
		maxAlt = a;
		origem = o;
		destino = d;
	}
}

class Grafo {
	LinkedList<No> nos;
	LinkedList<Caminho> caminhos;

	Grafo() {
		nos = new LinkedList<No>();
		caminhos = new LinkedList<Caminho>();
	}

	void AdicionaNo(int v) {
		for (No i : nos) {
			if (i.val == v)
				return;
		}
		nos.add(new No(v));
	}

	void AdicionaCaminho(int l, int c, int a, int o, int d) {
		caminhos.add(new Caminho(l, c, a, d, o));
		caminhos.add(new Caminho(l, c, a, o, d));
	}
}

public class Encomenda {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		Grafo grafo = new Grafo();

		int minLarg = in.nextInt();
		int maxLarg = in.nextInt();
		int minComp = in.nextInt();
		int maxComp = in.nextInt();
		int minAlt = in.nextInt();

		int origem = in.nextInt();
		int destino = in.nextInt();

		int a = in.nextInt();

		while (a != -1) {
			int b = in.nextInt();
			int larg = in.nextInt();
			int comp = in.nextInt();
			int alt = in.nextInt();

			grafo.AdicionaNo(a);
			grafo.AdicionaNo(b);
			grafo.AdicionaCaminho(larg, comp, alt, a, b);

			a = in.nextInt();
		}

		// Dijkstra
		LinkedList<No> nos = new LinkedList<No>();
		for (No i : grafo.nos) {
			if (i.val == origem)
				i.comp = maxComp;
			nos.add(i);
		}

		while (!nos.isEmpty()) {
			// EXTRACT-MAX
			No maximo = new No(0);
			maximo.comp = 0;
			for (No i : nos)
				if (maximo.comp <= i.comp)
					maximo = i;
			nos.remove(maximo);

			for (Caminho c : grafo.caminhos) {
				if (c.origem == maximo.val) {
					if (ExisteNo(nos, c.destino) && c.maxAlt >= minAlt && c.maxComp >= minComp && c.maxLarg >= minLarg) {
						int iOrig = EncontraNo(grafo.nos, c.origem);
						int iDest = EncontraNo(grafo.nos, c.destino);
						int mComp = Math.min(grafo.nos.get(iOrig).comp, c.maxComp);

						grafo.nos.get(iDest).comp = Math.max(mComp, grafo.nos.get(iDest).comp);
					}
				}
			}
		}
		System.out.println(grafo.nos.get(EncontraNo(grafo.nos, destino)).comp);
	}

	static boolean ExisteNo(LinkedList<No> nos, int v) {
		for (No i : nos)
			if (i.val == v)
				return true;
		return false;
	}

	static int EncontraNo(LinkedList<No> nos, int v) {
		for (int i = 0; i < nos.size(); i++) {
			if (nos.get(i).val == v)
				return i;
		}
		return -1;
	}
}

import java.util.*;
import java.io.*;

public class Prob06{

	//É chamada para cada valor chave
	public static void PesquisaBinaria(int sum[], int inicio, int fim, int chave){

		int meio=inicio;

        //Se o valor for menor que a primeira soma
        if(chave <= sum[inicio])
            System.out.println(sum[0]);

        //Se o valor for maior que a ultima soma
        else if(chave >= sum[fim])
            System.out.println(sum[fim]);

        else{
            while(inicio<fim){
                meio = inicio+(fim-inicio)/2;		//posição do meio

                if(chave <= sum[meio]) 				//Se o valor for menor que a pos meio, divide-se o array
                	fim=meio;						//fim passa a ser a posição do meio

                else 
                	inicio=meio+1;					//Senão inicio passa a ser a posição seguinte ao meio
            }

            //Se chave = soma mais proxima
            int centro = Math.abs(sum[inicio] - chave);
            //Se chave < soma mais proxima
            int esquerda = Math.abs(sum[inicio-1] - chave);
            //Se chave > soma mais proxima
            int direita;
            if(inicio + 1 <= fim) 
            	direita = Math.abs(sum[inicio+1] - chave);
            else
            	direita=-1;

            //Se ambas as somas se encontram a mesma distancia
            //ordena a soma por ordem crescente
            if(esquerda == centro && sum[inicio-1] != sum[inicio])
                System.out.println(sum[inicio-1] + " " + sum[inicio]); 
            else if(direita != -1 && centro == direita && sum[inicio] != sum[inicio + 1])
                System.out.println(sum[inicio] + " " + sum[inicio+1]);

            //Se a soma é menor que o valor de chave
            else if(esquerda < centro)
                System.out.println(sum[inicio-1]);

            //Se a soma é maior que o valor de chave
            else if(direita!=-1 && direita < centro)
                System.out.println(sum[inicio+1]);

            //Se a soma for o valor de chave
            else
                System.out.println(sum[inicio]);
        }
	}

	public static void main(String args[]){
		Scanner inp = new Scanner(System.in);

		int n  = inp.nextInt();
		int v[] = new int [n];

		int n2, chave=0;

		//le o array v
		for(int i=0; i<n; i++){
			v[i]=inp.nextInt();
		}

		//Array soma 
		int nSomas = (n*(n-1))/2;
		//nSomas são todas as somas de elementos diferentes sem repetições
		int sum[] = new int [nSomas];

		int k=0; 
		//Faz todas a somas possiveis com o array v
		for(int i=0; i<n; i++){
			for(int j=i+1; j<n; j++){
				sum[k++] = v[i]+v[j];
			}
		}

		//ordena o array soma
		Arrays.sort(sum);

		//Com o array soma ordenado le cada valor chave e faz pesquisa binaria para encontrar a solução pedida
		n2 = inp.nextInt();
		for(int i=0;i<n2; i++){
			chave=inp.nextInt();
			PesquisaBinaria(sum, 0, nSomas-1, chave);
		}

	}
}

