import java.util.*;
class segmento implements Comparable<segmento>{
	int l;
	int r;
	int visitado = 0;
	segmento(int a, int b){
		l=a;
		r=b;
	}

	@Override
	public int compareTo(segmento m){
		if(l<m.l) return -1;
		else if(l>m.l) return +1;
		else {
			if(r>m.r) return -1;
			else return +1;
		}

	}
}


