public class Negocio {


    public static void main(String[] args) {
        Scanner stdin = new Scanner(System.in);
        int nlojas = stdin.nextInt();
        int source = stdin.nextInt();
        int [][] mat = new int[nlojas+1][nlojas+1];
        No [] grafo = new No[nlojas+1];

        for(int i=0; i<=nlojas; i++) {
            grafo[i] = new No(i);
        }

        grafo[source].dist = 0;

        int key1 = stdin.nextInt();
        int key2;
        int w;

        while(key1!=-1) {

            key2 = stdin.nextInt();
            w = stdin.nextInt();
            mat[key1][key2] = w;
            mat[key2][key1] = w;

            key1 = stdin.nextInt();

        }

        LinkedList<No> fila = new LinkedList<No>();
        for(int k=1; k<=nlojas; k++) {

            fila.addFirst(grafo[k]);

        }

        while(fila.isEmpty()!=true) {

            No u = extractmin(fila);
            for (int m=1; m<=nlojas; m++) {

                No n = grafo[m];
                if(mat[u.key][m]!=0) {
                    relax(u,n,mat);
                }
                u.determinado = true;
            }
            if(fila.isEmpty()) {
                System.out.print(u.key);

            }
            else {
                System.out.print(u.key + " ");
            }

        }

    }

    public static No extractmin(LinkedList<No> fila) {
        No min = new No(0);
        LinkedList<No> fila2 = new LinkedList<No>();
        while(!fila.isEmpty()) {
            No teste = fila.removeFirst();
            if(teste.dist < min.dist) {
                min = teste;
            }
            fila2.addLast(teste);
        }        
        while(!fila2.isEmpty()) {
            No test = fila2.removeFirst();
            if(test != min) {
                fila.addFirst(test);
            }
        } 
        return min;




    }

    public static void relax(No u, No v, int[][] mat) {
        if(v.dist > (u.dist + mat[u.key][v.key])) {
            v.dist = (u.dist + mat[u.key][v.key]);
            v.pai = u;
        }
    }

}

import java.util.Arrays;
import java.util.Scanner;

public class Somas {

    static int bsearch(int v[], int low, int n, int k) {

        int middle;

        while (low < n) {
            middle = low + (n - low) / 2;
            if (k == v[middle]) {
                return middle;
            } else if (k < v[middle]) {
                n = middle - 1;
            } else {
                low = middle + 1;
            }
        }

        middle = low;

        if (middle > 0 && middle < n) {
            if (k - v[middle - 1] < v[middle] - k) {
                return middle - 1;
            }
            if (k - v[middle - 1] == v[middle] - k) {
                return middle;
            }
            if (v[middle] - k < k - v[middle - 1]) {
                return middle;
            }
        }
        if (middle >= n) {
            middle = n - 1;
        }

        return middle;
    }

    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int v[] = new int[n];
        int size = (n * (n - 1)) / 2;
        int somas[] = new int[size];
        int pos = 0;
        int pi;
        int resp;

        for (int i = 0; i < n; i++) {
            v[i] = in.nextInt();
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - 1; j++) {
                somas[pos++] = v[i] + v[j];
            }
        }
        Arrays.sort(somas);

        int p = in.nextInt();
        for (int i = 0; i < p; i++) {
            pi = in.nextInt();
            resp = bsearch(somas, 0, n, pi);
            if (resp != -1) {
                System.out.println(somas[resp]);
            } else {
                System.out.println(resp);
            }
        }

    }
}

