}


class Grafo{
	int nreg;
	int dest;
	No n[];
	int pesos[][];


	Grafo(int nr, int d){
		nreg = nr;
		dest = d;
		n = new No[nreg+1];
		pesos = new int [nreg+1][nreg+1];

	}

	void inicializar(){
		for(int i=1; i<=nreg; i++){
			n[i] = new No(i);	
		}
		n[dest].peso = 0;
	}

	void criarGrafo(int p1, int p2, int dt){
		pesos[p1][p2] = dt;
		pesos[p2][p1] = dt;
	}

	void Dijkstra(){
		LinkedList<No> Q = new LinkedList<No>();
		for(int i=1; i<n.length; i++){
			Q.addFirst(n[i]);
		}

		while(Q.isEmpty()!=true){
			No u = extract_Min(Q);

			for(int j=1; j<n.length; j++){
				No v = n[j];
				if(pesos[u.valor][j] != 0)
					if(v.peso > (u.peso + pesos[u.valor][v.valor])){
						v.peso = (u.peso + pesos[u.valor][v.valor]);
						v.pai = u;
					}
			}
			u.visitado = true;

			if(Q.isEmpty())
				System.out.print(u.valor);
			else
				System.out.print(u.valor + " ");
		}

	}

	private No extract_Min(LinkedList<No> Q){
		 No min = new No(0);

		 LinkedList<No> S = new LinkedList<No>();
		 while(!Q.isEmpty()){
			 No tmp = Q.removeFirst();
			 if(tmp.peso < min.peso)
				 min = tmp;
			 S.addLast(tmp);
		 }
		 while(!S.isEmpty()){
			 No tmp = S.removeFirst();
			 if(tmp != min)
				 Q.addFirst(tmp);
		 }
		 return min;
	}	
}


