public class Optica {
	public static void main(String [] args){
		Scanner in = new Scanner(System.in);
		int nnos=in.nextInt();
		int nligacoes=in.nextInt();
		int custo=in.nextInt();
		Grafo g= new Grafo(nnos+1);
		int index=0;
		int first=0;
		for(int i=0; i<nligacoes;i++){
			int no1=in.nextInt();
			int no2=in.nextInt();
			if(index==0){
				first=no1;
				index=1;
			}
			int no3=in.nextInt();
			g.insert_new_arc(no1,no2,no3-custo);
			g.insert_new_arc(no2,no1,no3-custo);
		}
		prim(g,first);
	}

	private static void prim(Grafo g, int first) {
		int dist[] = new int[g.nvs+1];
		LinkedList<Integer> visitados = new LinkedList<Integer>();
		for(int i=1;i<=g.nvs;i++){
			dist[i]=Integer.MIN_VALUE;
			dist[first]=0;
		}
			Heapmax h= new Heapmax(dist,g.nvs-1);
			int sum=0,m=0;
			while(h.size>0){
				m=h.extractMin();
				if(dist[m]!=Integer.MIN_VALUE){
					for(Arco a: g.adjs_no(m)){
						if(a.valor_arco()>dist[a.extremo_final()] && !visitados.contains(a.extremo_final())){
							//visitados.add(a.extremo_final());
							dist[a.extremo_final()] =a.valor_arco();
							h.decreaseKey(a.extremo_final(), dist[a.extremo_final()]);
						}
					}
				}
				visitados.add(m);
				sum+=dist[m];

			}
			if (dist[m] == Integer.MIN_VALUE)
				System.out.println("impossivel");
			else
				System.out.println("rendimento optimo: " + sum);


	}
}

