class NegocioEletronico {

	public static void main(String[] args) {
		Scanner moo = new Scanner(System.in);
		int lojas = moo.nextInt();
		int destino = moo.nextInt();

		Grafo g = new Grafo(lojas);

		int vA = moo.nextInt();
		while (vA != -1) {
			int vB = moo.nextInt();
			int peso = moo.nextInt();
			g.insert_new_arc(vA, vB, peso);
			g.insert_new_arc(vB, vA, peso);

			vA = moo.nextInt();
		}
		int[] caminho = new int[lojas+1];
		caminho = Dijkstra(g, destino);
		System.out.print(destino);
		for (int i = 1,j=1; i < caminho.length; i++) {
			if(caminho[i]==j){
				System.out.print(" "+i);
				j++;
				i=0;
			}
		}
		System.out.println();

	}

	private static int[] Dijkstra(Grafo g, int destino) {
		int[] dist = new int[g.nvs + 1];
		int[] pai = new int[g.nvs + 1];
		for (int i = 0; i < dist.length; i++) {
			pai[i] = -1;
		}
		for (int i = 0; i < dist.length; i++) {
			dist[i] = Integer.MAX_VALUE;
		}
		dist[destino] = 0;

		Heapmin Q = new Heapmin(dist, g.nvs);
		int count=0;
		while (Q.size != 0) {

			int v = Q.extractMin();

			pai[v]=count;
			count++;
			for (Arco w : g.adjs_no(v)) {
				if (dist[w.no_final] > w.valor+dist[v]) {
					dist[w.no_final] = w.valor+dist[v];

					Q.decreaseKey(w.no_final, dist[w.no_final]);
				}
			}
		}
		return pai;
	}
}

import java.util.*;

public class Prob05 {

	static int merge(int v[], int start, int middle, int end) {
		int i, p1, p2;
		int aux[] = new int[end + 1];
		int cnt = 0;

		p1 = start; // "Apontador" do array da metade esquerda
		p2 = middle + 1; // "Apontador" do array da metade direita
		i = start; // "Apontador" do array aux[] a conter juncao

		while (p1 <= middle && p2 <= end) {
			if (v[p1] <= v[p2])
				aux[i++] = v[p1++];
			else
				aux[i++] = v[p2++];

			cnt = cnt + ((middle + 1) - p1);
		}
		while (p1 <= middle) {
			aux[i++] = v[p1++]; // Adicionar o que resta
		}
		while (p2 <= end) {
			aux[i++] = v[p2++];
		}
		for (i = start; i <= end; i++)
			v[i] = aux[i]; // Copiar array aux[] para v[]

		return cnt;
	}

	static int mergesort(int v[], int start, int end) {
		int cnt = 0, middle;

		if (start < end) {
			middle = (start + end) / 2;

			cnt += mergesort(v, start, middle);
			cnt += mergesort(v, middle + 1, end);
			cnt += merge(v, start, middle, end);

			return cnt;
		} else
			return 0;
	}

	public static void main(String args[]) {

		Scanner stdin = new Scanner(System.in);

		int n = stdin.nextInt();
		int v[] = new int[n];
		for (int i = 0; i < n; i++)
			v[i] = stdin.nextInt();

		int cnt = mergesort(v, 0, n - 1);

		System.out.println(cnt);
	}
}

