		int mid=0;

		while(low<high){

			mid=low+(high-low)/2;

			if(q==v[mid]){			return mid;}
			else if(q < v[mid]){	high=mid;	}
			else 					low=mid+1;
		}


		mid=low;
		if(mid>0){
			if(q-v[mid-1] < v[mid]-q){return mid-1;} 
			else if(q-v[mid-1] == v[mid]-q){System.out.print(v[mid-1] + " "); return mid;}
			else if(q-v[mid-1] > v[mid]-q){return mid;}
