class Arco implements Comparable<Arco> {
	int vertexA, vertexB;
	int peso;

	public Arco(int vA, int vB, int p) {
		vertexA = vA;
		vertexB = vB;
		peso = p;
	}

	public int getVertexA() {
		return vertexA;
	}

	public int getVertexB() {
		return vertexB;
	}

	public int getpeso() {
		return peso;
	}

	public int compareTo(Arco Arcoe) {
		if (this.peso > Arcoe.peso)
			return 1;
		else
			return -1;

	}
}


class Grafo {
	int nvs;
	LinkedList<LinkedList<Integer>> grafo = new LinkedList<LinkedList<Integer>>();
	LinkedList<Arco> kruskalArcoes = new LinkedList<Arco>();

	Grafo(int n) {
		nvs = n;
		for (int i = 1; i <= n; i++) {
			LinkedList<Integer> lista = new LinkedList<Integer>();
			lista.add(i);
			grafo.addLast(lista);

		}

	}

	public LinkedList<Arco> getedges() {
		return kruskalArcoes;
	}

	LinkedList<Integer> findSet(int vertex) {
		for (LinkedList<Integer> lista : grafo) {
			if (lista.contains(vertex)) {
				return lista;
			}
		}
		return null;
	}

	public void kruskal(Stack<Arco> edges) {
		while (!edges.isEmpty()) {
			if (kruskalArcoes.size() == nvs - 1)
				break;
			Arco edge = edges.pop();
			int vertexA = edge.getVertexA();
			int vertexB = edge.getVertexB();

			LinkedList<Integer> listaA = findSet(vertexA);
			LinkedList<Integer> listaB = findSet(vertexB);

			if (listaA != listaB) {
				listaA.addAll(listaB);
				grafo.remove(listaB);
				kruskalArcoes.add(edge);
			}
//			System.out.println(grafo.size() + " grafo");
//			System.out.println(kruskalArcoes.size() + " kruskal");
		}
	}
}

