class Enc{
	static int nDestinos;
	static LinkedList<Local> locais;
	static Local getLocalByID(int id){
		for(Local l : locais)
			if(l.id==id)
				return l;
		nDestinos++;
		Local l = new Local(id);
		locais.add(l);
		return l;

	}

	static Local getMax(){
		Local max = new Local(0);
		for(Local l : locais)
			if(!l.visitado && l.cMax>max.cMax)
				max = l;
		return max;
	}
