				if(x==origem){
					lOrigem = lX;
					//System.out.println(lOrigem.id);
				}
				else if(x==destino)
					lDestino = lX;
				if(y==origem)
					lOrigem = lY;
				else if(y==destino)
					lDestino = lY;
				lX.destinos.add(new Destino(lY, c));
