	int cont = 0;
	if(inicio < fim) {
	    meio = (inicio+fim)/ 2;
	    cont += mergesort(v, inicio, meio);
	    cont += mergesort(v, meio+1, fim);
	    cont += merge(v, inicio, meio ,fim);
	}
	return cont;
}

    static int merge(int v[], int inicio, int meio, int fim) {
	int i, p1, p2;
	int aux[] = new int[fim+1];
