class Edge{
	Node 	start, end;	
	double  peso;




	Edge(Node x, Node y){
		start	  = x;
		end	  = y;
		this.peso = Math.sqrt(((start.x - end.x) * (start.x -end.x)) + ((start.y - end.y)*(start.y - end.y)));
	}




}
class Graph {
    int n;           // Numero de nos do grafo
    Node nodes[];    // Array para conter os nos
    Edge edges[];

    Graph(int n) {
	this.n = n;
	nodes  = new Node[n+1]; // +1 se os comecam em 1 ao inves de 0


    }

    public double peso(int x, int y){

    	double p = Math.sqrt(((nodes[x].x - nodes[y].x) * (nodes[x].x - nodes[y].x)) + ((nodes[x].y - nodes[y].y)*(nodes[x].y - nodes[y].y)));
	return p;

    }
    // Algoritmo de pesquisa em largura







	public void Prim(int v) {
	LinkedList<Integer> q = new LinkedList<Integer>();

	for(int i=1; i<=n; i++){
		nodes[i].distance = Double.MAX_VALUE;
		q.add(i);
	}
	nodes[v].distance = 0;
	double min = Double.MAX_VALUE;
	int u = 0;
	int menor = 0;
	while (q.size() > 0) {
		min = Double.MAX_VALUE;
	    for(int i=1; i<=n; i++)
		if(q.contains(i) && nodes[i].distance < min){
			min = nodes[i].distance;
			menor = i;
		}

	    q.removeFirstOccurrence(menor);
		u = menor;

	    for (int w : nodes[u].adj) {
		double p = peso(u, w);
		if (q.contains(w) && p < nodes[w].distance)  {
		    nodes[w].pai = u;
		    nodes[w].distance = p;
		}	

	    }

	}

    }
}
