class GraphF{
	int tempo, npessoas;
	NoF g[];
	NoF gt[];
	LinkedList<Integer> grupos;

	GraphF(int np){
		this.npessoas = np;
		tempo = 0;
		g = new NoF[np+1];
		gt = new NoF[np+1];
		grupos = new LinkedList<Integer>();
	}
	private void inicializar(){
		for(int i = 1; i<=npessoas; i++){
			g[i] = new NoF(i);
			gt[i] = new NoF(i);
		}
	}
	void createGrafo(Scanner in){
		inicializar();
		for(int i = 1; i<=npessoas; i++){
			int namigo = in.nextInt();
			for(int j = 0; j<namigo; j++){
				int amigo = in.nextInt();
				g[i].addLigacao(g[amigo]);
				gt[amigo].addLigacao(gt[i]);
			}
		}
	}

	void DFS(){
		for(int i = 1; i<=npessoas; i++){
			if(!g[i].visitado)
				DFSVisit(g[i]);
		}
	}
	private void DFSVisit(NoF x){
		tempo++;
		x.visitado = true;
		for(NoF cursor: x.adj){
			if(!cursor.visitado)
				DFSVisit(cursor);
		}
		tempo++;
		x.tempof =tempo;
		gt[x.no].tempof = tempo;
	}
	private NoF findMax(){
		int maximo = 0; 
		NoF max = new NoF(0);

		for(int i = 1; i<=npessoas; i++){
			if(!gt[i].visitado){
				if(gt[i].tempof > maximo){
					maximo = gt[i].tempof;
					max = gt[i];
				}
			}
		}
		return max;
	}
	private boolean allVisited(){
		for(int i = 1; i<=npessoas; i++){
			if(!gt[i].visitado)
				return false;
		}
		return true;
	}

	void DFS_T(){
		while(!allVisited()){
			NoF TMax = findMax();
			int nelementos = NelementosGrupo(TMax);
			grupos.addLast(nelementos);
			TMax.tempof = 0;
		}
	}
	private int NelementosGrupo(NoF x){
		int count = 1;
		x.visitado = true;
		for(NoF cursor: x.adj){
			if(!cursor.visitado)
				count +=NelementosGrupo(cursor);
		}
		return count;
	}

