class Comb{
  private int n , k, apont=0;//apont serve para na recursividade goSumComb saber onde guardar
  private int comb[];
  private int aux[];
  private int pair[] = new int[2];

  Comb(int n, int k, int vetor[]){
    this.n=n;
    this.k=k;

    //new Output(vetor);

    aux= new int[numberComb()]; // ver isto
    //System.out.println(numberComb());
    goSumComb(0,0,0,vetor);
    Arrays.sort(aux);
    comb=removeDuplicates(aux);
    //new Output(comb);
  }

  private int numberComb(){ //retorna o numero de combinações possiveis
    return((n*(n-1))/2);
  }

