  private void goSumComb(int pos,int first,int o,int vetor[]){ //efetua as combinaces
    if (pos == k) {
      //System.out.println(pair[0]+" "+pair[1]);
      aux[apont++]=pair[0]+pair[1];
    }
    else{
      for (int i = first;i<n ;i++ ) {
        pair[o]=vetor[i];
        goSumComb(pos+1,i+1,o+1,vetor);
      }
    }
  }

  public static int[] removeDuplicates(int[] arr) {
    Set<Integer> alreadyPresent = new HashSet<Integer>();
    int[] whitelist = new int[0];

    for (int nextElem : arr) {
      if (!alreadyPresent.contains(nextElem)) {
        whitelist = Arrays.copyOf(whitelist, whitelist.length + 1);
        whitelist[whitelist.length - 1] = nextElem;
        alreadyPresent.add(nextElem);
      }
    }

    return whitelist;
  }


  private int bsearch(int low,int high,int condicao){ //efetua pesquisa binaria
    while(low < high){
      int middle=low + (high-low)/2;
      if(comb[middle]==condicao) return middle;
      if(condicao < comb[middle]) high=middle;
      else low=middle+1;
    }
    return low;
  }

