            else               {contador+=(middle-p1)+1; aux[i++] = v[p2++]; }

        }
        while (p1<=middle) {aux[i++] = v[p1++];}     // Adicionar o que resta
        while (p2<=end)    {aux[i++] = v[p2++];}

        for (i=start; i<=end; i++) v[i] = aux[i];  // Copiar array aux[] para v[]
    }

