class Sap implements Comparable<Sap>{
    public int dur;
    public int mul;
    public float tot;
    public int ind;
    Sap(int d, int m, int k){
	dur=d;
	mul=m;
	tot=((float)m)/d;
	ind=k;
    }
    @Override
    public int compareTo(Sap t){
	if(tot > t.tot) return -1;
	if(tot < t.tot) return +1;
	if(dur > t.dur) return +1;
	if(dur < t.dur) return -1;
	if(ind > t.ind) return -1;
	if(ind < t.ind) return +1;
