import java.util.*;

public class Ordenando {

	public static int[] mergeSort(int [] a){
		if(a.length<=1)
			return a;

		//dividir array
		int[] first = new int[a.length/2];
		int[] second = new int[a.length - first.length];

		//copiar valores do vector a

		System.arraycopy(a, 0, first, 0, first.length);
		System.arraycopy(a, first.length, second, 0, second.length);

		//recursao do metodo
		mergeSort(first);
		mergeSort(second);

		//merge para resultado final
		merge(first, second, a);
		return a;
	}

	public static void merge(int[] first, int second[], int [] result){
		int a = 0; //posicao do vector first
		int b = 0; //posicao do vector second
		int i=0;   //posicao do vector end

		while(a<first.length && b<second.length){
			if(first[a]<second[b]){
				result[i] = first[a];
				a++;
			}
			else{
				result[i] = second[b];
				b++;
			}
			i++;
		}

		System.arraycopy(first, a, result, i, first.length -a);
		System.arraycopy(second, b, result, i, second.length-b);
	}

	public static void main(String[] args){
		Scanner in = new Scanner(System.in);
		int tam = in.nextInt();
		int[] aven = new int[tam];
		for(int i=0; i<tam; i++){
			aven[i] = in.nextInt();
		}
		aven = mergeSort(aven);
		for(int i=0; i<tam; i++){
			if(i>0)
				System.out.print(" ");
			System.out.print(aven[i]);
		}
		System.out.println();
	}
}

import java.lang.*;
import java.util.*;
import java.util.LinkedList;
import java.util.Scanner;

class NegocioElectronico {
    private static Scanner stdin = new Scanner(System.in);

    public static void main(String [] args) {
        int nStores = stdin.nextInt();
        int destination = stdin.nextInt();

        Grafo g = lerLojas(nStores);
        analisarLojas(g, destination);
    }

    public static Grafo lerLojas(int nStores) {
        Grafo g = new Grafo(nStores);

        int a = stdin.nextInt();
        while (a != -1) {
            int b = stdin.nextInt();
            int w = stdin.nextInt();

            g.insert_new_arc(a, b, w);
            g.insert_new_arc(b, a, w);

            a = stdin.nextInt();
        }

        return g;
    }

    public static void analisarLojas(Grafo g, int origem) {
        int [] dist = new int[g.num_vertices() + 1];
        boolean [] seen = new boolean[g.num_vertices() + 1];
        int [] pred = new int[g.num_vertices() + 1];

        for (int u = 1; u <= g.num_vertices(); u++) {
            dist[u] = Integer.MAX_VALUE;
            seen[u] = false;
            pred[u] = -1;
        }

        dist[origem] = 0;
        pred[origem] = origem;
        Heapmin q = new Heapmin(dist, g.num_vertices());

        while (q.size != 0) {
            int u = q.extractMin();

            for (Arco temp : g.adjs_no(u)) {
                int v = temp.extremo_final();

                if (dist[u] + g.find_arc(u, v).valor_arco() < dist[v]) {
                    dist[v] = dist[u] + g.find_arc(u, v).valor_arco();
                    q.decreaseKey(v, dist[v]);
                    pred[v] = u;
                }
            }
            seen[u] = true;
        }
    }
}

