class No {
    double x, y;
    boolean visitado;

    No(double x, double y) {
	this.x = x;
	this.y = y;
	visitado = false;
    }   
}

class Aresta implements Comparable<Aresta>{
    No a, b;
    double distancia;

    Aresta() {
    }

    Aresta(No x, No y) {
	a = x;
	b = y;
	double dis1 = (a.x - b.x);
	double dis2 = (a.y - b.y);
	dis1 = dis1 * dis1;
	dis2 = dis2 * dis2;
	distancia = Math.sqrt(dis1+dis2);
    }

    @Override
    public int compareTo(Aresta x) {
	return Double.compare(this.distancia, x.distancia);
    }


}

