    static int high;
    static int key;
    static int middle;

    //--------------------------------------------------

    static void sum(int v[]){
	int conta=0;

	soma =new int[k];

	for(int i=0;i<n-1;i++){
	    for(int j=i+1;j<n;j++){
		soma[conta]=v[i]+v[j];
		conta++;
	    }
	}

	aux =new int[conta];//int[conta] -> conta é o Nº de combinações possivei

	for(int i=0;i<conta;i++){
	    aux[i]=soma[i];
	}

	Arrays.sort(aux);

	for(int i=0;i<p;i++){
	    System.out.println( bsearch(aux,0,conta,val[i]));
	}
    }
    //----------------------------------------------------------------------

    static int bsearch(int v[], int low, int high, int key){
	while(low <= high){
	    middle = low+ (high-low)/2;
	    if(key == v[middle]){        
		return v[middle];
	    }	  
	    else if(key < v[middle]){        
		high=middle-1;       
	    }
	    else if(key > v[middle]){
		low= middle+1;
	    }
	}
	if(low-1<0)  //caso em que a resposta está no início do array
	    return v[0];
	else if(Math.abs(key-v[low]) == Math.abs(key-v[low-1])){ //caso em que as distâncias à resposta são iguais
	    System.out.print(v[low-1] + " ");
	    return v[low];
	}
	else
	    return v[low-1];
    }

