        for ( int i = 0; i < nLojas; i++)
        {
            arN[i]  =   Integer.MAX_VALUE;
            alQ.add(i+1);

        }

        arN[nEnd-1] =   0;

        //Dijsktra
        while ( !alQ.isEmpty() )
        {
            nIndex  =   GetMin(alQ, arN);

            System.out.print(nIndex+1 + " ");

            // Extract Min
            for ( int i = 0; i < alQ.size(); i++)
            {
                if ( alQ.get(i) == nIndex+1)
                {
