                }
            }

            // Adjacentes
            for ( int i = 0; i < nLojas; i++)
            {
                if ( arDist[nIndex][i] > 0 )
                {
                    arDist[i][nIndex]   =   0;

                    //Relax
                    if ( arN[i] > arN[nIndex] + arDist[nIndex][i] )
                    {
                        arN[i]  =   arN[nIndex] + arDist[nIndex][i];
                    }
                }
            }

        }        
    }

    public static int GetMin (ArrayList<Integer> alList, int[] arN)
    {
        int nResult = -1;
