class Seg implements Comparable<Seg>{
    public int dir,esq,tamanho;
    Seg(int e,int d){
        esq=e;
        dir=d;
        tamanho=d-e;
    }
    @Override
    public int compareTo(Seg s){
        if(esq<s.esq) 
			return -1;
        else if(esq>s.esq) 
			return 1;
        else if(dir<s.dir) 
			return -1;
        else if(dir>s.dir) 
			return 1;
        return 0;
    }
}

