	public ENC(HashMap<Integer, ArrayList<Integer>> HM, int [][] l , int [][] c, int [][] a,
			int lmin, int lmax,int cmin, int cmax, int alt, int p, int f, ArrayList<Integer> ll){
		hm = HM;
