		for (int i : ll) {
			for (int j : ll){
				if (i != j) {
					vis.clear();
					caminhos(i,j);
				}
			}
		}

	}

	public void  caminhos(int vertice, int fim){		
		vis.add(vertice);
		for (int i : hm.get(vertice)){
			if (i==fim){
				//System.out.println(vertice);
				if(largura[vertice][i]>=larg_min && largura[vertice][i]<=larg_max && 
					comprimento[vertice][i]>=comp_min && comprimento[vertice][i]<=comp_max &&
					altura[vertice][i]>=alt_min){
					cam +=1;
				}
				//return 0;
			}
			else {
				if (!vis.contains(i)){
					if(largura[vertice][i]>=larg_min && largura[vertice][i]<=larg_max && 
							comprimento[vertice][i]>=comp_min && comprimento[vertice][i]<=comp_max &&
							altura[vertice][i]>=alt_min){
					caminhos(i, fim);
					}
				}
			}
		}			

	}

	public void res(){
		if (cam!=0){
		System.out.println(cam);
		}
		else {System.out.println("impossivel");}
	}

