public class cigarras {

	public static int analisa_caminho(int key, int valor, int[] locais){
		int i = 0;
		boolean isset = false;
		while ( i<=key) {
			if (locais[i]==valor) { //se exite
				key = i; //guarda a key
				isset=true;
			}
		i++;		
		}
		if (!isset) {
			locais[key+1] = valor;
			key++;
		}
	return key;
	}


	public static void escreve_caminho(int key, int[] locais){
		int c = 0;
		while (locais[c]!=0 && c<=key){
