		for(int j=0;j<c.length;j++)
			if(!p[c.length-1][j])
				c[c.length-1][j]++;

		for(int i=c.length-2;i>=0;i--)
			for(int j=0;j<=i;j++)
				if(!p[i][j]){
					c[i][j]+=c[i+1][j];
					if(j+1<c.length)
						c[i][j]+=c[i+1][j+1];
				}
	}		
}

