class Queue {
    int queue[];
    int size;
    int first;
    int last;
    int cap;

    Queue (int c) {
	cap = c;
	queue = new int[c];
	size = first = last = 0;
    }

    boolean isEmpty() {
	return (size == 0);
    }

    int remove() {
	int r = queue[first];
	first = (first+1) % cap;
	size--;
	return r;
    }

    void add (int node) {
	queue[last] = node;
	last = (last+1) % cap;
	size++;
    }
}

public class prat21 {
    static ArrayList<LinkedList<Integer>> nodeMap = new ArrayList<LinkedList<Integer>>();
    static boolean[] visited;
    static int[][] dist;
    static int nv,ne;
    static int diametro = 0;

    static int excentricidade (int node) {
	int max = 0;
	for (int i = 0; i < nv+1; i++) {
	    if (dist[node][i] > max) max = dist[node][i];
	}
	return max;
    }

    static void bfs (int node) {
	Queue q = new Queue(nv+1);
	q.add(node);
	dist[node][node] = 0;
	visited[node] = true;
	while (!q.isEmpty()) {
	    int u = q.remove();
	    for(int x : nodeMap.get(u)) {
		if (!visited[x]) {
		    q.add(x);
		    visited[x] = true;
		    dist[node][x] = dist[x][node] = dist[node][u] + 1; 
		    if (dist[node][x] > diametro) diametro = dist[node][x];
		}
	    }
	}
    }

