	boolean visitado;

	Node(int n, int p) {
		num = n;
		peso = p;
		ligacoes = new LinkedList<Node>();
		visitado = false;		
	}

}

class Grafo {

	LinkedList<Node> arvore;
	LinkedList<Node> arvoreMinima;

	Grafo() {
		arvore = new LinkedList<Node>();
		arvoreMinima = new LinkedList<Node>();
	}

	void colocaGrafo(int n) {
		arvore.add(new Node(n, 0));
	}

	void adicionaLigacao(int o, int d, int valor) {
		for (Node n : arvore)
			if (n.num == o)
				n.ligacoes.add(new Node(d, valor));
	}

	void Prim(Node i) {
		int max = 0;
		Node NoMax = null;
		i.peso = 0;
		LinkedList<Node> fila = new LinkedList<Node>();
		fila.add(i);
		while (fila.isEmpty() == false) {
			for (Node l : fila) {
				if (l.peso >= max) {
					max = l.peso;
					NoMax = l;
				}
			}
			fila.remove(NoMax);
			for (Node n : NoMax.ligacoes) {
				if (n.peso > arvore.get(n.num - 1).peso
						&& arvore.get(n.num - 1).visitado == false) {
					arvore.get(n.num - 1).peso = n.peso;
					if (fila.contains(arvore.get(n.num - 1)) == false)
						fila.add(arvore.get(n.num - 1));
				}
			}
			arvore.get(NoMax.num - 1).visitado = true;
			arvoreMinima.add(new Node(NoMax.num, NoMax.peso));
			max = 0;
		}
	}
}

public class OticaMinimalista {
	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);

		int custo = 0;
		Node inicio = null;

		int nNos = in.nextInt();
		int nLig = in.nextInt();
		int manutencao = in.nextInt();
		Grafo grafo = new Grafo();

		for (int i = 1; i <= nNos; i++) {
			grafo.colocaGrafo(i);
		}

		for (int i = 0; i < nLig; i++) {
			int n1 = in.nextInt();
			int n2 = in.nextInt();
			int peso = in.nextInt();
			grafo.adicionaLigacao(n1, n2, peso);
			grafo.adicionaLigacao(n2, n1, peso);
		}
		if (nLig < nNos - 1)
			System.out.println("impossivel");

		else {
			for (Node n : grafo.arvore)
				if (n.num == 1)
					inicio = n;

			grafo.Prim(inicio);

			if (grafo.arvoreMinima.size() < nNos)
				System.out.println("impossivel");
			else {
				for (Node n : grafo.arvoreMinima)
					custo += n.peso;
				System.out.println("rendimento optimo: " + (custo - ((nNos - 1) * manutencao)));
			}
		}
	}
}

