			while (b <= e) {
				m  = b + (e-b) / 2;				
				if (Math.abs(s[m] - query) < Math.abs(query - min))
					min = s[m];
				if (s[m] == query)
					break;
				else if (query > s[m])
					b = m+1;
				else
					e = m-1;
			}

			int other = -1;
			if (min < query && Arrays.binarySearch(s, 0, d, query + (query-min)) >= 0)
				System.out.println(min + " " + (query + (query-min)) );
			else if (min > query && Arrays.binarySearch(s, 0, d, query + (query-min)) >= 0)
