import java.util.*;
//import java.io.*;

class krusk {

    int mat[][];
    int nos[][];
    int p;
    int r;
    int na;
    int cnt;
    int custos;
    int v[];
    krusk(int matriz[][],int tnos,int tlig,int zz,int valores[]){
	p = tnos;
	mat = matriz;
	r = tlig;
	nos = new int[p][3];
	na = 0;
	cnt=0;
	custos=zz;
	v = valores;
    }

    void principal () {

	int ii=0;

	quicksort(v,0,r-1);



	for (int e=0;e<r;e++) {

	    for (int j=0;j<p;j++){
		for (int k=0;k<p;k++)
		    if (mat[j][k] == v[e]) {
			if ((findset(j)) != (findset(k))){
			    ii++;
			    cnt += mat[j][k];
			    union(j,k);
			}
			mat[j][k] = 0;
			k=p;
			j=p;
		    }
	    }
	}
	if (ii == (p-1)){

	    System.out.println("rendimento optimo:" + (cnt+custos));
	}
	else {System.out.println("impossivel");

	}
    }

    void makeset(int x) {

	nos[na][0] = x;
	nos[na][1] = 0;
	nos[na][2] = x;
	na++;


    }

    int findset(int x) {

	int ind = find (x);
	if (nos[ind][2] != x) {
	    nos[ind][2] = findset(nos[ind][2]);
	}
	return nos[ind][2];
    }

    int find(int x){

	for(int i=0;i<p;i++){
	    if (nos[i][0]==x){
		return i;	
	    }
	}
	makeset(x);
	return na-1;
    }

    void union (int x,int y){

	link(findset(x),findset(y));
    }

    void link(int x,int y){

	int h = find(x);
	int g = find(y);

	if (nos[h][1] > nos[g][1]){
	    nos[g][2] = nos[h][0];
	}
	else {
	    nos[h][2] = nos[g][0];
	    if (nos[h][1] == nos[g][1]){
		nos[g][1] += 1;
	    }
	}
    }

    void quicksort (int f[],int pp,int rr){

	if (pp < rr){
	    int q = part(f,pp,rr);
	    quicksort(f,pp,q-1);
	    quicksort(f,q+1,rr);
	}
    }

    int part(int f[],int pp,int rr){

	int z = f[rr];

	int i = pp-1;

	for (int j=pp;j<=rr-1;j++){
	    if (f[j] <= z){
		i++;
		int xx = f[i];
		f[i] = f[j];
		f[j] = xx;
	    }
	}
	int xx = f[i+1];
	f[i+1] = f[rr];
	f[rr] = xx;

	return i+1;

    }
}

