	public static int Calc(int n, int count[][]){
		for(int i=n-1; i>=1; i--){	
			for(int j=1; j<= i;j++){
				if(count[i][j]!=0){
					count[i][j] = count[i+1][j]+count[i+1][j+1];

				}
			}
		}

		return count[1][1];
	}

}

