public class somas {   
    public static int bsearch(int v[], int k){
	int low=0;
	int high=v.length;
	int dist;
	int dist2;
	while(low< high){
	    int middle=low+(high-low)/2;
	    if( k<v[middle]) high=middle;
	    else if(k>v[middle])low=middle+1;
	    else return v[middle];
	}

	if(low!=0){
	 dist=v[low]-k;
	dist2=v[low-1]-k;
	if(dist2>dist)
	    return v[low];
	else if(dist2<dist)
	    return v[low-1];
	else if(dist2==dist)
	    return v[low-1];
	}
	return v[low];
    }

