class Grafo{
	int tempo;
	int nalunos;
	No g[];
	No gt[];
	int grupos;
	int count;

	Grafo(int n){
		nalunos=n;
		tempo=0;
		g=new No[nalunos+1];
		gt=new No[nalunos+1];
		grupos = 0; 
		count=0;
	}

	private void inicializar(){
		for(int i=1; i<=nalunos; i++){
			g[i]=new No(i);
			gt[i]=new No(i);
		}
	}

	void create(Scanner in){
		inicializar();
		for(int i=1; i<=nalunos; i++){
			int namigos=in.nextInt();
			for(int j=0; j<namigos; j++){
				int amigo=in.nextInt();
				g[i].addligacao(g[amigo]);
				gt[amigo].addligacao(gt[i]);
				if(amigo==1) count++;
			}
		}
	}

	void DFS(){
		for(int i=1; i<=nalunos; i++){
			if(!g[i].visitado) DFSV(g[i]);
		}
	}

	void DFSV(No x){
		x.visitado=true;
		tempo++;
		for(No aux : x.adj){
			if(!aux.visitado) DFSV(aux);
		}
		tempo++;
		x.tempof=tempo;
		gt[x.id].tempof=tempo;
	}

	void DFS_T(){
		while(!allvisited()){
			No x = findmaxno();
			nelementosof(x);
			grupos++;
		}
	}
	private boolean allvisited(){
		for(int i=1; i<=nalunos; i++){
			if(!gt[i].visitado) return false;
		}
		return true;
	}

	private No findmaxno(){
		int max=0;
		No maximum=new No(0);
		for(int i=1; i<=nalunos; i++){
			if(!gt[i].visitado){
				if(gt[i].tempof>max){
					max=gt[i].tempof;
					maximum=gt[i];
				}
			}
		}
		return maximum;
	}

	private void nelementosof(No x){
		x.visitado=true;
		for(No aux : x.adj){
			if(!aux.visitado) nelementosof(aux);
		}
	}

	private void limpar(){
		for(int i=1; i<=nalunos; i++){
			g[i].visitado=false;
		}
	}

	void BFS(){
		limpar();
		LinkedList<No> lista = new LinkedList<No>();
		g[1].visitado=true;
		g[1].dia=0;
		lista.addLast(g[1]);

		while(!lista.isEmpty()){
			No x = lista.removeFirst();
			for(No aux : x.adj){
				if(!aux.visitado){
					aux.visitado=true;
					aux.dia=x.dia+1;
					lista.addLast(aux);
				}
			}
		}
	}

	int findmaxday(){
		int max=0;
		for(int i=1; i<=nalunos; i++){
			if(g[i].dia>max) max=g[i].dia;
		}
		return max+1;
	}	
	void output(){
		System.out.println(grupos);
	}

