class Sociologia {
	public static void main(String args[]){
		Scanner in = new Scanner(System.in);
		Grafo g;
		int casos = in.nextInt();
		for (int i = 0; i < casos; i++) {
			g = makeGraf(in);
			System.out.println("Caso #"+(i+1));
			DFS(g);
		}

	}
	static Grafo makeGraf(Scanner in) {
		int nAlunos = in.nextInt();
		Grafo g = new Grafo(nAlunos);

		for (int i = 0; i < nAlunos; i++) {
			int aluno = in.nextInt();
			int amigos = in.nextInt();
				for (int j = 0; j < amigos; j++) {
				int amigo = in.nextInt();
				g.insert_new_arc(aluno, amigo, 0);
			}
		}

		return g;
	}

	static void DFS(Grafo g) {
		Stack<Integer> s = new Stack<Integer>();
		int visitados[] = new int[g.nvs+1];
		for (int i = 1; i <= g.nvs; i++) {
			if(visitados[i]==0){
				DFS_Visit(g, i, s, visitados);
			}
		}

		Grafo gt = gTransposto(g);
		int vis[] = new int[g.nvs+1];
		int pessoas = 0, quatro = 0;
		while(!s.isEmpty()) {
			int i = s.pop();
			if(vis[i]==0){
				int c = DFS_Transposto(gt, i,vis);
				if(c>=4) {
					quatro++;
				}
				else{
					pessoas+=c;
				}
			}
		}
		System.out.println(quatro + " " + pessoas);
	}

	static void DFS_Visit(Grafo g, int v, Stack<Integer> s, int[] visitados){
		visitados[v]=1;
		for (Arco a : g.adjs_no(v)) {
			int w = a.extremo_final();
			if(visitados[w]==0){
				DFS_Visit(g, w, s, visitados);
			}
		}
		s.push(v);

	}

	static int DFS_Transposto(Grafo g, int v, int[] visitados) {
		int c=1;
		visitados[v]=1;
		for (Arco a : g.adjs_no(v)) {
			int w = a.extremo_final();
			if(visitados[w]==0){
				c+=DFS_Transposto(g, w, visitados);

			}
		}
		return c;
	}

	static Grafo gTransposto(Grafo g){
		Grafo gt = new Grafo(g.nvs);
		for (int i = 1; i <= g.nvs; i++) {
			for (Arco a : g.adjs_no(i)) {
				int w = a.extremo_final();
				gt.insert_new_arc(w, i, 0);
			}
		}
		return gt;
	}
}

import java.util.*;
import java.lang.*;

class Graph {
	LinkedList<Integer>[] adj;
	int[] parent, dist;
	int[][] distance;

	@SuppressWarnings("unchecked")
	Graph(int dim) {
		adj = new LinkedList[dim];
		parent = new int[dim];
		dist = new int[dim];
		distance = new int[dim][dim];
	}

	void printGraph() {
		for (int i = 0; i < adj.length; i++) {
			Iterator<Integer> it = adj[i].iterator();
			System.out.printf("%d ", i+1);
			while(it.hasNext()) {
				System.out.printf("%d ", it.next()+1);
			}
			System.out.println();
		}
	}

	void printMatrix() {
		for (int i = 0; i < adj.length; i++) {
			for (int j = 0; j < adj.length; j++)
				System.out.printf("%d ", distance[i][j]);
			System.out.printf("\n");
		}
	}

	int extractMin(PriorityQueue<Integer> q) {
		Iterator<Integer> it = q.iterator();
		int min = Integer.MAX_VALUE;
		int indMin = -1;
		while (it.hasNext()) {
			int index = it.next();
			if (dist[index] < min) {
				min = dist[index];
				indMin = index;
			}
		}
		if (indMin == -1 && !q.isEmpty())
			indMin = q.peek();
		q.remove(indMin);
		return indMin;
	}

	PriorityQueue<Integer> dijkstra(int source) {
		PriorityQueue<Integer> s = new PriorityQueue<Integer>();
		Arrays.fill(parent, -1);
		Arrays.fill(dist, Integer.MAX_VALUE);
		dist[source] = 0;
		PriorityQueue<Integer> vertices = new PriorityQueue<Integer>();
		for (int i = 0; i < adj.length; i++)
			vertices.add(i);
		while (!vertices.isEmpty()) {
			int u = extractMin(vertices);
			s.add(u);
			Iterator<Integer> it = adj[u].iterator();
			while (it.hasNext()) {
				int v = it.next();
				if (dist[v] > dist[u] + distance[u][v]) {
					dist[v] = dist[u] + distance[u][v];
					parent[v] = u;
				}
			}
		}
		return s;
	}

	void output(PriorityQueue<Integer> s) {
		while (!s.isEmpty()) {
			System.out.printf("%d", extractMin(s) + 1);
			if(!s.isEmpty())
				System.out.printf(" ");
		}
		System.out.printf("\n");
	}
}

