	public static void main(String [] args){
		Scanner in = new Scanner(System.in);
		int nv = in.nextInt();
		Grafo g = new Grafo(nv);
		int pais[] = new int[nv+1];
		int dest[]= new int[nv+1];
		int destino = in.nextInt();
		int pai = in.nextInt();
		while(pai!=-1){
			int filho = in.nextInt();
		    int dist = in.nextInt();
		    g.insert_new_arc(pai,filho,dist);
		    g.insert_new_arc(filho,pai,dist);
		    pai=in.nextInt();
		}
		eletronico(g,pais,dest,destino);

	}

	private static void eletronico(Grafo g, int[] pais, int[] dest, int destino) {
		for(int i=0;i<=g.num_vertices();i++){
			pais[i]=0;
			dest[i]= Integer.MAX_VALUE;
		}
		dest[destino]=0;
		Heapmin q = new Heapmin(dest, g.num_vertices());
		while(q.size!=0){
			int v=q.extractMin();
			System.out.print(v);
		    if(q.size!=0) System.out.print(" ");
			for(Arco a: g.adjs_no(v)){
				int w=a.extremo_final();
				if((dest[v]+a.valor_arco()<dest[w]) && (dest[v]!=Integer.MAX_VALUE)){
					dest[w] = dest[v] + a.valor_arco();
					pais[w] = v;
					q.decreaseKey(w, dest[w]);

				}
			}
		}
		System.out.println();
	}
}

