import java.io.*;
import java.util.*;

public class p5{

    // Juntar dois arrays ordenados
    // Assumir que os arrays sao v[start..middle] e v[middle+1..end]
    static int merge(int v[], int start, int middle, int end){
    int i, p1, p2;
    int aux[] = new int[end+1];
    int contador=0;

    p1=start;     // "Apontador" do array da metade esquerda
    p2=middle+1;  // "Apontador" do array da metade direita
    i = start;    // "Apontador" do array aux[] a conter juncao
    while (p1<=middle && p2<=end) {            // Enquanto de para comparar
        if (v[p1] <= v[p2]){
        aux[i++] = v[p1++];  // Escolher o menor e adicionar
        }
        else{
        aux[i++] = v[p2++];
        contador += middle-p1+1;
        }
    }
    while (p1<=middle) aux[i++] = v[p1++];     // Adicionar o que resta
    while (p2<=end)    aux[i++] = v[p2++];

    for (i=start; i<=end; i++) v[i] = aux[i];  // Copiar array aux[] para v[]


    return contador;
    }

    // Ordenar array v[] com mergesort entre posicoes start e end
    static int mergesort(int v[], int start, int end){
    int middle;
    int contador =0;
    if (start<end) {                 // Parar quando tamanho do array < 2
        middle = (start+end)/2;        // Calcular ponto medio
       contador+= mergesort(v, start, middle);
       contador+= mergesort(v, middle+1, end);
       contador+= merge(v, start, middle, end);  
    }
    return contador;
    }

    public static void main(String args[]){

    Scanner stdin = new Scanner(System.in);

    // Ler N numeros
    int n   = stdin.nextInt();
    int v[] = new int[n];
    for (int i=0; i<n; i++)
        v[i] = stdin.nextInt();


    System.out.println(mergesort(v, 0, n-1));
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
	static BufferedReader stdin = new BufferedReader(new InputStreamReader(
			System.in));
	static StringTokenizer st = new StringTokenizer("");

	// Read next input-token as string.
	static String readString() throws Exception {
		while (!st.hasMoreTokens()) {
			st = new StringTokenizer(stdin.readLine());
		}
		return st.nextToken();
	}

	// Read next input-token as integer.
	static int readInt() throws Exception {
		return Integer.parseInt(readString());
	}

	// Read next input-token as double.
	static double readDouble() throws Exception {
		return Double.parseDouble(readString());
	}

	public static void main(String[] args) throws Exception {


			Double total = Double.valueOf(0);
			int numberOfFreckles = readInt();

			Double[][] freckles = new Double[numberOfFreckles][2];
			int[] sets = new int[numberOfFreckles];

			for (int i = 0; i < numberOfFreckles; i++) {
				freckles[i][0] = readDouble();
				freckles[i][1] = readDouble();
				sets[i] = i; //legger alle fregner i et set
			}

			for (int i = 1; i < numberOfFreckles; i++) {

				// curretn set sets[i];
				Double shortest = Double.MAX_VALUE;
				int s = -1;

				// finn naermeste fregne fra f[i] som ikke er i samme sett
				for (int j=0; j < numberOfFreckles; j++) {
					s = -1;

//					System.out.println("set i: " + sets[i] + " set j: " + sets[j]);

					if ( sets[i] != sets[j]) {

						Double n = findDistance(freckles[i], freckles[j]);
						if (n < shortest) {
							shortest = n;
							s = sets[j];
						}
					}
				}

				total += shortest;
				sets[i] = s;
			}

			System.out.printf("%.2f\n", total);

	}

	private static double findDistance(Double[] f1, Double[] f2) {
		return Math.sqrt( ((f1[0] - f2[0])*(f1[0] - f2[0])) + ((f1[1] - f2[1])*(f1[1] - f2[1])) );
	}


}

