    static void algoritmoDijkstra (Grafo g, int origem){

            int[] dist = new int[g.nvs+1];
            for (int i=1; i<dist.length; i++){
                if(i != origem)
                    dist[i]=Integer.MAX_VALUE;
                else 
                    dist[i]=0;
            }

