    public static void pesquisa(int[] a, int b, int inicio, int fim) {

        while(inicio <=fim) {	    
	    int meio = (inicio + ((fim - inicio) / 2));
	    if(b == a[meio]) {
		System.out.println(a[meio]);
		return;
	    }
	    else
		if(inicio == fim) {
		    System.out.println(a[inicio]);
		    return;
		}

		else 
		    {
			if(b < a[meio]) {
			    if(meio-1 >= inicio) 
				if(b > a[meio-1]) {
				    verifica(b, meio, a);
				    return;
				}
			    fim = meio-1;
			}
			else {
			    if(meio+1 <= fim)
				if(b > a[meio] && b < a[meio+1]) {
				    verifica(b, meio, a);
				    return;
				}
			inicio = meio+1;
			}
		    }
	}
