	}	
}

class Grafo{

	No nos[];
	No nosT[];
	int npessoas;
	LinkedList<Integer> list=new LinkedList<Integer>(); 
	int time=0;

	Grafo(int n){
		npessoas=n;
		nos=new No[npessoas+1];
		nosT=new No[npessoas+1];
	}

	void inicializar(){
		for(int i=1; i<=npessoas; i++){
			nos[i]=new No();
			nosT[i]=new No();
		}
	}
	void criar_grafo(Scanner in){

		inicializar();
		for(int i=0; i<npessoas; i++){
			int pessoa=in.nextInt();
			int namigos=in.nextInt();
			for(int j=1; j<=namigos; j++){
				int amigo=in.nextInt();
				nos[pessoa].addligacao(nos[amigo]);
				nosT[amigo].addligacao(nosT[pessoa]);
			}
		}
	}

	void DFS(){

		for(int i=1; i<=npessoas; i++){
			if(nos[i].visitado!=true){
				DFSVisit(nos[i]);
			}
		}
	}

	private void DFSVisit(No u){
		u.visitado=true;
		time=time+1;

		for(No x: u.adj){
			if(x.visitado==false){
				DFSVisit(x);
			}
		}
		u.tempo=time+1;
	}

	void atualiza(){
		for(int i=1; i<=npessoas; i++){
			nosT[i].tempo=nos[i].tempo;
		}
	}

	private No findmax(){
		int max=0;
		No maximo=new No();
		for(int i=1; i<=npessoas; i++){
			if(nosT[i].tempo>max){
				max=nosT[i].tempo;
				maximo=nosT[i];
			}
		}
		return maximo;
	}

	private boolean allvisited(){
		for(int i=1; i<=npessoas; i++){
			if(nosT[i].visitado==false) return false;
		}
		return true;
	}

	void DFSTransposta(){

		while(!allvisited()){
			No u = findmax();
			int nelementos=DFS2(u);
			list.addLast(nelementos);
		}
	}

	private int DFS2(No u){
		u.visitado=true;
		int count=1;
		for(No x : u.adj){
			if(!x.visitado){
				count+=DFS2(x);
			}
		}
		return count;
	}

	void countgrupos(){
		int countngrupos=0;
		int outliers=0;
		for(int x : list){
			if(x>=4) countngrupos++;
			else
				outliers+=x;
		}
		System.out.println(countngrupos + " " + outliers);
	}
}

