	LinkedList<No> adj;

	No(int v){
		valor = v;
		visitado = false;
		peso = Integer.MAX_VALUE;
		adj = new LinkedList<No>();
	}

	void adicionarLigacao(No n){
		adj.addLast(n);
	}
}


class Grafo{
	int nreg;
	int dest;
	No n[];
	int pesos[][];
	LinkedList<Integer> S;

	Grafo(int nr, int d){
		nreg = nr;
		dest = d;
		n = new No[nreg+1];
		pesos = new int [nreg+1][nreg+1];
		S = new LinkedList<Integer>();
	}

	void inicializar(){
		for(int i=1; i<=nreg; i++){
			n[i] = new No(i);
		}
	}

	void criarGrafo(int p1, int p2, int dt){
		pesos[p1][p2] = dt;
		pesos[p2][p1] = dt;
		n[p1].adicionarLigacao(n[p2]);
		n[p2].adicionarLigacao(n[p1]);
	}

	void Dijkstra(){
		LinkedList<Integer> Q = new LinkedList<Integer>();

		for(int i=1; i<n.length; i++){
			Q.addLast(n[i].valor);
		}
		n[dest].peso = 0;

		while(!Q.isEmpty()){
			int u = extract_Min(Q);
			S.addLast(u);

			for(int i=0; i<n[u].adj.size(); i++){
				int v = n[u].adj.get(i).valor;
				int d = n[u].peso + pesos[u][v];
				if(n[v].peso > d){
					n[v].peso = d;
				}
			}
		}
	}

	private int extract_Min(LinkedList<Integer> Q){
		int min_peso = Integer.MAX_VALUE;
		int index = 0;
		int valor = -1;
		for(int i=0; i<Q.size(); i++){
			int tmp = Q.get(i);
			if(n[tmp].peso < min_peso){
				min_peso = n[tmp].peso;
				index = i;
				valor = Q.get(i);
			}
		}
		Q.remove(index);
		return valor;
	}

	void output(){
		for(int i=0; i<S.size(); i++){
			if(i == (S.size()-1)){
				System.out.print(S.get(i));
				System.out.println();
			}
			else{
				System.out.print(S.get(i) + " ");
			}
		}
	}

}


