public class Somas {

    static int bsearch(int[] v, int low, int n, int k) {
        int middle = 0;
        while (low < n) {
            middle = low + (n - low) / 2;
            if (k == v[middle]) {
                return middle;
            } else if (k < v[middle]) {
                n = middle;
            } else {
                low = middle + 1;
            }
        }

        middle = low;

        if (middle > 0) {
            if (k - v[middle - 1] < v[middle] - k) {
                return middle - 1;
            }
            if (k - v[middle - 1] == v[middle] - k) {
                System.out.print(v[middle - 1] + " " );
                return middle;
            }
            if (v[middle] - k < k - v[middle - 1]) {
                return middle;
            }
        }

        return middle;
    }

    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
