    public static int[] gerarLista(int nNmr, int min, int max) {

        if (min > max) {
            throw new IllegalArgumentException("Numero inicial superior do que o final.");
        }

        int[] lista = new int[nNmr];

        int valor;

        for (int i = 0; i < nNmr; i++) {
            valor = (int) (Math.random() * (max - min) + min);
            lista[i] = valor;
            //System.out.println(valor);
        }

        return lista;
    }

    public static void mergesort(int v[], int start, int end) {
        if (end - start == 0) {
            return;
        }

        int middle = (start + end) / 2;

        mergesort(v, start, middle);
        mergesort(v, middle + 1, end);
        merge(v, start, middle, end); /*fazer o merge das duas partições anteriores*/

    }

    public static void merge(int v[], int start, int middle, int end) {        
        for (int h = start; h <= end; h++) {
            aux[h] = v[h];
        }

        int i = start, j = middle+1, k = start;
        while (i <= middle && j <= end) {
            if (aux[i] <= aux[j]) {
                v[k] = aux[i];
                i++;
            } else {
                v[k] = aux[j];
                j++;
            }
            k++;
        }

        while (i <= middle) {
            v[k] = aux[i];
            k++;
            i++;
        }      
    }

    /**
     * @param args the command line arguments
     */
    public static void main(String[] args) throws IOException {
