class ProbA {
	static String comparaPalavras(String a, String b, int rev) {
		int l, i;

		l = a.length();
		for (i=0; i < l; i++) {
			if (a.charAt(i) != b.charAt(i) && rev == 0)
				return "" + a.charAt(i) + b.charAt(i);
			else if (a.charAt(i) != b.charAt(i) && rev == 1)
				return "" + b.charAt(i) + a.charAt(i);

		}

		return "Nenhum";
	}


