import java.util.*;

class OpticaMinimalista {
    public static void main(String args[]){

        Scanner stdin = new Scanner(System.in);
        int nnos = stdin.nextInt();
        int nligacoes = stdin.nextInt();
        int custoligacao = stdin.nextInt();

        Grafo rede = new Grafo(nnos);

        for (int i = 0; i < nligacoes; i++) {
            analisaLigacao(rede, stdin);
        }

        boolean conexa = rede.Prim();

        if (!conexa)
            System.out.println("impossivel");
        else {
            int rendoptimo = rede.calculaRendimentoOptimo(custoligacao);
            System.out.printf("rendimento optimo: %d\n", rendoptimo);
        }
    }

    public static void analisaLigacao(Grafo rede, Scanner stdin) {
        int indnoorigem = stdin.nextInt() - 1;
        int indnodestino = stdin.nextInt() - 1;
        int rbruto = stdin.nextInt();

        Vertex noorigem = rede.vertices[indnoorigem];
        Vertex nodestino = rede.vertices[indnodestino];
        noorigem.arcosadj.add(new Arco(nodestino, rbruto));
        nodestino.arcosadj.add(new Arco(noorigem, rbruto));
    }

    static class Grafo {
        Vertex[] vertices;

        Grafo(int n) {
            vertices = new Vertex[n];

            for (int i = 0; i < n; i++) {
                vertices[i] = new Vertex(i);
            }
        }

        public boolean Prim() {
            PriorityQueue<Vertex> q = new PriorityQueue<Vertex>(11,
                    new VertexComparator());
            Vertex root = this.vertices[0];
            root.key = 0;
            for (int i = 0; i < this.vertices.length; i++) {
                q.add(this.vertices[i]);
            }

            Vertex u = q.poll();
            while (u.key != Integer.MIN_VALUE) {
                for (int i = 0; i < u.arcosadj.size(); i++) {
                    Vertex v = u.arcosadj.get(i).nodestino;
                    if ((q.contains(v)) && (u.arcosadj.get(i).rbruto > v.key)) {
                        v.pred = u;
                        v.key = u.arcosadj.get(i).rbruto;
                        q.remove(v);
                        q.add(v);
                    }
                }

                if (!q.isEmpty()) {
                    u = q.poll();
                }
                else {
                    break;
                }
            }

            if (!q.isEmpty())
                return false;
            return true;
        }

        public int calculaRendimentoOptimo(int custoligacao) {
            int rendliquido = 0;
            for (int i = 1; i < this.vertices.length; i++) {
                Vertex extrem1 = this.vertices[i].pred;
                Vertex extrem2 = this.vertices[i];
                rendliquido = rendliquido + procuraValor(extrem1, extrem2, custoligacao);
            }
            return rendliquido;
        }

        public int procuraValor(Vertex extrem1, Vertex extrem2, int custoligacao) {
            int valor = 0;
            for (int i = 0; i < extrem1.arcosadj.size(); i++) {
                if (extrem1.arcosadj.get(i).nodestino == extrem2) {
                    valor = extrem1.arcosadj.get(i).rbruto - custoligacao;
                }
            }
            return valor;
        }

    }

    static class Vertex {
        int id;
        int key;
        Vertex pred;
        LinkedList<Arco> arcosadj;

        Vertex(int i) {
            id = i;
            key = Integer.MIN_VALUE;
            pred = null;
            arcosadj = new LinkedList<Arco>();
        }
    }

    static class Arco {
        int rbruto;
        Vertex nodestino;

        Arco(Vertex d, int r) {
            nodestino = d;
            rbruto = r;
        }
    }

    static class VertexComparator implements Comparator<Vertex> {
        public int compare(Vertex v1, Vertex v2) {
            if (v1.key > v2.key) {
                return -1;
            }

            if (v1.key < v2.key) {
                return 1;
            }

            return 0;
        }
    }

}

