    static int matrix[][];
    static int visited[];

    static void dfs(int v){
    	visited[v] = 1;
    	for(int i=1; i<=verts; i++){
    		if(matrix[v][i]==1 && visited[i]==0){
    			dfs(i);
    		}
    	}
    }

    public static void main(String args[]){
    	int aux = 0;
		Scanner in = new Scanner(System.in);

		verts = in.nextInt();
		int connections = in.nextInt();
		matrix = new int[verts+1][verts+1];
		visited = new int[verts+1];


		for(int i=0; i<connections; i++){
			int temp1 = in.nextInt();
		    int temp2 = in.nextInt();
		    matrix[temp1][temp2] = matrix[temp2][temp1] = 1;
		}

		for(int i=1; i<=verts; i++){
			if(visited[i]==0) {
				aux++;
				dfs(i);
			}
		}

		if(connections==0){
			System.out.println(verts); 
		}
		else{System.out.println(aux);}


    }
}

import java.io.*;
import java.util.*;

class Sociologia{

	public static int G[][];
	public static int cont[];
	public static Stack<Integer> stk;
	public static boolean color[];

	public static int Gt[][];
	public static int cont_gt[];

	public static void main(String args[]){
		Scanner scn = new Scanner(System.in);

		int nr_casos = scn.nextInt();
		for (int nc=1; nc<=nr_casos; nc++){

			int nr_alunos = scn.nextInt();
			G = new int[nr_alunos+1][];
			cont = new int[nr_alunos+1];

			for (int na=0; na<nr_alunos; na++){

				int id = scn.nextInt();
				int nr_f = scn.nextInt();
				G[id] = new int[nr_f];

				for (int nf=0; nf<nr_f; nf++)
					G[id][cont[id]++] = scn.nextInt();
			}

			stk = new Stack<Integer>();
			color = new boolean[nr_alunos + 1];

			DFSpile(1);

			// criar GT
			Gt = new int[nr_alunos+1][];
			cont_gt = new int[nr_alunos+1];

			for (int i=1; i<=nr_alunos; i++)
				Gt[i] = new int [nr_alunos-1];

			for (int na=1; na<=nr_alunos; na++){
				for (int i=0; i<cont[na]; i++){
					int x = G[na][i];
					Gt[x][cont_gt[x]++] = na;
				}	                        
			}

			Arrays.fill(color, false);
			int n = 0; //nr de componentes
			int r = 0; //nr de alunos

			while (!stk.isEmpty()){
				int a = stk.pop();
				if (!color[a]){
					int x = DFScont(a);
					if (x >= 4) n++;
					else r += x;
				}
			}

			System.out.println("Caso #" + nc);
			System.out.println(n + " " + r);
		}
	}

	public static void DFSpile(int root){
		color[root] = true;

		for (int i=0; i<cont[root]; i++){
			int x = G[root][i];
			if (!color[x])
				DFSpile(x);
		}
		stk.push(root);
	}

	public static int DFScont(int root){
		color[root] = true;
		int t = 1;
		for (int i=0; i<cont_gt[root]; i++){
			int x = Gt[root][i];
			if (!color[x])
				t += DFScont(x);
		}
		return t;
	}
}

import java.util.*;

class Node {
	public LinkedList<Integer> adj;
	public boolean visited;
	public int distance;   

	Node() {
		adj = new LinkedList<Integer>();
		visited = false;
		distance = -1;
	}
}


class Graph {
	int n; 
	Node nodes[];

	int exc; 

	Graph(int n) {
		this.n = n;
		nodes  = new Node[n+1]; 
		for (int i=1; i<=n; i++)
			nodes[i] = new Node();
	}

	public void addLink(int a, int b) {
		nodes[a].adj.add(b);
		nodes[b].adj.add(a);
	}


	public void bfs(int v) {
		LinkedList<Integer> q = new LinkedList<Integer>();

		q.add(v);
		nodes[v].visited = true;
		nodes[v].distance = 0;

		while (q.size() > 0) {
			int u = q.removeFirst();
			for (int w : nodes[u].adj)
				if (!nodes[w].visited) {
					q.add(w);
					nodes[w].visited  = true;
					nodes[w].distance = nodes[u].distance + 1; 
				}	    
		}
		exc = -1; 
		for(int i=1; i<=n; i++) {
			if(nodes[i].distance  > exc)
				exc = nodes[i].distance;
		}		
	}

	public int eccentricity() {
		return exc;
	}

	public void unvisit() {
		for(int i = 1; i<=n; i++) {
			nodes[i].visited = false;
		}
	}
}

public class prob19 {
	public static void main(String args[]) {
		Scanner in = new Scanner(System.in);
		Graph g = new Graph(in.nextInt());
		int   e = in.nextInt();
		for (int i=0; i<e; i++) 
			g.addLink(in.nextInt(), in.nextInt());
		int[] excentricidade = new int[g.n+1];		
		for(int i = 1; i<=g.n;i++) {
			g.bfs(i);
			excentricidade[i] = g.eccentricity();
			g.unvisit();
		}		

		int diameter = 0, radius = Integer.MAX_VALUE;

		for(int i = 1; i<=g.n;i++) {
			if (diameter < excentricidade[i]) {
				diameter = excentricidade[i];
			}
			if (radius > excentricidade[i]) {
				radius = excentricidade[i];
			}
		}

		System.out.println(diameter);
		System.out.println(radius);		
		String center = new String();
		for(int i = 1; i<=g.n; i++) {
			if(excentricidade[i] == radius) center += i + " ";
		}
		if (center.endsWith(" ")) {
			center = center.substring(0, center.length() - 1);
		}
		System.out.println(center);
		String periferal = new String();
		for(int i = 1; i<=g.n; i++) {
			if(excentricidade[i] == diameter) periferal += i + " ";
		}
		if (periferal.endsWith(" ")) {
			periferal = periferal.substring(0, periferal.length() - 1);
		}
		System.out.println(periferal);				
	}
}

