class Edg
{
    String vertexA, vertexB;
    int peso;

    public Edg(String vA, String vB, int p)
    {
        vertexA = vA;
        vertexB = vB;
        peso = p;
    }
    public String getVertexA()
    {
        return vertexA;
    }
    public String getVertexB()
    {
        return vertexB;
    }
    public int getpeso()
    {
        return peso;
    }
}
class Kruskl
{
    LinkedList<LinkedList<String>> grafo = new LinkedList<LinkedList<String>>();
    LinkedList<Edg> kruskalEdges = new LinkedList<Edg>();

    public LinkedList<Edg> getEdges()
    {
        return kruskalEdges;
    }


    LinkedList<String> getlista(String vertex)
    {
        for (LinkedList<String> lista : grafo) {
            if (lista.contains(vertex)) {
                return lista;
            }
        }
        return null;
    }
    public void insertEdge(Edg edge)
    {
        String vertexA = edge.getVertexA();
        String vertexB = edge.getVertexB();

        LinkedList<String> listaA = getlista(vertexA);
        LinkedList<String> listaB = getlista(vertexB);

        if (listaA == null) {
           kruskalEdges.add(edge);
            if (listaB == null) {
                LinkedList<String> novalista = new LinkedList<String>();
                novalista.add(vertexA);
                novalista.add(vertexB);
                grafo.add(novalista);
            }
            else {
                listaB.add(vertexA);           
            }
        }
        else {
            if (listaB == null) {
                listaA.add(vertexB);
                kruskalEdges.add(edge);
            }
            else if (listaA != listaB) {
                listaA.addAll(listaB);
                grafo.remove(listaB);
                kruskalEdges.add(edge);
           }
       }
    }  
}

