class Grafo {
    No verts[];
    int nvs, narcos;

    public Grafo(int n) {
	nvs = n;
	narcos = 0;
	verts  = new No[n+1];
	for (int i = 1 ; i <= n ; i++)
	    verts[i] = new No();
        }

    public int num_vertices(){
	return nvs;
    }

    public int num_arcos(){
	return narcos;
    }

    public LinkedList<Arco> adjs_no(int i) {
	return verts[i].adjs;
    }

    public void insert_new_arc(int i, int j, int valor_ij){
	verts[i].adjs.addFirst(new Arco(j,valor_ij));
        narcos++;
    }

    public Arco find_arc(int i, int j){
	for (Arco adj: adjs_no(i))
	    if (adj.extremo_final() == j) return adj;
	return null;
    }

    public void Prim(){
    	boolean a=false;
    	int dist[] = new int[nvs+1];
    	boolean op[] = new boolean[nvs+1];
    	int pai[]=new int[nvs+1];

    	for(int i=1;i<=nvs;i++){
    		dist[i]=Integer.MAX_VALUE;
    		op[i]=false;
    	}
    	dist[1]=0;
    	pai[1]=0;
    	Heapmin Q = new Heapmin(dist,nvs);
    	int u;
    	Arco n;
    	while(Q.size!=0){
    		u=Q.extractMin();
    			ListIterator<Arco> li = verts[u].adjs.listIterator();
				while(li.hasNext()){
					n=li.next();
					if((op[n.no_final]==false)&&(n.valor<dist[n.no_final])){
						dist[n.no_final]=n.valor;
						Q.decreaseKey(n.no_final, dist[n.no_final]);
						pai[n.no_final]=u;
					}
					op[u]=true;

    		}    			
    	}
    	int max=0;
    	for(int i=1;i<=nvs;i++){
    		if(dist[i]!=Integer.MAX_VALUE){
    			max=max+(dist[i]);
    		}
    		else{
    			System.out.println("impossivel");	
    			a=true;
    			break;
    		}


    	}
    	if(a!=true){
    		System.out.println("rendimento optimo: "+max*(-1));
    	}

    }
}

