class intercalScheduling{

    public static int Output(evento[] n,int m, int p){
	int end=0, pos=0, count=0;
	int best;

	while(end<m){
	    best=-1;
	    while(pos<p && n[pos].inicio<=end){
		if(n[pos].fim>best)
		    best=n[pos].fim;
		pos++;
	    }
	    end=best;
	    count++;
	}
	return count;
    }


