class EmptyQueueException extends RuntimeException {
    private static final long serialVersionUID = 1L;
    public EmptyQueueException(String err) {
	super(err);
    }
}
// no generico para uma lista ligada
class Node<E> {
    E       val;
    Node<E> next;

    Node() {
		val		= null;
		next	= null;
    }

    Node(E v, Node<E> n) {
		val= v;
		next= n;
    }
}

class Queue<E>  
{
    private int size;      // num. elementos
    private Node<E> first; // primeiro da fila
    private Node<E> last;  // ultimo da fila

    Queue()  {             // construtor fila vazia 
    	size= 0;
    	first= last= null;
    }

    public boolean isEmpty()  { return (size==0); }
    public int size() { return size; }

    // remove do inicio da fila
    public E dequeue() throws EmptyQueueException {
    	if (isEmpty())
    		throw new EmptyQueueException("Fila vazia!");

    	E r		= first.val;
    	first 	= first.next;
    	size--;

    	if (first==null) last=null;
			return r;
    }

    // adiciona ao fim da fila
    public void enqueue(E v) {
    	Node<E> n 		= new Node<E>(v, null);
    	Node<E> newNode	= new Node<E>();
		if (isEmpty()) {
		    last=n;
		    first=last;
		}
		else{
			newNode		= first;
			first		= n;
			n.next		= newNode;
		    //last.next=n;
		    //last=n;
		}

		size++;
    }
}

