	/* PSEUDOCODE
	 function Busca_Profundidade(Inicio, Alvo)
	  empilha(Pilha,Inicio)
	  while Pilha is not empty
	    var Nodo := desempilha(Pilha)
	    Colore(Nodo, Cinza)
	    if Nodo = Alvo
	      return Nodo
	    for Filho in Expande(Nodo)
	      if Filho.cor = Branco
	        empilha(Pilha, Filho)
	    Colore(Nodo, Preto)		 
	 */

	// Busca em profundidade
	public static int DFS(PointNode[] aPointNode, String sStreetBegin, String sStreetEnd)
	{
		int 				nResult		= -1;
		int					nCount		= 0;
		int 				nIndex		= 0;
		PointNode			pointnode	= null;
		Queue<PointNode>	queue 		= null;

		nIndex	= getArrayIndexByName(aPointNode, sStreetBegin);
		queue	= new Queue<PointNode>();

		if(nIndex == -1)
		{
			System.err.println("Something is Wrong. That Point does not exists");
			System.exit(1);
		}

		queue.enqueue(aPointNode[nIndex]);

		nIndex	= 0;

		while(!queue.isEmpty())
		{
			pointnode	= queue.dequeue();
			pointnode.setColor(GREY);

			if(pointnode.getName().equals(sStreetEnd))
			{
				nCount++;
			}

			for(int i = 0; i < pointnode.getConns().size(); i++)
			{
				nIndex	= getArrayIndexByName(aPointNode, pointnode.getConns().get(i));
				if(aPointNode[nIndex].getColor() == WHITE)
				{
					queue.enqueue(aPointNode[nIndex]);
				}
			}

			pointnode.setColor(BLACK);
		}

		return nCount;
	}
	public static int getArrayIndexByName(PointNode[] aPointNode, String sPointName)
	{
		int nResult	= -1;

		for(int i = 0; i < aPointNode.length; i++)
		{
			if(aPointNode[i].getName().equals(sPointName))
			{
				nResult	= i;
				break;
			}
		}

		return nResult;
	}
}

