class encomenda implements Comparable <encomenda> {
    int dias;
    int multa;
    float ratio;
    int index;

    public encomenda (int dias, int multa, float ratio, int index) {
        this.dias = dias;
        this.multa = multa;
        this.ratio = ratio;
        this.index = index;
    }

    @Override

    public int compareTo (encomenda enc) {
        if (ratio < enc.ratio) return -1;
	if (ratio > enc.ratio) return +1;
        if (ratio == enc.ratio) {
            if (multa < enc.multa) return -1;
            if (multa > enc.multa) return +1;
        }
	return 0;
    }
}


