		    cont += 1;
	    }
	}
	int print = mergesort(vetor, 0 ,n-1);
	System.out.println(print);
    }


    static int mergesort(int v[], int inicio, int fim) {
	int meio;
	int cont = 0;
	if(inicio < fim) {
	    meio = (inicio+fim)/ 2;
	    cont += mergesort(v, inicio, meio);
	    cont += mergesort(v, meio+1, fim);
	    cont += merge(v, inicio, meio ,fim);
	}
	return cont;
}

    static int merge(int v[], int inicio, int meio, int fim) {
	int i, p1, p2;
	int aux[] = new int[fim+1];
	int cont1 = 0;
	p1 = inicio;
	p2 = meio +1;
	i = inicio;

	while(p1 <= meio && p2 <= fim) {

	    if(v[p1] <= v[p2]) {
		cont1++;
		aux[i++] = v[p1++];
	    }
	    else {
		aux[i++] = v[p2++];
	    }
	}
	    while(p1 <= meio) {
		aux[i++] = v[p1++];
		cont1++;
	    }

	    while(p2 <= fim) {
		aux[i++] = v[p2++];
		cont1++;
	    }

	    for(i = inicio; i <= fim; i++) {
		v[i] = aux[i];
	    }
	    return cont1;
    }
}

