class ne {
	public static void main(String args[]) {
		Scanner in = new Scanner(System.in);

		int nnos = in.nextInt();
		int t = in.nextInt();

		Grafo g = criaGrafo(in, nnos);

		DijkstraminAdap(g, t);
	}

	static Grafo criaGrafo(Scanner in, int n) {
		Grafo g = new Grafo(n);

		int v = in.nextInt();
		while (v!=-1) {
			int w = in.nextInt();
			int d = in.nextInt();

			g.insert_new_arc(v, w, d);
			g.insert_new_arc(w, v, d);

			v = in.nextInt();
		}

		return g;
	}

	static void DijkstraminAdap(Grafo g, int s) {
		boolean vis[] = new boolean[g.num_vertices()+1];
		int dist[] = new int[g.num_vertices()+1];
		for (int i = 1; i <= g.num_vertices(); i++) {
			dist[i] = Integer.MAX_VALUE;
		}
		dist[s] = 0;

		Heapmin pq = new Heapmin(dist, g.num_vertices());
		int last=0;

		while (pq.size>0) {
			int v = pq.extractMin();
			vis[v] = true;
			if(dist[v]==Integer.MAX_VALUE) break;

			for (Arco a : g.adjs_no(v)) {
				int w = a.extremo_final();

				if(!vis[w]) {
					if(dist[v]+a.valor_arco()<dist[w]) {
						dist[w] = dist[v]+a.valor_arco();
						pq.decreaseKey(w, dist[w]);
					}
				}
			}

			if(last!=0) System.out.print(last+" ");
			last = v;
		}

		System.out.print(last+"\n");
	}
}

