		for (int i=1;i<n; i++) {
			for (int j = 0; j<n;j++){			
				if (  (j+1<n) &&  (piramide[i][j] != -1) ) {
					long b = piramide[i-1][j];
					long a = piramide[i-1][j+1]; 
					if (a !=-1 && b !=-1){
						piramide[i][j] = a+b;
					}
					else if (a != -1){
						piramide[i][j] += a;
					}
					else if (b !=-1){
						piramide[i][j] += b;
					}
				}
			}
		}
