class Encomenda implements Comparable<Encomenda>{
    int dias;
    int multa;
    int ordem;

    Encomenda(int dias, int multa, int ordem){
	this.dias = dias;
	this.multa = multa;
	this.ordem = ordem;
    }

    @Override
    public int compareTo(Encomenda x){
	float ratioA = (float)this.multa/this.dias;

	float ratioB = (float)x.multa/x.dias;

	if(ratioA>ratioB){
	    return -1;
	}
	else if(ratioA<ratioB){
	    return 1;
	}
	else{
	    if(this.ordem<x.ordem) return -1;
	    else if(this.ordem>x.ordem) return 1;
	    else return 0;
	}
    }
}

