    //  - numero > 0 se objecto for maior que objecto "n"
    //  - zero, se objecto for igual ao objecto "n"
    @Override
    public int compareTo(Sapato n){

	if(racio == n.racio)
	    if(index < n.index) return -1;
	    else return 1;
	else
	    if(racio < n.racio) return 1;
	    else return -1;

    }
}

