class Vertice {
    int vert;
    int chave;

    Vertice(int v,int c){
	vert=v;
	chave=c;
    }
}

class Heap {
    Vertice fila_p[]; //fila de prioridade. Tem dimensao igual ao numero de vertices do grafo
    int pos_v[]; //pos_v[i] e o indice de posicao do vertice i na fila de prioridade. Tem dimensao igual ao numero de vertices do grafo
    int nverts; //indica o numero de vertices que a fila de prioridade tem. Quando o i=nverts, fila_p[i] contem o elemento que esta 

    Heap(int nv){
	fila_p=new Vertice[nv+1];
	pos_v=new int[nv+1];

	for(int i=0;i<=nv;i++){
	    fila_p[i]=new Vertice(i,1000);
	    pos_v[i]=i;
	}

	nverts=nv;
    }

    boolean isEmpty(){
	return nverts==0;
    }

    Vertice paiVert_fila_p(int i){ //retorna toda a identificacao, que existe na fila de prioridade, do pai do vertice que tem posicao i na heap
	int p=i/2;
	return fila_p[p];
    }
    int paiVert_pos_v(int i){ //retorna a posicao do pai do vertice que tem posicao i, em relacao a fila de prioridade 
	int p=i/2;
	return p;
    }

    private void troca(int i, int pai_i){ //troca o vertice que tinha a posicao i com o seu pai que tinha posicao pai_i na heap
	int v1=fila_p[i].vert, v2=fila_p[pai_i].vert;
	pos_v[v1]=pai_i;
	pos_v[v2]=i;

	Vertice aux=fila_p[pai_i];
	fila_p[pai_i]=fila_p[i];
	fila_p[i]=aux;
    }

    private void heapify(int i){ //no inicio, o vertice que esta na posicao i da heap, esta na raiz, ou seja, i=1. Este vertice vai descer da arvore, caso este nao respeite a ordencao correcta da heap
	int fesq=i*2; //posicao do filho esquerdo (se existir) do vertice que esta na posicao i, na fila de prioridade 
	int fdir=i*2+1; //posicao do filho direito (se existir) do vertice que esta na posicao i, na fila de prioridade
	int fmin=0; //posicao do filho (se existir) que tem menor chave entre o filho da esquerda e o da direita; ou o que tem menor vertice, caso ambos os filhos tenham a mesma chave; ou o filho esquerdo, caso nao exista o filho direito 
	int min=i; //posicao do vertice que tem menor chave dos 3 vertices que estao a ser comparados, ou entao caso todos tenham a mesma chave e a posicao do que tem vertice menor, na fila de prioridade

	if(fesq<=nverts){
	    if(fdir<=nverts){
		if((fila_p[fesq].chave<fila_p[fdir].chave) || (fila_p[fesq].chave==fila_p[fdir].chave && fila_p[fesq].vert<fila_p[fdir].vert))
		    fmin=fesq;
		else
		    fmin=fdir;
	    }
	    else
		fmin=fesq;
	}

	if(fmin>0 && ((fila_p[fmin].chave<fila_p[i].chave) || (fila_p[fmin].chave==fila_p[i].chave && fila_p[fmin].vert<fila_p[i].vert))) 
	    min=fmin;

	if(min!=i){
	    troca(min,i);
	    heapify(min); //na verdade, faz-se o heapify no vertice que tinha anteriormente a posicao i na heap, mas agora o i ja e o valor de fmin, devido a troca que foi feita
	}
    }

    void decreaseKey(int v,int cnova){ //diminui a chave do vertice i na heap e, consequentemente, podera ser necessario repor as condicoes iniciais de ordenacao
	int i=pos_v[v];
	fila_p[i].chave=cnova;
	while(i>1 && (fila_p[i].chave < paiVert_fila_p(i).chave || (fila_p[i].chave==paiVert_fila_p(i).chave && fila_p[i].vert < paiVert_fila_p(i).vert))){ //i>1 porque i=1 e a raiz da arvore da fila de prioridade
	    troca(i,paiVert_pos_v(i));
	    i=paiVert_pos_v(i);
	}
    }

    int extractMin(){ //retira o primeiro elemento da heap, que esta na posicao 1 e retorna esse valor. Como consequencia, a heap fica alterada e e necessario repor as suas condicoes iniciais de ordenacao 
	int vmin=fila_p[1].vert;
	fila_p[1]=fila_p[nverts];

	pos_v[vmin]=0;
	pos_v[fila_p[1].vert]=1;
	pos_v[fila_p[nverts].vert]=0;

	heapify(1);
	nverts--;
	return vmin;
    }
}
