class krusk {

    int mat[][];
    int nos[][];
    int a[][];
    int p;
    int r;
    int na;
    int cnt;
    int custos;
    krusk(int matriz[][],int tnos,int tlig,int zz){
	p = tnos;
	mat = matriz;
	r = tlig;
	nos = new int[p][3];
	na = 0;
	a = new int [tnos][3];
	cnt=0;
	custos=zz;
    }

    void principal () {

	inicio();

	int u = -1;
	int z = 1;
	int uz = 1;
	int i = 0;

	while (uz != 0){
	    z = min(r,mat);
	    if (u != z) {

		if ((findset(mat[z][0])) != (findset(mat[z][1]))){
		    a[i][0] = mat[z][0];
		    a[i][1] = mat[z][1];
		    cnt += mat[z][2];
		    union(mat[z][0],mat[z][1]);
		    i++;
		}
		mat[z][2]=0;
		u = z;
	    }
	    else {uz = 0;}
	}

	if (i == (p-1)){

	    System.out.println("rendimento optimo:" + (cnt+custos));
	}
	else {System.out.println("impossivel");

	}
    }

    void inicio() {

	for (int ij=0;ij<p;ij++){
	    nos[ij][0] = 0;
	}
    }

    void makeset(int x) {

	nos[na][0] = x;
	nos[na][1] = 0;
	nos[na][2] = x;
	na++;


    }

    int findset(int x) {

	int ind = find (x);
	if (nos[ind][2] != x) {
	    nos[ind][2] = findset(nos[ind][2]);
	}
	return nos[ind][2];
    }

    int find(int x){

	for(int i=0;i<p;i++){
	    if (nos[i][0]==x){
		return i;	
	    }
	}
	makeset(x);
	return na-1;
    }

    void union (int x,int y){

	link(findset(x),findset(y));
    }

    void link(int x,int y){

	int h = find(x);
	int g = find(y);

	if (nos[h][1] > nos[g][1]){
	    nos[g][2] = nos[h][0];
	}
	else {
	    nos[h][2] = nos[g][0];
	    if (nos[h][1] == nos[g][1]){
		nos[g][1] += 1;
	    }
	}
    }

    int min(int pp,int f[][]){

	int ind = 0;
	int i =0;

	while (f[i][2] == 0){
	    i++;
	    if (i==(pp-1)){break;}
	}


	int min = f[i][2];
	for (int b=i;b<pp;b++) {

	    if (min >= f[b][2] && f[b][2] != 0){
		min = f[b][2];
		ind = b;
	    }
	}

	return ind;
    }
}


