    void quicksort (int f[],int pp,int rr){

	if (pp < rr){
	    int q = part(f,pp,rr);
	    quicksort(f,pp,q-1);
	    quicksort(f,q+1,rr);
	}
    }

    int part(int f[],int pp,int rr){

	int z = f[rr];

	int i = pp-1;

	for (int j=pp;j<=rr-1;j++){
	    if (f[j] <= z){
