class VerticesAdj {//os objectos desta classe serao guardados em listas (cada um e no duma lista). Cada uma das listas tera todos vertices que tem em comum um vertice que que lhes esta ligado no grafo e tambem sera guardado o custo dessas ligacoes (arestas) nos vertices correspondentes.

    int vertice;
    int cmax; //comprimento maximo
    VerticesAdj prox;

    VerticesAdj(int v, int c, VerticesAdj p){
	vertice=v;
	cmax=c;
	prox=p;
    }
}

class Grafo {

    VerticesAdj v[]; //v[i] tem todos os vertices que estao ligados ao vertice i (lista dos vertices adjacentes de i). Os vertices estao numerados de 1 a nverts
    int nverts;

    int cmax; //comprimento maximo que a jaula pode ter

    /*********************Algoritmo Dijkstra*********************/

    private int comp[]; //comp[i] e o comprimento maximo que a jaula pode ter durante o caminho de um dado vertice ate i
    private int prec[]; //prec[i] e o precedente do vertice i, no caminho de distancia minima (custo minimo) de um dado vertice ate ao vertice i   

    /*********************Algoritmo Dijkstra*********************/

    Grafo(int nv, int cm){
	nverts=nv;

	v=new VerticesAdj[nv+1];
	for(int i=1;i<=nv;i++)
	    v[i]=null;

	cmax=cm;

	comp=new int[nv+1];
	prec=new int[nv+1];
    }

    void inserirLigacao(int v1, int v2, int c){
	v[v1]=new VerticesAdj(v2,c,v[v1]);
	v[v2]=new VerticesAdj(v1,c,v[v2]);
    }

    void comprimentoMax_jaula(int origem, int destino){
	dijkstra(origem);

	if(comp[destino]==cmax)
	    System.out.println("0");
	else
	    System.out.println(comp[destino]);
    }

    /*********************Algoritmo Dijkstra*********************/
    private int comprimento_Min(int c1, int c2){
	if(c1<c2)
	    return c1;
	return c2;
    }

    private void dijkstra(int vert){

	for(int i=1;i<=nverts;i++){ 
	    comp[i]=0; 
	    prec[i]=nverts;
	}

	comp[vert]=cmax;

	Heap f=new Heap(nverts);
	f.newKey(vert,comp[vert]);

	while(!f.isEmpty()){ 
	    int u=f.extractMax();

	    for(VerticesAdj p=v[u];p!=null;p=p.prox)
		if(comprimento_Min(comp[u],p.cmax)>comp[p.vertice]){
		    comp[p.vertice]=comprimento_Min(comp[u],p.cmax);
		    f.newKey(p.vertice,comp[p.vertice]);
		    prec[p.vertice]=u; 
		}
	}

    }
    /*********************Algoritmo Dijkstra*********************/

}

