	int counter=0;
	for (int i=0; i<nligaçoes; i++) {
	    int a = input.nextInt();
	    int b = input.nextInt();
	    adj[a][b] = adj[b][a] = true;
	}

    if(nligaçoes==0) counter=n;
    else
    {
        for(int i=1;i!=n;i++)
        {
            if(!visited[i]){
            dfs(i);
            counter++;
            }
        }
    }
	dfs(1); // Pesquisa em profundidade a partir do no 1
