}
class Grafo{
	int tempo, nalunos;
	No g[];
	No gt[];
	LinkedList<Integer> grupos;

	Grafo(int np){
		this.nalunos = np;
		tempo = 0;
		g = new No[np+1];
		gt = new No[np+1];
		grupos = new LinkedList<Integer>();
	}
	private void ini(){
		for(int i = 1; i<=nalunos; i++){
			g[i] = new No(i);
			gt[i] = new No(i);
		}
	}
	void criaGrafo(Scanner in){
		ini();
		for(int i = 1; i<=nalunos; i++){
			int namigo = in.nextInt();
			for(int j = 0; j<namigo; j++){
				int amigo = in.nextInt();
				g[i].addL(g[amigo]);
				gt[amigo].addL(gt[i]);
			}
		}
	}
	void DFS(){
		DFSVisit(g[1]);
	}
	private void DFSVisit(No x){
		x.visitado = true;
		for(No cursor: x.adj){
			if(!cursor.visitado)
				DFSVisit(cursor);
		}
		tempo++;
		x.tempof =tempo;
		gt[x.val].tempof = tempo;
	}	
	private No findMax(){
		int maximo = 0; 
		No max = new No(0);

		for(int i = 1; i<=nalunos; i++){
			if(!gt[i].visitado){
				if(gt[i].tempof > maximo){
					maximo = gt[i].tempof;
					max = gt[i];
				}
			}
		}
		return max;
	}
	private boolean allVisited(){
		for(int i = 1; i<=nalunos; i++){
			if(!gt[i].visitado)
				return false;
		}
		return true;
	}
	void DFS_T(){
		while(!allVisited()){
			No TMax = findMax();
			int nelementos = n_eg(TMax);
			grupos.addLast(nelementos);
			TMax.tempof = 0;
		}
	}
	private int n_eg(No x){
		int count = 1;
		x.visitado = true;
		for(No cursor: x.adj){
			if(!cursor.visitado)
				count +=n_eg(cursor);
		}
		return count;
	}
}

