				System.out.println(m);
		}
	}

	static int bsearch(int v[], int low, int high, int key){
		int middle = 0;
		while(low < high){
			middle = low + (high - low)/2;
			if(key == v[middle])
				return middle;
			else if(key < v[middle])
				high = middle;
			else 
				low = middle + 1;
		}
		//middle vai sempre ser o valor imediatamente atrás do high
		//ou o valor imediatamente a seguir ao low
		middle = low;
		if(middle > 0){
			if(key - v[middle-1] < v[middle] - key)
				return middle-1;
			if(key - v[middle-1] == v[middle] - key){
				System.out.print(v[middle-1] + " " );
				return middle;
			}
			if(v[middle]-key < key - v[middle-1])
				return middle;
		}
		return middle;

	}
}

