class Qnode {
    int vert;
    int vertkey;

    Qnode(int v, int key) {
	vert = v;
	vertkey = key;
    }
}

class Heapmax {
    private static int posinvalida = 0;
    int sizeMax,size;

    Qnode[] a;
    int[] pos_a;

    Heapmax(int vec[], int n) {
	a = new Qnode[n + 1];
	pos_a = new int[n + 1];
	sizeMax = n;
	size = n;
	for (int i = 1; i <= n; i++) {
	    a[i] = new Qnode(i,vec[i]);
	    pos_a[i] = i;
	}

	for (int i = n/2; i >= 1; i--)
	    heapify(i);
    }

    int extractMin() {
	int vertv = a[1].vert;
	swap(1,size);
	pos_a[vertv] = posinvalida;  // assinala vertv como removido
	size--;
	heapify(1);
	return vertv;
    }

    void decreaseKey(int vertv, int newkey) {

	int i = pos_a[vertv];
	a[i].vertkey = newkey;

	while (i > 1 && compare(i, parent(i)) > 0) { 
	    swap(i, parent(i));
	    i = parent(i);
	}
    }


    void insert(int vertv, int key)
    { 
	if (sizeMax == size)
	    new Error("Heap is full\n");

	size++;
	a[size].vert = vertv;
	pos_a[vertv] = size;   // supondo 1 <= vertv <= n
	decreaseKey(vertv,key);   // diminui a chave e corrige posicao se necessario
    }

    void write_heap(){
	System.out.printf("Max size: %d\n",sizeMax);
	System.out.printf("Current size: %d\n",size);
	System.out.printf("(Vert,Key)\n---------\n");
	for(int i=1; i <= size; i++)
	    System.out.printf("(%d,%d)\n",a[i].vert,a[i].vertkey);

	System.out.printf("-------\n(Vert,PosVert)\n---------\n");

	for(int i=1; i <= sizeMax; i++)
	    if (pos_valida(pos_a[i]))
		System.out.printf("(%d,%d)\n",i,pos_a[i]);
    }

    private int parent(int i){
	return i/2;
    }
    private int left(int i){
	return 2*i;
    }
    private int right(int i){
	return 2*i+1;
    }

    private int compare(int i, int j) {
	if (a[i].vertkey < a[j].vertkey)
	    return -1;
	if (a[i].vertkey == a[j].vertkey)
            if (a[i].vert>a[j].vert) return 1;
            else return -1;
	return 1;
    }


    private void heapify(int i) {
	int l, r, smallest;

	l = left(i);
	if (l > size) l = i;

	r = right(i);
	if (r > size) r = i;

	smallest = i;
	if (compare(l,smallest) > 0)
	    smallest = l;
	if (compare(r,smallest) > 0)
	    smallest = r;

	if (i != smallest) {
	    swap(i, smallest);
	    heapify(smallest);
	}

    }

    private void swap(int i, int j) {
	Qnode aux;
	pos_a[a[i].vert] = j;
	pos_a[a[j].vert] = i;
	aux = a[i];
	a[i] = a[j];
	a[j] = aux;
    }

    private boolean pos_valida(int i) {
	return (i >= 1 && i <= size);
    }
}

class Arco {
    int no_final;
    int valor;

    Arco(int fim, int v){
	no_final = fim;
	valor = v;
    }

    int extremo_final() {
	return no_final;
    }

    int valor_arco() {
	return valor;
    }
}


class No {
    //int label;
    LinkedList<Arco> adjs;

    No() {
	adjs = new LinkedList<Arco>();
    }
}


class Grafo {
    No verts[];
    int nvs, narcos;

    public Grafo(int n) {
	nvs = n;
	narcos = 0;
	verts  = new No[n+1];
	for (int i = 0 ; i <= n ; i++)
	    verts[i] = new No();
        // para vertices numerados de 1 a n (posicao 0 nao vai ser usada)
    }

    public int num_vertices(){
	return nvs;
    }

    public int num_arcos(){
	return narcos;
    }

    public LinkedList<Arco> adjs_no(int i) {
	return verts[i].adjs;
    }

    public void insert_new_arc(int i, int j, int valor_ij){
	verts[i].adjs.addFirst(new Arco(j,valor_ij));
        narcos++;
    }

    public Arco find_arc(int i, int j){
	for (Arco adj: adjs_no(i))
	    if (adj.extremo_final() == j) return adj;
	return null;
    }
}

public class Optica_mini {
    public static void main (String args[]) {
        Scanner in = new Scanner (System.in);
        int nnos = in.nextInt();
        Grafo g = new Grafo (nnos+1);
        int nl = in.nextInt();
        int custo = in.nextInt();
        int index = 0;
        int primeiro = 0;

        for (int i=0; i<nl; i++) {
            int a1 = in.nextInt();
            if (index == 0) {
                primeiro = a1;
                index = 1;

            }
            int a2 = in.nextInt();
            int rendim = in.nextInt();
            g.insert_new_arc(a1, a2, rendim-custo);
            g.insert_new_arc(a2, a1, rendim-custo);
        }

        Prim (g, primeiro);
    }

    public static void Prim (Grafo g, int p) {
        int dist []= new int[g.num_vertices()+1];
        LinkedList<Integer> visitado = new LinkedList<Integer>();

        for (int i=1; i<=g.num_vertices(); i++) {
            dist[i] = Integer.MIN_VALUE;
            dist[p] = 0;
        }

        Heapmax h = new Heapmax (dist, g.num_vertices()-1);
        int sum = 0, m=0;
        while (h.size>0) {
            m = h.extractMin();
            if (dist[m]!=Integer.MIN_VALUE) {
                for (Arco a:g.adjs_no(m)) {
                    if (a.valor_arco()>dist[a.extremo_final()] && !visitado.contains(a.extremo_final())) {
                        dist[a.extremo_final()]=a.valor_arco();
                        h.decreaseKey(a.extremo_final(), dist[a.extremo_final()]);
                    }
                }
            }
            visitado.add(m);
            sum+=dist[m];
        }

        if (dist[m] == Integer.MIN_VALUE) {
            System.out.println("impossivel");
        }

        else {
            System.out.println("rendimento optimo: " + sum);
        }
    }
}

import java.util.*;

class Regiao{
	LinkedList<Ligacao> ligacoes;
	int distancia;
	boolean visitado;
	int nome;
	Regiao(int nome){
		ligacoes = new LinkedList<Ligacao>();
		distancia = 999999999;
		visitado = false;
		this.nome = nome;
	}
}

class Ligacao{
	int regiao;
	int distancia;
	Ligacao(int regiao, int distancia){
		this.regiao = regiao;
		this.distancia = distancia;
	}
}

public class NegocioEletronico {
	static Regiao[] sort(Regiao[] regioes){
		Regiao[] res = new Regiao[regioes.length];
		res[0] = regioes[0];
		int i, j;
		Regiao k, m;
		for(i=1; i<regioes.length; i++){
			k = regioes[i];
			for(j=0; j<res.length && res[j]!=null && k.distancia>=res[j].distancia; j++);
			while(j<res.length){
				m = res[j];
				res[j] = k;
				k = m;
				j++;
			}
		}
		return res;
	}

	static int getMin(Regiao[] regioes){
		int i=0, min=-1;
		for(; i<regioes.length; i++)
			if(!regioes[i].visitado){
				min=i;
				break;
			}
		for(; i<regioes.length; i++)
			if(!regioes[i].visitado && regioes[i].distancia<regioes[min].distancia)
				min = i;
		return min;
	}
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		int d = in.nextInt()-1;
		Regiao[] regioes = new Regiao[n];
		for(int i=0; i<n; regioes[i]=new Regiao(i), i++);
		int x, y, dis;
		while(true){
			x = in.nextInt()-1;
			if(x==-2) break;
			y = in.nextInt()-1;
			dis = in.nextInt();
			regioes[x].ligacoes.add(new Ligacao(y, dis));
			regioes[y].ligacoes.add(new Ligacao(x, dis));
		}
		int nVisitados = 1;
		regioes[d].visitado = true;
		regioes[d].distancia = 0;
		for(Ligacao l : regioes[d].ligacoes)
			regioes[l.regiao].distancia = l.distancia;
		int i;
		while(nVisitados<n){
			i = getMin(regioes);
			if(i<0)
				break;
			regioes[i].visitado = true;
			for(Ligacao l : regioes[i].ligacoes)
				if(regioes[l.regiao].distancia>regioes[i].distancia+l.distancia)
					regioes[l.regiao].distancia = regioes[i].distancia+l.distancia;
		}
        regioes = sort(regioes);
		for(i=0; i<regioes.length; i++){
			System.out.print(regioes[i].nome+1);
            if(i!=regioes.length-1)
                System.out.print(' ');
            else
                System.out.print('\n');
        }
	}
}

import java.util.LinkedList;
import java.util.Scanner;

class Node{
	int value;
	int timef;
	boolean visit;
	LinkedList<Node> adj;

	Node(int v){
		value = v;
		timef = 0;
		visit = false;
		adj = new LinkedList<Node>();
	}

	void addConnection(Node n){
		adj.addLast(n);
	}
}

class Graph{
	int nstudents;
	int time;
	Node g[];
	Node gt[];
	LinkedList<Integer> group;

	Graph(int nst){
		nstudents = nst;
		g = new Node[nst+1];
		gt = new Node[nst+1];
		time = 0;
		group = new LinkedList<Integer>();
	}

	void initialize(){
		for(int i=1; i<=nstudents; i++){
			g[i] = new Node(i);
			gt[i] = new Node(i);
		}
	}

	void createGraph(int s, int f){
		g[s].addConnection(g[f]);
		gt[f].addConnection(gt[s]);
	}


	void DFS(){
		for(int i=1; i<=nstudents; i++){
			if(!g[i].visit)
				DFS_Visit(g[i]);
		}
	}
	private void DFS_Visit(Node n){
		time++;
		n.visit = true;

		int size = n.adj.size();
		for(int i=0; i<size; i++){
			Node v = n.adj.get(i);
			if(!v.visit){
				DFS_Visit(v);
			}
		}
		time++;
		n.timef = time;
		gt[n.value].timef = time;
	}


	private Node discover(){
		int max_timef = 0;
		Node last_node = new Node(0);

		for(int i=1; i<=nstudents; i++){
			if(!gt[i].visit){
				if(gt[i].timef > max_timef){
					max_timef = gt[i].timef;
					last_node = gt[i];
				}
			}
		}
		return last_node;
	}


	private boolean nodeVisited(){
		for(int i=1; i<=nstudents; i++){
			if(!gt[i].visit)
				return false;
		}
		return true;
	}


	private int countNodes(Node n){
		int count = 1;
		n.visit = true;

		int size = n.adj.size();
		for(int i=0; i<size; i++){
			Node tmp = n.adj.get(i);
			if(!tmp.visit){
				count += countNodes(tmp);
			}
		}
		return count;
	}


	void DFS_T(){
		while(!nodeVisited()){
			Node v = discover();
			int nelem = countNodes(v);
			group.addLast(nelem);
			v.timef = 0;
		}
	}


	void output(){
		int ngroup = 0;
		int nout = 0;

		int size = group.size();
		for(int i=0; i<size; i++){
			int x = group.get(i);
			if(x >= 4)
				ngroup++;
			else
				nout += x;
		}
		System.out.printf("%d %d\n", ngroup, nout);
	}
}




public class Sociologia {
	public static void main(String args[]){
		Scanner stdin = new Scanner(System.in);


		int nscenarios = stdin.nextInt();

		for(int i=1; i<=nscenarios; i++){

			int nstudents = stdin.nextInt();

			Graph G = new Graph(nstudents);
			G.initialize();
			for(int j=1; j<=nstudents; j++){
				int student = stdin.nextInt();
				int nfriends = stdin.nextInt();
				for(int k=0; k<nfriends; k++){
					int friend = stdin.nextInt();
					G.createGraph(student, friend);
				}
			}

			G.DFS();
			G.DFS_T();

			System.out.printf("Caso #%d\n", i);
			G.output();
		}
	}
}

