	for (int j = 0; j < q; j++){
	    quest [j] = stdin.nextInt();
	    int res = bsearch (somas(v),0,somas(v).length-1,quest[j]);
	    solve (somas(v), res, quest[j]);  
	    System.out.println();
	}
    }
}

