		ArrayList<aPatrao> patroes = new ArrayList<aPatrao>();
		for(int j = 1; j < patrao.length ; j ++){
			patroes.add(patrao[j]);
		}

		while(patroes.isEmpty() == false){


			aPatrao amigoDoBoss = null;
			int temp_count = 0;
			patrao[1].marked = true;
			patroes.remove(patrao[1]);
			for(int i = 1; i < patrao.length ; i++){

				if (patrao[i].marked == true){
					for(int temp_patrao : patrao[i].listAdj.keySet()){
						if(patrao[i].listAdj.get(temp_patrao) > temp_count  && patrao[temp_patrao].marked == false){
							temp_count = patrao[i].listAdj.get(temp_patrao);
							amigoDoBoss = patrao[temp_patrao];
						}
					}
				}
			}
			patroes.remove(amigoDoBoss);
			amigoDoBoss.setMarked(true);

			rendimento_max += temp_count;

		}
	}
