import java.util.*;

class Arco{
    int x;
    int y;
    int peso;

    Arco(int a, int b, int c){
	x= a;
	y= b;
	peso= c;
    }
}

class GNode{
    int nome= Integer.MIN_VALUE;
    int pai= Integer.MIN_VALUE;
    int rank= Integer.MIN_VALUE;
}

class MST{
    void Kruskal(GNode[] G, ArrayList<Arco> A, int C){
	int nligacoes= A.size();
	ArrayList<Arco> Resultado= new ArrayList<Arco>();
	for(int i= 0; i< G.length; i++){
	    MakeSet(G[i]);
	}
	for(int i= 0; i< nligacoes; i++){
	    Arco arcmax= new Arco(Integer.MIN_VALUE, Integer.MIN_VALUE, Integer.MIN_VALUE);
	    int index= Integer.MIN_VALUE;
	    for(int j= 0; j< A.size(); j++){
		if(A.get(j).peso> arcmax.peso){
		    arcmax= A.get(j);
		    index= j;
		}
	    }
	    A.remove(index);
	    if(FindSet(G[(arcmax.x)-1], G)!= FindSet(G[(arcmax.y)-1], G)){
		Resultado.add(arcmax);
		Union(G[(arcmax.x)-1], G[(arcmax.y)-1], G);
	    }
	}


	int somatotal= 0;
	int narvores= 0;
	for(int i= 0; i< G.length; i++){
	    if(G[i].pai== G[i].nome){
		narvores++;
	    }
	}
	if(narvores== 1){
	    for(int i= 0; i< Resultado.size(); i++){
		somatotal= somatotal + Resultado.get(i).peso;
	    }
	    System.out.println("rendimento optimo: " + somatotal);
	}
	else{
	    System.out.println("impossivel");
	}
    }

    void MakeSet(GNode n){
	n.pai= n.nome;
	n.rank= 0;
    }

    int FindSet(GNode n, GNode[] G2){
	if(n.pai!= n.nome){
	    n.pai= FindSet(G2[n.pai-1], G2);
	    return n.pai;
	}
	else{
	    return n.pai;
	}
    }

    void Union(GNode p, GNode q, GNode[] G3){
	Link(G3[FindSet(p, G3)-1], G3[FindSet(q, G3)-1]);
    }

    void Link(GNode m, GNode n){
	if (m.rank> n.rank){
	    n.pai= m.nome;
	}
	else{
	    m.pai= n.nome;
	    if (m.rank== n.rank){
		n.rank++;
	    }
	}
    }
}

