		Vertice x = g.vertices.get(inp.nextInt() - 1);
		Vertice y = g.vertices.get(inp.nextInt() - 1);
		g.addAresta(x, y);		
	}

	int c = 0;
	for(Vertice x:g.vertices){
		x.visit = false;
	}
	for(Vertice x:g.vertices){
		if(x.visit == false){
			c++;
			g.dfs(x);
		}
	}

	System.out.println(c);
	inp.close();
    }
}

