        Scanner scan = new Scanner(System.in);

        int nVec=Integer.parseInt(scan.next());

        v = new int[nVec];

        aux = new int[nVec];

        int valor, k=0;
        /**/
        while(k<nVec){
            valor=Integer.parseInt(scan.next());
            v[k]=valor;
            k++;
         }
        /**/
        //v = gerarLista(nVec, 1, 130);

        //imprLista(v);

        mergesort(v, 0, v.length - 1);

        imprLista(v);
    }
}

