		for(int i=0;i<n;i++) vetor[i]=in.nextInt();
		int trocas = bubbleSort(vetor);
		System.out.println(trocas);


	}
	public static int bubbleSort(int[] valores)
	{	
		int trocas=0;
		boolean trocado=true;
		for(int i=0;i<valores.length-1 && trocado;i++)
		{
			trocado=false;
			for(int j=0;j<valores.length-1;j++)
			{
				if(valores[j]>valores[j+1])
				{
					swap(valores,j,j+1);
					trocado=true;
					trocas++;
				}
			}
		}
		return trocas;
	}

	public static void swap(int[] valores,int i,int j)
	{
		int temporario = valores[i];
		valores[i]=valores[j];
		valores[j]=temporario;
	}

}

import java.util.*;

public class InversoesV2 {
    public static long inversoes = 0;

    public static void merge(int left[], int right[], int resultado[]) {
	int i = 0, j = 0, k = 0;
	while(i < left.length && j < right.length) {
	    if(left[i] > right[j]) {
		resultado[k++] = right[j++];
		inversoes += left.length - i;
	    }
	    else resultado[k++] = left[i++];
	}

	for(int t = i; t < left.length; t++) resultado[k++] = left[t];
	for(int t = j; t < right.length; t++) resultado[k++] = right[t];
    }

    public static void mergesort(int numeros[]) {
	if(numeros.length <= 1) return;

	int middle = numeros.length / 2;
	int left[] = new int[middle];
	int right[] = new int[numeros.length - middle];

	System.arraycopy(numeros, 0, left, 0, left.length);
	System.arraycopy(numeros, middle, right, 0, right.length);

	mergesort(left);
	mergesort(right);
	merge(left, right, numeros);

	return;
    }

    public static void main(String args[]) {
	Scanner scanf = new Scanner(System.in);

	int n = scanf.nextInt();
	int numeros[] = new int[n];
	for(int i=0; i<n; i++) numeros[i] = scanf.nextInt();

	mergesort(numeros);

	System.out.println(inversoes);
    }
}

import java.util.*;

class Node {

	public LinkedList<Integer> adj; 
	public boolean visited;         
	public int distance;            

	Node() {

		adj = new LinkedList<Integer>();
		visited = false;
		distance = -1;
	}
}

class Graph {

	int n;         	
	Node nodes[];   			
	int exc; 

	Graph(int n) {

		this.n = n;
		nodes  = new Node[n+1]; 
		for (int i=1; i<=n; i++)
			nodes[i] = new Node();

	}

	public void addLink(int a, int b) {

		nodes[a].adj.add(b);
		nodes[b].adj.add(a);

	}

	public void bfs(int v) {

		LinkedList<Integer> q = new LinkedList<Integer>();

		q.add(v);
		nodes[v].visited = true;
		nodes[v].distance = 0;

		while (q.size() > 0) {
			int u = q.removeFirst();

			for (int w : nodes[u].adj)
				if (!nodes[w].visited) {
					q.add(w);
					nodes[w].visited  = true;
					nodes[w].distance = nodes[u].distance + 1; 
				}	    
		}

		exc = -1; 
		for(int i=1; i<=n; i++) {
			if(nodes[i].distance  > exc)
				exc = nodes[i].distance;
		}		
	}

	public int eccentricity() {
		return exc;
	}

	public void unvisit() {

		for(int i = 1; i<=n; i++) {
			nodes[i].visited = false;

		}
	}
}

