class DAA007 {

    static int n, k, l=0; // Combinacoes de 'n', 'k' a 'k'
    static int comb[], s[], somas[];   // Guardar a combinacao em si

    // Funcao recursiva para colocar numero na posicao 'pos',
    // sabendo que nesta posicao podem vir numeros a partir de 'first'
    static void goComb(int pos, int first) {

	// Chegamos ao fim da combinacao, vamos imprimi-la
	if (pos == k) {
        int sum = 0;
	    for (int i=0; i<k; i++) {
        sum += s[comb[i]];
        }
        somas[l] = sum;
        l++;
	}

	// Vamos a meio da combinacao
	// Gerar numero nao usado para colocar nesta posicao
	else {
	    for (int i=first; i<n; i++) {
		comb[pos] = i;
		goComb(pos+1, i+1);
	    }
	}
    }

    static int binom(int n, int k) {

        if (k>n-k) k=n-k;

        int b=1;

        for (int i=1, m=n; i<=k; i++, m--)
            b=b*m/i;

        return b;
    }

    static int bsearch(int v[], int low, int high, int key) {

        while (low <= high) {

            int middle = low + (high-low)/2;

            if (key == v[middle]) return v[middle];
            else if (key < v[middle]) { high=middle-1; return bsearchn(v,low,high,key); }
            else { low = middle+1; return bsearchn(v,low,high,key); }
        }

        return -1;
    }

    static int bsearchn(int v[], int low, int high, int key) {

        //System.out.println("low: "+low+" high: "+high);

        while (low < high) {

            int middle = low + (high-low)/2;

            if (v[middle] >= key) high = middle;
            else low = middle+1;

            //System.out.println("low: "+low+" high: "+high);
        }

        if (v[low] < key) return -1;
        if (v[low] == key) return v[low];
        if (low > 0) { 
            if (Math.abs(v[low]-key) == Math.abs(v[low-1]-key)) {

                int [] a = {v[low], v[low-1]};
                System.out.print(v[low-1]+" "); 
                return v[low]; }
            else return v[low-1];
        }
        return v[low];
    }

    public static void main (String args[]) {

        Scanner in = new Scanner(System.in);

        n = in.nextInt();

        s = new int [n];

        for (int i=0; i<n; i++) s[i] = in.nextInt();

        int p = in.nextInt();

        int q[] = new int [p];

        for (int i=0; i<p; i++) q[i] = in.nextInt();

        k = 2;

        int npares = binom(n,k);

        somas = new int[npares];

        // Alocar memoria para criar combinacoes
        comb = new int[n];

        // Iniciar a combinacao na posicao 0
        goComb(0, 0);

        Arrays.sort(somas);

        for (int i=0; i<p; i++) System.out.println(bsearch(somas,0,somas.length,q[i]));

    }
}

