	public int compareTo(Node x){
	if(this.distance<x.distance) return -1;
	else if(this.distance>x.distance) return 1;
	else{
	    if(this.number<x.number) return -1;
	    else if(this.number>x.number) return 1;
	    else return 0;
	}
    }
}

