import java.util.*;
import java.io.*;

public class SomasMaisProximas {

	public static int valorCondicional = 0;
	public static int pesquisar(List<Integer> v, int key){
		valorCondicional = 0;
		int middle, end = v.size(), start = 0;
		if(key < v.get(start)){
			return v.get(start);
		}
		else if(key >= v.get(end-1)){
			return v.get(end-1);
		}
		while(start <= end){
			middle = (start+end)/2;
			if(key == v.get(middle)){
				return v.get(middle);
			}
			else if(key < v.get(middle) && key > v.get(middle-1)){
				if(v.get(middle)-key < key-v.get(middle-1)){
					return v.get(middle);
				}
				if(v.get(middle)-key > key-v.get(middle-1)){
					return v.get(middle-1);
				}
				else {
					valorCondicional = v.get(middle);
					return v.get(middle-1);
				}
			}
			else if(key < v.get(middle)){
				end = middle-1;
			}
			else {
				start = middle+1;
			}
		}
		return -1;
	}

	public static void main(String[] args) throws IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int nPerguntas = Integer.parseInt(br.readLine());
		String perguntas[] = new String[nPerguntas];
		perguntas = br.readLine().split(" ");
		int nQueries = Integer.parseInt(br.readLine());
		String queries[] = new String[nQueries];
		queries = br.readLine().split(" ");
		List<Integer> somas = new ArrayList<Integer>();
		for(int i = 0; i < nPerguntas-1; i++){
			for(int j = i+1; j < nPerguntas; j++){
				somas.add(Integer.parseInt(perguntas[i]) + Integer.parseInt(perguntas[j]));
			}
		}
		Collections.sort(somas);
		for(int i = 0; i < nQueries; i++){
			int k = pesquisar(somas, Integer.parseInt(queries[i]));			
			if(valorCondicional != 0){
				System.out.println(k + " " + valorCondicional);
			}
			else {
				System.out.println(k);	
			}
		}
	}
}

