	static void tratargrafo(Grafo g) {
		Grafo gt=ConstroiTransposto(g); // algoritmo de kosaraju-sharir
		g=GrafoNvisitado(g);
	    Stack<Integer> pilha=new Stack<Integer>();
	    for(int i=1;i<=g.nverts;i++)
			if(!g.verts[i].visitado)
				DFS_Visit(g,i,pilha);
		gt=GrafoNvisitado(gt);
		while(!pilha.isEmpty()){
			int vert=pilha.pop();
				if(!gt.verts[vert].visitado){
					int aux=ContaElGrupos(gt,vert);
					if(aux>=4)
						resp[1]++;
					else
						resp[0]++;
			}
		}
	}		
	static void DFS_Visit(Grafo gr,int vert,Stack<Integer> s) {
		gr.verts[vert].visitado=true;
		for(Arco a: gr.verts[vert].adjs){
			int w=a.no_final;
			if(!gr.verts[w].visitado)
				DFS_Visit(gr,w,s);
			}
		s.push(vert);
	}
	static int ContaElGrupos(Grafo gr,int vert) {
		int contador=1; // cada grupo tem no minimo um elemento: o proprio 
		gr.verts[vert].visitado=true;
		for(Arco a: gr.verts[vert].adjs){
			int w=a.no_final;
			if(!gr.verts[w].visitado)
				contador+=ContaElGrupos(gr,w);
			}
			return contador;
		}



	static Grafo GrafoNvisitado (Grafo gr) {
		for(int i=1;i<=gr.nverts;i++)
		  gr.verts[i].visitado=false;
		return gr;
	}
	static Grafo ConstroiTransposto(Grafo gr) {
		Grafo g=new Grafo(gr.nverts+1);
		for(int i=1;i<=gr.nverts;i++){
			for(Arco a: gr.verts[i].adjs)
				g.insert_new_arc(a.no_final,i);
			}
			return g;
		}


	static void escreverResp(int i) {
		System.out.println("Caso #"+i+"\n"+resp[1]+" "+resp[0]);
		}

	}

import java.util.*;

class Segm {
	int b, e, s;

	public Segm(int b, int e) {
		this.b = b;
		this.e = e;
		this.s = e-b; }

	public static void quicksort(int[] main, int[] index) { quicksort(main, index, 0, index.length - 1); }

	// quicksort a[left] to a[right]
	public static void quicksort(int[] a, int[] index, int left, int right) {
	    if (right <= left) return;
	    int i = partition(a, index, left, right);
	    quicksort(a, index, left, i-1);
	    quicksort(a, index, i+1, right); }

	// partition a[left] to a[right], assumes left < right
	private static int partition(int[] a, int[] index, 
	int left, int right) {
	    int i = left - 1;
	    int j = right;
	    while (true) {
	        while (less(a[++i], a[right]))      // find item on left to swap
	            ;                               // a[right] acts as sentinel
	        while (less(a[right], a[--j]))      // find item on right to swap
	            if (j == left) break;           // don't go out-of-bounds
	        if (i >= j) break;                  // check if pointers cross
	        exch(a, index, i, j);               // swap two elements into place
	    }
	    exch(a, index, i, right);               // swap with partition element
	    return i; }

	// is x < y ?
	private static boolean less(int x, int y) { return (x < y); }

	// exchange a[i] and a[j]
	private static void exch(int[] a, int[] index, int i, int j) {
	    int swap = a[i];
	    a[i] = a[j];
	    a[j] = swap;
	    int b = index[i];
	    index[i] = index[j];
	    index[j] = b; }}

