class No {
    //int label;
    LinkedList<Arco> adjs;

    No() {
	adjs = new LinkedList<Arco>();
    }
}


class Grafo {
    No verts[];
    int nvs, narcos;

    public Grafo(int n) {
	nvs = n;
	narcos = 0;
	verts  = new No[n+1];
	for (int i = 0 ; i <= n ; i++)
	    verts[i] = new No();
        // para vertices numerados de 1 a n (posicao 0 nao vai ser usada)
    }

    public int num_vertices(){
	return nvs;
    }

    public int num_arcos(){
	return narcos;
    }

    public LinkedList<Arco> adjs_no(int i) {
	return verts[i].adjs;
    }

    public void insert_new_arc(int i, int j, int valor_ij){
	verts[i].adjs.addFirst(new Arco(j,valor_ij));
        narcos++;
    }

    public Arco find_arc(int i, int j){
	for (Arco adj: adjs_no(i))
	    if (adj.extremo_final() == j) return adj;
	return null;
    }

    public int prim(){
    	int custos[] = new int[nvs+1];
    	boolean visitado[] = new boolean[nvs+1];
    	int pai[]= new int[nvs+1];
    	for (int x=1; x<=nvs; x++){
    		custos[x]=Integer.MIN_VALUE;
    		visitado[x]=false;
    	}
    	custos[1]=0;
    	Heapmin hm= new Heapmin(custos, nvs);
    	while (hm.size!=0){
    		int no= hm.extractMax();
    		if (custos[no]==Integer.MIN_VALUE){
    			return Integer.MIN_VALUE;
    		}
    		Iterator<Arco> adj= verts[no].adjs.iterator();
    		while(adj.hasNext()){
    			Arco ex= adj.next();
    			if (visitado[ex.no_final]==false && custos[ex.no_final]<ex.valor){
    				custos[ex.no_final]=ex.valor;
    				pai[ex.no_final]=no;
    				hm.increaseKey(ex.no_final, custos[ex.no_final]);
    			}

    		}
    		visitado[no]=true;
    		}
    	int t=0;
		for (int x=1; x<=nvs;x++){
			t+=custos[x];

    	}
    	return t;
    }

}

