import java.util.Scanner;

public class Inversoes {
    static int n;
    static int v[];
    // Juntar dois arrays ordenados
    // Assumir que os arrays sao v[start..middle] e v[middle+1..end]

    static int merge(int v[], int start, int middle, int end) {
        int i, p1, p2;
        int aux[] = new int[end + 1];
        int count = 0;
        p1 = start;     // "Apontador" do array da metade esquerda
        p2 = middle + 1;  // "Apontador" do array da metade direita
        i = start;    // "Apontador" do array aux[] a conter juncao
        while (p1 <= middle && p2 <= end) {            // Enquanto de para comparar
            if (v[p1] <= v[p2]) {
                aux[i++] = v[p1++];  // Escolher o menor e adicionar
            } else {
                aux[i++] = v[p2++];
                count = count + middle + 1 - p1;
            }
        }
        while (p1 <= middle) {
            aux[i++] = v[p1++];     // Adicionar o que resta
        }
        while (p2 <= end) {
            aux[i++] = v[p2++];
        }

        for (i = start; i <= end; i++) {
            v[i] = aux[i];  // Copiar array aux[] para v[]
        }
        return count;
    }

    // Ordenar array v[] com mergesort entre posicoes start e end
    static int mergesort(int v[], int start, int end) {
        int middle, contador=0;
        if (start < end) {                 // Parar quando tamanho do array < 2
            middle = (start + end) / 2;        // Calcular ponto medio
            contador += mergesort(v, start, middle);   // Ordenar metade esquerda
            contador += mergesort(v, middle + 1, end);   // Ordenar metade direita
            contador += merge(v, start, middle, end);// Combinar duas metades ordenadas
        }
        return contador;
    }

    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        v = new int[n];

        for (int i = 0; i < n; i++) {
            v[i] = in.nextInt();
        }
        // Ordenar
       // mergesort(v, 0, n - 1);

        // Imprimir
        int a = mergesort(v,0,n-1);
        System.out.println(a);

    }
}

import java.io.*;
import java.util.*;

class Encomenda {

	public static int nNodes;
	public static int D[];		// melhor comprimento
	public static int color[];
	public static int W[][];	// comprimentos maximos 
	public static ArrayList<ArrayList<Integer>> AdjList;
	public static int lmin, lmax, cmin, cmax, amin;
	public static int src, dest;

	public static TreeMap<Integer, Integer> map = new TreeMap<Integer, Integer>();
	public static LinkedList<Integer> list = new LinkedList<Integer>();

	/*
	 * usa uma TreeMap para criar indices a partir de 0 de forma a poucar memoria 
	 * como nao temos conhecimento do limite dos nos (no maximo o maximo inteiro)
	 */
	public static int getIndex(int key) {
		if (map.containsKey(key)) return map.get(key);
		map.put(key, map.size());
		return map.size()-1;
	}

	/*
	 * processa o input para determinar o numero de nos do grafo
	 * armazena a informacao necessaria para criar o grafo na lista list
	 * elimina arcos em que nao respeitam as dimensoes minimas do caixote
	 */
	public static int getNnodes(Scanner scn) {
		int x;
		while ((x = scn.nextInt()) != -1) {
			int y = scn.nextInt();
			int l = scn.nextInt();
			int c = scn.nextInt();
			int a = scn.nextInt();
			if (l >= lmin && c >= cmin && a >= amin) {
				list.add(getIndex(x));
				list.add(getIndex(y));
				list.add(c);
			}
		}
		return map.size();
	}

	public static void input(Scanner scn) {
		lmin = scn.nextInt();
		lmax = scn.nextInt();
		cmin = scn.nextInt();
		cmax = scn.nextInt();
		amin = scn.nextInt();
		src = getIndex(scn.nextInt());
		dest = getIndex(scn.nextInt());
		nNodes = getNnodes(scn);
		D = new int[nNodes];
		color = new int[nNodes];
		W = new int[nNodes][nNodes];
		AdjList = new ArrayList<ArrayList<Integer>>();
		for (int i=0; i<nNodes; i++)
			AdjList.add(new ArrayList<Integer>());
		while(!list.isEmpty()) {
			int x = list.removeFirst();
			int y = list.removeFirst();
			int c = list.removeFirst();
			AdjList.get(x).add(y);
			AdjList.get(y).add(x);
			W[x][y] = c;
			W[y][x] = c;
		}
	}

	public static void Dijkstra() {
		for (int i=0; i<nNodes; i++) 
			D[i] = -1;
		D[src] = Integer.MAX_VALUE;
		Queue<Integer> Q = new PriorityQueue<Integer>(nNodes, new Comparator<Integer>() {
			public int compare(Integer a, Integer b) {
				if (D[b] > D[a]) return 1;
				else if(D[b] < D[a]) return -1;
				else return 0;
				//return D[b]-D[a]; // overflow causa problemas
			}
		});
		for (int i=0; i<nNodes; i++)
			Q.add(i);
		while(!Q.isEmpty()) {
			int u = Q.poll();
			for (int v: AdjList.get(u)) 
				if (color[v] == 0) {
					int min = Math.min(D[u], W[u][v]);
					if (D[v] < min) {
						D[v] = min;
						Q.remove(v);
						Q.add(v);
					}
				}
			color[u] = 2;
		}
	}

	public static void main(String args[]) {
		Scanner scn = new Scanner(System.in);
		input(scn);
		Dijkstra();
		System.out.println((D[dest] != -1) ? D[dest] : 0 );
	}
}

