class Graf
{
	int nos;
	int nligacoes;
	int custo;
	int G[][];
	static Ligacoes x[];

	Graf(int nnos, int nl, int c)
	{
		nos=nnos;
		nligacoes=nl;
		custo=c;
		G=new int[nnos+1][nnos+1];
		x=new Ligacoes[nnos+1];
	}

	private void inicializa()
	{
		for(int i = 1; i<=nos; i++)
		{
			x[i]= new Ligacoes(i);
		}
	}

	void createGraf(Scanner in)
	{
		inicializa();
		for(int i=0; i<nligacoes; i++)
		{
			int p1 = in.nextInt();
			int p2 = in.nextInt();
			int rend = in.nextInt();
			G[p1][p2]=rend;
			G[p2][p1]=rend;
			x[p1].addLigacao(x[p2]);
			x[p2].addLigacao(x[p1]);
		}
	}

	void Prim()
	{
		x[1].peso=0;

		Comparator<Integer> cmp = new Cmp();
		PriorityQueue<Integer> aux = new PriorityQueue<Integer>(nos,cmp);
		aux.add(1);

		while(!aux.isEmpty())
		{
			int u = aux.remove();
			if(!x[u].visitado)
			{
				for(Ligacoes cursor : x[u].adj)
				{
					int k=cursor.ponto;
					if(!x[k].visitado && cursor.peso < G[u][k])
					{
						cursor.peso = G[u][k];
						aux.add(k);
					}
				}
				x[u].visitado=true;
			}
		}
	}

	public static class Cmp implements Comparator<Integer>
	{
		public int compare(Integer z, Integer y)
		{
			return x[y].peso - x[z].peso;
		}
	}

	void Output()
	{
		boolean conectado=true;
		int soma=0;
		for(int i=2; i<=nos;i++)
		{
			if(x[i].peso==Integer.MIN_VALUE)
			{
				conectado= false;
				break;
			}
			soma += x[i].peso;
		}
		if(!conectado){System.out.println("impossivel");}
		else
		{
			int total = soma 
					- (custo*(nos-1));
			System.out.println("rendimento optimo: "+ total);
		}
	}

}



