	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int nnos = in.nextInt();
		int nl = in.nextInt();
		int custo = in.nextInt();
		Grafo novo = new Grafo(nnos, nl, custo);
		novo.createGrafo(in);
		novo.Prim();
		novo.Output();
	}
}

