class Grafo {
    No verts[];
    int nvs, narcos;

    public Grafo(int n) {
	nvs = n;
	narcos = 0;
	verts  = new No[n+1];
	for (int i = 0 ; i <= n ; i++)
	    verts[i] = new No();
        // para vertices numerados de 1 a n (posicao 0 nao vai ser usada)
    }

    public int num_vertices(){
	return nvs;
    }

    public int num_arcos(){
	return narcos;
    }

    public LinkedList<Arco> adjs_no(int i) {
	return verts[i].adjs;
    }

    public void insert_new_arc(int i, int j, int valor_ij){
	verts[i].adjs.addFirst(new Arco(j,valor_ij));
        narcos++;
    }

    public Arco find_arc(int i, int j){
	for (Arco adj: adjs_no(i))
	    if (adj.extremo_final() == j) return adj;
	return null;
    }

    public int dijsktra(int orig,int dest){
    	int dist[] = new int[nvs + 1];
		for (int i = 1; i <= nvs; i++) {
			dist[i] = 0;
		}
		dist[orig] = Integer.MAX_VALUE;
		Heapmax Q = new Heapmax(dist, nvs);
		while (Q.size != 0) {
			int v = Q.extractMax();
			ListIterator<Arco> li = verts[v].adjs.listIterator();
			while (li.hasNext()) {
				Arco w = li.next();
				int cCurrente; 
				if(w.valor < dist[v]) cCurrente = w.valor; 
                else{ 
                    cCurrente = dist[v]; 
                } 
                if(cCurrente > dist[w.no_final]){ 
                    dist[w.no_final] = cCurrente; 
                    Q.increaseKey(w.no_final, dist[w.no_final]); 
                } 
			}
		}
		return(dist[dest]);

    }
}

