public class DFS {
    static int n;                 // Numero de nos do grafo
    static boolean adj[][]; // Matriz de adjacencias
    static boolean visited[];  // Que nos ja foram visitados?
    static int contador;
	static int edges;

    static void dfs(int v) {
	contador=0;
	visited[v] = true;
	for (int i=1; i<=n; i++)		
	    if (adj[v][i] && !visited[i]){
		dfs(i);
		contador+=1;
		}



    }

