import java.util.LinkedList;
import java.util.Scanner;
// assinala vertv como removido
// supondo 1 <= vertv <= n
// diminui a chave e corrige posicao se
// necessario
/*-------------------------------------------------------------------*\
 |  Definicao de grafos com pesos (int)                                |
 |     Assume-se que os vertices sao numerados de 1 a |V|.             |
 |                                                                     |
 |   A.P.Tomas, CC211 (material para prova pratica), DCC-FCUP, 2012    |
 |   Last modified: 2013.01.03                                         |
 \--------------------------------------------------------------------*/

class Qnode {
	int vert;
	int vertkey;

	Qnode(int v, int key) {
		vert = v;
		vertkey = key;
	}
}

class Heapmax {
	private static int posinvalida = 0;
	int sizeMax, size;

	Qnode[] a;
	int[] pos_a;

	Heapmax(int vec[], int n) {
		a = new Qnode[n + 1];
		pos_a = new int[n + 1];
		sizeMax = n;
		size = n;
		for (int i = 1; i <= n; i++) {
			a[i] = new Qnode(i, vec[i]);
			pos_a[i] = i;
		}

		for (int i = n / 2; i >= 1; i--)
			heapify(i);
	}

	int extractMax() {
		int vertv = a[1].vert;
		swap(1, size);
		pos_a[vertv] = posinvalida; // assinala vertv como removido
		size--;
		heapify(1);
		return vertv;
	}

	void increaseKey(int vertv, int newkey) {

		int i = pos_a[vertv];
		a[i].vertkey = newkey;

		while (i > 1 && compare(i, parent(i)) > 0) {
			swap(i, parent(i));
			i = parent(i);
		}
	}

	void insert(int vertv, int key) {
		if (sizeMax == size)
			new Error("Heap is full\n");

		size++;
		a[size].vert = vertv;
		pos_a[vertv] = size; // supondo 1 <= vertv <= n
		increaseKey(vertv, key); // diminui a chave e corrige posicao se
									// necessario
	}

	void write_heap() {
		System.out.printf("Max size: %d\n", sizeMax);
		System.out.printf("Current size: %d\n", size);
		System.out.printf("(Vert,Key)\n---------\n");
		for (int i = 1; i <= size; i++)
			System.out.printf("(%d,%d)\n", a[i].vert, a[i].vertkey);

		System.out.printf("-------\n(Vert,PosVert)\n---------\n");

		for (int i = 1; i <= sizeMax; i++)
			if (pos_valida(pos_a[i]))
				System.out.printf("(%d,%d)\n", i, pos_a[i]);
	}

	private int parent(int i) {
		return i / 2;
	}

	private int left(int i) {
		return 2 * i;
	}

	private int right(int i) {
		return 2 * i + 1;
	}

	private int compare(int i, int j) {
		if (a[i].vertkey < a[j].vertkey)
			return -1;
		if (a[i].vertkey == a[j].vertkey)
			return 0;
		return 1;
	}

	private void heapify(int i) {
		int l, r, smallest;

		l = left(i);
		if (l > size)
			l = i;

		r = right(i);
		if (r > size)
			r = i;

		smallest = i;
		if (compare(l, smallest) > 0)
			smallest = l;
		if (compare(r, smallest) > 0)
			smallest = r;

		if (i != smallest) {
			swap(i, smallest);
			heapify(smallest);
		}

	}

	private void swap(int i, int j) {
		Qnode aux;
		pos_a[a[i].vert] = j;
		pos_a[a[j].vert] = i;
		aux = a[i];
		a[i] = a[j];
		a[j] = aux;
	}

	private boolean pos_valida(int i) {
		return (i >= 1 && i <= size);
	}

	public boolean isEmpty() {
		return (size == 0);
	}
}

class Arco {
	int no_final;
	int largura;
	int comprimento;
	int altura;

	Arco(int fim, int l, int c, int a) {
		no_final = fim;
		largura = l;
		comprimento = c;
		altura = a;
	}

	int extremo_final() {
		return no_final;
	}

	int retorna_largura() {
		return largura;
	}

	int retorna_comprimento() {
		return comprimento;
	}

	int retorna_altura() {
		return altura;
	}
}

class No {
	// int label;
	LinkedList<Arco> adjs;

	No() {
		adjs = new LinkedList<Arco>();
	}
}

class Grafo {
	No verts[];
	int nvs, narcos;

	public Grafo(int n) {
		nvs = n;
		narcos = 0;
		verts = new No[n + 1];
		for (int i = 0; i <= n; i++)
			verts[i] = new No();
		// para vertices numerados de 1 a n (posicao 0 nao vai ser usada)
	}

	public int num_vertices() {
		return nvs;
	}

	public int num_arcos() {
		return narcos;
	}

	public LinkedList<Arco> adjs_no(int i) {
		return verts[i].adjs;
	}

	public void insert_new_arc(int i, int j, int largura_ij,
			int comprimento_ij, int altura_ij) {
		verts[i].adjs.addFirst(new Arco(j, largura_ij, comprimento_ij,
				altura_ij));
		narcos++;
	}

	public Arco find_arc(int i, int j) {
		for (Arco adj : adjs_no(i))
			if (adj.extremo_final() == j)
				return adj;
		return null;
	}
}

public class main {

	public static int Dijsktra(Grafo g, int s, int t) {
		int numVertices = g.num_vertices();
		int cap[] = new int[numVertices + 1];
		for (int i = 1; i <= numVertices; i++) {
			cap[i] = 0;
		}
		cap[s] = Integer.MAX_VALUE;

		int v = 0, w = 0, cvw = 0;

		Heapmax Q = new Heapmax(cap, numVertices);

		while (!Q.isEmpty()) {
			v = Q.extractMax();
			for (Arco a : g.adjs_no(v)) {
				w = a.extremo_final();
				cvw = a.retorna_comprimento();
				if (cap[w] < Math.min(cap[v], cvw)) {
					cap[w] = Math.min(cap[v], cvw);
					Q.increaseKey(w, cap[w]);
				}
			}
		}
		return cap[t];
	}

	public static void main(String[] args) {

		Scanner stdin = new Scanner(System.in);

		int larguraMinima = 0;
		int larguraMaxima = 0;
		int compMinimo = 0;
		int compMaximo = 0;
		int altMinima = 0;

		int origem = 0;
		int destino = 0;

		int ext1 = 0;
		int ext2 = 0;
		int maxLarg = 0;
		int maxComp = 0;
		int maxAlt = 0;

		larguraMinima = stdin.nextInt();
		larguraMaxima = stdin.nextInt();
		compMinimo = stdin.nextInt();
		compMaximo = stdin.nextInt();
		altMinima = stdin.nextInt();

		origem = stdin.nextInt();
		destino = stdin.nextInt();

		Grafo g = new Grafo(compMinimo + compMaximo + 1);

		while ((ext1 = stdin.nextInt()) != -1) {
			ext2 = stdin.nextInt();
			maxLarg = stdin.nextInt();
			maxComp = stdin.nextInt();
			maxAlt = stdin.nextInt();
			if ((maxLarg >= larguraMinima && maxComp >= compMinimo && maxAlt >= altMinima)
					&& (maxComp <= compMaximo)) {
				g.insert_new_arc(ext1, ext2, maxLarg, maxComp, maxAlt);
				g.insert_new_arc(ext2, ext1, maxLarg, maxComp, maxAlt);
			}
		}
		System.out.println(Dijsktra(g, origem, destino));

	}
}

