/*  Fila de Prioridade (HEAP) de minimo
 *  
 * Alterar para Heap de maximo  basta mudar o comparador na funcao compare()
 * 
 */

class PrioritiQueue{


    class QNode{
        int vert;
        int vertkey;

        QNode(int v, int k){
        this.vert=v;
        this.vertkey=k;

            }
    }
    private static final int posinvalida=0;
    int MAX;
    int size;
    QNode[] a;
    int[] pos_a;

    PrioritiQueue(int max){
        this.MAX=max;
        this.size=0;
        pos_a=new int[max+1];
        a=new QNode[max+1];
        Arrays.fill(pos_a, 0);
        Arrays.fill(a, null);
        }
    PrioritiQueue(int max, int vec[]){
            this.MAX=max;
            this.size=max  ;
            a=new QNode[max+1];
            pos_a=new int[max+1];
            for (int i = 1; i <=max ; i++) {
            a[i]=new QNode(i,vec[i]);

            pos_a[i]=i;    

        }
            for (int i = max/2 ; i >= 1; i--) {
                heapify(i);

       }
            }

    private int left(int i){
        return i*2;

            }
    private int right(int i){
    return i*2+1;
    }
    private int pai(int i){
    return i/2;
    }
    private int compare(int i, int j){
            if(a[i].vertkey<a[j].vertkey)return -1;
            if((a[i].vertkey==a[j].vertkey) && (a[i].vert<a[j].vert))return -1;
            return 1;
            }
    private void heapify(int i) {
        int l,r,smallest;
        l=left(i);
        if(l>size)l=i;
        r=right(i);
        if(r>size)r=i;
        smallest=i;
        if(compare(l,smallest)<0)smallest=l;
        if(compare(r,smallest)<0)smallest=r;
        if(i!=smallest){swap(i,smallest);
        heapify(smallest);}

    }
    private void swap(int i, int j){
        QNode aux;
        pos_a[a[j].vert]=i;
        pos_a[a[i].vert]=j;
        aux=a[i];
        a[i]=a[j];
        a[j]=aux;
        }
    private boolean pos_valida(int i){
        return (i>0 && i<=size); 

        }
    public void insert(int v, int k){
        if(size==MAX) throw new Error("Heap is full");
        size++;
        a[size].vert=v;
        pos_a[v]=size;
        decreaseKey(v,k);
    }
    public void decreaseKey(int v, int k){
    int i = pos_a[v];
    a[i].vertkey=k;
    while((i>1) && (compare(i,pai(i))<0)){
        swap(i,pai(i));
        i=pai(i);

            }

    }
    public int extractmin(){
    int vertv=a[1].vert;
    swap(1,size);
    pos_a[vertv]=posinvalida;
    size--;
    heapify(1);
    return vertv;
    }


}



