    Dijkstra(Grafo_LL g, int vi, int vf, int cm){
            nvs=g.vertices.size();
            dist=new int[nvs+1];
            pai=new int[nvs+1];
            vert_ini=vi;
            vert_final=vf;
            grafo=g;
            pos_vert=new int[nvs+1];
            fila=new LinkedList<Integer>();
            max=cm;
            Arrays.fill(pai, -1);
            Arrays.fill(dist, Integer.MAX_VALUE);

            int i=1;
            for (Vertice v : g.vertices) {
            pos_vert[i]=v.nome;

            i++;    
        }
            heap=new PrioritiQueue(dist.length-1,dist);
            }

int indexOf(int vertice){
    for (int i = 1; i <pos_vert.length; i++) {
        if(pos_vert[i]==vertice)return i;
    }
    return 0;
}
void run(){
    int ind =indexOf(vert_ini);
    dist[ind]=0;
    pai[ind]=ind;
    heap.decreaseKey(ind, 0);


    while(heap.size!=0){
    int v =heap.extractmin();

    if(pai[v]==-1)break;

        Vertice tmp=grafo.findVert(pos_vert[v]);

        for (Aresta a : tmp.adj) {

            if(a.dist<max){max=a.dist;dist[indexOf(a.destino.nome)]=max;heap.decreaseKey(indexOf(a.destino.nome),max);}
        }
    if(tmp.nome==vert_final)break;
    }
    System.out.println(max);
            }

}

