import java.util.*;
class Segment implements Comparable<Segment>{
	int l,r,d;

	Segment(int l, int r){
		this.l = l;
		this.r = r;
		d = r - l;
	}

	@Override
    public int compareTo(Segment t){
    	if(l<t.l)
    		return -1;
    	else if(l>t.l)
    		return 1;
    	else{
    		if(d<t.d)
    			return 1;
    		else if(d>t.d)
    			return -1;
    		else
    			return 0;
    	}
    }
}
