		int [] vetor = new int[n];
		boolean x=true;
		for(int i=0;i<n;i++) vetor[i]=in.nextInt();
		if(isReversed(vetor))
		{
			System.out.println("0");
			x=false;
		}
		int trocas = bubbleSort(vetor);
		if(x) System.out.println(trocas);


	}

	public static boolean isReversed(int[] valores)
	{
		for(int i=0;i<valores.length-1;i++)
		{
			if(valores[i]<valores[i+1]) return false;
		}

		return true;
	}
	public static int bubbleSort(int[] valores)
	{	
		int trocas=0;
		boolean trocado=true;
		for(int i=0;i<valores.length-1 && trocado;i++)
		{
			trocado=false;
			for(int j=0;j<valores.length-1;j++)
			{
				if(valores[j]>valores[j+1])
				{
					swap(valores,j,j+1);
					trocado=true;
					trocas++;
				}
			}
		}
		return trocas;
	}

	public static void swap(int[] valores,int i,int j)
	{
		int temporario = valores[i];
		valores[i]=valores[j];
		valores[j]=temporario;
	}

}

