		MelhorCam(int largMin, int largMax, int compMin, int compMax, int altMin)
		{
			resolve = new Dijkstra();
			this.largMin = largMin;
			this.largMax = largMax;
			this.compMin = compMin;
			this.compMax = compMax;
			this.altMin = altMin;
			origem = 0;
