	static void bfs() {

		LinkedList<Integer> x = new LinkedList<Integer>();
		LinkedList<Integer> y = new LinkedList<Integer>();

		for(int i=0; i<l; i++)
			for(int j=0; j<c; j++)
				if(map[i][j] == '#'){
					x.add(i);
					y.add(j);
					nos[i][j].visited = true;
					nos[i][j].distance = 0;
				}

		while (x.size() > 0) {
			int u = x.removeFirst();
			int v = y.removeFirst();
			if (v < c-1 && !nos[u][v+1].visited) {
				x.add(u);
				y.add(v+1);
				nos[u][v+1].visited  = true;
				nos[u][v+1].distance = nos[u][v].distance + 1; 
			}

			if (v > 0 && !nos[u][v-1].visited) {
				x.add(u);
				y.add(v-1);
				nos[u][v-1].visited  = true;
				nos[u][v-1].distance = nos[u][v].distance + 1; 
			}

			if (u < l-1 && !nos[u+1][v].visited) {
				x.add(u+1);
				y.add(v);
				nos[u+1][v].visited  = true;
				nos[u+1][v].distance = nos[u][v].distance + 1; 
			}

			if (u > 0 && !nos[u-1][v].visited ) {
				x.add(u-1);
				y.add(v);
				nos[u-1][v].visited  = true;
				nos[u-1][v].distance = nos[u][v].distance + 1; 
			}	    
		}
	}

