			for(int j=0; j<c; j++)
				nos[i][j] =  new Node();

		bfs();
		for (int i=0; i<l; i++)
			for(int j=0; j<c; j++)
				if(map[i][j] == 'A'){
					if(nos[i][j].distance > big)
