class Node {

	int regiao;
	int dist, custo;
	boolean visitado;
	LinkedList<Node> ligacoes;

	Node(int r, int d) {
		regiao = r;
		dist = d;
		ligacoes = new LinkedList<Node>();
		custo = Integer.MAX_VALUE;
		visitado = false;
	}
}

class Grafo {

	LinkedList<Node> arvore;

	Grafo() {
		arvore = new LinkedList<Node>();
	}

	void colocaGrafo(int r, int dist) {
		arvore.add(new Node(r, dist));
	}

	void adicionaLigacao(int o, int d, int dist) {
		for (Node n : arvore)
			if (n.regiao == o)
				n.ligacoes.add(new Node(d, dist));
	}

	void Dijkstra(int rdestino) {
		LinkedList<Node> fila = new LinkedList<Node>();
		arvore.get(rdestino - 1).custo = 0;
		for (Node n : arvore)
			fila.add(n);
		while (fila.isEmpty() == false) {
			Node minimo = new Node(0, Integer.MAX_VALUE);
			for (Node n : fila)
				if (minimo.custo > n.custo)
					minimo = n;
			fila.remove(minimo);
			for (Node n : minimo.ligacoes) {
				if (arvore.get(n.regiao - 1).custo > minimo.custo + n.dist)
					arvore.get(n.regiao - 1).custo = minimo.custo + n.dist;
			}
		}
	}
}

