class Ponto{
    double x;
    double y;
    Ponto(double a , double b){
	x=a;
	y=b;
    }

    double distancia(Ponto p2){
	double dist;
	dist = Math.sqrt(Math.pow((x-p2.x),2)+Math.pow((y-p2.y),2));
	return dist;
    }
}

