        			return vetor[middle - 1];
        		else if(d1 > d)
        			return vetor[middle];
        	}
        	else if(vetor[middle] < key){
        		d = Math.abs(key - vetor[middle]);
        		d1 = Math.abs(key - vetor[middle + 1]);
        		if(d < d1)
        			return vetor[middle];
        		else if(d > d1)
        			return vetor[middle + 1];
        	}
        }
	    return 0;
	}


