class Heap {
    class HeapNode implements Comparable {
	int prio;
	int node;

	HeapNode(int n, int p) {
	    prio = p;
	    node = n;
	}

	public int compareTo(Object o) {
	    HeapNode other = (HeapNode) o;
	    if (this.prio > other.prio)
		return -1;
	    else if (this.prio < other.prio)
		return 1;
	    else
		return 0;
	}
    }

    static int maxSize;
    int size;
    HeapNode a[];
    int ord[];

