	m = matriz;
	d = dest;
	t = total;
    }

    void inicio() {

	int u = -1;
	int z = 1;
	int uz = t-1;

	Q[d].peso = 0;

	while (uz > 0){
	    z = extractmin(Q);
	    if (u != z) {
		relax(Q[z],m);
		Q[z].cor = "black";
		if (uz != 1){ 
		    System.out.print(Q[z].id + " ");
		}
		else {System.out.print(Q[z].id);}
		u = z;
		uz--;
	    }
	}

	System.out.println();
    }

    void relax(no p,int mat[][]){

	while (! p.isempty()){
	    int x = p.removefilho();
	    if (Q[x].peso > Q[p.id].peso + mat[p.id][Q[x].id] || Q[x].peso == 1000000){
		Q[x].peso = Q[p.id].peso + mat[p.id][Q[x].id];
	    }   
	}
    }

    int extractmin(no q[]){

	int i=1;

	while(q[i].peso == 1000000 || q[i].cor.equals("black") ){
	    i++;
	    if (i==t-1){break;}
	}
	int min = q[i].peso;
	int ind = i;
	for (int b=1;b<t;b++) {

	    if (q[b].cor.equals("white")){
		if (min > q[b].peso){
		    min = q[b].peso;
		    ind = b;
		}
	    }
	}
	return ind;
    }
}

