import java.util.*;
import java.lang.*;

class Graph {
	LinkedList<Integer>[] adj;
	int[] parent, key;
	int[][] cost;
	PriorityQueue<Integer> vertices;
	@SuppressWarnings("unchecked")
	Graph(int dim) {
		adj = new LinkedList[dim];
		parent = new int[dim];
		key = new int[dim];
		cost = new int[dim][dim];
		vertices = new PriorityQueue();
	}

	boolean findValue(int value) {
		Iterator<Integer> it = vertices.iterator();
		while(it.hasNext()) {
			int val = it.next();
			if(val == value)
				return true;
		}
		return false;
	}

	int extractMax() {
		Iterator<Integer> it = vertices.iterator();
		int max = Integer.MIN_VALUE;
		int indMax = -1;
		while (it.hasNext()) {
			int index = it.next();
			if (key[index] > max){
				max = key[index];
				indMax = index;
			}
		}
		if (indMax == -1) indMax = vertices.peek();
		vertices.remove(indMax);
		return indMax;
	}

	void primMST() {
		Arrays.fill(parent, -1);
		Arrays.fill(key, Integer.MIN_VALUE);
		key[0] = 0;
		while(!vertices.isEmpty()) {
			int u = extractMax();
			Iterator<Integer> it = adj[u].iterator();
			while (it.hasNext()) {
				int v = it.next();
				if (findValue(v) && key[v] < cost[u][v]) {
					parent[v] = u;
					key[v] = cost[u][v];
				}
			}
		}
	}

	String spannGraph() {
		int count = 0;
		for (int i = 1; i < adj.length; i++) {
			if (key[i] == Integer.MIN_VALUE)
				return "impossivel";
			count += key[i];
		}
		return "rendimento optimo: " + count;
	}
}

