class Dijkstra {

	Vectores dPV;
	Vectores primeirodPV;
	int tam;


	Dijkstra()
	{
		primeirodPV = dPV = null;
		tam = 0;
	}

	void dijk(Lista grafo, int origem, int compMax)
	{
		mudar(origem, false, 0, "dist");
		int prox;
		int d = 0;

		for(int i = 0; i < tam; i++)
		{
			prox = vertMax();
			mudar(prox, true, 0, "vist");

			int n[] = grafo.adjacentes (prox);

			for(int j = 0; n[j]!= 0; j++)
			{
				int v = n[j];
				if(buscarPred(prox) != v)
				{
					d = grafo.getArea(prox, v);
					//System.out.println(d);
					if(buscarDist(v) < d)
					{
						mudar(v, false, d, "dist");
						mudar(v, false, prox, "pred");
					}
				}
			}
			//System.out.println(" -------- fim ---------");
		}
	}

	int vertMax()
	{
		int x = -1;
		int y = -1; //grafo nao conectado ou nao visitado
		for (int i = 1; i <= tam; i++)
		{
			if((buscarVistPos(i) != true) && (buscarDistPos(i) > x))
			{
				y= buscarNumPos(i);
				x = buscarDistPos(i);
				//System.out.println(i + " y > " + buscarNumPos(i) + " x > " + x + " dist > " + buscarDistPos(i));
			}
		}
		return y;
	}

	void inserirVect(int ponto)
	{
		Vectores novo;
		int flag = 0;

		if(primeirodPV == null)
		{
			novo = new Vectores(ponto, ++tam);
			dPV = novo;
			primeirodPV = dPV;
		}
		else
		{
			Vectores temp = primeirodPV;
			while(temp != null)
			{
	                if(temp.getPonto() == ponto)
	                {
	                	flag = 1;
	                	break;
	                }
	                temp = temp.getPrx();
			}
			if(flag != 1)
			{
				novo = new Vectores(ponto, ++tam);
				dPV.setPrx(novo);
				dPV = novo;
			}
		}
	}

	void mudar(int ponto, boolean vis, int valor, String s)
	{
		Vectores temp = primeirodPV;
		while(temp != null)
		{
			if(temp.getPonto() == ponto)
			{
				if(s == "dist")
					temp.setDist(valor);
				else
					if(s == "pred")
						temp.setPred(valor);
					else
						if(s == "vist")
							temp.setEst(vis);
			}
			temp = temp.getPrx();
		}
	}

	int buscarDist(int ponto)
	{
		Vectores temp = primeirodPV;
		while(temp != null)
		{
			if(temp.getPonto() == ponto)
				return temp.getDist();
			temp = temp.getPrx();
		}
		return 0;
	}

	int buscarPred(int ponto)
	{
		Vectores temp = primeirodPV;
		while(temp != null)
		{
			if(temp.getPonto() == ponto)
				return temp.getPred();
			temp = temp.getPrx();
		}
		return 0;
	}

	boolean buscarVist(int ponto)
	{
		Vectores temp = primeirodPV;
		while(temp != null)
		{
			if(temp.getPonto() == ponto)
				return temp.getEst();
			temp = temp.getPrx();
		}
		return false;
	}

	int buscarDistPos(int pos)
	{
		Vectores temp = primeirodPV;
		while(temp != null)
		{
			if(temp.getPos() == pos)
				return temp.getDist();
			temp = temp.getPrx();
		}
		return 0;
	}

	boolean buscarVistPos(int pos)
	{
		Vectores temp = primeirodPV;
		while(temp != null)
		{
			if(temp.getPos() == pos)
				return temp.getEst();
			temp = temp.getPrx();
		}
		return false;
	}

	int buscarNumPos(int pos)
	{
		Vectores temp = primeirodPV;
		while(temp != null)
		{
			if(temp.getPos() == pos)
				return temp.getPonto();
			temp = temp.getPrx();
		}
		return 0;
	}

    public void mostrarLista()
    {
            Vectores noTemp = primeirodPV;

            while (noTemp !=null)
            {
                    System.out.print(noTemp.getPonto() + " ");                  
                    noTemp = noTemp.getPrx();
            }
            System.out.println();
    }

    int maiorPred(int origem, int destino)
    {
    	int pred;
    	int max;

    	pred = buscarPred(destino);
    	max = buscarDist(destino);
    	while(pred != origem)
    	{
    		if(buscarDist(pred) < max)
    			max = buscarDist(pred);
    		pred = buscarPred(pred);
    	}
    	return max;
    }
}

