        else if(right != -1 && center == right && s[start] != s[start-1]) {
            System.out.println(s[start] + " " + s[start+1]);
            return;
        }
        else if(left < center) {
            System.out.println(s[start-1]);
            return;
        }
        else if(right != -1 && right < center) {
            System.out.println(s[start+1]);
            return;
        }
        else {
            System.out.println(s[start]);
            return;
        }
    }
}

