            if (vet[i].li <= fim){
                count++;
                fim = vet[i].ri;
                int j = i+1;
                while (j < numN && vet[j].li <= fim) {
                    if (vet[j].ri > bigR) {
                        bigR = vet[j].ri;
                        i = j;
                    }
                    j++;
