	}

	public void heapify(int i) {
		int l, r, smallest;

		l = 2 * i;
		if (l > size)
			l = i;

		r = (2 * i) + 1;

		if (r > size)
			r = i;

		smallest = i;

		if (compare(l, smallest) < 0)
			smallest = l;
		if (compare(r, smallest) < 0)
			smallest = r;

		if (i != smallest) {
			swap(i, smallest);
			heapify(smallest);
		}

	}

