			cont++;
	    }
	}

	while (p1<=meio) {
	    aux[i++] = v[p1++];
	}

  	while (p2<=fim){
	    aux[i++] = v[p2++];
	}

	for (i=inicio; i<=fim; i++){
	    //	    if (v[i] != aux[i]) cont++;
	    v[i] = aux[i];
	}

	return cont;
    }

   public static int mergesort(int v[], int inicio, int fim) {
	int meio;

	if (inicio<fim) {
	    meio = (inicio + fim)/2;
	    mergesort(v, inicio, meio);
	    mergesort(v, meio+1, fim);
	    merge(v, inicio, meio, fim);
	    cont++;
	}

	return cont;
    }


