import java.util.*;

class Edge{
    public int e;
    public int w;
    Edge(int e, int w){
	this.e=e;
	this.w=w;
    }
}

class Sol{

    Scanner input;
    Sol(Scanner input){this.input=input;}
    ArrayList<ArrayList<Edge>> g = new ArrayList<ArrayList<Edge>>();
    LinkedList<Integer> l = new LinkedList<Integer>();
    int index = 1;
    int nrNodes;
    int src;

    void read(){
	g.add(new ArrayList<Edge>());
	nrNodes = input.nextInt();
	src    = input.nextInt();

	while(input.hasNext()){
	    int s1 = input.nextInt();
	    if(s1==-1)
		break;
	    int s2=handles(s1);
	    int e = handles(input.nextInt());
	    int w = input.nextInt();
	    Edge e1 = new Edge(e,w);
	    Edge e2 = new Edge(s2,w);
	    g.get(s2).add(e1);
	    g.get(e).add(e2);
	}
    }

    void solve(){
	//printGraph();
	dijkstra();
	System.out.println();
    }

    void dijkstra(){
	int[] dist = new int[g.size()];
	int[] pred = new int[g.size()];
	int[] visi = new int[g.size()];
	init(dist);

	for(int i=1; i<dist.length; i++){
	    int n = minEdge(dist,visi);
	    System.out.print(n+" ");
	    visi[n]=1;

	    for(int j=0; j<g.get(n).size(); j++){
		int f = g.get(n).get(j).e;
		int w = g.get(n).get(j).w;
		relax(dist,pred,n,f,w);
	    }
	}
    }

    void relax(int[] dist, int[] pred, int n, int f, int w){
	int aux = dist[n]+w;
	if(aux<dist[f]){
	    dist[f]=aux;
	    pred[f]=n;
	}
    }

    int minEdge(int[] dist, int[] visi){
	int min = Integer.MAX_VALUE;
	int ind = 0;
	for(int i=0; i<dist.length; i++){
	    if(visi[i]==0 && dist[i]<min){
		min=dist[i];
		ind=i;
	    }
	}
	return ind;
    }

    void init(int[] dist){
	for(int i=0; i<dist.length; i++)
	    dist[i]=Integer.MAX_VALUE;
	dist[src]=0;
    }


    int handles(int n){
	if(l.contains(n))
	    return n;
	else{
	    g.add(new ArrayList<Edge>());
	    l.addLast(n);
	    return index++;
	}
    }

    void printGraph(){
	for(int i=0; i<g.size(); i++){
	    System.out.print(i+" -> ");
	    for(int j=0; j<g.get(i).size(); j++)
		System.out.print(g.get(i).get(j).e+"/"+g.get(i).get(j).w+" ");
	    System.out.println();
	}
    }
}

