			if(locais[j]>0)
				System.out.println(locais[j]);
	}

	static boolean existe(int valor, int[] locais){
		for(int i=0;i<30;i++)
			if(valor==locais[i])
				return true;
		return false;
	}

	static int[] apaga(int valor, int[] locais,int n){
		boolean flag=false;
		int i=n;
		while(flag==false){
			locais[i]=0;
			i=i-1;
			if(locais[i]==valor || i<0)
				flag = true;
		}
		return locais;
	}
}

