class Queue {
    int queue[];
    int size;
    int first;
    int last;
    int cap;

    Queue (int c) {
	cap = c;
	queue = new int[c];
	size = first = last = 0;
    }

    boolean isEmpty() {
	return (size == 0);
    }

    int remove() {
	int r = queue[first];
	first = (first+1) % cap;
	size--;
	return r;
    }

    void add (int node) {
	queue[last] = node;
	last = (last+1) % cap;
	size++;
    }
}

