class Grafo {
    No verts[];
    int nvs, narcos;

    public Grafo(int n) {
	nvs = n;
	narcos = 0;
	verts  = new No[n+1];
	for (int i = 0 ; i <= n ; i++)
	    verts[i] = new No();
        // para vertices numerados de 1 a n (posicao 0 nao vai ser usada)
    }

    public int num_vertices(){
	return nvs;
    }

    public int num_arcos(){
	return narcos;
    }

    public LinkedList<Arco> adjs_no(int i) {
	return verts[i].adjs;
    }

    public void insert_new_arc(int i, int j, int valor_ij){
	verts[i].adjs.addFirst(new Arco(j,valor_ij));
        narcos++;
    }

    public Arco find_arc(int i, int j){
	for (Arco adj: adjs_no(i))
	    if (adj.extremo_final() == j) return adj;
	return null;
    }

    public int[] prim(){
		int[] key = new int[nvs+1];
		int[] pred = new int[nvs+1];
		boolean[] visited = new boolean[nvs+1];

		for(int i=1;i<=nvs;i++){
			key[i] = Integer.MAX_VALUE;
			visited[i] = false;
		}

		key[1] = 0;
		Heapmin hm = new Heapmin(key,nvs);
		pred[1] = 0;

		int u;
		Arco e;
		while(hm.size != 0){
			u = hm.extractMin();
			ListIterator<Arco> li = verts[u].adjs.listIterator();
			while(li.hasNext()){
				e = li.next();
				if(!visited[e.no_final] && e.valor < key[e.no_final]){
					key[e.no_final] = e.valor;
					hm.decreaseKey(e.no_final,key[e.no_final]);
					pred[e.no_final] = u;
				}
			}
			visited[u] = true;
		}

		return key;
	}
}



