		d = new int[G.length];
		for(int i=2; i<G.length; i++){
			d[i]=Integer.MIN_VALUE;
		}

		Comparator<Integer> cmp = new Cmp();
		PriorityQueue<Integer> Q = new PriorityQueue<Integer>(G.length, cmp);

		Q.add(1);
		while(!Q.isEmpty()){
			int x=Q.remove();
			if(!color[x]){
				for(int i=0; i<adjsize[x]; i++){
					int k=G[x][i];
					if(!color[k] && d[k]<w[x][k]){
						d[k]=w[x][k];
						Q.add(k);
					}

				}
				color[x]=true;
			}
		}

	}

