class problema6 {
    public static void main(String args[]) {
	Scanner in = new Scanner(System.in);

	int n = in.nextInt();
	int numeros[] = new int[n];

	for(int i = 0; i < n; i++) {
	    numeros[i] = in.nextInt();
	}

	int p = in.nextInt();
	int perguntas[] = new int[p];


	for(int j = 0; j < p; j++) {
	    perguntas[j] = in.nextInt();
	}
	int total = (n * (n-1)) / 2;  //progressoes aritmeticas
	int cont = 0;
	int somas[] = new int[total];
	for(int i=0; i < n ; i++) {
	    for(int j = i+1; j < n  ; j++) {
		somas[cont] = numeros[i] + numeros[j];	       
		cont++;
	    }
	}


	Arrays.sort(somas);

	/*for(int i=0; i < n*(n-1)/2 ; i++)
	    System.out.print(somas[i] + " ");
	    System.out.println();
	*/

	for(int i = 0; i < p; i++) {
	    pesquisa(somas, perguntas[i], 0,total-1);
	    System.out.println("entrei");
	}
    }

    public static void pesquisa(int[] a, int b, int inicio, int fim) {

        while(inicio <=fim) {	    
	    int meio = inicio + (fim - inicio) / 2;
	    if(b == a[meio]) {
		System.out.println(a[meio]);
		return;
	    }
	    else
		if(inicio == fim) {
		    System.out.println(a[0]);
		    return;
		}

		else {
		    if(b < a[meio]) {
			if(meio-1 >= inicio) 
			    if(b > a[meio-1]) {
				verifica(b, meio, a);
				return;
			    }
			fim = meio;
		    }
		    else {
			if(meio+1 <= fim)
			    if(b > a[meio] && b < a[meio+1]) {
				verifica(b, meio, a);
				return;
			    }
			inicio = meio;
		    }
		}
	}
    }

    public static void verifica(int b, int meio, int[] c) {

	if(meio > b) {
	    int p1 = Math.abs(c[(meio - 1) - b]);
	    int p2 = Math.abs(c[meio] - b);

	    if(p1 == p2 && c[meio-1] != c[meio] )
		System.out.println(c[meio-1] + " " + c[meio]);
	    else
		if(p1 >= p2)
		    System.out.println(c[meio]);
		else
		    System.out.println(c[meio-1]);			   
	}
	else {
	    if(meio < b) {
		int p1 = Math.abs(c[meio] - b);
		int p2 = Math.abs(c[(meio+1)]-b);

		if(p1 == p2 && c[meio] != c[meio+1])
		    System.out.println(c[meio] + " " + c[meio+1]);
		else {
		    if(p1 >= p2)
			System.out.println(c[meio+1]);
		    else

			System.out.println(c[meio]);			  
		}	 
	    }
	}
    }
}

import java.util.*;
public class bioNetwork
{
	static int distancesArray[][];	// Global array of distances between knots.
	static int nodes;				// Number of knots.
	// A list of linked lists:
	// Each element of the ArrayList represents a knot
	// Each element of the LinkedList represent the connected knots a knot has.
	static ArrayList<LinkedList<Integer>> nodeMap;
	static boolean checkArray[];	// Checks wich knots are left to visit.
	public static void main (String args[])
	{
		Scanner input = new Scanner(System.in);	// Scanner declaration
		nodes = input.nextInt();	// Number of nodes.
		int links = input.nextInt();	// Number of links.
		distancesArray = new int[nodes][nodes];	// Giving size to the distances array.
		nodeMap = new ArrayList<LinkedList<Integer>>();	// Creating the array of lists.
        for(int i=0;i<nodes;i++)	// Adding linked lists to the array.
        	nodeMap.add(new LinkedList<Integer>());
		for(int i=0;i<links;i++)	
		{
			int a = input.nextInt();	// Reading first knot.
			int b = input.nextInt();	// Reading second knot.
			nodeMap.get(a-1).add(b-1);	// Finding first knot in the array and adding second knot to its linked list.
			nodeMap.get(b-1).add(a-1);
		}
		checkArray = new boolean[nodes];	// Defining checkArray, it will tell for each knot wich knots are left to visit.
		for (int i=0;i<nodes;i++)			// For each node, all other nodes are to visit.
		{
            Arrays.fill(checkArray,false);	// All nodes are not visited.
            bfs(i);							// Width search.
    }
    //Building an array of excentricity
    int excentricity = 0;	// Starts at 0.
    int exArray[] = new int[nodes];
    for(int i=0;i<nodes;i++)
      {
	       for(int i2=0;i2<nodes;i2++)
	       {
	        // It finds the excentricity of each node.
	        if(distancesArray[i][i2] > excentricity)
	        {
	        	excentricity = distancesArray[i][i2];
	        }   	
	       }	
	       exArray[i] = excentricity;	// After the excentricity is found, it is stored in the array.
	       excentricity = 0;			// And after that it goes back to zero.
        }
        // Getting width and radius.
        int width = Integer.MIN_VALUE;	// Is the biggest excentricity of all nodes.
        int radius = Integer.MAX_VALUE; // Is the lowest excentricity of all nodes.
        for(int i=0;i<nodes;i++)
        {
	        if(exArray[i] > width) width = exArray[i];
	        if(exArray[i] < radius) radius = exArray[i];
        }
       	// Getting centrals and periferic
       	boolean isCentral[] = new boolean[nodes];	// Creating isCentral bool array.
       	boolean isPeri[] = new boolean[nodes];	// Creating isPeriferic bool array.
       	Arrays.fill(isCentral,false);				// Fills with false
       	Arrays.fill(isPeri,false);				// Fills with false
       	// If the excentricit of a node is equal to the radius, then that node is central, thus it says true in the array.
       	for(int i=0;i<nodes;i++)
       	{
       		if(exArray[i] == radius) isCentral[i] = true;
       		if(exArray[i] == width) isPeri[i] = true; //If the excentricity equals the width then it is periferic.
       	}
       	//OUTPUT
      	System.out.println(width);
      	System.out.println(radius);
        int helper = 0;
      	for(int i=0;i<nodes;i++)
      	{
      		if(isCentral[i]==true)
      		{
      			if(helper==0)System.out.print(i+1);
            else System.out.print(" " + (i+1));
            helper++;
      		}
      	}
		    System.out.println();
        helper = 0;
      	for(int i=0;i<nodes;i++)
      	{
      		if(isPeri[i]==true)
      		{
      			if(helper==0)System.out.print(i+1);
            else System.out.print(" " + (i+1));
            helper++;
      		}
      	}
      	System.out.println();
	}
	static void bfs (int node) {
        LinkedList<Integer> nodeQueue = new LinkedList<Integer>();
        nodeQueue.add(node);
        distancesArray[node][node] = 0;
        checkArray[node] = true;
        while (!nodeQueue.isEmpty()) {
            int currentNode = nodeQueue.remove();
            for(int linkedTo : nodeMap.get(currentNode)) {
                if (!checkArray[linkedTo]) {
                    nodeQueue.add(linkedTo);
                    checkArray[linkedTo] = true;
                    distancesArray[node][linkedTo] = distancesArray[node][currentNode] + 1;
                }
            }
        }
    }

}

import java.util.*;

class negocioelec
{
  public static void main(String[] args)
  {
    Scanner stdin=new Scanner(System.in);
    int numl=stdin.nextInt();
    int dest=stdin.nextInt();
    stdin.nextLine();
    int[][] ligas=new int[numl][numl];
    while (stdin.hasNextLine())
    {
      String line=stdin.nextLine();
      Scanner aux=new Scanner(line);
      int s=aux.nextInt();
      if (s==-1)
        break;
      else
      {
        int t=aux.nextInt();
        int peso=aux.nextInt();
        ligas[s-1][t-1]=peso;
        ligas[t-1][s-1]=peso;
      }
    }
    int[] order=new int[numl];
    order[0]=dest;
    int pos=1;
    int i=dest;
    while (true)
    {
      int min=Integer.MAX_VALUE;
      int mem=0;
      for (int j=0;j<numl;j++)
      {
        if (ligas[i][j]>0 && ligas[i][j]<min)
        {
          mem=j;
          min=ligas[i][j];
        }
      }
      if (mem!=0)
      {
        ligas[i][mem]=0;
        ligas[mem][i]=0;
        order[pos]=mem+1;
        i=mem;
        pos++;
      }
      else
        break;
    }
    System.out.print(order[0]);
    for (int k=1;k<pos;i++)
    {
      if (order[k]!=0)
        System.out.print(" " + order[i]);
    }
  }
}

import java.util.*;

class Arco {
    int no_final;
    int valor;

    Arco(int fim, int v){
	no_final = fim;
	valor = v;
    }

    int extremo_final() {
	return no_final;
    }

    int valor_arco() {
	return valor;
    }
}


class No {
    //int label;
    LinkedList<Arco> adjs;

    No() {
	adjs = new LinkedList<Arco>();
    }
}


class Grafo {
    No verts[];
    int nvs, narcos;

    public Grafo(int n) {
	nvs = n;
	narcos = 0;
	verts  = new No[n+1];
	for (int i = 0 ; i <= n ; i++)
	    verts[i] = new No();
        // para vertices numerados de 1 a n (posicao 0 nao vai ser usada)
    }

    public int num_vertices(){
	return nvs;
    }

    public int num_arcos(){
	return narcos;
    }

    public LinkedList<Arco> adjs_no(int i) {
	return verts[i].adjs;
    }

    public void insert_new_arc(int i, int j, int valor_ij){
	verts[i].adjs.addFirst(new Arco(j,valor_ij));
        narcos++;
    }

    public Arco find_arc(int i, int j){
	for (Arco adj: adjs_no(i))
	    if (adj.extremo_final() == j) return adj;
	return null;
    }
}


class Qnode {
    int vert;
    int vertkey;

    Qnode(int v, int key) {
	vert = v;
	vertkey = key;
    }
}

class Heapmin {
    private static int posinvalida = 0;
    int sizeMax,size;

    Qnode[] a;
    int[] pos_a;

    Heapmin(int vec[], int n) {
	a = new Qnode[n + 1];
	pos_a = new int[n + 1];
	sizeMax = n;
	size = n;
	for (int i = 1; i <= n; i++) {
	    a[i] = new Qnode(i,vec[i]);
	    pos_a[i] = i;
	}

	for (int i = n/2; i >= 1; i--)
	    heapify(i);
    }

    int extractMin() {
	int vertv = a[1].vert;
	swap(1,size);
	pos_a[vertv] = posinvalida;  // assinala vertv como removido
	size--;
	heapify(1);
	return vertv;
    }

    void decreaseKey(int vertv, int newkey) {

	int i = pos_a[vertv];
	a[i].vertkey = newkey;

	while (i > 1 && compare(i, parent(i)) < 0) { 
	    swap(i, parent(i));
	    i = parent(i);
	}
    }


    void insert(int vertv, int key)
    { 
	if (sizeMax == size)
	    new Error("Heap is full\n");

	size++;
	a[size].vert = vertv;
	pos_a[vertv] = size;   // supondo 1 <= vertv <= n
	decreaseKey(vertv,key);   // diminui a chave e corrige posicao se necessario
    }

    void write_heap(){
	System.out.printf("Max size: %d\n",sizeMax);
	System.out.printf("Current size: %d\n",size);
	System.out.printf("(Vert,Key)\n---------\n");
	for(int i=1; i <= size; i++)
	    System.out.printf("(%d,%d)\n",a[i].vert,a[i].vertkey);

	System.out.printf("-------\n(Vert,PosVert)\n---------\n");

	for(int i=1; i <= sizeMax; i++)
	    if (pos_valida(pos_a[i]))
		System.out.printf("(%d,%d)\n",i,pos_a[i]);
    }

    private int parent(int i){
	return i/2;
    }
    private int left(int i){
	return 2*i;
    }
    private int right(int i){
	return 2*i+1;
    }

    private int compare(int i, int j) {
	if (a[i].vertkey < a[j].vertkey)
	    return -1;
	if (a[i].vertkey == a[j].vertkey)
	    return 0;
	return 1;
    }


    private void heapify(int i) {
	int l, r, smallest;

	l = left(i);
	if (l > size) l = i;

	r = right(i);
	if (r > size) r = i;

	smallest = i;
	if (compare(l,smallest) < 0)
	    smallest = l;
	if (compare(r,smallest) < 0)
	    smallest = r;

	if (i != smallest) {
	    swap(i, smallest);
	    heapify(smallest);
	}

    }

    private void swap(int i, int j) {
	Qnode aux;
	pos_a[a[i].vert] = j;
	pos_a[a[j].vert] = i;
	aux = a[i];
	a[i] = a[j];
	a[j] = aux;
    }

    private boolean pos_valida(int i) {
	return (i >= 1 && i <= size);
    }
}

