import java.util.ArrayList;
import java.util.Scanner;

public class Encomenda {
	static class Gnode {
		int val;
		int d;
		ArrayList<Edge> adj;

		Gnode(int val) {
			this.val=val;
			d=Integer.MIN_VALUE;
			adj=new ArrayList<Edge> ();
		}
	}
	static class Edge {
		Gnode dest; //destino
		int p; //peso

		Edge(Gnode dest, int p) {
			this.dest=dest;
			this.p=p;
		}
	}

	private static ArrayList<Gnode> list;

	public static void main(String[] args) {
		Scanner in=new Scanner(System.in);
		int lmin, lmax, cmin, cmax, amin;
		int origem, destino;
		int plmax, pcmax, pamax;

		boolean terminou=false;
		int a, b;

		list=new ArrayList<Gnode> ();

		lmin=in.nextInt();
		lmax=in.nextInt();
		cmin=in.nextInt();
		cmax=in.nextInt();
		amin=in.nextInt();
		origem=in.nextInt();
		destino=in.nextInt();

		while(!terminou) {
			a=in.nextInt();
			if(a==-1)
				terminou=true;
			else {
				b=in.nextInt();
				plmax=in.nextInt();
				pcmax=in.nextInt();
				pamax=in.nextInt();
				if(plmax>=lmin && pcmax>=cmin && pamax>=amin && plmax<=lmax && pcmax<=cmax)
						inserirPercurso(a,b,pcmax);
			}
		}
		if(pertenceAoGrafo(origem, destino))
			Dijkstra(origem, destino);
		else
			System.out.println(0);
	}

	private static void Dijkstra(int origem, int destino) {
		int res=Integer.MAX_VALUE;
		changeDist(origem, 0);

		while(!list.isEmpty()) {
			Gnode u=extractMax(list);

			if(u.d>0 && u.d<res)
				res=u.d;
			if(u.val==destino)
				break;

			for(Edge v: u.adj)
				relax(u,v.dest,v.p);
		}
		if(res==Integer.MAX_VALUE)
			res=0;
		System.out.println(res);
	}

	private static void relax(Gnode u, Gnode v, int p) {
		if(u.d==0)
			v.d=p;
		else
			v.d=Math.min(u.d,p);
	}

	private static Gnode extractMax(ArrayList<Gnode> list) {
		int size=list.size();
		int max=-1;
		int index=-1;

		for(int i=0; i<size; i++) {
			Gnode tmp=list.get(i);
			if (tmp.d>max) {
				max=tmp.d;
				index=i;
			}
		}
		return list.remove(index);
	}

	private static void changeDist(int key, int k) {
		Gnode tmp;
		boolean found=false;
		int i=-1;

		while(!found) {
			i++;
			tmp=list.get(i);
			if(tmp.val==key) {
				tmp.d=k;
				list.set(i, tmp);
				found=true;
			}	
		}
	}

	private static void inserirPercurso(int a, int b, int pcmax) {
		int n=list.size();
		Gnode tmp;
		Gnode    nodeA,  nodeB;
		int		  indA,   indB;
		boolean foundA, foundB;

		nodeA=nodeB=null;
		indA=indB=-1;
		foundA=foundB=false;

		for(int i=0; i<n; i++) {
			tmp=list.get(i);
			if(!foundA && tmp.val==a) {
				foundA=true;
				nodeA=tmp;
				indA=i;
			}
			else if (!foundB && tmp.val==b) {
				foundB=true;
				nodeB=tmp;
				indB=i;
			}

			if(foundA && foundB)
				break;
		}

		if(!foundA)
			nodeA=new Gnode(a);
		if(!foundB) 
			nodeB=new Gnode(b);

		nodeA.adj.add(new Edge(nodeB, pcmax));
		nodeB.adj.add(new Edge(nodeA, pcmax));

		if(!foundA)
			list.add(nodeA);
		else
			list.set(indA, nodeA);
		if(!foundB)
			list.add(nodeB);
		else
			list.set(indB, nodeB);
	}

	private static boolean pertenceAoGrafo(int a, int b) {
		boolean foundA, foundB;
		Gnode tmp;

		int n=list.size();
		foundA=foundB=false;

		for(int i=0; i<n; i++) {
			tmp=list.get(i);
			if(!foundA && tmp.val==a) 
				foundA=true;
			else if (!foundB && tmp.val==b) 
				foundB=true;

			if(foundA && foundB)
				return true;
		}
		return false;
	}

}

