		int min[]= new int[n+1];
		int max = 0;

		for(int i = 1; i<=n;i++){
			for(int j = 1;j<=n;j++){
				if(matriz[i][j] > max )
					max = matriz[i][j];
			}
			min[i] = max;
			max = 0; 
		}

		Arrays.sort(min);

		return min[1];
	}

