class ex7 {

	public static Scanner in;

	public static void main(String[] args) {

		in = new Scanner(System.in);

		int n = in.nextInt(), p;

		int[] input = new int[n];

		float size = n;
		size -= 1;
		size /= 2;
		size *= n;

		int[] sums = new int[(int) size];

		for (int i = 0; i < n; i++) {
			input[i] = in.nextInt();
		}

		createSums(input, sums, n);
		Arrays.sort(sums);

		p = in.nextInt();

		for (int i = 0; i < p; i++) {
			searchArray(sums, in.nextInt());
		}

	}

	private static void createSums(int[] input, int[] sums, int n) {

		int actsum = 0;

		for (int i = 0; i < n; i++) {
			for (int j = i + 1; j < n; j++, actsum++) {
				sums[actsum] = input[i] + input[j];
			}
		}
	}

	private static void searchArray(int[] sums, int val) {

		int dif = 10000000;
		int holder, i = 0;
		int[] results = new int[sums.length];

		for (int sum : sums) {

			holder = Math.abs(sum - val);

			if (holder == dif) {
				i++;
				results[i] = sum;
			}

			else if (holder < dif) {
				dif = holder;
				i = 0;
				results[i] = sum;
			}

		}

		if (i > 0) {
			for (int j = 0; j <= i; j++) {
				if (j == i)	System.out.println(results[j]);
				else	System.out.print(results[j] + " ");
			}
		} else
			System.out.println(results[0]);
	}

}

