public class prob2 {


	static private void mergeSort(int low, int high, int v[]) {

        if (low < high) {
            int middle = low + (high - low) / 2;
            mergeSort(low, middle, v);
            mergeSort(middle + 1, high, v);
            merge(low, middle, high, v);
        }
    }

    static private void merge(int low, int middle, int high, int v[]) {

        int[] arrayAux= new int[v.length];

        for (int i = low; i <= high; i++) {
            arrayAux[i] = v[i];
        }
        int i = low;
        int j = middle + 1;
        int k = low;
        while (i <= middle && j <= high) {
            if (arrayAux[i] <= arrayAux[j]) {
                v[k] = arrayAux[i];
                i++;
            } else {
                v[k] = arrayAux[j];
                j++;
            }
            k++;
        }
        while (i <= middle) {
            v[k] = arrayAux[i];
            k++;
            i++;
        }



    }



	public static void main(String args[]){
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int v[]= new int[n];

		for(int i=0;i<n;i++) v[i]=sc.nextInt();

		mergeSort(0,n-1, v);

		for (int i=0;i<n-1;i++)
		System.out.print(v[i] + " ");
		System.out.println(v[n-1]);

	}
}

