	System.out.println(d);
	System.out.println(r);

	for (int i=1; i<=n; i++) {
	    if (v1[i] == r) {
		if (out1st == true){
		    System.out.print(i);
		    out1st= false;}
		else
		    System.out.print(" "+i);

	    }
	}
	System.out.println();


	out1st = true;
	for (int i=1; i<=n; i++) {
	    if(v1[i]== d) {
		if (out1st== true){
		    System.out.print(i);
