		// a cigarra vai visitar
		int[] locais = new int[30];
		int i, j = 0;
		// a cada iteração do ciclom ou seja enquanto nao
		// for lido o input 0
		while((i = in.nextInt())!=0) {
			// guardar o local no vector
			locais[j] = i;
			// e verificar se o local não e repetido,
			// ou seja se a sigarra anda nao o visitou
			for(int a = 0; a<j;a++) {
				// caso ja o tenha visitado, j = a que é a
				// posição no vector que contem o mesmo local
				// mas visitado anteriormente
				if(locais[a] == locais[j]) {
					j = a;
					// esta operação serve para parar o ciclo
					// e impedir que seja verificados locais
					// visitados que ja não interessam
					a = j;
				}
			}
			j++;
		}
		for(i=0;i<j;i++) System.out.println(locais[i]);
	}
}

import java.util.*;
import java.lang.*;

class Graph {
	LinkedList<Integer>[] adj;
	int[] parent, key;
	int[][] cost;
	PriorityQueue<Integer> vertices;
	@SuppressWarnings("unchecked")
	Graph(int dim) {
		adj = new LinkedList[dim];
		parent = new int[dim];
		key = new int[dim];
		cost = new int[dim][dim];
		vertices = new PriorityQueue();
	}

	boolean findValue(PriorityQueue<Integer> q, int value) {
		Iterator<Integer> it = q.iterator();
		while(it.hasNext()) {
			int val = it.next();
			if(val == value)
				return true;
		}
		return false;
	}

	int extractMax(PriorityQueue<Integer> q) {
		Iterator<Integer> it = q.iterator();
		int max = Integer.MIN_VALUE;
		int indMax = -1;
		while (it.hasNext()) {
			int index = it.next();
			if (key[index] > max){
				max = key[index];
				indMax = index;
			}
		}
		if (indMax == -1) indMax = vertices.peek();
		q.remove(indMax);
		return indMax;
	}

	String primMST() {
		Arrays.fill(parent, -1);
		Arrays.fill(key, Integer.MIN_VALUE);
		key[0] = 0;
		while(!vertices.isEmpty()) {
			int u = extractMax(vertices);
			Iterator<Integer> it = adj[u].iterator();
			while (it.hasNext()) {
				int v = it.next();
				if (findValue(vertices, v) && key[v] < cost[u][v]) {
					parent[v] = u;
					key[v] = cost[u][v];
				}
			}
		}
		int count = 0;
		for (int i = 0; i < key.length; i++) {
			if (i != 0 && key[i] == Integer.MIN_VALUE)
				return "impossivel";
			count += key[i];
		}
		return "rendimento optimo: " + count;
	}

}

