			if (max[i] == maxi) p = p + i + " ";
		}
		System.out.println(c.trim());
		System.out.println(p.trim());
	}

	static void dfs_art(ArrayofLists graph[], int exc[][], int v) {
		max_aux=0;
		boolean vis[] = new boolean[nos+1];
		nonvisited.clear();
