import java.util.*;



public class SomasMaisProximas {

	public static int valorCondicional = 0;
	public static int pesquisar(List<Integer> v, int key){
		valorCondicional = 0;
		int middle, end = v.size(), start = 0;
		if(key < v.get(start)){
			return v.get(start);
		}
		else if(key >= v.get(end-1)){
			return v.get(end-1);
		}
		while(start <= end){
			middle = (start+end)/2;
			if(key == v.get(middle)){
				return v.get(middle);
			}
			else if(key < v.get(middle) && key > v.get(middle-1)){
				if(v.get(middle)-key < key-v.get(middle-1)){
					return v.get(middle);
				}
				if(v.get(middle)-key > key-v.get(middle-1)){
					return v.get(middle-1);
				}
				else {
					valorCondicional = v.get(middle);
					return v.get(middle-1);
				}
			}
			else if(key < v.get(middle)){
				end = middle-1;
			}
			else {
				start = middle+1;
			}
		}
		return -1;
	}

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);

		int nPerguntas = sc.nextInt();
		sc.nextLine();
		int perguntas[] = new int[nPerguntas];
		for(int i = 0; i < nPerguntas; i++){
			perguntas[i] = sc.nextInt();
		}
		int nQueries = sc.nextInt();
		sc.nextLine();
		int queries[] = new int[nQueries];
		for(int i = 0; i < nQueries; i++){
			queries[i] = sc.nextInt();
		}
		List<Integer> somas = new ArrayList<Integer>();
		for(int i = 0; i < nPerguntas-1; i++){
			for(int j = i+1; j < nPerguntas; j++){
				somas.add(perguntas[i] + perguntas[j]);
			}
		}
		Collections.sort(somas);
		for(int i = 0; i < nQueries; i++){
			int k = pesquisar(somas, queries[i]);			
			if(valorCondicional != 0){
				System.out.println(k + " " + valorCondicional);
			}
			else {
				System.out.println(k);	
			}
		}
	}
}

