# DFS

def DFS(G):
	cor={}
	ordem_ter=[] #ordem de terminacao
	for n in G:
		cor[n]=0 # nao visitado
	for n in G:
		if cor[n]==0:
			(cor,ordem_ter)=DFS_Visit(G,n,cor,ordem_ter)
	ordem_ter.reverse()
	return (ordem_ter)

def DFS_Visit(G,n,cor,ordem_ter):
	cor[n]= 1 # a ser processado
	for v in G[n]:
		if cor[v]==0:
			(cor,ordem_ter)=DFS_Visit(G,v,cor,ordem_ter)
	ordem_ter.append(n) # guarda o vertices por ordem dos que foram primeiro visitados, ie, os que tem tempo de terminacao menor
	return (cor,ordem_ter)

# Grafo transposto

def TranspostoGrafo(G):
    GT={}
    for n in G:
        GT[n]=[]
    for n in G:
        for arc in G[n]:
            GT[arc].append(n)
    return GT

# DFS pela ordem de vertices terminados

def DFS_ter(G,ordem_ter):
    cor={}
    Mais=0
    Menos=0
    for n in G:
        cor[n]=0 # nao visitado
    for n in ordem_ter:
        if cor[n]==0:
            Num=1
            (cor,Num)=DFS_Visit_ter(G,n,cor,Num)
            if Num>=4:
                Mais=Mais+1
            else:
                Menos=Menos+Num
    return (Mais,Menos)

def DFS_Visit_ter(G,n,cor,Num):
    cor[n]= 1 # a ser processado
    for v in G[n]:
        if cor[v]==0:
            Num=Num+1
            (cor,Num)=DFS_Visit_ter(G,v,cor,Num)
    return (cor,Num)

