def dijkstra(grafo, dados, start, end, cmax):
	visitados=[]
	comprimentos={}
	for i in grafo:
		comprimentos[i]=0
	comprimentos[start]=cmax
	while (len(grafo)>len(visitados)):
		maximo=-10
		no=0
		for i in comprimentos:
			if i not in visitados:
				if comprimentos[i]>maximo:
					maximo=comprimentos[i]
					no=i
		visitados.append(no)
		for i in grafo[no]:
			if i not in visitados:
				comprimentos[i]=max(min(comprimentos[no],dados[no,i][1]),comprimentos[i])
	return comprimentos[end]

