class Vertice:
    def __init__(self, visitado=None, peso=None):
        self.visitado = visitado
        self.peso = peso

def optica():
    linha = map(int, input().split(' '))
    global nnos
    global nligacoes
    global custo
    nnos = linha[0]
    nligacoes = linha[1]
    custo = linha[2]
    for i in range(nligacoes):
        linha = map(int, input().split(' '))
        u = linha[0]
        v = linha[1]
        w = linha[2]
        if u not in G:
            G[u]={}
            Vertices[u] = Vertice(False, -1)
        G[u][v] = w
        if v not in G:
            G[v]={}
            Vertices[v] = Vertice(False, -1)
        G[v][u] = w
    res = Prim(1)
    if (res != "impossivel"):
        print("rendimento optimo:", res)
    else:
        print("impossivel")

def Prim(inicio):
    global nnos
    global nligacoes
    global custo
    Vertices[inicio].peso = 0
    maxsum = 0
    Q = []
    for i in G:
        Q.append(i)
    while (len(Q)>0):
        u = extractmax(Q)
        if u == -1:
            return "impossivel"
        Vertices[u].visitado = True
        maxsum+=Vertices[u].peso
        for v in G[u]:
            if Vertices[v].visitado==False:
                if Vertices[v].peso < G[u][v]:
                    Vertices[v].peso = G[u][v]
    return maxsum-((nnos-1)*custo)


def extractmax(Q):
    maxi = -1
    toreturn = -1
    for i in Q:
        if Vertices[i].peso>maxi:
            maxi = Vertices[i].peso
            toreturn = i
    if toreturn!=-1:
        Q.remove(toreturn)
    return toreturn
