import sys

def find_all_paths(graph, start, end, path=[]):
    path = path + [start]
    if start == end:
        return [path]
    if not graph.has_key(start):
        return []
    paths = []
    for node in graph[start]:
        if node not in path:
            newpaths = find_all_paths(graph, node, end, path)
            for newpath in newpaths:
                paths.append(newpath)
    return paths

def min_path(graph,paths):
    ruas = []
    for x in paths:
        temp = []
        for i in range(1,len(x)):
            temp.append(graph[x[i-1]][x[i]])
        ruas.append(min(temp))
    if len(ruas) == 0:
        return 0
    return max(ruas)

def find_shortest_path(graph,start,end):
    return min_path(graph,find_all_paths(graph,start,end))

