def major(graph, q):
    major_v = None
    major_i = None

    for i in q:
        if graph[i].length > major_v:
            major_v = graph[i].length
            major_i = i
    return major_i

def dijkstra(graph, restrictions):
    graph[restrictions.source].length = 0
    q = graph.keys()

    while len(q) != 0:
        major_i = major(graph, q)
        q.pop(q.index(major_i))            # :: TODO :: Change

        for i in graph[major_i].vertexes:
            if i.destiny in q:

                if graph[major_i].previous == None:
                    aux = i.maxlength
                else:
                    aux = min(graph[major_i].length, i.maxlength)

                if aux*(-1)+9999999999 < graph[i.destiny].length*(-1)+9999999999:
                    graph[i.destiny].length = aux
                    graph[i.destiny].previous = major_i

    aux = min(graph[restrictions.destiny].length, restrictions.maxlength)
    if aux < restrictions.minlength:
        aux = 0
    return aux

