def estudar_cenario(grafo):
    global visitado, retorno_dfs
    visitado={}
    retorno_dfs=[]  
    for i in grafo:
        visitado.update({i:False})

    for i in grafo:                                             #primeiro depth first search
        if not visitado[i]:
            dfs(i,grafo)

    grafo_inv=inv_grafo(grafo)                                  #inverter grafo
    resultados=[]
    for i in retorno_dfs:                                       #segundo depth first search
        for j in grafo_inv:
            visitado[j]=False
        retorno_dfs=[]
        if not visitado[i]:
            dfs(i,grafo_inv)
        resultados.append(retorno_dfs)

    if len(resultados)>1:                                       #eleminar resultados iguais
        resultados=resultados_iguais(resultados)    

    grupos=cons_grupos(resultados)                              #defenir os grupos

    n_grupos=0
    n_pessoas_fora=0
    for i in range(len(grupos)):
        if len(grupos[i])>3:
            n_grupos+=1
        else:
            n_pessoas_fora+=len(grupos[i])

    return [n_grupos,n_pessoas_fora]

