class BH:
	def __init__(self):
		self.data = {}

	def empty(self):
		return self.data == {}

	def pop(self):
		x = self.front()
		del self.data[x]
		return x

	def front(self):
		f = -1
		for x in self.data:
			if f < 0 or self.data[x] < self.data[f]: f = x
		return f

	def push(self, key, pri):
		self.data[key] = pri

	def value(self,key):
		return self.data[key]



