def Dijkstra(start):
    cam = []
    VERTICES[start].Length = 0
    Q.change(start,VERTICES[start])
    while not Q.isEmpty():
        u = Q.front()
        cam.append(u)
        Q.EXTRACT_MIN()
        VERTICES[u].Visited = True
        for v in G[u]:
            if not VERTICES[v].Visited:
                w = G[u][v]
                Relax(u,v,w)
    return cam

def Relax(u,v,w):
    if VERTICES[v].Length > VERTICES[u].Length + w:
        VERTICES[v].Length = VERTICES[u].Length + w
        VERTICES[v].Parent = u
        Q.change(v,VERTICES[v])

