def tarjan(dic):
    def search(dic, inicial):
        dic["indicies"][inicial] = dic["indice"]
        dic["raizes"][inicial] = dic["indice"]
        dic["indice"] += 1
        deslocamento = len(dic["stack"])
        dic["stack"].append(inicial)

        for i in dic[inicial]:
            if i in dic:
                if not dic["indicies"].has_key(i):
                    search(dic, i)
                    dic["raizes"][inicial] = min(dic["raizes"][inicial], dic["raizes"][i])
                elif i in dic["stack"]:
                    dic["raizes"][inicial] = min(dic["raizes"][inicial], dic["raizes"][i])

        if dic["indicies"][inicial] == dic["raizes"][inicial]:
            aux = dic["stack"][deslocamento:]
            dic["stack"] = dic["stack"][:deslocamento]
            return aux

    result = []
    dic["indice"] = 0
    dic["stack"] = []
    dic["indicies"] = {}
    dic["raizes"] = {}
    nao_visitar = []

    for i in dic:
        if type(i) == int and i not in nao_visitar:
            dic["indice"] = 0
            dic["stack"] = []
            dic["indicies"] = {}
            dic["raizes"] = {}
            grupo = search(dic, i)

            for j in grupo:
                nao_visitar.append(j)

            result.append(grupo)
    return result

