def dijkstra(graph, start, end, testes, cmax):
    visited=[]
    distance={}
    for i in graph:
        distance[i]=0
    distance[start]=cmax

    while len(graph)>len(visited):
        length=-1
        edge=0
        for i in distance:
            if i not in visited:
                if distance[i]>length:
                    edge=i
                    length=distance[i]
        visited.append(edge)

        for i in graph[edge]:
            if i not in visited:
                distance[i]=max(min(distance[edge],testes[edge,i][1]), distance[i])

    return distance[end]




