    n = len(edges)
    for i in range(n-1):
        mini = i
        for j in range(i+1, n):
            if (edges[j][2]< edges[mini][2]):
                mini = j
        edges[i][0],edges[mini][0]=edges[mini][0],edges[i][0]
        edges[i][1],edges[mini][1]=edges[mini][1],edges[i][1]
