class No:
    def __init__(self, vizinhos):
        self.vizinhos = vizinhos
        self.devo_visitar = True
        self.indice = None
        self.raiz = None
        self.visitado = False

def readln():
    return map(int, input().split())

def tarjan(grafo, inicial):
    grafo[inicial].visitado = True
    grafo[inicial].indice = grafo["indice"]
    grafo[inicial].raiz = grafo["indice"]
    grafo["indice"] += 1
    deslocamento = len(grafo["stack"])
    grafo["stack"].append(inicial)

    for i in grafo[inicial].vizinhos:
        if i in grafo:
            if not grafo[i].visitado:
                tarjan(grafo, i)
                grafo[inicial].raiz = min(grafo[inicial].raiz, grafo[i].raiz)
            elif i in grafo["stack"]:
                grafo[inicial].raiz = min(grafo[inicial].raiz, grafo[i].raiz)

    if grafo[inicial].indice == grafo[inicial].raiz:
        grupo = grafo["stack"][deslocamento:]
        grafo["stack"] = grafo["stack"][:deslocamento]
        return grupo

def fprocura(grafo):
    grafo["indice"] = 0
    grafo["stack"] = []
    resultado = []

    for i in grafo:
        if type(i) == int and grafo[i].devo_visitar == True:
            grupo = tarjan(grafo, i)

            for j in grupo:
                grafo[j].devo_visitar = False

            for j in grafo:
                if type(j) == int:
                    grafo[j].visitado = False

            resultado.append(grupo)

    return resultado

