    if s not in g.keys():
        return []
    if visto == None:
        visto = [s]
    for k in g[s]:
        if k not in visto: 
            visto.append(k)
            dfs(g,k,visto)
    return visto

def dfs2(g,s,x,visto=None):
    if s not in g.keys():
        return []
    if visto == None:
        visto = [s]
    for k in g[s]:
        if k not in visto and k not in x: 
            visto.append(k)
            dfs2(g,k,x,visto)
    return visto

