class PQ:
    def __init__(self):
        self.data = {}

    def front(self):
        f = -1
        for x in self.data:
            if f<0 or self.data[x].peso < self.data[f].peso:
                f = x
        return f

    def EXTRACT_MIN(self):
        del self.data[self.front()]

    def change(self, key, pri):
        self.data[key] = pri

    def isEmpty(self):
        return self.data == {}

class vertice(object):
	def __init__(self, parent=None, visitado=None, peso=None):
		self.parent=parent
		self.visitado=visitado
		self.peso=peso

