def Dijsktra(ori):
	caminho = []
	VERTICE[ori].peso=0
	Q.change(ori,VERTICE[ori])
	while not Q.isEmpty():
		u=Q.front()
		caminho.append(u)
		Q.EXTRACT_MIN()
		VERTICE[u].visitado=True
		for v in G[u]:
			if not VERTICE[v].visitado:
				p=G[u][v]
				Relax(u,v,p)
	return caminho

def Relax(o,d,p):
	if VERTICE[d].peso > VERTICE[o].peso+p:
		VERTICE[d].peso=VERTICE[o].peso+p
		VERTICE[d].parent=o
		Q.change(d,VERTICE[d])

