def extrair_min(dist, V, visited):
	minimo=sys.maxint
	for i in V:
		if (not visited[i]) and dist[i] < minimo:
			minimo=dist[i]
			indice=i
	return indice
def dijkstra(d, V, A):
	dist= []
	visited={}
	nvisitados=0
	nv = len(V)
	for i in range(len(V)+1):
		dist.append(sys.maxint)
		visited[i]=False
	C=[]
	dist[0]=sys.maxint
	dist[d]=0
	while (nvisitados != nv):
		n = extrair_min(dist,V, visited)
		visited[n]=True
		nvisitados=nvisitados+1
		C.append(n)
		for i in A[n].keys():      
			if (not visited[i]) and dist[i] > dist[n] + A[n][i]:
				dist[i] = dist[n] + A[n][i]
	return C


