def kruskal(g,edge,n):
    floresta = g.keys()
    sort(edge)
    optimo = 0
    while(len(floresta)>=2 and len(edge)!=0):
        flag=0
        x = edge.pop()
        if ((x[0] in floresta) and (x[1] in floresta)):
            floresta.remove(x[0])
            floresta.remove(x[1])
            floresta.append([x[0],x[1]])
            optimo = optimo + x[2] - 2
            flag=1
        elif (x[0] in floresta):
            for i in range(len(floresta)):
                if type(floresta[i]) != int:
                    if x[1] in floresta[i]:
                        floresta[i].append(x[0])
                        floresta.remove(x[0])
                        optimo = optimo + x[2] - 2
                        flag=1
                        break
        elif (x[1] in floresta):
            for i in range(len(floresta)):
                if type(floresta[i]) != int:
                    if x[0] in floresta[i]:
                        floresta[i].append(x[1])
                        floresta.remove(x[1])
                        optimo = optimo + x[2] - 2
                        flag=1
                        break
        else:
            flag0=(-1)
            flag1=(-1)
            for i in range(len(floresta)):
                if type(floresta[i]) != int:
                    if x[0] in floresta[i]:
                        flag0=i
                    if x[1] in floresta[i]:
                        flag1=i
            if flag0!=flag1:
                aux=floresta[flag0]
                for i in aux:
                    floresta[flag1].append(i)
                floresta.remove(aux)
                optimo = optimo + x[2] - 2
                flag=1
    if flag==1:
        print('rendimento optimo: '+ str(optimo))
    else:
        print('impossivel')

def sort(edges):
    n = len(edges)
    for i in range(n-1):
        mini = i
        for j in range(i+1, n):
            if (edges[j][2]< edges[mini][2]):
                mini = j
        edges[i][0],edges[mini][0]=edges[mini][0],edges[i][0]
        edges[i][1],edges[mini][1]=edges[mini][1],edges[i][1]
        edges[i][2],edges[mini][2]=edges[mini][2],edges[i][2]

