        if no in baixo: return

        num = len(baixo)
        baixo[no] = num
        stack_posicao = len(stack)
        stack.append(no)

        for sucessor in grafo[no]:
            visita(sucessor)
            baixo[no] = min(baixo[no], baixo[sucessor])

        if num == baixo[no]:
            componente = tuple(stack[stack_posicao:])
            del stack[stack_posicao:]
            resultado.append(componente)
