def ts(grafo):
    count = { }
    for no in grafo:
        count[no] = 0
    for no in grafo:
        for sucessor in grafo[no]:
            count[sucessor] += 1

    pronto = [ no for no in grafo if count[no] == 0 ]

    resultado = [ ]
    while pronto:
        no = pronto.pop(-1)
        resultado.append(no)

        for sucessor in grafo[no]:
            count[sucessor] -= 1
            if count[sucessor] == 0:
                pronto.append(sucessor)

    return resultado


