    def __init__(self, Parent=None, Length=None):
        self.Parent =   Parent
        self.Length =   Length

class PQ:
    def __init__(self):
        self.data= {}

    def push(self, key, pri):
        self.data[key]=pri

    def front(self): #retorna o indice com maior length
        f = -1 #indice com maior
        for x in self.data:
            if f<0 or self.data[x].Length > self.data[f].Length:
                f = x
        return f

    def EXTRACT_MAX(self): #retorna e apaga o valor max
        del self.data[self.front()]

    def isEmpty(self):
        return self.data == {}

Nodes = {}
Graph = {}
Q = PQ()

def optica_minimalista():
    linha = map(int, input().split(' '))
    num_nodes = linha[0]
    num_edges = linha[1]
    custo_man = linha[2]

    for i in range(0,num_edges):
        linha = map(int, input().split(' '))
        u = linha[0]
        v = linha[1]
        w = linha[2]

        if u not in Graph:
            Graph[u]    = {}
            Graph[u][v] = w
            Nodes[u]    = Node(None, -1)
            Q.push(u, Nodes[u])
        else:
            Graph[u][v] = w

        if v not in Graph:
            Graph[v]    = {}
            Graph[v][u] = w
            Nodes[v]    = Node(None, -1)
            Q.push(v, Nodes[v])
        else:
            Graph[v][u] = w

    cam = MST_Prim(u) #random start node
#    print cam

    if -1 not in cam:
        print("Rendimento Optimo: ", sum(cam)-(len(cam)-1)*custo_man)
    else:
        print("impossivel")

def MST_Prim(start):
    cam = []
    Nodes[start].Length = 0
    while not Q.isEmpty():
        u = Q.front()
        Q.EXTRACT_MAX()
        cam.append(Nodes[u].Length)
        for v in Graph[u]:
            if v in Q.data and Graph[u][v] > Nodes[v].Length:
                Nodes[v].Parent = u
                Nodes[v].Length = Graph[u][v]
    return cam

