def extrair_min(dist, V):
	minimo=sys.maxint
	for i in V:
		if dist[i-1] < minimo:
			minimo=dist[i-1]
			indice=i-1
	return indice
def dijkstra(d, V, A):
	dist= []
	for i in range(len(V)):
		dist.append(sys.maxint)
	C=[]
	dist[d-1]=0
	while V != []:
		ind_minimo = extrair_min(dist,V)
		n=ind_minimo+1
		C.append(n)
		del(V[V.index(n)])
		for i in A:
			if i[0]==n:
				if dist[i[1]-1] > dist[n-1] + A[i]:
					dist[i[1]-1] = dist[n-1] + A[i]
	return C


