def djikstra(grafo, origem, destino):
    INF = 2147483647
    Q = grafo.keys()
    pi={}
    for v in Q:
        pi[v] = -1
    pi[origem] = INF
    while Q != [] :
        u = extract_max(pi, Q)
        if u==destino: return pi[destino]
        for v in grafo[u].keys():
            relax(grafo,pi,u,v)

def extract_max(pi,Q):
    u = 0
    for i in Q:
        if pi[i] > u:
            u = pi[i]
            aux = i
    Q.remove(aux)
    return aux

def relax(grafo,pi,u,v):
    if pi[v] == -1 or minimo(pi[u],grafo[u][v]) > pi[v]:
        pi[v] = minimo(pi[u],grafo[u][v])

def minimo(a,b):
    if a > b : return b
    else: return a

