def kruskal(E,nos):
    A = []
    for v in range(1,nos+1):
        make_set(v)
    E.sort(lambda (a1,b1,c1),(a2,b2,c2):cmp(c1,c2), reverse = True)
    for (u,v,r) in E:
        if find_set(u) != find_set(v):
            A = A + [(u,v)]
            union(u,v)
    return A

def make_set(x):
    p[x] = x
    ordem[x] = 0

def union(x,y):
    link(find_set(x),find_set(y))

def link(x,y):
    if ordem[x] > ordem[y]:
        p[y] = x
    else:
        p[x] = y
        if ordem[x] == ordem[y]:
            ordem[y] = ordem[y] + 1

def find_set(x):
    if x != p[x]:
        p[x] = find_set(p[x])
    return p[x]

def rendimento(grafo, spanningT, nos, custo):
    if len(spanningT) != nos-1 :
        return "impossivel"
    rend_optimo = 0
    for u,v in spanningT:
        rend_optimo += grafo[u][v]
    rend_optimo -= custo * (nos-1)
    return "rendimento optimo: " + str(rend_optimo)

