class Disjoint_set:
    def __init__(self, n):
        self.rank = [0] * n
        self.p = [0] * n
        for i in range(n):
            self.rank[i] = 0
            self.p[i] = i
    def union(self, x, y):
        self.link(self.find_set(x), self.find_set(y))
    def find_set(self, x):
        if self.p[x] != x: self.p[x] = self.find_set(self.p[x])
        return self.p[x]
    def link(self, x, y):
        if self.rank[x] > self.rank[y]: self.p[y] = x
        else: 
            self.p[x] = y
            if self.rank[x] == self.rank[y]:
                self.rank[y] += 1

