class Heap_min:
  def __init__(self):
    self.heapKeys=[0]
    self.heapNos=[0]
    self.size=0

  def inorder(self, tab=0, i=1):
    if i<self.size+1:
      self.inorder(tab+2, i*2)
      print(tab*' ', self.heapKeys[i], self.heapNos[i])
      self.inorder(tab+2, i*2+1)

  def min_heapify(self, i):
    left=2*i
    right=2*i+1

    if left<=self.size and self.heapKeys[i]>self.heapKeys[left]:
      min1=left
    elif left<=self.size and self.heapKeys[i]==self.heapKeys[left]:
      ind=min(int(self.heapNos[i]), int(self.heapNos[left]))
      min1=self.heapNos.index(str(ind))
    else:
      min1=i

    if right<=self.size and self.heapKeys[right]<self.heapKeys[min1]:
      min1=right
    elif right<=self.size and self.heapKeys[i]==self.heapKeys[right]:
      ind=min(int(self.heapNos[i]), int(self.heapNos[right]))
      min1=self.heapNos.index(str(ind))

    if i!=min1:
      self.heapKeys[i], self.heapKeys[min1] = self.heapKeys[min1], self.heapKeys[i]
      self.heapNos[i], self.heapNos[min1] = self.heapNos[min1], self.heapNos[i]
      self.min_heapify(min1)

  def decrease_key(self, no, newKey):
    key=self.heapNos.index(no)
    if self.heapKeys[key]<newKey:
      print('new key is smaller than current key')
    else:
      self.heapKeys[key]=newKey
      while key>1 and self.heapKeys[key/2]>self.heapKeys[key]:
        self.heapKeys[key/2], self.heapKeys[key] = self.heapKeys[key], self.heapKeys[key/2]
        self.heapNos[key/2], self.heapNos[key] = self.heapNos[key], self.heapNos[key/2]
        key=key/2
        if key>1 and self.heapKeys[key/2]==self.heapKeys[key]:
          if self.heapNos[key/2]<self.heapNos[key]:
            self.heapKeys[key/2], self.heapKeys[key] = self.heapKeys[key], self.heapKeys[key/2]
            self.heapNos[key/2], self.heapNos[key] = self.heapNos[key], self.heapNos[key/2]
          else:
            self.heapKeys[key/2], self.heapKeys[key] = self.heapKeys[key], self.heapKeys[key/2]
            self.heapNos[key/2], self.heapNos[key] = self.heapNos[key], self.heapNos[key/2]

  def insert(self, key, no):
    self.size+=1
    self.heapKeys.append(1000000)
    self.heapNos.append(no)
    self.decrease_key(no, key)

  def get_min(self):
    if self.size==0:
      print('heap vazia')
    else:
      max=self.heapNos[1]
      max02=self.heapKeys[1]
      self.heapNos[1]=self.heapNos[self.size]
      self.heapKeys[1]=self.heapKeys[self.size]
      del self.heapKeys[self.size]
      del self.heapNos[self.size]
      self.size-=1
      self.min_heapify(1)
      return [max, max02]


