        self.Parent = Parent
        self.Visited = Visited
        self.Length = Length

class PQ:
    def __init__(self):
        self.data = {}

    def push(self, key, pri):
        self.data[key] = pri

    def front(self):
        f = -1
        for x in self.data:
            if f<0 or self.data[x].Length < self.data[f].Length:
                f = x
        return f #minimum length node

    def EXTRACT_MIN(self):
        del self.data[self.front()]

    def change(self, key, pri):
        self.data[key] = pri

