def Djikstra(origin):
    #Initialize Single Source already done in node instantiation
    path=[]
    nodes[origin].Length = 0
    queue.change(origin, nodes[origin])
    while queue.data != {} :
        u = queue.front()
        path.append(u)  
        queue.EXTRACT_MIN()
        nodes[u].Visited = True
        for v in graph[u]:
            if not nodes[v].Visited:
                Relax(u,v)
    return path

def Relax(u,v):
    if nodes[v].Length > nodes[u].Length + graph[u][v]:
        nodes[v].Length = nodes[u].Length + graph[u][v]
        nodes[v].Parent = u
        queue.change(v, nodes[v])

