def qsort1(lst):
	if len(lst) <= 1:
		return lst
	pivot = lst.pop(0)
	greater_eq = qsort1([i for i in lst if i[2] >= pivot[2]])
	lesser = qsort1([i for i in lst if i[2] < pivot[2]])
	return lesser + [pivot] + greater_eq

