class PQ:
    def __init__(self):
        self.data = {}
    def front(self):
        f = -1
        for x in self.data:
            if f<0 or self.data[x]>self.data[f]: f = x
        return f
    def pop(self):
        del self.data[self.front()]
    def push(self,key,pri):
        self.data[key] = pri
    def change_pri(self,key,pri):
        self.data[key] = pri
    def empty(self):
        return self.data == {}

