def tratamenor(lista,semgrupo):#trata caso o grupo tenha menos de 4 pessoas. Junta essas pessoas 'as sem grupo, elimina essas pessoas de todas as restantes listas e elimina a lista actual
    for i in range(len(lista[0])):
        for j in range(1,len(lista)):
            while lista[0][i] in lista[j]:
                if lista[0][i] not in semgrupo:
                    semgrupo.append(lista[0][i])
                del lista[j][lista[j].index(lista[0][i])]
            if lista[0][i] not in semgrupo:
                    semgrupo.append(lista[0][i])
    del lista[0]
    return lista,semgrupo

def tratamaior(lista,numgrupos):#trata caso o grupo tenha mais ou igual a 4 pessoas. Junta um grupo 'a variavel numgrupos, elimina essas pessoas de todas as restantes listas e elimina a lista actual
    for i in range(len(lista[0])):
        for j in range(1,len(lista)):
            while lista[0][i] in lista[j]:
                del lista[j][lista[j].index(lista[0][i])]
    del lista[0]
    numgrupos.append('0') 
    return lista,numgrupos

def dfs(g,s,temp=None):#pesquisa em profundidade
    if temp==None:
        temp=[s]
    for rep in g[s]:
        if rep not in temp:
            temp+=[rep]
            dfs(g,rep,temp)

    return temp

def todoscaminhos(grafo,inicio,fim,caminho=[]):#funcao que da todos os caminhos entre dois vertices do grafo
    caminho=caminho+[inicio]
    if inicio==fim:
        return [caminho]
    if not grafo.has_key(inicio):
        return []
    caminhos=[]
    for nozinho in grafo[inicio]:
        if nozinho not in caminho:
            novoscaminhos = todoscaminhos(grafo,nozinho,fim,caminho)
            for novocaminho in novoscaminhos:
                caminhos.append(novocaminho)
    return caminhos

def sortlist(lista):#funcao que ordena listas pelo seu comprimento
    for j in range(len(lista)):
        for i in range(len(lista)-1):
            if len(lista[i])>len(lista[i+1]):
                lista[i],lista[i+1]=lista[i+1],lista[i]
    return lista


