def contagem(grupos):
    fora = 0
    n_grupos = 0
    for i in range(len(grupos)):
        if len(grupos[i]) >= 4:
            n_grupos += 1
        elif len(grupos[i]) <4:
            fora = fora + len(grupos[i])
    return n_grupos,fora

def elimina_rep(grupos):
	for i in range(len(grupos) - 1):
		for j in range(i + 1, len(grupos)):
			for k in grupos[i]:
				if k in grupos[j]:
					del grupos[j][grupos[j].index(k)]
	return grupos

def dfs(dic,inicio,visitado=None):
    if visitado == None:
        visitado = [inicio]
    for v in dic[inicio]:
        if v not in visitado:
            visitado.append(v)            
            dfs(dic,v,visitado)
    return visitado


def ordena_lista(grupos):
    for i in range(len(grupos)):
        for j in range(len(grupos)-1):
            if len(grupos[j])>len(grupos[j+1]):
                grupos[j],grupos[j+1]=grupos[j+1],grupos[j]
    return grupos

def fazer_grupos(dic):
    grupos = []
    for i in dic.keys():    
        temp = dfs(dic,i)   
        temp.sort()         
        if temp not in grupos:  
            grupos += [temp]   
    return grupos
