def strongly_connected_components(graph):
    result = [ ]
    stack = [ ]
    low = { }

    def visit(node):
        if node in low:
           return

        num = len(low)
        low[node] = num
        #print node, num
        stack_pos = len(stack)
        #print stack
        stack.append(node)

        for successor in graph[node]:
            visit(successor)
            #print low[node], low[successor], num
            low[node] = min(low[node], low[successor])

        if num == low[node]:
            #print num
            component = tuple(stack[stack_pos:])
            del stack[stack_pos:]
            result.append(component)

    for node in graph:
        visit(node)

    return result


