	minimo=infinito
	for i in V:
		if dist[i] < minimo:
			minimo=dist[i]
			no=i
	return no
def dijkstra(d, V, A):
	global infinito
	dist= []
	for i in range(len(V)+1):
		dist.append(infinito)
	C=[]
	dist[0]=infinito
	dist[d]=0
	while V!=[]:
		n = extrair_min(dist,V)
		C.append(n)
		del(V[V.index(n)])
		for i in A[n].keys():
		      if dist[i] > dist[n] + A[n][i]:
			      dist[i] = dist[n] + A[n][i]
	return C
