def estudar_cenario(grafo):
    global visitado, retorno_dfs
    visitado={}
    retorno_dfs=[]  
    for i in grafo:
        visitado.update({i:False})

    for i in grafo:                                             #primeiro depth first search
        if not visitado[i]:
            dfs(i,grafo)

    grafo_inv=inv_grafo(grafo)                                  #inverter grafo
    resultados=[]
    for i in retorno_dfs:                                       #segundo depth first search
        for j in grafo_inv:
            visitado[j]=False
        retorno_dfs=[]
        if not visitado[i]:
            dfs(i,grafo_inv)
        resultados.append(retorno_dfs)

    if len(resultados)>1:                                       #eleminar resultados iguais
        resultados=resultados_iguais(resultados)    

    grupos=cons_grupos(resultados)                              #defenir os grupos

    n_grupos=0
    n_pessoas_fora=0
    for i in range(len(grupos)):
        if len(grupos[i])>3:
            n_grupos+=1
        else:
            n_pessoas_fora+=len(grupos[i])

    return [n_grupos,n_pessoas_fora]

def dfs(v,grafo):
    visitado[v]=True
    for i in grafo[v]:
        if visitado[i]==False:
            dfs(i,grafo)
    retorno_dfs.append(v)

def inv_grafo(grafo):
    grafo_inv={}
    for v in grafo:
        grafo_inv.update({v:[]})
    for v in grafo:
        for i in range(len(grafo[v])):
            grafo_inv[grafo[v][i]].append(v)
    return grafo_inv

def resultados_iguais(resultados):
    for i in range(len(resultados)):
        resultados[i].sort()
    resultados.sort()
    iguais=[]
    for i in range(len(resultados)-1):
        if resultados[i]==resultados[i+1]:
            iguais.append(resultados[i])
    for i in range(len(iguais)):
        resultados.remove(iguais[i])
    return resultados

def cons_grupos(resultados):
    grupos=[]
    for s in range(len(resultados)):
        tamanho={}
        for i in range(len(resultados)):
            tam=len(resultados[i])
            tamanho[tam]=i
        pequeno=resultados[tamanho[min(tamanho)]]
        grupos.append(pequeno)
        resultados.remove(pequeno)
        for i in range(len(resultados)):
            for j in range(len(pequeno)):
                if pequeno[j] in resultados[i]:
                    resultados[i].remove(pequeno[j])
    return grupos

