def scc(G,v,tabela):
    G["index"] += 1
    tabela[0][v] = G["index"]
    tabela[1][v] = G["index"]
    x = len(G["stack"])
    G["stack"].append(v)
    G["visitados"].append(v)
    for w in G[v]:
        if w not in G["visitados"]:
            scc(G,w,tabela)
            tabela[1][v] = min(tabela[1][v], tabela[1][w])
        else:
            if tabela[0][w] < tabela[0][v]:
                if w in G["stack"]:
                    tabela[1][v] = min(tabela[1][v], tabela[0][w])
    if tabela[1][v] == tabela[0][v]:
        cfc = []
        if len(G["stack"]) > 0:
            w = G["stack"][-1]
            while tabela[0][w] >= tabela[0][v] and len(G["stack"]) >= 1:
                cfc.append(G["stack"].pop())
                if len(G["stack"]) != 0:
                    w = G["stack"][-1]
        G["cfc"].append(cfc)
    return G, tabela


