    if i<self.size+1:
      self.inorder(tab+2, i*2)
      print(tab*' ', self.heapKeys[i], self.heapNos[i])
      self.inorder(tab+2, i*2+1)

  def min_heapify(self, i):
    left=2*i
    right=2*i+1
    if left<=self.size and self.heapKeys[i]>self.heapKeys[left]:
      min=left
    else:
      min=i
    if right<=self.size and self.heapKeys[right]<self.heapKeys[min]:
      min=right
    if i!=min:
      self.heapKeys[i], self.heapKeys[min] = self.heapKeys[min], self.heapKeys[i]
      self.heapNos[i], self.heapNos[min] = self.heapNos[min], self.heapNos[i]
      self.min_heapify(min)

