    key=self.heapNos.index(no)
    if self.heapKeys[key]<newKey:
      print('new key is smaller than current key')
    else:
      self.heapKeys[key]=newKey
      while key>1 and self.heapKeys[key/2]>self.heapKeys[key]:
        self.heapKeys[key/2], self.heapKeys[key] = self.heapKeys[key], self.heapKeys[key/2]
        self.heapNos[key/2], self.heapNos[key] = self.heapNos[key], self.heapNos[key/2]
        key=key/2

