class PQ:
    def __init__(self):
        self.data = {}

    def push(self, key, pri):
        self.data[key] = pri

    def front(self):
        f = -1
        for x in self.data:
            if f<0 or self.data[x].Length < self.data[f].Length:
                f = x
        return f

    def EXTRACT_MIN(self):
        del self.data[self.front()]

    def change(self, key, pri):
        self.data[key] = pri

    def isEmpty(self):
        return self.data == {}

