class PQ:
	def __init__(self):
		self.data = {}

	def empty(self):
		return self.data == {}

	def pop(self):
		del self.data[self.front()]

	def front(self):
		f = -1
		for x in self.data:
			if f < 0 or self.data[x] < self.data[f]: f = x
		return f

	def push(self, key, pri):
		self.data[key] = pri

	def value(self,key):
		return self.data[key]

