def dfs(g):
    visitados = []
    for v in g.keys():
        if v not in visitados:
            visitar(g, v, visitados)
            if v in visitados:
                del visitados[visitados.index(v)]
            visitados.append(v)
    return visitados

def visitar(g, v, visitados=None):
        if visitados == None:
            visitados = []
        for u in g[v]:
            if u not in visitados:
                visitados.insert(0,u)
                visitados = visitar(g, u, visitados)
        return visitados

def transpor(g):
    transposto = {}
    for no in g.keys():
        transposto[no] = []
    for v in g:
        for a in g[v]:
            transposto[a] = transposto[a] + [v]
    return transposto

def apagar_comp(scc, grafo, stack):
    for no in scc:
        while no in stack:
            del stack[stack.index(no)]
        grafo = eliminar_no(grafo, no)
