def dijkstra(g,destino,V):
    dist=[]
    fim=[]
    dist.append(sys.maxint)
    for i in V:
        dist.append(sys.maxint)
    dist[destino]=0
    while len(V)!=0:
        t=extract_min(V,dist)
        V.remove(t)
        fim.append(t)
        for y in g[t].keys():
            if y in V:
                dist[y]=min(dist[y],dist[t]+g[t][y])
    return fim
def extract_min(V,dist):
	min=0
	for i in V:
		if dist[i]<dist[min]:
			min=i
	return min

