    for i in q:
        if pi[i] > u:
            u = pi[i]
            aux = i
    q.remove(aux)
    return aux

def relax(grafo,pi,u,v):
    if pi[v] == -1 or minimo(pi[u],grafo[u][v]) > pi[v]:
        pi[v] = minimo(pi[u],grafo[u][v])

def minimo(a,b):
    if a > b : return b
    else: return a

