def Dijkstra(start):
    cam=[]
    vertices[start].Length=0
    Q.change(start,vertices[start])
    while not Q.isEmpty():
        u=Q.front()
        cam.append(u)
        Q.extract_min()
        vertices[u].Visited=True
        for v in G[u]:
            if not vertices[v].Visited:
                w=G[u][v]
                Relax(u,v,w)
    return cam

