    return graph

def caminho(graph,start,finish,compmax):
    dist={}
    visited=[]
    for i in graph:
        dist[i]=0
    dist[start]=compmax
    while len(graph)>len(visited):
        maximo=-1
        vertice=0
        for i in dist:
            if i not in visited:
                if dist[i]>maximo:
                    vertice=i
                    maximo=dist[i]
        visited.append(vertice)
        for i in graph[vertice].keys():
            if i not in visited:
                dist[i]=max(min(dist[vertice],graph[vertice][i]),dist[i])
    return dist[finish]

