class Heap_min:
  def __init__(self):
    self.keys=[0]
    self.nos=[0]
    self.size=0

  def inorder(self, tab=0, i=1):
    if i<=self.size:
      self.inorder(tab+2, i*2)
      print(tab*' ', self.keys[i], self.nos[i])
      self.inorder(tab+2, i*2+1)

  def min_heapify(self, i):
    left=2*i
    right=2*i+1
    #print 'antes'
    #self.inorder()
    if left<=self.size and self.keys[i]>self.keys[left]:
      min1=left
    elif left<=self.size and self.keys[i]<self.keys[left]:
      min1 =i 

    if left<=self.size and self.keys[i]==self.keys[left]:
      if left<=self.size and self.nos[i]>self.nos[left]:
        min1=left
      else:
        min1=i

    if right<=self.size and self.keys[right]<self.keys[min1]:
      min1=right

    if right<=self.size and self.keys[min1]==self.keys[right]:

      if right<=self.size and self.nos[min1]>self.nos[right]:
        min1=right


    if right>self.size and left>self.size:
      min1=i

    if i!=min1:
      self.keys[i], self.keys[min1] = self.keys[min1], self.keys[i]
      self.nos[i], self.nos[min1] = self.nos[min1], self.nos[i]
      #print 'depois'
      #self.inorder()
      self.min_heapify(min1)


  def get_min(self):
    if self.size==0:
      print('heap vazia')
    else:
      min=self.nos[1]
      min02=self.keys[1]
      self.nos[1]=self.nos[self.size]
      self.keys[1]=self.keys[self.size]
      del self.keys[self.size]
      del self.nos[self.size]
      self.size-=1
      self.min_heapify(1)
      return [min, min02]

  def decrease_key(self, no, newKey):
    key=self.nos.index(no)

    if self.keys[key]<newKey:
      return
    else:
      self.keys[key]=newKey
      while key>1 and self.keys[key/2]>self.keys[key]:
        self.keys[key/2], self.keys[key] = self.keys[key], self.keys[key/2]
        self.nos[key/2], self.nos[key] = self.nos[key], self.nos[key/2]
        key=key/2
      #print 'decrease_antes\n',self.inorder()
      if key>1 and self.keys[key/2]==self.keys[key]:
        #print 'decrase_entra', self.nos[key/2], self.nos[key]
        while key>1 and self.nos[key/2]>self.nos[key]:
          self.keys[key/2], self.keys[key] = self.keys[key], self.keys[key/2]
          self.nos[key/2], self.nos[key] = self.nos[key], self.nos[key/2]
          key=key/2
      #print 'decrease_depois\n',self.inorder()    

  def insert(self, key, no):
    self.size+=1
    self.keys.append(1000000)
    self.nos.append(no)
    self.decrease_key(no, key)

