def bfs(graph, start, visited=[]):
    stack=[]
    stack.insert(0, start)
    visited=visited+[start]
    while len(stack)>0:
        w=stack.pop()
        for v in graph[w]:
            if v not in visited:
                visited=visited+[v]
                stack.insert(0, v)
    return visited

