class CRestriction:
    def __init__(self, restrictions, travel):
        self.minwidth, self.maxwidth, self.minlength, self.maxlength, self.minheight = restrictions
        self.source, self.destiny = travel

class CVertex:
    def __init__(self, destiny, atts):
        self.maxwidth, self.maxlength, self.maxheight = atts
        self.destiny = destiny

class CNode:
    def __init__(self):
        self.vertexes = []
        self.length = -1
        self.previous = None

    def append(self, vertex):
        self.vertexes.append(vertex)

def readiln():
