def kruskal(g,edge,custo):
    floresta=[]
    for i in g.keys():
        floresta.append([i])
    edge=qsort1(edge)
    optimo=0
    f=len(floresta)
    e=len(edge)
    while(f>=2 and e!=0):
        x=edge.pop()
        e-=1
        if (([x[0]] in floresta) and ([x[1]] in floresta)):
            floresta.remove([x[0]])
            floresta.remove([x[1]])
            floresta.append([x[0]]+[x[1]])
            optimo = optimo + x[2] - custo
            f-=1
        elif ([x[0]] in floresta):
            for i in range(f):
                if x[1] in floresta[i]:
                    floresta[i].append(x[0])
                    floresta.remove([x[0]])
                    optimo= optimo + x[2] - custo
                    f-=1
                    break
        elif ([x[1]] in floresta):
            for i in range(f):
                if x[0] in floresta[i]:
                    floresta[i].append(x[1])
                    floresta.remove([x[1]])
                    optimo= optimo + x[2] - custo
                    f-=1
                    break
        else:
            v0=(-1)
            v1=(-1)
            for i in range(f):
                if x[0] in floresta[i]:
                    v0=i
                if x[1] in floresta[i]:
                    v1=i
                if v0!=(-1) and v1!=(-1):
                    break
            if v0!=v1:
                floresta[v1]=floresta[v1]+floresta[v0]
