def dijkstra(graph, init):
    dist = {}
    visited = []
    for i in graph:
        dist[i] = 2**30
    dist[init] = 0
    Q = PQ()
    Q.push(init, 0)
    while not Q.empty():
        u = Q.front()
        Q.pop()
        visited.append(u)
        for (v,w) in graph[u]:
            aux = dist[u] + w
            if dist[v] > aux:
                dist[v] = aux
                Q.change_pri(v,w)
    return dist

class PQ:
    def __init__(self):
        self.data = {}
    def front(self):
        f = -1
        for x in self.data:
            if f<0 or self.data[x]>self.data[f]: f = x
        return f
    def pop(self):
        del self.data[self.front()]
    def push(self,key,pri):
        self.data[key] = pri
    def change_pri(self,key,pri):
        self.data[key] = pri
    def empty(self):
        return self.data == {}


