class MPQ:

    def __init__(self, A):
        self.data = A
        self.size = len(A)

    def isEmpty(self):
        return len(self.data) == 0

    def isIn(self,v):
        for k in self.data.keys():
            if (self.data[k].id == v):
                return True
        return False

    def getKey(self,v):
        for k in self.data.keys():
            if (self.data[k].id == v):
                return self.data[k].key

    def setKey(self,v,w):
         for k in self.data.keys():
            if (self.data[k].id == v):
                self.data[k].key = w        

    def heapify(self, i):
        left = 2*i
        right = 2*i + 1
        if (left <= self.size and self.data[left].key > self.data[i].key ):
            largest = left
        else:
            largest = i
        if (right <= self.size and self.data[right].key > self.data[largest].key):
            largest = right
        if (largest != i):
            aux = self.data[i]
            self.data[i] = self.data[largest]
            self.data[largest] = aux
            self.heapify(largest)

    def build(self):
        lista = range(1, self.size/2 + 1)
        lista.reverse()
        for i in lista:
            self.heapify(i)

    def extract(self): 
        if self.size < 1:
            return "heap underflow"
        maximum = self.data[1]
        self.data[1] = self.data[self.size]
        del self.data[self.size]
        self.size -= 1
        self.heapify(1)
        return maximum

