def scc(graph):
    result = [ ]
    stack = [ ]
    low = { }
    low["index"] = 0

    for l in graph.keys():
        elem = graph[l]
        z=0
        while len(elem)>z:
            if elem[z] not in graph.keys():
                elem.pop(z)
                z-=1
            z+=1

    def visit(node):
        if node in low:
           return
        num = low["index"]
        low[node] = low["index"]
        low["index"] = low["index"] +1
        stack_pos = len(stack)
        stack.append(node)

        for successor in graph[node]:
            if successor not in low:
                visit(successor)
                low[node] = min(low[node], low[successor])
            elif successor in stack:
                low[node] = min(low[node], low[successor])


        if num == low[node]:
            component = tuple(stack[stack_pos:])
            del stack[stack_pos:]
            result.append(component)

    for node in graph:
        visit(node)

    validos = 0
    soltos = 0

    for n in range(len(result)):
        if len(result[n])<4:
            soltos += len(result[n])
        else:
            validos +=1
    return result,validos,soltos


