def Prim(inicio):
    global nnos
    global nligacoes
    global custo
    Vertices[inicio].peso = 0
    maxsum = 0
    Q = []
    for i in G:
        Q.append(i)
    while (len(Q)>0):
        u = extractmax(Q)
        if u == -1:
            return "impossivel"
        Vertices[u].visitado = True
        maxsum+=Vertices[u].peso
        for v in G[u]:
            if Vertices[v].visitado==False:
                if Vertices[v].peso < G[u][v]:
                    Vertices[v].peso = G[u][v]
    return maxsum-((nnos-1)*custo)


def extractmax(Q):
    maxi = -1
    toreturn = -1
    for i in Q:
        if Vertices[i].peso>maxi:
            maxi = Vertices[i].peso
            toreturn = i
    if toreturn!=-1:
        Q.remove(toreturn)
    return toreturn
