def dijkstra(grafo,destino,regioes):
    dist={}
    for i in range(1,regioes+1):
        dist[i]=inf
    n_visited=grafo.keys()
    n_visited.remove(destino)
    pathL=0
    cursor=destino
    while n_visited:
        for i in grafo[cursor].keys():
            if i in n_visited:
                size=grafo[cursor][i]+pathL
                if size<dist[i]:
                    dist[i]=size
        cursor,pathL=select_min(n_visited,dist)        
    return dist


def select_min(n_visited,dist):
    miN=inf
    for i in n_visited:
        if dist[i]<miN:
            miN=dist[i]
            cursor=i
    n_visited.remove(cursor)
    return cursor,miN


