def ordenar(arestas):
        for i in range(len(arestas)):
		for j in range(len(arestas)):
			if arestas[i][2] > arestas[j][2]:
				(arestas[i],arestas[j]) = (arestas[j],arestas[i])
	return arestas
def kruskal(nos, adj):
	conj=[]
	for i in range(nos):
		conj.append(set())
		conj[i].add(i+1)
	rendB = 0
	for i in adj:
		x=i[0]
		y=i[1]
		if pai(x,conj) != pai(y,conj):
			conj=uniao(conj, x, y)
			rendB = rendB + i[2]
	return rendB,conj
def pai(conj, x):
	for i in range(len(conj)):
		if x in conj[i]:
			return i
def uniao(conj, x, y):
	feito = False
	for i in range(len(conj)):
		for j in range(len(conj)):
			if x in conj[i] and y in conj[j]:
				conj[i]=conj[i].union(conj[j])
				del(conj[j])
				feito = True
				break
		if feito==True: break
	return conj
