class PriorityQueue():

    def __init__(self,items=[]):
        self.items=items

    def insert(self,item):
        self.items.append(item)
        heapify_up(self.items,len(self.items))

    def ExtractMax(self):
        aux=len(self.items)-1
        self.items[0],self.items[aux]=self.items[aux],self.items[0]
        a=self.items.pop()
        heapify_down(self.items,aux,0)
        return a

    def getKey(self,no):
        for x in self.items:
            if x[0]==no:
                return x[1]

    def increaseKey(self,no,oldkey,newkey):
        i=self.items.index((no,oldkey))
        self.items[i]=(no,newkey)
        heapify_up(self.items,i+1)

    def isEmpty(self):
        return self.items == []

    def size(self):
        return len(self.items)


def heapify_down(items,n,i):
    l=2*(i+1)-1
    r=(2*(i+1))
    if l<n and items[l][1]>items[i][1]:
        largest= l
    else:
        largest=i
    if r<n and items[r][1]>items[largest][1]:
        largest=r
    if largest != i:
        items[i],items[largest]=items[largest],items[i]
        heapify_down(items,n,largest)
    return items

def heapify_up(items,i):
    pai=(i/2)-1
    i-=1
    if items[pai][1]<items[i][1] and pai>0:
        items[i],items[pai]=items[pai],items[i]
        heapify_up(items,pai+1)
    elif items[pai][1]<items[i][1] and pai==0:
        items[i],items[pai]=items[pai],items[i]
    return items


