def prim(grafo):
    pi={}
    key={}
    Q = grafo.keys()
    for v in Q:
        key[v] = -1
    random = Q[0]
    key[random] = INF

    while Q != []:
        u = extract_max(Q,key)
        if u == False:
            return False
        for v in grafo[u].keys():
            if (v in Q) and (grafo[u][v] > key[v]):
                key[v] = grafo[u][v]
                pi[v] = u
    lista = []
    for i in grafo.keys():
        if i != random:
            lista = lista + [(i,pi[i])]
    return lista

def extract_max(Q,key):
    try:
        u = -1
        for i in Q:
            if key[i] > u:
                u = key[i]
                aux = i
        Q.remove(aux)
        return aux
    except:
        return False

def rendimento(grafo, spanningT, nos, custo):
    if spanningT == False :
        return "impossivel"
    rend_optimo = 0
    for u,v in spanningT:
        rend_optimo += grafo[u][v]
    rend_optimo -= custo * (nos-1)
    return "rendimento optimo: " + str(rend_optimo)

