			indice=i-1
	return indice
def dijkstra(d, V, A):
	dist= []
	for i in range(len(V)):
		dist.append(sys.maxint)
	C=[]
	dist[d-1]=0
	while V != []:
		ind_minimo = extrair_min(dist,V)
