def djikstra(g,start,end):
    keys=g.keys()
    visited={}
    distancia={}
    for i in keys:
        visited[i]=False
        distancia[i]=infinity
    visited[start]=True
    if start not in g:
        return 0
    else:
        limite=g[start][escolhe_maximo(g[start],visited)]
    while start!=end:
        visited[start]=True
        keys=not_visited(g[start].keys(),visited)
        for i in keys:
            if visited[i]==False:
                if distancia[i]==infinity or distancia[i]<g[start][i]:
                    distancia[i]=g[start][i]   
        start=escolhe_maximo(distancia,visited)
        if start== -1:
                return 0
        else:
            if distancia[start]<limite:
                limite=distancia[start]
    return limite

def not_visited(list,visited):
    l=[]
    for i in list:
        if visited[i]==False:
            l.append(i)
    return l

def escolhe_maximo(g,visited):
    ind=-1
    max=-1
    for i in g.keys():
        if visited[i]==False and g[i]!=infinity:
            if g[i]>=max:
                max=g[i]
                ind=i
    return ind    

