class Heap(): # bad :|

    def __init__(self):
        self.data = {}
    def find_min(self): #O(N)
        ind = -1
        for i in self.data:
            if ind < 0 or self.data[ind] > self.data[i]: ind = i
        return ind
    def del_min(self): #O(N)
        del self.data[self.find_min()]
    def decreaseKey(self, key, value): #O(1)
        self.data[key] = value
    def insert(self, key, value): #O(1)
        self.data[key] = value
    def isEmpty(self): #O(1)
        return len(self.data) == 0
    def size(self):
        return len(self.data)
    def printElements(self):
        return self.data

def dijkstra_modified(graph, init):
    p = {}
    dist = {}
    visited = []
    Q = Heap()
    for i in graph:
        p[i] = None
        dist[i] = 2**30
        Q.insert(i, dist[i])
    dist[init] = 0
    Q.insert(init, 0)
    while not Q.isEmpty():
        u = Q.find_min()
        Q.del_min()
        visited.append(u)
        for (v,w) in graph[u]:
            if v not in visited:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    p[v] = u
                    Q.decreaseKey(v, w)
    return dist

