def bfs(g, s, visitados=[]):
    Q=[]
    Q.insert(0, s)
    visitados=visitados+[s]
    while len(Q)>0:
        w=Q.pop()
        for v in g[w]:
            if v not in visitados:
                visitados=visitados+[v]
                Q.insert(0, v)
    return visitados

