def procura_comp(dic,inicio,fim,compMax):
    distancia = {}   #dicionario das distancias
    visitados = []   #lista de visitados
    for i in dic:
        distancia[i] = 0
    distancia[inicio] = compMax
    while len(dic) > len(visitados):
        maior = -999999
        vertice = 0
        for i in distancia:
            if i not in visitados:
                if distancia[i] > maior:
                    vertice = i
                    maior = distancia[i]
        visitados.append(vertice)
        for j in dic[vertice]:
            if j not in visitados:
                distancia[j] = max(min(distancia[vertice],dic[vertice][j]), distancia[j])
    return distancia[fim]


