def visitar(g, v, visitados=None):
        if visitados == None:
            visitados = []
        for u in g[v]:
            if u not in visitados:
                visitados.insert(0,u)
                visitados = visitar(g, u, visitados)
        return visitados

def transpor(g):
    transposto = {}
    for no in g.keys():
        transposto[no] = []
    for v in g:
        for a in g[v]:
            transposto[a] = transposto[a] + [v]
    return transposto

def apagar_comp(scc, grafo, stack):
    for no in scc:
        while no in stack:
            del stack[stack.index(no)]
        grafo = eliminar_no(grafo, no)
    return grafo, stack


def eliminar_no(grafo, no):
    del grafo[no]
    for i in grafo:
        if no in grafo[i]:
            del grafo[i][grafo[i].index(no)]
    return grafo

