def trat(lis):
    x=0
    lis.reverse()
    for i in range (len(lis)-1):
        for j in range (i+1,len(lis)-1):
           if (lis[i] == lis[j]):
               if (x==0):
                   x=i
               lis.pop(j)
    for i in range (x+1,len(lis)-1):
        lis.pop(i)
    lis.reverse()
    return lis

