class heap_no :

	def __init__(self,identificador,valor) :
		self.identificador = identificador
		self.valor = valor

	def comparar(self,outro) :
		return self.valor <= outro.valor

	def __str__(self):
		return self.valor

class heap :

	lista = [0]

	def size(self) :
		return len(self.lista) - 1

	def adicionar(self,elemento) :

		self.lista += [elemento]		
		actual = len(self.lista) - 1

		while True :			
			if(actual == 1):
				break

			pai = actual // 2

			if(self.lista[actual].comparar(self.lista[pai])) :
				self.lista[pai] , self.lista[actual] = self.lista[actual] , self.lista[pai]
				actual = pai
			else :
				break

	def melhor(self) :

		if(len(self.lista) == 1) :
			return None

		melhor = self.lista[1]
		self.lista[1] = self.lista[-1]
		self.lista = self.lista[:-1]

		actual = 1

		while True :

				filho_e = actual * 2
				filho_d = filho_e + 1

				if filho_d >= len(self.lista) :
					if filho_e >= len(self.lista) :
						break
					else :
						menor = filho_e

				else :
					if self.lista[filho_e].comparar(self.lista[filho_d]) :
						menor = filho_e
					else :
						menor = filho_d

				if self.lista[menor].comparar(self.lista[actual]) :
					self.lista[menor] , self.lista[actual] = self.lista[actual] , self.lista[menor]
					actual = menor

				else :
					break

		return melhor

