    return y

def Dijkstra(G,start,end,compmaxi):
    d={}
    for i in G: #inicializar o dic dos valores
        d[i] = 0
    d[start]=compmaxi #inicio com o valor max ja fornecido
    marcados=[]
    while(len(marcados)!= len(G)):
        maximo = extract_max(d,marcados)
        marcados.append(maximo)
        for i in G[maximo]:
            if i not in marcados:
                d[i]= max(d[i] , min(d[maximo],G[maximo][i]))
    return d[end]


