def Dijkstra(G,start,end=None):
    d = {}
    for i in G:
        d[i]=0
    #print d
    d[start]=0
    for i in G:
        if i in G[start]:
            d[i]=G[start][i]

    d[start]=0
    visit_list = [start]

    while(len(visit_list)!=len(G)):
        if end in visit_list:
            break
        maximo = extract_max(d,visit_list)
        if maximo == 0:
            return 0
        visit_list += [maximo]
        for v in G[maximo]:
            if v not in visit_list:
                if (d[maximo] <= G[maximo][v]):
                    if d[v]< d[maximo]:
                        d[v] = d[maximo]
    return d[end]

