def Dijkstra(inicio):
    Vertices[inicio].peso = 0
    S = []
    Q = []
    for i in G:
        Q.append(i)
    while len(Q)>0:
        u = extractMin(Q)
        Vertices[u].visitado = True
        S.append(u)
        for v in G[u]:
            if Vertices[v].visitado == False:
                relax(u, v)

    return S

def extractMin(Q):
