def todoscaminhos(grafo,inicio,fim,cam=[]):
    cam=cam+[inicio]
    if inicio==fim:
        return [cam]
    if not grafo.has_key(inicio):
        return []
    cams=[]
    for nozinho in grafo[inicio]:
        if nozinho not in cam:
            newcams = todoscaminhos(grafo,nozinho,fim,cam)
            for newcam in newcams:
                cams.append(newcam)
    return cams

