    return visitados

def visitar(g, v, visitados=None):
        if visitados == None:
            visitados = []
        visitados.insert(0,v)
        for u in g[v]:
            if u not in visitados:
                visitados = visitar(g, u, visitados)
        return visitados

def transpor(g):
    transposto = {}
    for no in g.keys():
        transposto[no] = []
    for v in g:
        for a in g[v]:
            transposto[a] = transposto[a] + [v]
    return transposto

