def Kruskal(G,M):
    # representante
    repre={}
    total=0
    for n in G:
        repre[n]=n
    edges = [(G[u][v],u,v) for u in G for v in G[u]]
    edges.sort() # arestas ordenadas por odem crescente
    edges.reverse() # arestas ordenas por ordem decrescente
    # numero de nos na arvore de cobertura maxima
    Arvore = 0
    for (p,x,y) in edges:
        if repre[x]!=repre[y]:
            total = total+p
            repre = Union(repre,x,y) #union
	    Arvore = Arvore+1
    if Arvore!=len(G)-1:
        print('impossivel')
	return
    else:
        print('rendimento optimo:',total-M*Arvore)
	return

# Union
def Union(repre,x,y):
	r1 = repre[x]
	r2 = repre[y]
	for n in G:
		if repre[n]==r2:
			repre[n]=r1
	return repre

