from string import *
def fis(graph, start, end, path=[]):
    path = path + [start]
    if start == end:
        return [path]
    if not graph.has_key(start):
        return []
    paths = []
    for node in graph[start]:
        if node not in path:
            newpaths = fis(graph, node, end, path)
            for newpath in newpaths:
                paths.append(newpath)
    return paths

