def tarjan(amigos):
    dic={}
    lista=[]
    ciclos=[]
    def visit(amigo):
        if amigo in dic: return
        n=len(dic)
        dic[amigo]=n
        quant_amigos=len(lista)
        lista.append(amigo)
        for outro_amigo in amigos[amigo]:
            visit(outro_amigo)
            dic[amigo]=min(dic[amigo],dic[outro_amigo])
        if n==dic[amigo]:
            ciclo=lista[quant_amigos:]
            del lista[quant_amigos:]
            ciclos.append(ciclo)
            for i in ciclo:
                dic[i]=len(amigos)
    for amigo in amigos:
        visit(amigo)
    return ciclos

