def extract_max(d,visit_list):
    menor = -1
    key = 0
    for i in d:
        if ((i not in visit_list) and (d[i]>menor)):
            menor = d[i]
            key = i
    return key

def Dijkstra(G,start,end=None):
    d = {}
    d[start]=0
    for i in G:
        if i in G[start]:
            d[i]=G[start][i]
        else : d[i] = -1
    d[start]=0
    visit_list = []
    visit_list = [start]

    while(len(visit_list)!=len(G)):
        if end in visit_list:
            break
        max = extract_max(d,visit_list)
        if max==0:
            return 0
        visit_list += [max]
        for v in G[max]:
            if v not in visit_list:
                if (d[max] <= G[max][v]):
                    d[v] = d[max]
    return d[end]

