def imprimelista(lista):
    out=""
    while lista != []:
        indice, valor = lista.pop(0)
        if out == "":
            out += str( indice )
        else:
            out += " " + str( indice )        
    return out

def dijkstra(grafo, origem, destino):
    pi = {}
    Q = [(0,origem)]
    while Q :
        dist,u = heappop(Q)
        if u in pi:
            continue
        pi[u] = dist
        if u == destino : return pi[u]
        for v in grafo[u].keys():
            heappush(Q , ( pi[u] + grafo[u][v] , v ) )

