def procura_comp(dic,inicio,fim,compMin):
    aux = {}         #dicionario das distancias
    visitados = []   #lista de visitados
    for i in dic:
        aux[i] = 0
    aux[inicio] = compMin
    while len(dic) > len(visitados):
        maior = -999999
        vertice = 0
        for i in aux:
            if i not in visitados:
                if aux[i] > maior:
                    vertice = i
                    maior = aux[i]
        visitados.append(vertice)
        for j in dic[vertice]:
            if j not in visitados:
                aux[j] = max(min(aux[vertice],dic[vertice][j]), aux[j])
    return aux[fim]


